export const ASSIST_DOCS_INDEX: readonly AssistDocsSection[] = [
  { path: '/building-sites/besigner/animations', title: 'Element animations', heading: '', anchor: '', text: 'Element animations\nAny element on a screen can animate. Pick a preset, choose when it plays, and adjust a few numbers — there is no CSS to write.' },
  { path: '/building-sites/besigner/animations', title: 'Element animations', heading: 'Add an animation', anchor: '#add-an-animation', text: '1. Select the element on the canvas.\n2. Open the Attributes tab in the right-hand panel.\n3. Scroll to Animation and pick a preset.\nThe rest of the animation fields appear once a preset is chosen.\nPresets\n| Preset | Entrance | On hover |\n| Fade in | Fades up from invisible | Dims slightly |\n| Slide up | Rises into place while fading in | Lifts |\n| Slide down | Drops into place while fading in | Sinks |\n| Slide left | Enters from the right | Nudges left |\n| Slide right | Enters from the left | Nudges right |\n| Zoom in | Grows from slightly small | Grows |\n| Zoom out | Shrinks from slightly large | Shrinks |\nPlays\n- On scroll into view (default) — the animation runs the first time the element reaches the viewport. This is the right choice for anything below the top of the page.\n- On page load — runs immediately. Best for a hero or a headline that is visible the moment the page opens.\n- On hover — the element eases to its emphasis state while the pointer is over it, and eases back when the pointer leaves.\nDuration and delay\nBoth are in milliseconds. Duration is how long the motion takes; 600 is a natural default and anything over 3000 is capped. Delay is how long to wait before starting.\nEasing\nEasing is the shape of the motion — whether it starts fast and settles, or moves at one steady speed. It changes how an animation feels far more than its duration does.\n| Easing | Feels like |\n| Smooth (default) | Starts quickly and settles gently. The safe choice. |\n| Steady | One constant speed from start to finish. Mechanical, good for subtle moves. |\n| Gentle start | Eases in slowly, then arrives quickly. |\n| Gentle end | Starts quickly, then slows into place. |\n| Gentle start and end | Slow at both ends, quickest in the middle. |\n| Settles into place | Travels a little past its ' },
  { path: '/building-sites/besigner/animations', title: 'Element animations', heading: 'Animations do not play on the canvas', anchor: '#animations-do-not-play-on-the-canvas', text: 'The besigner shows every element in its finished, un-animated state so you can always see and select it. Use Preview or the published site to watch an animation run.' },
  { path: '/building-sites/besigner/animations', title: 'Element animations', heading: 'Accessibility', anchor: '#accessibility', text: 'Some people get motion sickness, migraines or vertigo from movement on screen, and both macOS and Windows have a system setting to ask for less of it.\nAglyn honors that setting. A visitor who has turned on Reduce motion sees your page with every element in its final position, fully visible, with no movement at all — including elements set to animate on scroll. You do not have to do anything, and there is no way to override it.\nThis is also why the presets are what they are. Every one of them only fades, slides a short distance or changes size slightly; none of them spin or parallax, and the most emphatic thing on offer is the Settles into place easing — which travels a little past its resting place before coming back to it, and which you have to choose deliberately.' },
  { path: '/building-sites/besigner/animations', title: 'Element animations', heading: 'Speed and layout', anchor: '#speed-and-layout', text: 'Animations are pure CSS. A published page loads no animation library, and a page with no animations on it ships nothing extra at all — no stylesheet, no script. A page that uses the scroll trigger adds a few hundred bytes of inline code to watch for elements entering the viewport.\nStaggering a row costs nothing extra. The page watches the row, not each card in it, so twelve cards arriving one after another is one thing to keep track of rather than twelve — the spacing between them is plain CSS.\nThe presets only ever change an element\'s opacity and its position on the screen, never the space it takes up. Nothing on the page moves to make room for an animation, so animations cannot cause the layout shift that search engines penalise.' },
  { path: '/building-sites/besigner/animations', title: 'Element animations', heading: 'If a visitor has JavaScript turned off', anchor: '#if-a-visitor-has-javascript-turned-off', text: 'Everything stays visible. Scroll-triggered elements simply appear in their final state rather than animating in, and load and hover animations still work normally. Search engines see the full text of the page either way.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: '', anchor: '', text: 'Copy & paste elements\nDuplicate makes another copy right where you are. Copy and paste goes further: it carries an element, with everything inside it, to somewhere else entirely — another screen, a layout, a reusable component, an email template.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Copy', anchor: '#copy', text: 'Select an element and either:\n- press Cmd / Ctrl + C , or\n- open the element\'s ⋮ menu (on the canvas overlay or in the hierarchy) and choose Copy.\nThe whole subtree comes along — a column you built copies with every link inside it.\nWith several elements selected the menu reads Copy selection and takes them all, in document order. If your selection includes both a container and something already inside it, the container wins: you get one copy, not two.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Paste', anchor: '#paste', text: 'Select where it should go and press Cmd / Ctrl + V , or choose Paste from the same ⋮ menu. The menu item names what\'s waiting — Paste Stack, Paste 3 elements — and is greyed out when nothing has been copied.\nWhere it lands follows the same rule as Add element:\n- Select a container (a Stack, Section, Container) and the copy goes inside it, at the end.\n- Select a leaf — a Screen Link, button, icon, image — and the copy goes beside it as the next sibling, because a leaf has no slot to render children in.\nEverything pasted is selected afterwards, so you can retext or restyle it straight away. Paste is a single undo step.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Between documents', anchor: '#between-documents', text: 'What you copy stays copied after you navigate. Open a different screen, layout, component or template and paste — the clipboard is still there. This is the fastest way to reuse a structure you have already built and refined.\nTwo things to know:\n- The copy is a snapshot, not a link. Editing the original later does not change what you pasted. When you want one source of truth across many places, promote it to a reusable component instead.\n- Elements have to exist where you\'re pasting. A block copied from an email template uses email elements, and pasting it into a site screen is refused with a message naming the element that isn\'t available there. Nothing is half-pasted — the paste either lands completely or not at all.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Copy & paste vs. Duplicate vs. reusable components', anchor: '#copy--paste-vs-duplicate-vs-reusable-components', text: '| You want | Use |\n| -- | -- |\n| Another one right here | Duplicate |\n| The same structure somewhere else, edited separately from then on | Copy & paste |\n| One thing that updates everywhere it appears | Reusable component |' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Shortcuts', anchor: '#shortcuts', text: '| Action | Shortcut |\n| -- | -- |\n| Copy selection | Cmd / Ctrl + C |\n| Paste | Cmd / Ctrl + V |\n| Select every element at the same depth | Cmd / Ctrl + A |\nThese act on elements, not text. While you\'re editing text — in the attributes panel, in a dialog, or directly on the canvas — the shortcuts do the ordinary thing and copy or paste the text instead.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Related', anchor: '#related', text: '- Multi-select & multi-drag\n- Reusable components\n- The Besigner' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: '', anchor: '', text: 'Drag-and-drop hierarchy\nEvery element on the canvas is a node in a tree. You rearrange that tree by dragging — and you add new elements by dragging them in from the drawer. This page covers all the ins and outs: where you can drag, how drop zones decide placement, why some elements accept children and others don\'t, and what happens when a drop isn\'t allowed.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Where you can drag', anchor: '#where-you-can-drag', text: 'Drag-and-drop works in two places, and they stay in sync:\n- The hierarchy panel — drag a node up, down, or onto another node to reorder or reparent it. Good for precise moves and for deeply nested trees.\n- The canvas — grab an element on the live page and drop it where you want. Good for visual, in-context placement.\nA move made in one place is immediately reflected in the other.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'What a drag does', anchor: '#what-a-drag-does', text: '- Reorder — drag a node between two siblings to change its position in the same parent.\n- Reparent — drag a node onto a different container to move it into that container.\n- Add — drag a component from the elements drawer onto the canvas to create a new element at the drop point.\nEvery drag is a single undoable step — press Undo (⌘/Ctrl+Z) to put it back.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Drop zones: edges vs. center', anchor: '#drop-zones-edges-vs-center', text: 'As you drag over an element, the Besigner splits it into drop zones and shows a placement marker for the zone you\'re pointing at. The zone decides where your element lands:\n- Edges — the thin bands along an element\'s top, bottom, left, and right. Dropping on an edge places your element as a sibling, before (top/left) or after (right/bottom) the element you\'re over — in the same parent.\n- Center — the large area in the middle. Dropping in the center places your element inside, as a child of that element.\nThe placement marker is the source of truth. A line between elements means "reorder/insert as a sibling here"; a marker within an element means "drop inside as a child." Always glance at the marker before you release.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Containers vs. leaf elements', anchor: '#containers-vs-leaf-elements', text: 'Whether the center zone means "drop inside" depends on the kind of element you\'re over.\nContainers accept children\nContainers are built to hold other elements: Stack, Box, Section, Card, App Bar, Toolbar, and similar. Dropping onto a container\'s center nests your element inside it. This is how you build structure — a Stack of buttons, a Section full of blocks, and so on.\nLeaf elements don\'t — dropping on one makes a sibling\nLeaf elements have no slot for child elements. There are three kinds:\n- Text elements render their content as inline text — a Screen Link, a Button, or a Text element. Their words are their content; there\'s nowhere to nest a child.\n- Self-closing elements draw themselves and take no children at all — an Image, an Icon, or a Video.\n- Elements whose content is an attribute look like containers but draw only what their attributes say — a Markdown block (its document is the Content attribute), a List Item Text row (its words are Primary/Secondary), a Reusable Component instance (its content lives in the definition), and a Layout Slot (filled by the screen bound to the layout). Anything nested inside one of these has nowhere to appear on the published page.\nDropping onto a leaf places your element as a sibling right after it, inside the leaf\'s parent — never nested inside the leaf. Over a leaf you\'ll only ever see a before/after placement marker, never an "inside" one, so the marker always matches where the element actually lands.\nWhy this matters Aiming at the middle of a small element like a Screen Link used to tuck the new element inside it, where it wouldn\'t render as expected. Now a leaf\'s center reads as "place next to me," which is almost always what you want — and you don\'t have to aim precisely at its edges.\nThe third kind is the one that used to' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Adding a new element', anchor: '#adding-a-new-element', text: 'Insert → New Element (and the toolbar +) adds the component you pick relative to your current selection, following the same container-vs-leaf logic as a drop:\n- Select a container — a stack, section, or the document itself — and the new element is added inside it.\n- Select a leaf — anything without a child slot, such as a screen link, button, or icon — and the new element lands as its next sibling in the same container, rather than nested inside it.\n- With nothing selected, the element is added at the end of the document.\nYou can also drag straight from the elements drawer, which groups components into curated categories (Sections & Blocks first, then Layout, Navigation, Text, and so on). A dragged-in component lands using the same drop-zone and placement rules described above.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'When a drop is rejected', anchor: '#when-a-drop-is-rejected', text: 'Not every element can go everywhere. Two kinds of guardrails apply:\n- Placement (lineal) rules. Components can declare what they accept as children or require as a parent — a Toolbar belongs in an App Bar, a layout slot accepts only certain content, and so on. If a drop breaks a rule, the Besigner rejects it and tells you why, naming the specific rule, so you can adjust instead of guessing. The same rules run for Insert → New Element, so you can\'t create an arrangement that drag-and-drop would refuse to make.\n- You can\'t move an element inside itself (or into one of its own descendants). That move is blocked with a clear message.\nLayout-only components are additionally gated by the view type you\'re editing (a screen vs. a shared layout).' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Moving an element without dragging', anchor: '#moving-an-element-without-dragging', text: 'Dragging isn\'t the only way to move an element between containers. Every element\'s ⋮ menu — on the canvas overlay, and on the hierarchy row — carries four move actions that work by clicking:\n- Shift up / Shift down — reorder the element among its siblings, without changing its container.\n- Move out of container — lift the element out of the container it\'s in, landing it directly after that container, one level up.\n- Move into element above — tuck the element into the sibling directly above it.\nUsed together, these reach anywhere in the tree: move out, shift until the element is sitting next to the container you want, then move into. This is the reliable route in a deeply nested tree, on a long page where the source and destination aren\'t on screen at the same time, or any time a drag is fiddly.\nEach action is a single undoable step, and each obeys exactly the same rules a drag does — including the leaf rule. An element whose content is an attribute (a Markdown block, a Reusable Component instance, a Layout Slot, a List Item Text) can\'t hold other elements, so Move into element above is greyed out over one, and Move out of container refuses to drop an element into one. When an action is unavailable the Besigner says why rather than moving the element somewhere it would never render.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Multi-drag', anchor: '#multi-drag', text: 'Select several nodes first, then drag any one of them to move the whole selection at once. The group keeps its document order at the destination, and each node is still checked against the placement rules — anything that can\'t legally move is skipped rather than blocking the rest. See Multi-select & multi-drag.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Tips', anchor: '#tips', text: '- Watch the placement marker — it\'s the definitive preview of where the drop lands.\n- Aim at an edge to place beside an element; aim at the center of a container to place inside it.\n- Dropping on a leaf always makes a sibling — you don\'t have to be precise about its edges.\n- Undo any drag you didn\'t mean.\n- Use the hierarchy panel for precise moves in busy or deeply nested trees.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Related', anchor: '#related', text: '- Multi-select & multi-drag\n- The Besigner overview\n- Inline & rich text editing\n- Screens & layouts' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: '', anchor: '', text: 'Edit from the live site\nBrowsing your published site and spot something to fix? The admin bar connects your console edit access to the live site, so any page you\'re looking at is one click from its screen in the besigner.\nRolling out The admin bar is a release-flagged feature, currently being rolled out — it may not be available on your site yet. Nothing needs configuring; it switches on per-workspace as the rollout proceeds.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Call it up', anchor: '#call-it-up', text: 'On any page of your published site, either:\n- add ?aglyn-edit to the URL — handy as a shareable habit, or\n- press Cmd/Ctrl + Shift + E.\nA small Edit this site pill appears in the bottom-right corner. Visitors never see it — the pill only appears when you ask for it, and the bar itself only renders for accounts that actually hold edit access.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Connect your access', anchor: '#connect-your-access', text: 'Click the pill. Because your published site and the console live on different domains, a small console popup opens to confirm it\'s really you: it checks your console sign-in and your role on this site, then reports "Connected — edit access confirmed" and closes itself. If you\'re not signed in to the console, it says so and waits for you to sign in and try the shortcut again; an account without edit rights gets a plain "No edit access".\nEdit access means what it does everywhere else: a site admin or editor, or a workspace owner, admin, or editor. Viewers don\'t get a read-only bar — they simply don\'t get one.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'The bar', anchor: '#the-bar', text: 'Once connected, a slim dark bar sits along the bottom of the page:\n- the site name, and the name of the screen serving the current page;\n- Edit this page — opens the besigner for exactly that screen, in a new tab (shown whenever the page maps to a routed screen);\n- Open console — the site\'s dashboard;\n- × hides the bar for the rest of the page view.\nThe bar follows you as you browse — navigate to another page and it re-resolves which screen you\'re on.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Good to know', anchor: '#good-to-know', text: '- The connection lasts for the browser tab (and tokens expire after 30 minutes on their own) — closing the tab forgets it, and the site sets no new cookies.\n- The bar is a convenience surface only: it never changes what the page serves, and all real editing still happens in the console with your normal permissions.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Publish your first screen\n- Teams, roles & membership' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: '', anchor: '', text: 'Element catalog\nThese are the built-in elements in the ELEMENTS drawer, grouped by the categories the drawer uses. Every one of them ships with a preset — dropping it gives you an element that already has content in it, not an empty box you have to fill before you can see it.\nElements from installed plugins appear under their own groups (Marketplace, Your components) and are not listed here.\nAnything on this page can be styled from the Styles panel, targeted by interactions, and made responsive per breakpoint. The attributes below are the element-specific settings in the Attributes panel.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Finding the one you want', anchor: '#finding-an-element', text: 'You do not have to recognize an element by name. Two places offer them — the Elements tab beside Hierarchy, and the Choose element dialog — and both search and describe them the same way.\nSearch {#element-search}\nType in Search elements and the categories collapse into a single Best matches list. Searching looks at more than the name: an element\'s description, its category and its keywords all count, so "space" finds Stack and "sign in" finds the member elements even though neither says so in its title.\nMatches on the name always come first — an exact name, then a name starting with what you typed, then a name containing it — and only after those, elements matched on their description or keywords. So typing grid puts Grid at the top rather than burying it under everything whose description happens to mention a grid. Clearing the box brings the curated categories back.\nWhat an element says about itself {#element-detail}\nPoint at an element and a detail view explains it before you commit to it:\n- A live preview — the element genuinely rendered, with its preset content and your site\'s theme, so the colors and type are the ones you will actually get. It is a picture, not a playground: nothing in it is clickable.\n- What it is for, in a sentence — written per element rather than generated, so it tells you when to reach for this one instead of the similar one next to it.\n- What it will and won\'t do — whether it holds other elements, which children it accepts, whether it must sit inside something else, whether its text is edited on the canvas, and which plugin provides it.\n- Its attributes, and a Learn more link into this page at the right category.\nSome elements have nothing to show on their own — a table row, a tab panel — and say so, naming the parent they belong inside rath' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Layout', anchor: '#layout', text: '| Element | What it\'s for |\n| Box | The plain container. No styling of its own — you give it padding, background and borders from the Styles panel. Renders as div, span, p, figure, figcaption, blockquote or pre. For landmarks, use Section instead. |\n| Section | Grouping inside a semantic HTML element (section, article, aside, nav, header, footer, main) with an accessible label, so the page keeps a meaningful document outline. |\n| Container | Centers content and caps its maximum width. |\n| Stack | One-dimensional row or column with a gap. Also the element that carries repeat over a dataset. |\n| Grid | Responsive 12-column layout. See Grid below. |\n| Layout slot | Where a bound layout injects the screen\'s own content. |\nGrid\nGrid does both jobs in one element, matching Material UI\'s current API:\n- Turn Container on for the row. It gets Spacing, Row spacing, Column spacing and Columns (the row is divided into 12 by default).\n- Leave Container off for a cell, and give it a Span.\nSpan and Offset are typed as text so one field covers every breakpoint:\n| You type | You get |\n| 6 | Half the row at every size |\n| auto | Just wide enough for the content |\n| grow | All the space the other cells don\'t take (Span only) |\n| xs:12 md:4 | Full width on mobile, a third from md up |\nBreakpoint keys are xs, sm, md, lg and xl; xs:12, md:4 with commas works too. If part of what you type can\'t be read, the whole value is ignored rather than half-applied — a layout that silently differs from what you typed is worse than one that plainly doesn\'t work.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Surface', anchor: '#surface', text: '| Element | What it\'s for |\n| Paper | A themed surface. Elevation 0–24 raises it with a shadow; the Outlined variant swaps the shadow for a border (and hides the elevation control, which does nothing there). |\n| Card | A surface for one subject, composed from Card Header (title + subheader), Card Content (the padded body) and Card Actions (the button row). Each piece is its own element, so you can select, style and reorder them. |\n| Accordion | A header that expands to reveal its details, built from Accordion Summary and Accordion Details. See Accordion below. |\nAccordion\nStart expanded controls whether visitors arrive with the panel open. On the canvas the panel is always shown open regardless — collapsed details can\'t be selected or styled. Preview and the published site both behave the way you configured it, so what ships is never in doubt.\nAccordion Summary takes an optional Header links to. Leave it empty and the whole header row toggles the panel, which is what every accordion does by default. Point it at a screen and the row splits in two: the header text becomes a link to that screen, and the chevron beside it becomes the toggle. That split is the only way a header can do both — a link placed inside the toggle button is invalid markup and unreachable by keyboard. It is what lets a mobile drawer offer Product both as a group to open and as a page to visit.\nThe FAQ preset drops three complete panels at once.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Navigation', anchor: '#navigation', text: '| Element | What it\'s for |\n| Screen Link | A link that targets a screen by id, so it survives slug renames. Renders as a button or as a text link. |\n| App bar / Toolbar | The site header frame. |\n| Nav menu / Mega menu | Dropdown and full-width navigation menus. |\n| Drawer / Menu Button | A panel that slides in from the left, right, top or bottom. Open it with a Menu Button or an interaction. Width applies to left/right drawers; top and bottom sheets span the viewport, and the control is hidden for them. The Mobile Nav preset wires a hamburger, a drawer and a desktop link row in one insert. |\n| Tabs / Tab Panel | A tab strip and its panels. See Tabs below. |\n| Breadcrumbs | The trail showing where a page sits. Fill it with Screen Links so it survives renames, and leave the current page as plain Typography — linking a page to itself is the classic breadcrumb mistake. Set Collapse above to fold a long trail into an ellipsis. |\n| Pagination | A page picker. See Pagination below. |\n| Language switcher / Theme mode switcher | Locale and light/dark controls. |\n| Table of Contents | An "On this page" list built from the headings of a Markdown element on the same screen. |\nTabs\nType the tab names into Tabs, one per line. Then each Tab Panel child names the tab it belongs to in Shows under tab (capitalisation and surrounding spaces are ignored).\nPanels are matched by label, not by position, so reordering them in the hierarchy never shuffles your content. The preset ships three tabs with three matching panels, so you only touch the matching if you add a panel yourself.\nOn the canvas every panel is shown stacked, each captioned with the tab it belongs to — a hidden panel can\'t be edited, and a caption with a name you don\'t recognize is a label typo you can see. Preview and the pu' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Text', anchor: '#text', text: '| Element | What it\'s for |\n| Typography | One run of text — a headline, a label, a paragraph. The element you edit inline on the canvas. |\n| Markdown | A whole document, held as markdown source in one element. For policies, terms and anything whose real source is a .md file. See Long documents in markdown. |\n| Entry Body | A content entry\'s markdown body, on an entry-template screen. |' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Data Display', anchor: '#data-display', text: '| Element | What it\'s for |\n| List | A vertical list. Optional sticky Heading, plus Dense and Disable padding. |\n| List Item | One row, with Divider, Align items, Dense, Disable gutters and Disable padding. |\n| List Item Text | Primary and secondary text, plus Inset to line the text up with rows that have an icon or avatar. |\n| Collection entries and friends | Content collections — entry lists, bodies, related posts, share bars. |\n| Custom HTML | Sanitized markup you supply. |' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Media', anchor: '#media', text: '| Element | What it\'s for |\n| Image | An image with fit, size and radius controls, an optional link, and an automatic responsive srcSet for media-library URLs. |\n| Video | Hosted or embedded video. |\n| Icon | Any icon from the icon picker. |\n| Image List / Image List Item | A dense gallery. See Image List below. |\nImage List\nPick a Variant:\n- Standard — a plain grid.\n- Quilted — tiles can span several columns and rows. Set Column span / Row span on the tiles; only this variant reads them.\n- Masonry — every image keeps its own aspect ratio. Row height is ignored here (and hidden), because a fixed height would crop exactly what masonry exists to preserve.\n- Woven — alternating tile sizes.\nEach tile holds an ordinary Image element, so galleries get the same responsive srcSet and lazy loading as an image anywhere else. Fill in Caption for a caption bar, or leave it blank for no bar at all.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Forms, Input, Commerce, Members', anchor: '#forms-input-commerce-members', text: 'Forms and fields, buttons and widgets, product grids and cart companions, and the member sign-in/sign-up elements. These are covered with the features they belong to — see Forms, Commerce and Member accounts.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Drag-and-drop hierarchy — which elements accept which children\n- Long documents in markdown — the Markdown and Table of contents elements\n- Responsive styling\n- Interactions & custom HTML' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: '', anchor: '', text: 'Interactions & custom HTML' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Fluent interactions', anchor: '#fluent-interactions', text: 'Select any element, open the Interactions tab in the right-hand panel — beside Attributes and Styles — and use Add interaction. Everything configures in one dialog without leaving the besigner:\n- Trigger: when the element is clicked, hovered, the hover ends, or it scrolls into view.\n- Frequency: every time (the default — repeatable, for menu and drawer toggles), once per page view, once per session, once per visitor, or with a cooldown.\n- Actions (stack as many as you need). The basic actions below are pure in-page choreography — available on every plan (see Plan availability):\n- Show / hide / show-hide an element — pick any other canvas element from a list; no selectors or classes needed. Use the target\'s ⋮ → Start hidden until an interaction shows it to make it start hidden on the live site and on the canvas; selecting it opens it again while you design. (Not the eye on the Hierarchy row — that hides an element outright, and nothing reveals it.) Each of these takes an optional Delay (a later show/hide on the same target cancels a pending one — the classic hover grace period) and, for steps that can show, Close on Esc / Close on outside click so a revealed panel dismisses itself like a real menu.\n- Open / close / open-close a menu — drives a Dropdown or Mega Menu element. The target defaults to the element itself when it is a menu; leave it empty to address the page\'s first menu. A menu opened by When hovered closes itself when the pointer leaves the nav item and its panel.\n- Open / close / open-close a drawer — drives a Drawer element; leave the target empty to address the page\'s first drawer.\n- Toggle / append / remove a class — targets this element by default, or any CSS selector. Pair with your theme\'s utility classes for menus, reveals, and state changes.\n- Make t' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Interactions belong to the page they are on', anchor: '#interactions-belong-to-the-page-they-are-on', text: 'An interaction is stored on the element, inside the screen, layout, component or template that holds it. That is what makes the obvious things true:\n- it publishes and rolls back with the page — restoring an earlier version restores the interactions that version had;\n- it travels with the element — duplicate a section, copy a component to another site, or package a template, and the choreography arrives with it, bound to the copy rather than the original;\n- it is removed with the element — deleting a button takes its click behaviour with it, leaving nothing pointing at something that is gone;\n- it is unsaved work until you save, like any other edit, rather than going live the moment the dialog closes.\nWorkflows → Actions is a different list. Actions are things the site does — an order was placed, a form was submitted — so they are site-wide and live outside any one page. Interactions are things an element does, and they are edited only here, on the element.\nInteractions you set up earlier Interactions created before this change are still listed on their element and still run. They are being moved onto their elements; nothing you need to do.' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Plan availability', anchor: '#plan-availability', text: 'Interactions come in two tiers, and the field editor labels the steps that need a higher plan:\n- Basic interactions — every plan, including Free. Opening and closing menus and drawers, showing and hiding elements, toggling classes, sticky nav, navigation, and site alerts are pure client-side DOM behavior with no server cost. They run everywhere and are never metered — a hover-to-open menu is not a paid feature.\n- The automations engine — Pro+, metered. Steps that reach the server or a data pipeline — overlays, analytics events, custom JS (Business), and the server steps (workflows, email, datasets, campaigns) — require the actions entitlement and count against your monthly action runs.\nOn a plan without the automations entitlement, an interaction that mixes tiers still runs its basic steps live; the Pro+ steps are simply skipped until you upgrade. See workflows & actions for the full step catalog and metering.' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Pick the target by clicking', anchor: '#pick-the-target-by-clicking', text: 'Any action that points at an element — open a menu, show / hide, open a drawer — lets you choose the target visually: click Pick element, click the element on the canvas, and confirm. No CSS selectors to write, and the picker resolves the stable data-aglyn id under the hood so the target survives edits. A custom selector field is there as a secondary option for advanced cases (a class or attribute selector you maintain yourself).\nInteraction cookbook\n- Hamburger menu: on any button, When clicked → Open/close a drawer. (The Menu Button element does this without any interaction at all.)\n- Hover menu: on a Dropdown or Mega Menu element, When hovered → Open a menu at frequency every time. Clicking already toggles every menu with zero configuration; this adds the hover-open, and the menu closes itself when the pointer leaves.\n- Hover reveal: When hovered → Show an element plus When hover ends → Hide an element, both at frequency every time.\n- Mega menu from scratch (no Mega Menu element): wrap a trigger button and a panel in one Stack (wrapper: position relative; panel: ⋮ → Start hidden until an interaction shows it, position absolute below the trigger). On the wrapper: When hovered → Show the panel, When hover ends → Hide it with a small Delay (say 250ms) so the pointer can travel; add Close on Esc to the show step for keyboard dismissal. The Dropdown Panel preset (Navigation group) inserts exactly this pattern with both interactions pre-wired — see menus & navigation.\n- Scroll reveal: on a section, When scrolled into view → Append class visible with a CSS transition, frequency once per visitor.\n- Announcement click-through: When clicked → Track analytics event plus Go to a URL.' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Track an analytics event', anchor: '#analytics-event-step', text: 'When clicked → Track an analytics event sends an event of your own naming to your site\'s Google Analytics property, alongside the events Aglyn already sends. It is a Pro+ step, and it is the only way to measure something the built-in events do not already cover — a click on one particular button, a tab someone opened, a video they started.\nThe step takes an event name and up to 10 parameters, each a name and a value. See Google Analytics events for everything your property receives without you doing anything.\nNaming the event {#analytics-event-name}\nType a readable name; Aglyn normalizes it into the shape GA4 accepts. CTA Click! is stored and sent as ctaclick — lowercased, anything that is not a letter, digit or underscore becomes an underscore, runs of underscores collapse, a trailing one is dropped, and the result is cut to 40 characters.\nTwo names are refused outright rather than rewritten, with the reason shown as you save:\n- A name GA4 reserves for itself, or one starting firebase, google or ga. GA4 would silently discard the event.\n- A name Aglyn already uses, such as purchase or generatelead. Reusing one would mix your events into a report built on a different shape.\nA name that does not start with a letter is refused too.\nParameters {#analytics-event-parameters}\n| Limit | Value |\n| Parameters per event | 10 |\n| Parameter name length | 40 characters — GA4 drops anything longer |\n| Parameter value length | 100 characters — longer values are truncated |\nEvery parameter needs both a name and a value; a row with either half blank is not saved.\nParameters carry labels, never a visitor\'s details A parameter must not carry anything about the person — no email address, name, phone number, postal address or IP. Those parameter names are refused, and so is any value that l' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Custom HTML block', anchor: '#custom-html-block', text: 'The Custom HTML block accepts markup and CSS with a strict safety model:\n- Sanitized by default — scripts, iframes, objects, forms, and inline event handlers (onclick etc.) are stripped on every render. What you paste can style and structure, never execute.\n- Embed mode for third-party widgets: the raw snippet runs inside a sandboxed iframe with scripts allowed but no access to your site, cookies, or visitor data. Set the iframe height to fit the widget.\n- A url(...) still reaches out, and that is on you. Sanitizing stops your CSS from executing; it does not stop it from fetching. Only https:, data: and blob: addresses are accepted — anything else, http: included, is rewritten to url(about:invalid), which loads nothing and leaves the rest of the rule intact. Which https host you name is your choice, and we do not proxy it: your visitor\'s browser contacts that host directly, so it learns their IP address, user-agent and the page they are on. The same rule covers a style attribute inside your markup and the Styles panel\'s Custom CSS. Hosts you reference this way are yours to name in your own privacy notice — see Trust & security.\nPrefer first-party blocks where one exists — embeds can\'t participate in theming or interactions.' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Related', anchor: '#related', text: '- Walkthrough: build a mega menu with hover interactions\n- Menus & navigation\n- Besigner overview\n- Workflows & actions' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: '', anchor: '', text: 'Live co-editing & unsaved work\nThe besigner is safe to share. When teammates open the same document you see each other — avatars, cursors, and selections — and edits flow between you live. And if a tab crashes or closes with unsaved work, the besigner keeps a local draft and offers it back.\nThis works in every besigner editor: screens, layouts, reusable components, templates, and designed emails.\nPlan availability Free. Presence, co-editing, conflict protection, and draft recovery are on for every plan — how many teammates can edit is a question of collaborator seats, not of this feature.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Who\'s here', anchor: '#whos-here', text: 'When someone else has the document open, their avatar appears in the besigner toolbar (photo or initial, on their assigned color, ringed in that same color). Hovering says what to expect of working alongside them: "«Name» has this open too. Edits merge live, element by element, and either of you can save at any time — if you both change the same element, the last change wins."\nUp to six avatars are shown side by side; beyond that the rest collapse into a\n+N disc that says how many more are here. When you are the only one in the document, the toolbar shows nothing at all rather than an empty slot.\nIf your own account has the document open somewhere else — another tab, or your account signed in on another machine — that window gets its own avatar too, drawn with a dashed ring and a small screen badge so you can tell at a glance it is yours. It is treated as a separate session in every respect: edits merge between your windows the same way, and either window can save. The conflict guard has never keyed on who wrote, so two windows of one account are protected exactly as two people are. Your current window never draws an avatar for itself.\nOn the canvas, each collaborator shows up as:\n- a cursor in their color, with their name on a small pill — shown while they are moving around, and dropped once they have an element selected, where the selection already carries their name;\n- a selection outline around the element they have selected, with their name in a tab above it. Your own other tab is labeled "You, in another tab" rather than by name, and its outline is dashed.\nA collaborator\'s cursor is only broadcast while their pointer is genuinely over the canvas, so someone typing in a side panel stops trailing a cursor across your screen.\nThe overlays never intercept your clicks.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'One version, one room', anchor: '#per-version-rooms', text: 'Presence and live editing are scoped to one version of one document — not to the document as a whole.\nThat matters in practice: if a teammate is editing version 3 of a screen and you open version 4, you will not see each other. No avatar, no cursor, no selection box, and none of their typing arrives on your canvas.\nThis is not a gap — it is the honest answer. Live edits flow through a shared working copy that is itself per version, so two people on different versions were never going to reach each other. Showing an avatar would promise a connection that does not exist. If you mean to work together, make sure you are both on the same version.\nTemplates are the exception, because templates do not have versions: everyone editing one template shares a single room.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Who\'s in a document, before you open it', anchor: '#presence-in-lists', text: 'You don\'t have to open a document to find out someone is already in it. Small avatars appear on the row itself in:\n- the Screens list,\n- the Layouts list,\n- the Components card,\n- the Templates card, and\n- the Site emails card.\nUp to three faces are shown per row, then +N. A row with nobody in it shows nothing, so a quiet list stays quiet.\nTwo things are worth knowing about these row avatars, because they answer a slightly different question from the ones in the editor:\n- They mean "in this document", not "in this version." They are rolled up across every version, so a face on the row may be someone editing a version other than the one your Open button goes to. The tooltip says so.\n- They refresh about every 30 seconds, and only while the tab is in front — this is a periodic check, not the live connection the editor has. Treat a row avatar as "someone was here a moment ago", and the editor\'s toolbar as the live truth.\nOne person shows as one face here however many tabs they have open, and you will see yourself on a row if you have that document open in another window.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Presence is not a lock', anchor: '#not-a-lock', text: 'Seeing nobody does not reserve the document, and seeing somebody does not shut you out. Nothing is ever locked — anyone with edit access can open anything at any time. What actually protects your work is the save guard described in When a save is refused, not the avatars.\nSo an empty avatar row is a good sign, not a guarantee. If presence cannot reach the server the toolbar says so — an amber warning disc replaces the avatars, and clicking it explains what went wrong, what to do, and warns you explicitly that an empty stack is not proof you are alone.\nOn a self-hosted Aglyn without a Realtime Database configured, presence and live co-editing are simply not available; the toolbar shows a neutral "not set up" badge rather than an error, and everything else on this page — the save guard and draft recovery — carries on working.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Editing together', anchor: '#editing-together', text: 'Edits are shared live, per element: change a heading while a teammate restyles the footer and you both keep your work. What lands in the document:\n- Different elements — both sets of edits apply. This is the normal case, and it just works.\n- The same element — last write wins. Co-editing shares changes; it does not merge two versions of one element.\n- A teammate\'s changes never enter your undo stack — undo rewinds only your own edits, including edits that came back to you from another of your own tabs.\nOne rough edge in undo If you try to undo a change to an element a teammate has since edited themselves, the undo will step back without visibly changing anything — Aglyn will not roll back their work on your behalf. Press undo again to keep going back through your own edits. This is uncommon, and only happens on an element two of you touched.\nAnyone with edit access to the site (a site admin or editor, or a workspace owner / admin / editor) can co-edit. Viewers see presence but their changes are refused at the door.\nLive edits are working state, not saves — the document still saves when someone presses Save, and a successful save is what makes the shared state durable.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Saving together', anchor: '#saving-together', text: 'Everyone can save, in any order, as often as they like. One of you saves, the other carries on and saves a minute later — that is the normal rhythm and nothing interrupts it. It works because co-editing has already done the merging: your teammate\'s changes reached your canvas element by element before they pressed Save, so what you write next contains their work rather than overwriting it.\nThe besigner checks that rather than assuming it. Before letting a save through it confirms your document actually incorporates what is stored — every element the other save changed is on your canvas with the stored value, deletions included. Two people in step both pass, always.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'When a save is refused', anchor: '#when-a-save-is-refused', text: 'Two situations do not pass that check, and both are real:\n- Your session has fallen behind. A tab that lost its connection never received those elements, so it would write over work it has never seen.\n- You have both changed the same element. That is the one case co-editing cannot merge, and letting it through is exactly how the last writer silently wins.\nEither way the besigner tells you immediately — not twenty minutes later when you press Save:\n> Someone else saved this screen while you were editing. Saving is paused so their\n> work is not overwritten — reload to pick up their changes. Nothing you have done\n> here is lost until you do.\nThe banner has one action — Reload — and that\'s deliberate: there is no "save anyway" that could silently destroy a teammate\'s work. Your canvas keeps everything you\'ve done until you reload, so the recovery is calm: note (or copy) what you need, reload to pick up their version, and reapply.\nPressing Save while the banner is up answers with the same message rather than saving. The guard also runs server-side inside a transaction, so even a save racing the conflict by milliseconds is refused, never silently applied.\nThe guard identifies the other writer as a different editing session, not as a different person — so it applies to a second window of your own account just as it does to a colleague.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Local draft recovery', anchor: '#local-draft-recovery', text: 'The besigner continuously keeps a local draft of your unsaved work in the browser — written about a second after you pause, and flushed when the tab is hidden or closed. If the tab crashes, the machine sleeps at the wrong moment, or you just close without saving, the next time you open that document you\'re offered the work back:\n> Unsaved changes to this screen from 3 minutes ago were recovered from this\n> browser. Restoring puts them back on the canvas without saving; you can undo it.\n- Restore puts the draft back on the canvas — unsaved and undoable, so you can inspect before committing to it.\n- Discard deletes the draft from this browser and keeps the saved document. It changes nothing on the canvas and nothing for anyone else.\n- Nothing is ever restored automatically; the besigner always asks.\n- If someone saved while your draft was stranded, restoring it would roll their work back, so it is not offered — the banner says so and points you at Reload.\nThe offer only appears when you are alone in the document. Recovery is for a crash: a lost connection, a browser quit, a tab closed on unsaved work. If anyone else has the document open — including another of your own windows — live co-editing has already put the unsaved work back on the canvas, so there is nothing to recover and no prompt is shown. Your draft is still kept; it simply is not offered over the top of work other people are in the middle of.\nDrafts live in this browser only (they don\'t follow you across machines), are kept for up to 7 days, and are deleted the moment a save succeeds. They\'re a crash net, not version history — for named, durable snapshots use versions.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'The Save button always answers', anchor: '#the-save-button-always-answers', text: 'The toolbar\'s save control reads Save when there\'s work to save and Up to date when there isn\'t — including after a teammate saves work you already have, where the document is now stored exactly as your canvas holds it and there is nothing left to write — and clicking always produces an answer (saving, "Already saved", or the conflict warning), never silence.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Screens & layouts — versions\n- Teams, roles & membership' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: '', anchor: '', text: 'Long documents in markdown\nSome pages aren\'t designed — they\'re written. A privacy policy, terms of service, an acceptable-use page or a staff handbook is a document, and its real source is usually a markdown file somewhere else: a repo, a Drive folder, whatever your lawyer sends back.\nThe Markdown element puts that document on the canvas as one element, holding the source text. Updating the page is one paste. The Table of contents element reads that same text and builds the "On this page" list from its headings, so the list can never fall out of step with the document above it.\nBuilding a page out of one Typography element per paragraph is the alternative, and it costs you the thing that matters most here: you can\'t copy the page back out to compare it with the source file, and every heading you add means hand-editing the contents list too.' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'The Markdown element', anchor: '#the-markdown-element', text: 'Drop Markdown from the Text group of the ELEMENTS drawer, then write or paste your document into the Content attribute.\nContent is a visual editor, not a text box. Headings, bold, italic, links, lists, quotes, images, code blocks and tables all have toolbar buttons, and the shorthands below still work as you type — start a line with ## and it becomes a heading. Pasting from a word processor or a Google Doc keeps its formatting rather than arriving as one flat paragraph.\nThe toolbar\'s Markdown switch shows the raw source instead, for when you want to paste a whole file in one go or check exactly what\'s stored. Both views edit the same text — the element stores markdown either way.\nDouble-click the element on the canvas to get the same editor over the document itself, without going to the attributes panel — the same gesture that edits any other text element in place. What you type is kept as you type it, so Done, pressing Esc, and clicking another element all leave the document saved; use undo (⌘Z) to take an edit back.\nText is set for reading rather than for a layout: 17px on a generous line height, in the theme\'s primary text color, with headings that step up in size on wider screens. You don\'t need to style anything for it to look right.\nThe element draws its Content attribute and nothing else, so it takes no child elements — there\'s no position in a parsed document an element could occupy. Dropping onto it places your element next to the Markdown block rather than inside it, the same way every other leaf element behaves. To put a picture in the document, write it as markdown — — and to put one beside the document, drop an Image as a sibling.\nWhat the markdown supports\n| You write | You get |\n| ## A heading | A top-level heading — and an anchor a contents list can link' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'The Table of contents element', anchor: '#the-table-of-contents-element', text: 'Drop Table of contents from the Navigation group. On a page with one Markdown element, that\'s the whole setup — it finds it and lists its headings.\n| Attribute | What it does |\n| Markdown element | Which document to read. Leave it empty unless the screen has more than one. |\n| Heading | The label above the list. Defaults to On this page; clear it for no label. |\n| Levels | List ## and ### headings, or ## only. |\nSub-headings are indented under their parents. Each entry is a real link, so it can be copied, opened in a new tab and followed by a crawler — clicking one scrolls the page to the matching heading.\nHow it finds the markdown\nBy walking the screen, in reading order — not by looking for anything in the page\'s HTML. That\'s what makes it work everywhere: on the canvas, in Preview and on the published site.\n- Left empty, it takes the first document on the screen.\n- Set to a specific element, it takes that one.\n- Set to an element that\'s since been deleted, it falls back to the first one. Deleting and re-adding a Markdown element is exactly what re-pasting a document looks like, and a published page with an empty aside is the worse outcome.\nTwo elements count as a document: the Markdown element, and the Collection entry body on a blog article template. So an article template can carry an "On this page" aside beside the post, with no extra wiring — drop the Table of contents element on the screen and it reads the entry body.\nWhile you\'re authoring, the entry body still shows its {{entry.body}} token rather than a real post, so the contents list skips it and reads the next document on the screen instead. It fills in on Preview and on the published page, where the post is actually there.\nPut the contents list wherever you like — most often in an aside column beside the do' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'Heading links', anchor: '#heading-links', text: 'Every ## and ### heading gets an anchor id built from its own words — in the Markdown element, in a collection entry body, and in the console\'s own markdown preview, all from the same rule:\n- lower-cased, with accents folded to plain letters (Résumé → resume)\n- anything that isn\'t a letter or a digit becomes a hyphen, and runs of hyphens collapse\n- leading and trailing hyphens are trimmed\nSo ## Your Rights & Choices is #your-rights-choices, and ### Section 4.2 — Retention is #section-4-2-retention.\nThe rule is deterministic: the same words always produce the same link. Re-pasting an updated document doesn\'t break links people have already shared or bookmarked, as long as the heading still says the same thing.\nIf a document repeats a heading, the second one gets -2, the third -3, and so on in document order — and the numbering skips anything already taken, so a document containing Notice twice and ## Notice 2 still ends up with three distinct links.\nAnchors come from the document\'s own words, so two documents on one screen with the same headings will produce the same ids twice. On a page like that, give the second document distinct headings — or split it onto its own screen, which is usually what it wanted anyway.' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'Related', anchor: '#related', text: '- Element catalog\n- Text editing — for headlines and short copy, where Typography is the right element\n- Screens and layouts' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: '', anchor: '', text: 'Multi-select & multi-drag\nWorking element-by-element is slow. The Besigner lets you select multiple nodes — in the hierarchy or on the canvas — and act on them together.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Select multiple', anchor: '#select-multiple', text: '- On the canvas, add elements to the selection as you click.\n- In the hierarchy, select multiple nodes the same way.\n- Selection spans both surfaces — what you pick in the hierarchy is reflected on the canvas and vice versa.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Move the whole selection', anchor: '#move-the-whole-selection', text: 'Once several nodes are selected, dragging moves the entire selection at once, preserving their arrangement. This is the fast way to reposition a group without grouping them permanently.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'What the inspector shows', anchor: '#what-the-inspector-shows', text: 'The inspector\'s header names one element, and with several selected that element is the last one you added to the selection — not the first, and not "several". So a header reading Hero · Section while four things are highlighted is telling you about the fourth click, and the panel\'s Attributes and Styles tabs act on that element.\nPick the element you actually want to edit last, or drop back to a single selection before reaching for the inspector. Dragging, by contrast, still moves everything selected. See the inspector.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Tips', anchor: '#tips', text: '- Selection overlays render inside the viewport\'s stacking context, so they highlight the right elements without disturbing page scroll.\n- Combine with drag-and-drop reparenting to move a group into a new parent.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Related', anchor: '#related', text: '- Drag-and-drop hierarchy\n- The Besigner\n- The inspector' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: '', anchor: '', text: 'The Besigner\nThe Besigner is Aglyn\'s visual editor. You build a screen by placing components on a canvas, arranging them in a hierarchy, and editing content directly on the page. It renders your screen under the real site theme, so what you see matches what publishes.\n1. Primary bar — the document switcher, File/Edit/Insert menus, the Publish/Unpublish button, the ƒx functions panel, the version you\'re editing, and notifications.\n2. Toolbar — add elements, undo/redo, scheme and device preview, panel toggles, and the Live/Preview/save state on the right.\n3. Hierarchy & elements — the node tree of the screen and the drawer of components you can add.\n4. Canvas — your screen rendering live under the real site theme; select, drag, and edit text inline.\n5. Inspector — info, attributes, and styles for the selected element.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Preview vs. canvas', anchor: '#preview-vs-canvas', text: 'The canvas is an editing surface: hidden panels expand when you select them, so you can style what you can\'t otherwise reach, and nothing responds to hover the way a visitor would experience it.\nPreview (in the toolbar) renders the same draft the way the published site will: author-hidden panels start closed, and hover and click interactions actually run — so a mega menu, dropdown, or popup behaves exactly as it will live.\nTwo deliberate differences from the real site:\n- Links don\'t navigate. You stay on the screen you\'re previewing.\n- Server-side steps don\'t fire — no analytics events, webhooks, or automations. A preview never writes data or spends quota.\nUse Preview to check interaction behavior before publishing, and the canvas to edit the parts a visitor would never see open.\nPlan availability Free. The Besigner is core to building; some components and actions it exposes are plan-gated (noted where relevant).' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'What you can do', anchor: '#what-you-can-do', text: '- Drag-and-drop components from the drawer onto the canvas, and reparent them by dragging in the hierarchy or on the canvas. The drawer and the New Element picker group components into curated categories, with the Sections & Blocks library first — composed, ready-made sections ahead of the primitives. The groups, in order: Sections & Blocks, Layout (boxes, containers, stacks, grids, sections, layout slots), Navigation (app bar, toolbar, screen links, tabs, breadcrumbs, pagination, drawers, language switcher, social links), Text, Forms (forms, fields, search), Input (buttons, switches, widgets), Media (images, video, icons, image lists), Data Display (lists, custom HTML, feeds), Commerce (product grids, cart, checkout companions), Members (sign-in, sign-up, password recovery), Surface (paper, cards, accordions), then any plugin-provided groups such as Marketplace and Your components. Every built-in element is listed in the element catalog.\n- Multi-select across the hierarchy and canvas, then move the whole selection at once.\n- Edit text inline — double-click a text-capable element to type directly; opt-in elements support basic rich text.\n- Bind a layout so the screen renders inside a shared header/footer frame.\n- Preview color schemes with the artboard light/dark toggle, matching the live site\'s system-driven scheme.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'The canvas', anchor: '#the-canvas', text: 'The canvas shows your screen composed with its theme and, if bound, its layout. Selection overlays highlight the active element without affecting page scroll.\nWhen a drop isn\'t allowed, the Besigner explains why — it surfaces the specific placement (lineal) rule that rejected the move, so you\'re never guessing.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Hierarchy panel', anchor: '#hierarchy-panel', text: 'Every element on the canvas is a node in a tree. The hierarchy panel lets you:\n- Reorder and reparent nodes by dragging (with a placement marker showing the target slot).\n- Select multiple nodes and act on them together.\n- See which nodes are layout-only vs. screen content.\n- Read how deeply a node is nested by counting the guide lines to the left of its name — one per level, the same weight at every level. The branch holding the current selection draws its guides in the accent color.\n- Copy a node and its children and paste them elsewhere — including into a different screen, layout or component. See Copy & paste elements.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'The inspector', anchor: '#the-inspector', text: 'The right-hand panel has three tabs — Attributes, Styles and Info — and one header above all three naming what they act on, with a SELECTED chip opposite. It reads like Hero · Section: the element\'s name as the hierarchy shows it, then the component it actually is.\nRead it before you edit. On a canvas, clicking a child moves the selection under you — click a heading inside a hero and the panel silently switches from the section to the heading, with three tabs of controls that look identical either way. The header is what tells you which of the two your next change lands on.\nThe second half is dropped when it would only repeat the first, so a plain box reads Box, not Box · Box. Because the header is shared, Attributes, Styles and Info cannot disagree about what is selected. With nothing selected the panel shows its empty state instead.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Inline and rich text', anchor: '#inline-and-rich-text', text: '- Double-click any text-capable component to edit its text on the canvas.\n- Components that opt in support basic rich text (bold, links, and similar).\n- You can also set a component\'s text from the Text attribute field in the inspector.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Reusable components', anchor: '#reusable-components', text: 'Promote any subtree into a reusable component, then insert instances of it across screens. Editing the source updates every instance at render time. You can rename, demote, or delete reusable components from the site dashboard. See Reusable components.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Editing together', anchor: '#editing-together', text: 'Two people can open the same document and edit it live: you see each other\'s avatars in the toolbar, cursors and selections on the canvas, and element-level changes as they happen. Saves are protected against overwriting each other, and unsaved work survives a crash as a local draft. See Live co-editing & unsaved work.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'AI in the canvas', anchor: '#ai-in-the-canvas', text: '- AI copy assist rewrites or generates text for any canvas text prop.\n- AI Generate Section produces a constrained subtree straight onto the canvas.\nSee AI Assist.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Related', anchor: '#related', text: '- Element catalog\n- Copy & paste elements\n- Screens & layouts\n- Bindings & variables\n- Section & block library' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: '', anchor: '', text: 'Responsive styling & custom CSS' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Style per breakpoint', anchor: '#style-per-breakpoint', text: 'The artboard preview mode now doubles as your styling scope:\n- Fluid Responsive (default) — style edits apply at every screen size.\n- XS / SM / MD / LG / XL — edits in the styles panel apply from that breakpoint up, following the mobile-first cascade. Switch to SM – Tablet, change a padding, and phones keep the base value while tablets and up take the new one.\nA chip at the top of the styles panel always shows the active scope ("Styling: all screen sizes" or "Styling breakpoint: SM"). Values you don\'t touch keep inheriting — opening a panel at a breakpoint never pins anything by itself.\nSelecting a device also re-renders the canvas at that width: responsive values ({ xs, md }), visibility bands, and breakpoint-driven component layouts all resolve as they will on a real device of that size — the published site is untouched by preview mode.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Switch one style off to compare', anchor: '#mute-a-style', text: 'Every field that has a value carries an eye in its top corner. Click it and that one declaration stops applying on the canvas — the value stays in the box, struck through and dimmed, and clicking again puts it straight back. It is the way to answer "what does this section look like without the max width?" without deleting a value you want to compare against.\nThe same eye is on the rows under Classes & custom CSS: each declaration in the Builder list, and each class chip. A switched-off class stays on the element — the chip\'s ✕ is still the only thing that removes one — so the chips are always the class list your site ships. The one exception is aglyn-hidden — the class behind ⋮ → Start hidden until an interaction shows it. Its chip\'s eye shows the element on the canvas while you design it, because "stop applying the hidden class here" and "show this element while I design it" are one decision. Its ✕ still removes the class, which is the same as choosing Do not start hidden.\nThe eye on the Hierarchy row is a different control: it hides the element outright, in the besigner and on the published site. It writes no class, and it never touches the element\'s own styles — hide a Stack laid out with display: flex and you get that flex back when you show it again.\nSwitching a style off is a canvas setting, like the device preview: it is never saved, it never reaches Preview or your published site, and reloading the editor brings every declaration back. It also follows the scopes below — switching off a colour in the Hover state leaves the default colour applying, and one switched off while styling SM is back on at all screen sizes.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Style hover, focus and other states', anchor: '#interaction-states', text: 'Under the breakpoint chip is a second row of chips: Default, Hover, Active, Focus and Disabled. They answer the same question the breakpoint chip does — which version of this element am I editing?\nPick Hover and every field in the panel switches to that element\'s hover styles. Change the background, and you have said "this button is darker when you point at it". Pick Default again to go back to the resting styles.\n- Hover — while the pointer is over the element.\n- Active — while it is being pressed or clicked.\n- Focus — while it has keyboard focus (see the note below).\n- Disabled — while a form control is disabled.\nA chip with a • already has styles for that state. Selecting a state gives its chip an × that clears the whole state at once.\nYou can see the state while you style it\nYou cannot hover an element while working in a side panel, so picking a state also holds it on the canvas: the element renders as though you were hovering it (or pressing it, or focusing it) while you work, and a banner says so.\nThis is a preview. It is not saved, it does not appear in Preview, and it never reaches your published page — going back to Default ends it, and so does selecting a different element.\nFields you don\'t touch keep inheriting\nA state only overrides what you actually change. Set a hover background and the text color, padding and everything else keep coming from the default styles — which is exactly how the browser treats it.\nThat means setting a value back to what the default says removes it from the state rather than pinning a duplicate, and clearing a field lets the state inherit again.\nStates and breakpoints combine\nThe two chips work together. Choose MD – Laptop and Hover and you are editing "the hover style, on laptops and up" — phones keep whatever the smaller breakpoi' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Box stylers', anchor: '#box-stylers', text: 'The spacing styler is one diagram of the element\'s box, drawn the way a browser actually builds it: margin on the outside, then the border, then padding, and the content in the middle. Each region is shaded and labeled, and every side shows the value it is currently set to.\n- Pick the fan-out with Side / Axis / All: one side at a time, the vertical or horizontal pair together, or all four sides at once.\n- Click any side of the diagram to open its editor. Clicking the same side again closes it.\n- Every side takes either a spacing step from your theme or a custom amount with a unit you choose.\n- The border ring is shown so the diagram matches what the browser draws. Border width, style and color are edited under Borders & Shadows, not here — there is one place for each.\n- Everything respects the active breakpoint scope.\nThe sides are named, not abbreviated {#spacing-side-names}\nYou do not have to know that mt means margin-top. Each side announces itself in words — Space outside — top on the margin, Space inside — top on the padding — in its tooltip, in its heading when you open it, and to a screen reader. A side with nothing set on it simply reads Top, Right, Bottom or Left; once it has a value, the side shows the value instead (24px, 0px, auto), so the diagram doubles as the readout.\nThe legend beneath the diagram says what each region does, in the terms that actually matter when you are deciding which one to reach for:\n| Region | What it is |\n| Margin | Space outside the element, pushing its neighbors away |\n| Border | The line drawn around the element — set under Borders & Shadows |\n| Padding | Space inside the element, between its border and its content |\n| Contents | The element\'s own text or children |\nThe whole diagram is keyboard-reachable: Tab moves between the s' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Spacing steps & units', anchor: '#spacing-units', text: 'Space can be set two ways, and the difference matters more than it looks.\nSpacing steps (recommended) {#spacing-steps}\nA step is a rung on your site theme\'s own spacing ladder. The styler shows what each rung comes to on your theme today, but it stores the step, not the pixels.\n| Step | On a default theme |\n| None | 0px |\n| Hairline | 4px |\n| Extra small | 8px |\n| Small | 16px |\n| Medium | 24px |\n| Large | 32px |\n| Extra large | 48px |\n| Huge | 64px |\n| Giant | 96px |\nThose pixel figures are what a default theme resolves to, and they are shown beside each rung in the menu so you never have to guess. A site whose theme uses a different spacing unit gets a different column of numbers against the same names — which is the point.\nThat is the whole point. If you later retune your theme\'s spacing, or a different theme is applied, everything set to Medium moves with it. An element set to a fixed 24px stays at 24px forever and slowly falls out of step with the rest of the site.\nTwo entries in the menu are easy to confuse and mean opposite things:\n- Not set removes the property altogether, so the element goes back to inheriting whatever it would have had.\n- None is a real value of zero — an instruction to have no space here, which will override an inherited one.\nIf an element already carries a step that is not on the ladder — set in the JSS tab, or by a template — the menu keeps it rather than silently rounding it, shown as "10× the spacing unit" with its resolved size.\nReach for a custom amount when you need an exact figure — a hairline offset, a value that has to match a specific image — and for everything else use a step.\nUnder the hood A step is stored as the number MUI\'s theme.spacing() takes, so marginTop: 3 is what lands in the document and theme.spacing(3) resolves it at' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Style groups', anchor: '#style-groups', text: 'The styles panel organizes every control into accordions, and every field has exactly one home — no custom CSS needed for the common properties:\n- Flexbox & Grid — everything about laying an element out as a flex or grid container, and about where it sits inside its own parent: alignment and direction toggles, wrapping, the gap / row-gap / column-gap fields, the grid column and row track lists with auto-flow, and the per-item controls — grid column/row placement, flex grow, flex shrink, flex basis, and order.\n- Layout — display variant and float.\n- Colors — text color, background color, and Background Fill (see gradient backgrounds). Both pickers open on theme color references first (see scheme-scoped colors); a Custom color step reveals the full picker. The two color fields hold a color — a hex, an rgb()/hsl() value, or a theme reference. Paste anything else (a gradient, a url(…)) and the field says so and refuses it, rather than saving a value the browser would silently drop.\n- Sizing — width, height, and the min/max bounds for both.\n- Typography — Font Family first (a menu, see picking a font), then font size, weight, line height, letter spacing, text transform, and text decoration.\n- Borders & Shadows — a Border editor (thickness box + line-style menu) with its color beside it, the same editor per edge (top, right, bottom, left) for dividers and accent rails, a Corner Radius preset menu, an Outline, and a Shadow preset menu. The shorthand draws all four edges; use the per-edge fields when you want a rule under a header or a line between columns. See borders without CSS.\n- Position & Overflow — position scheme with top/right/bottom/left offsets, z-index, overflow, opacity, and cursor.\nEvery field also carries a ✕ at its top-right once it holds a value. That is how a ' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Gradient backgrounds', anchor: '#gradient-backgrounds', text: 'Background Fill in the Colors group builds a gradient by clicking — no custom CSS.\n1. Set Background Fill to Linear gradient (or Radial gradient) — the field opens as that one select. It starts from your theme\'s primary and secondary colors so you see a gradient immediately; Solid color paints no image and hands the element back to the Background Color field above.\n2. Set the Angle in degrees for a linear fill — 180 runs top to bottom, 90 left to right.\n3. Edit the color stops. Each stop is a color button plus a position in percent. The color button opens the same two-stage picker as every other color field, so a stop can be a theme color (it then follows your palette, in both light and dark) or a literal hex. One gradient can mix the two — bind the ends to Primary and Secondary and drop a literal mid-tone between them. Add stop adds one near the end of the ramp, ready to be positioned; a gradient always keeps at least two, so the remove button greys out at two.\nBackground Fill writes background-image, which paints over the Background Color — so a solid color set there still shows through anywhere the gradient is transparent, and stays as the fallback if you switch the fill back to solid.\nThe first choice in the menu — Default, or Inherited on a component instance — is not the same as Solid color. Default leaves the fill unset; Solid color is a positive "paint no image" (background-image: none). On an ordinary element they look identical, and on a component instance they are the difference between keeping the component\'s gradient and replacing it with your own background color.\nLike the other color fields, Background Fill is scheme-scoped: theme-color stops adapt on their own, and while the artboard previews dark you can give dark a different gradient outright.\nA backgr' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Visibility per device band', anchor: '#visibility-per-device-band', text: 'The Visibility accordion hides the selected element on whole device bands — mobile (under 600px), tablet (600–899px), and desktop (900px and up). Bands are range-scoped rather than mobile-first, so hiding one band never changes the element\'s display on the others — the classic "hide the link cluster on mobile, show a menu button instead" swap is two toggles (menus & navigation).\nOn the canvas, bands follow the artboard: select a device in the preview switcher and the matching band applies at that device\'s width — XS shows the mobile band, SM the tablet band, MD and up the desktop band. In Fluid Responsive mode the canvas follows the real browser window instead, so resize the window (or open the published site) to see bands flip.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Scheme-scoped colors', anchor: '#scheme-scoped-colors', text: 'Published sites follow each visitor\'s light/dark scheme (system setting, or their own choice via the theme mode switcher component), so a hardcoded light-mode hex can be unreadable in dark mode. Two tools keep colors correct in both schemes:\nTheme color references (preferred). Every color picker — text, background, and border color, plus color attributes on components — opens on your site theme\'s palette references first: Primary, Secondary, Background, Surface, Text, Divider, and friends. Each swatch is split to preview its light and dark resolutions, and selecting one stores the reference (e.g. background.paper), not a fixed color — the element automatically re-colors when the site switches schemes. Pick Custom color to reveal the full picker when you really want a fixed value.\nPer-scheme custom colors. The artboard\'s scheme toggle (the sun/moon button in the toolbar) doubles as a styling scope, exactly like the device preview does for breakpoints:\n- Light preview (default) — color edits set the element\'s base colors, which both schemes share until dark overrides exist.\n- Dark preview — the styles panel shows a "Styling: dark scheme" chip, and edits to text, background, and border color become dark-only overrides. Light mode keeps the base values; the canvas shows the dark result as you edit.\nOnly color fields scope to the scheme — spacing, sizing, typography, and layout always apply to both schemes no matter which one you preview. Clearing a color while previewing dark removes the override and falls back to the base color. Scheme overrides compose with breakpoint scoping: previewing dark on the MD – Laptop artboard writes a dark override that applies from MD up.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Custom classes', anchor: '#custom-classes', text: 'Every element accepts Classes (chips input under Classes & custom CSS). They merge into the rendered element, so you can target them from theme styles and from interaction class actions.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Custom CSS (sx)', anchor: '#custom-css-sx', text: 'The Classes & custom CSS section edits the element\'s sx in three modes:\n- Builder — property + value rows with grouped suggestions (layout, spacing, typography, background, border, effects).\n- CSS — paste plain declarations (border-radius: 8px;); they parse into the element\'s styles at the active breakpoint scope.\n- JSS (sx) — the full document as JSON, including responsive objects ({ xs, md }) and nested selectors ("&:hover"), for full control.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Semantic sections & theme mode', anchor: '#semantic-sections--theme-mode', text: '- The Section component groups children inside a real HTML element — section, article, aside, nav, header, footer, main, or div — keeping your page outline meaningful for SEO and assistive tech.\n- The Theme mode switcher component gives visitors a light/dark/ device-default override that persists across visits.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Edit JSON for one element', anchor: '#edit-json-for-one-element', text: 'Right-click any element → Edit JSON to edit just that element and its children as JSON (the rest of the screen is untouched). Apply validates component ids and node ids, and the change is undoable.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: '', anchor: '', text: 'Reusable components\nBuild something once — a card, a call-to-action, a footer block — and reuse it everywhere as a reusable component.\nAn instance is not a copy. It grafts the source at render time, so editing the component updates every page that places it. Change a font size once and the whole site follows.\nA component is content you repeat inside a page. If what you want is the frame around the page — header, navigation, footer — that is a layout, not a component. And if you want a starting point you copy once, with no live link back to the source, that is a template.\nPlan availability Starter and above. On Free, promoting an element answers "Reusable components require a Starter plan — see Billing to upgrade." There is no cap on how many components a site can have.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Promote', anchor: '#promote', text: '1. Select the element you want to reuse. The whole subtree comes with it.\n2. In the Attributes panel, choose Save as reusable component.\n3. Give it a name and an optional description, then Save component.\nThe element you promoted becomes the first instance of the new component, in place. It keeps its position in the page and its element id, so the parent\'s child list, your undo history and the current selection all stay valid.\nThat in-place swap is the point. If promoting left the original behind as ordinary elements, the document that defined the component would be the one place that never tracked it — you would edit the component later and this page alone would silently keep the old copy.\nSave as reusable component appears only on an element that is not already an instance and is not locked by a shared layout. Elements a layout frames are locked on the screens that use it — open the layout to promote from there.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Insert instances', anchor: '#insert-instances', text: 'Insert instances from Your components in the element drawer, on any screen, layout, template or other component.\nOn the canvas an instance renders its actual content, not a placeholder — what you see is what the page will render, with properties already resolved. The rendered elements are not canvas elements, though: clicking anywhere on an instance selects the instance, which is the only thing there you can select, move or delete. To change what is inside it, open the component.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Properties', anchor: '#properties', text: 'A component doesn\'t have to look identical everywhere. Give it properties and each place you use it supplies its own text, image or link — while the layout and the styling still come from the one component.\nThis is what stops a hero from being rebuilt on every page. Only the words differ.\nDeclare them\n1. Open the component and choose File ▸ Properties…\n2. Add property. Give it a name — headline, say — a type, an optional label for the Attributes panel, and a default.\n3. The dialog shows each property\'s token under its name.\n| Type | Field in Attributes |\n| -- | -- |\n| Text | Single-line text |\n| Long text | Multi-line text |\n| Image | Image picker |\n| Link | Screen picker, or an external URL |\n| Number | Number |\n| Yes / no | Toggle |\nA Link property is a screen picker at both ends — in the dialog\'s Default column and in each instance\'s Attributes panel — exactly like a Button\'s own Link to screen field. It stores the screen\'s id, not its address, so the link keeps working when that screen\'s slug or parent changes. Choose External URL or path… for anything that is not one of your screens; a typed address is used verbatim and does not follow a rename.\nLink properties written before the picker existed hold a typed address. They keep working unchanged — but they are still typed addresses, so pick the screen again if you want them to survive a rename.\nProperty names must start with a letter or underscore and contain only letters, numbers and underscores. A dot is rejected: the Attributes panel names its field for the storage path propValues. , which splits on dots, so hero.title would address a level that does not exist and its value would silently never reach the page.\nUse them\nInside the component, put the property\'s token wherever the value belongs:\nIt works in any text ' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Retrofit duplicated sections', anchor: '#retrofit-duplicated-sections', text: 'If the same section has already been copied onto several pages, converting it is safe and takes one pass:\n1. On the page whose wording is correct, promote the section. It becomes an instance and the definition is created from it.\n2. Open the component, declare a property for each part that differs between pages, and replace those texts with their tokens. Use the first page\'s wording as each default.\n3. Save properties, then publish.\n4. On every other page, insert an instance, check it renders, and only then delete the old section. Appending before deleting keeps the page\'s section order intact when the section is the last one.\n5. Fill in that page\'s wording on the instance — or leave the fields empty where the copy was already identical.\nDeleting last is what makes this reversible: at every point the page still has exactly one copy of the section.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Detach', anchor: '#detach', text: 'Detach from component, on an instance, turns it back into ordinary elements with fresh ids — the confirmation reads "Detached — this copy no longer follows the component." Use it when one page needs a variation the shared source shouldn\'t carry.\nWhat you get is what the page was showing. The property values set on that instance — and every per-instance style and attribute override applied to it, on its outer element and on each element inside it — are baked into the copy as ordinary text, images, styles and attributes, so the section looks identical before and after; it is simply editable now. Nothing in the copy still points at a property.\nDetach copies the component\'s published tree — unsaved or unpublished edits sitting in the component\'s working version are not what you get.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Nesting', anchor: '#nesting', text: 'A component can place instances of other components. Expansion runs to a depth of 5, which also bounds a component that accidentally references itself.\nNested components expand on the canvas too, not only in Preview and on the live site — so a shared button inside a shared nav is drawn where you are editing, and publishing that button updates every open canvas that shows it, however deeply it is nested.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Used by', anchor: '#used-by', text: 'A component\'s detail page has a Used by card listing everything that places an instance of it, so deleting one is not a guess.\nThree places are searched, which is everywhere the renderer expands an instance:\n- the published version of every screen,\n- the published version of every layout,\n- and other reusable components — a component can be placed inside another one, so one used nowhere else can still be very much in use.\nUnpublished drafts and templates in your library are not searched. If the check fails — a dropped connection, say — the card says so and shows a Try again button. It never reports "nothing uses this" when it could not actually look.\nIf a component is deleted while instances remain, those instances are left untouched rather than emptied: a missing definition never takes a published page down.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Manage', anchor: '#manage', text: 'From the site\'s Components page you can rename, edit the description, open the besigner, or delete a reusable component. The component\'s ID is persisted inside every screen that places it and never changes.\nYou can also give a component its own icon, from the same picker the besigner uses for icon elements — either in the Edit component dialog on the Components page, or on the component\'s detail page. Every instance is then marked with it: in the hierarchy, on the canvas badge, and in the element drawer under Your components. A page assembled from promoted sections becomes readable at a glance. Components without an icon keep the generic package glyph.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Copy & paste vs. reusable components', anchor: '#copy--paste-vs-reusable-components', text: '| You want | Use |\n| -- | -- |\n| Another one right here | Duplicate |\n| The same structure somewhere else, edited separately from then on | Copy & paste |\n| One thing that updates everywhere it appears | Reusable component |' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Tips', anchor: '#tips', text: '- Reusable components are perfect for anything that repeats across pages — headers, CTAs, contact blocks.\n- Give a property a default that reads well on its own. A page that sets nothing should still look finished.\n- Detach when you need a one-off variation that shouldn\'t affect the shared source.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Related', anchor: '#related', text: '- Copy & paste elements\n- The Besigner\n- Screens & layouts' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: '', anchor: '', text: 'Inline & rich text editing\nText is edited where it lives. Double-click a heading on the canvas and you are typing into that heading — the real one, at its real size, weight, color and position. Nothing pops open, nothing moves, and the page reflows around you as you type, exactly as visitors will see it.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Edit on the canvas', anchor: '#edit-inline', text: '- Double-click the text. A single click just selects the element.\n- The cursor lands at the end of the existing text — never selected-all, so a stray keystroke cannot wipe a heading you meant to add a word to.\n- Type. The surrounding layout moves in real time: a heading that grows to two lines pushes the paragraph below it down as it happens.\n- The selection outline and its shading step aside while you type, so you are looking at your text on the page rather than at editor chrome. It comes back when you finish.\nA Markdown element is different — double-clicking one opens the full document editor instead. See Long documents in markdown.\nFinishing, and changing your mind {#committing}\n| You press | Plain text element | Rich text element |\n| Enter | Commits the edit | Starts a new line |\n| Shift + Enter | Inserts a line break, keeps editing | Starts a new line |\n| Cmd/Ctrl + Enter | Commits the edit | Commits the edit |\n| Escape | Cancels — everything you typed is discarded | Cancels |\n| Click anywhere else | Commits, and selects whatever you clicked | Commits |\n| Done on the toolbar | Commits | Commits |\nTwo things worth knowing:\n- One edit is one undo step. Undo puts back the previous text, and for formatted text the previous formatting with it.\n- Opening and closing without typing is not an edit. No undo step is recorded and nothing is sent to anyone editing alongside you.\nWhile you are editing text, Cmd/Ctrl + C, V and A act on the text — not on canvas elements.\nThe toolbar {#inline-toolbar}\nA small toolbar floats above the text you are editing: Bold, Italic, Underline, Bulleted list, Numbered list, Insert link, the {} Insert data button, and Done. Insert link asks for the address (https://…).' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Rich text', anchor: '#rich-text', text: 'Rich text is opt-in per element — today that means Typography. Everywhere else, text is plain, which is deliberate: a button label or a link caption has no business carrying paragraphs.\nWhere it is available you can use bold, italic, underline, links, and bulleted or numbered lists. That is the whole list, and it is enforced rather than merely suggested: anything else — styling pasted in from another app, stray attributes, scripts — is stripped when the edit is committed. Links keep their address and nothing else.\nFormatting is not styling Rich text says a word is emphasised; it does not say what emphasis looks like. Color, size, weight and spacing come from your theme and the Styles panel, which is what keeps a site looking like one site. If you find yourself wanting to color a single word, that is the JSS (sx) tab, not this.\nIf you strip all the formatting back out on the canvas, the element quietly becomes a plain-text element again — there is no leftover empty markup to trip over later.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'The Text attribute', anchor: '#the-text-attribute', text: 'The Text field in the right-hand panel and double-clicking on the canvas edit the same value. Use whichever suits: the panel is often quicker for a short label you are setting alongside other attributes.\nWhen the Text field is read-only {#text-field-read-only}\nOnce an element carries formatted text, the Text field goes read-only and says so:\n> This text is formatted — double-click the element on the canvas to edit it. Remove\n> formatting to edit it here.\nThis is not the field being awkward. A plain text box can only show you the words, so anything you typed into it would have to throw the bold, the links and the lists away silently to save. Rather than do that behind your back, the field shows you the text, stays out of the way, and points you at the two things you can actually do.\nRemove formatting {#remove-formatting}\nAbove the field is a small Remove formatting button. It does exactly what it says and nothing more:\n- Kept — every word, and every line break.\n- Lost — bold, italic, underline, links, and list structure.\nThe element goes on saying the same thing in the same shape, and the Text field becomes editable again. It is one undo step, so if you press it by mistake, undo brings the formatting straight back.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Line breaks', anchor: '#line-breaks', text: 'Shift + Enter puts a real line break in plain text; on a rich text element, Enter does. Breaks survive into the Text field, which is a multi-line box that shows them as breaks.\nText wrapping because a container is narrow is not a line break, and correctly does not appear in the Text field — it is a fact about the width, not about the text, and it changes on a phone.\nAn element edited before this shipped Line breaks only started being carried into the Text field recently, and nothing was rewritten retroactively. An older element may show its text in the panel without the breaks until the next time you edit it on the canvas — after which it will look right there too.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Bindings in text', anchor: '#bindings-in-text', text: 'Text props accept bindings — {{variable}}, {{fn:name(args)}}, and dataset fields.\nOn the canvas, a binding normally shows you its resolved value. The moment you start editing, it turns into a single named pill instead. That is on purpose: a binding is one thing, and if it were spelled out as ordinary letters, a backspace in the middle of it would quietly destroy it. As a pill it can only be kept or removed whole — click it to Replace or Remove it, and use {} on the toolbar to insert a new one where the cursor is. The pill label is only ever a display; what gets saved is the {{…}} you wrote.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Where you cannot edit in place', anchor: '#limits', text: '- Elements that do not declare text. In-place editing is offered by the components built for it — Typography, inline text, buttons, screen links, accordion summaries and the email text blocks. Elsewhere, use the attribute panel.\n- Locked elements, such as the layout chrome shown around a screen. Double-click does nothing; edit it in the layout itself.\n- While the interaction builder is choosing a target — there, two clicks are two choices, not an edit.\n- Inside a reusable component instance, you can only edit a piece of text the component exposed as a prop. Text the component owns stays as the component defines it, which is the point of a component. Clearing an override you have set returns that text to the component\'s own copy.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Multi-line elements and the selection outline', anchor: '#wrapped-outlines', text: 'An inline run of text that wraps onto several lines is outlined line by line, with a single name label — the same way a browser highlights text you select with the mouse. It is one element, drawn as the several line boxes it genuinely occupies, rather than one big rectangle that would cover the empty space beside a short last line and the neighboring text beside the first.\nBlocks are unaffected: one element, one box, as before.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Responsive styling & custom CSS\n- Reusable components\n- Long documents in markdown\n- Bindings, variables & functions\n- Live co-editing & unsaved work' },
  { path: '/building-sites/besigner/theme-styles', title: 'Text styles & theme tokens', heading: '', anchor: '', text: 'Text styles & theme tokens\nEvery site has a theme — a named set of type sizes, weights, colours, spacing steps and shadows. The styles panel offers those names wherever one exists, and picking a name is almost always the better answer than typing a number.' },
  { path: '/building-sites/besigner/theme-styles', title: 'Text styles & theme tokens', heading: 'Why a name beats a number', anchor: '#why-a-name-beats-a-number', text: 'Type 13px into Font Size and that element is now pinned to 13 pixels forever. Pick Body compact and the element follows your theme: if the brand later decides small text should be 14px, every element that asked for Body compact moves, and the ones that were told 13px stay behind.\nThe same applies to weight, spacing, corner radius and shadow. Each control that can follow the theme shows you what the name resolves to today — Bold (theme) sits next to 700, Small next to 16px — so you can see the value without hard-coding it.' },
  { path: '/building-sites/besigner/theme-styles', title: 'Text styles & theme tokens', heading: 'Text Style sets everything at once', anchor: '#text-style-sets-everything-at-once', text: 'Text Style is the first control in the Typography group, and it is the one pick that can be right on its own. It applies the whole style — face, size, weight, line height and letter spacing — in a single choice.\nThe fields under it (Font Family, Font Size, Font Weight, and so on) are adjustments on top of a text style, not the way to build one. Reach for them when you need a deliberate exception, not to reconstruct a heading by hand.\nStart with Text Style If you find yourself setting size and weight and line height to match a heading elsewhere on the site, stop — that is a Text Style, and matching it by hand will drift the moment either place changes.' },
  { path: '/building-sites/besigner/theme-styles', title: 'Text styles & theme tokens', heading: 'What your theme offers', anchor: '#what-your-theme-offers', text: 'Aglyn\'s default theme carries the standard set plus a few rungs of its own. Your own theme may differ; the panel always lists what your site defines.\n| Text style | Typical use |\n| Heading 1 – Heading 6 | Page and section headings |\n| Lede | The intro paragraph under a heading |\n| Body / Body small | Running text |\n| Body compact | Dense labels and card text |\n| Caption | Small print under an element |\n| Micro | Metadata lines, fine detail |\n| Overline | The small label above a heading |\n| Button | Button text |\nFont weights are named too — Light, Regular, Medium, Semi bold, Bold, Extra bold and Black — and each row shows the number it resolves to.' },
  { path: '/building-sites/besigner/theme-styles', title: 'Text styles & theme tokens', heading: 'Colours, spacing and shadows', anchor: '#colours-spacing-and-shadows', text: 'The same rule runs through the rest of the panel:\n- Colours — pick from your theme\'s palette rather than pasting a hex code. A palette colour follows a rebrand; #00B0FF does not.\n- Spacing, Gap, Margin and Padding — the ladder (None, Extra small, Small, Medium, Large…) are multiples of your theme\'s spacing unit. Small stays correct if that unit changes.\n- Corner Radius — Square through Very rounded are multiples of your theme\'s shape scale. Pill and Circle are shapes rather than theme values, so those two are deliberately fixed.\n- Shadow — the rungs are your theme\'s elevation ladder, and each row previews the shadow it will draw.\nEvery one of these controls keeps a Custom… entry. The escape hatch is always there when a design genuinely needs a one-off — it is simply not the default.' },
  { path: '/building-sites/besigner/theme-styles', title: 'Text styles & theme tokens', heading: 'Checking a page you already built', anchor: '#checking-a-page-you-already-built', text: 'Open the styles panel on an element and look at the Typography group. If Font Size and Font Weight are filled in on a heading, that heading is describing itself in numbers rather than asking for a Text Style. Clearing those two and picking the matching Text Style leaves it looking the same today and keeps it correct tomorrow.\nChanging the theme itself Editing the theme changes every site that uses it, so it is a separate, deliberate step rather than something you do while styling one page. If a value you need has no name yet, that is a sign the theme is missing a rung — worth adding once, rather than typing the same number on twenty pages.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: '', anchor: '', text: 'Bindings, Variables & Functions\nBindings put live values into your content. Instead of hard-coding text, you reference a variable, a function result, or a dataset field, and Aglyn resolves it when the page renders.\nPlan availability Free to start, with plan caps on the number of variables, functions, and workflows.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Binding tokens', anchor: '#binding-tokens', text: 'Bindings appear inside text props as tokens:\n| Token | Resolves to |\n| {{name}} | A site variable. |\n| {{fn:name(args)}} | The result of a function. |\n| Dataset field bindings | A value from a dataset record. |\nThe Besigner resolves bindings WYSIWYG on the canvas and marks bound content so you can see what\'s dynamic.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Rename-safe id tokens', anchor: '#rename-safe-id-tokens', text: 'Bindings reference variables and functions by id, not by name. That means renaming a variable doesn\'t break anything that uses it. Legacy name-based tokens still resolve via a fallback, and imports are normalized to id form automatically. When you publish, older documents are migrated to id tokens.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Insert a variable', anchor: '#insert-a-variable', text: 'You never have to hand-type token syntax. Every text-capable attribute field in the Besigner (Text, Link URL, Image URL, …) has a small {x} insert button at its end. Click it to open the data picker — a searchable menu grouped by source:\n| Group | Tokens | When it appears |\n| Variables | Your site variables (inserted as rename-safe id tokens) | When the site has variables |\n| Functions | Your functions, with parameter placeholders | When the site has functions |\n| Entry | Collection-entry fields — Title, Excerpt, Link URL, Published date, … | Always (hint shows where they resolve) |\n| Collection | Collection name and slug | Always (resolves on collection pages) |\n| Dataset item | The fields of the repeated dataset, by display name | Only inside a repeating container |\nPicking an option inserts the token at your cursor, keeping the text around it — so you can compose values like Read “{{entry.title}}” → or https://example.com/blog/{{entry.slug}} by mixing typed text and inserted placeholders. Pick again to keep concatenating; the cursor lands right after each inserted token. Each variable option shows a live value preview so you can confirm what the binding resolves to before inserting it.\nSelected text is replaced by the inserted token, and the element-level Insert binding button on text elements opens the same picker (appending to the element text).\nToken pills\nPlaceholders never show up as raw {{...}} syntax while you edit — each one renders as a small colored pill carrying the binding\'s current display name. Variables, functions, entry fields, collection fields, and dataset items each get their own stable color, so a glance tells you what kind of data a pill resolves to. Under the hood the stored value still keeps the rename-safe id token: the pill is pure presentati' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Typed variables', anchor: '#typed-variables', text: 'Create typed site variables and reference them as {{name}} in any prop. Types keep values consistent across the site.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'No-code functions', anchor: '#no-code-functions', text: 'Build functions in the in-editor function builder with a safe evaluator — no arbitrary code execution. Compose variables and other functions, and call them inline with {{fn:name(args)}}.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Where-used & safety', anchor: '#where-used--safety', text: 'Before you rename or delete a variable or function, run the where-used scan to see every screen and prop that references it, so changes are safe.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Workflows', anchor: '#workflows', text: 'Variables and functions compose into workflows — multi-step logic triggered by site events. See Workflows & actions.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Related', anchor: '#related', text: '- Datasets\n- The Besigner' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: '', anchor: '', text: 'Connect a domain\nMove your site from its Aglyn subdomain to a domain you own. It\'s one card, one DNS record, and one button — there\'s no multi-step wizard.\nPlan availability Starter and above. On Free, the card explains: "Custom domains are included from the Starter plan — see Billing to upgrade."' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Steps', anchor: '#steps', text: '1. In the site\'s Admin page, open the Custom Domain tab. The card explains: "Point your domain at Aglyn, then verify. A subdomain like www uses a CNAME. A bare apex cannot carry a CNAME, so point it at the same hostname with an ALIAS — or use the A record if your registrar has no ALIAS. Any one of these verifies", and lists the records with your domain filled in, each with a line saying when it\'s the right one. Type a bare apex and the ALIAS line comes first; type a subdomain and the CNAME line does.\n2. At your registrar\'s DNS settings, add one of those records — see the quick reference below.\n3. Back in Aglyn, type your domain into the Domain field and press Verify & connect. Aglyn checks DNS from public resolvers and, if the record checks out, connects the domain in the same click.\n4. On success the card confirms "your-domain.com" connected and shows the domain as a green chip. An apex — connected by ALIAS or by A record, since both are checked the same way — gets an extra note: "Apex verified by the addresses it resolves to."\nIf DNS hasn\'t propagated yet, Verify & connect tells you what it found instead — either the record it saw and what it expected, or that no record exists yet — and asks you to try again in a while. Nothing is saved on a failed verify, so re-running it is always safe.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'After it connects', anchor: '#after-it-connects', text: 'The chip next to your domain says what it is actually doing. SSL provisions automatically — there is nothing to upload or renew — but it takes a few minutes, and the chip is how you tell "still working on it" from "stuck".\n| Chip | What it means | What to do |\n| your-domain.com — live | Attached, DNS resolves here, certificate issued. | Nothing. |\n| your-domain.com — issuing certificate | Everything checks out; the certificate is still being issued. | Wait a few minutes and press Check status. Until it finishes the domain may show a security warning. |\n| your-domain.com — ownership check needed | Your domain is registered to another account on our hosting platform, so it has to be proven yours first. | Add the TXT record the card prints, then press Re-attach. |\n| your-domain.com — DNS not pointing here | Attached, but the domain no longer resolves to us. | Check the record at your registrar — see troubleshooting. |\n| your-domain.com — not attached | Saved here, but not attached to the serving platform, so it serves nothing. | Press Retry attachment. If it keeps failing the domain is likely held by another account — contact support with the domain name. |\n| your-domain.com — attachment pending | Our attach call never landed, and the platform could not be asked just now. | Press Retry attachment. |\nThree buttons sit next to the chip:\n- Check status re-reads the live state. A certificate arrives on its own a few minutes later, and this is how you see that it has.\n- Retry attachment (labeled Re-attach once the domain is healthy) re-runs the platform attachment. Always safe to press.\n- Disconnect releases the domain — see below.\nIf other DNS records are answering for the same name, the card says so and names them, even when the domain is live. That is worth acting on: a left' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Your Aglyn subdomain afterwards', anchor: '#your-aglyn-subdomain-afterwards', text: 'Once the domain is connected and serving, your-site.aglyn.app redirects to it — same page, same path, so an old link to your-site.aglyn.app/pricing lands on https://your-domain.com/pricing.\nThat is deliberate. Serving the same pages at two addresses splits your search ranking between them, and lets a search engine pick which one to show. One address keeps the credit on the domain you own.\nDisconnect the domain and the Aglyn subdomain starts serving again on its own, within a minute or so. The redirect is temporary by design so that reversal always works.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Registrar quick reference', anchor: '#registrar-quick-reference', text: 'The exact screen differs by registrar, but you only ever add one record:\nA subdomain (www.example.com, shop.example.com, …):\n| Field | Value |\n| Type | CNAME |\n| Name / Host | www (or the subdomain you\'re connecting) |\n| Value / Target | sites.aglyn.app |\n| TTL | default is fine |\nA bare apex (example.com) — first choice:\n| Field | Value |\n| Type | ALIAS (also called ANAME, or "CNAME flattening") |\n| Name / Host | @ |\n| Value / Target | sites.aglyn.app |\n| TTL | default is fine |\nA bare apex, if your registrar has no ALIAS — fallback:\n| Field | Value |\n| Type | A |\n| Name / Host | @ |\n| Value | 216.198.79.1 |\n| TTL | default is fine |\nAn apex can\'t carry a CNAME (that\'s a DNS rule, not an Aglyn one), which is why it needs one of these two instead. Prefer the ALIAS: it names sites.aglyn.app rather than an address, so your registrar resolves it to wherever Aglyn is serving from at the time, and nothing in your zone has to change if those addresses ever do.\nThe A record is there because plenty of registrars offer no ALIAS/ANAME and no flattening — for those, it is the only way to point an apex, and it verifies exactly the same. Its one cost is that the address is pinned in your zone by hand: keep it in mind if you ever see the domain stop resolving long after it was working.\nCloudflare and other proxies CNAME flattening at the apex works, but leave the record DNS only (grey cloud) until verification succeeds — a proxied record resolves to the proxy\'s addresses, not Aglyn\'s.\nWant both www and the apex? Aglyn serves one connected domain per site. Connect the one you want as your canonical address, then have your registrar redirect the other to it — most registrars offer domain forwarding for exactly this.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'One domain per site', anchor: '#one-domain-per-site', text: 'Each site carries a single custom domain, and a domain can only be connected to one site across all of Aglyn — connecting it elsewhere answers "That domain is already connected to another site". Disconnect it from the old site first.\nSome names cannot be connected at all, and the wizard answers "That domain is reserved by the platform and cannot be connected to a site". These are Aglyn\'s own hostnames — anything ending in aglyn.com, aglyn.app or aglyn.io, including another site\'s your-site.aglyn.app address — and names on shared app-hosting suffixes such as vercel.app, pages.dev or github.io, which nobody can prove they own. Retrying will not help; connect a domain registered to you instead.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Disconnect', anchor: '#disconnect', text: 'Disconnect, next to the connected domain\'s chip, releases the domain immediately — there is no confirmation step — and the Aglyn subdomain resumes serving within a minute or so. Disconnecting requires the site admin role.\nAglyn never touches your DNS: the CNAME, ALIAS, or A record at your registrar is yours, so remember to remove or repoint it yourself after disconnecting.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Related', anchor: '#related', text: '- Troubleshoot verification\n- Redirects\n- SEO toolkit' },
  { path: '/building-sites/custom-domains/overview', title: 'Custom Domains', heading: '', anchor: '', text: 'Custom Domains\nEvery site starts on an Aglyn subdomain. When you\'re ready, connect your own domain — a subdomain like www.example.com or the bare apex example.com — self-serve, from the site\'s Admin page.\nPlan availability Starter and above.' },
  { path: '/building-sites/custom-domains/overview', title: 'Custom Domains', heading: 'Connect a domain', anchor: '#connect-a-domain', text: '1. In Admin, open the Custom Domain tab.\n2. Add one DNS record at your registrar — a CNAME to sites.aglyn.app for a subdomain, or an ALIAS/ANAME to the same hostname for a bare apex (an A record where your registrar offers no ALIAS).\n3. Type the domain into the Domain field and press Verify & connect. Aglyn checks DNS and connects the domain in the same click; SSL provisions automatically.\nEach site carries one custom domain, shown as a chip on the card with Re-attach and Disconnect actions beside it. Once it serves, your .aglyn.app subdomain redirects to it, path preserved, so old links keep working.\nHow-tos\n- Connect a domain — steps, apex records (ALIAS first, A as the fallback), and what happens after\n- Troubleshoot verification' },
  { path: '/building-sites/custom-domains/overview', title: 'Custom Domains', heading: 'Related', anchor: '#related', text: '- Getting started: create a site\n- SEO toolkit' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: '', anchor: '', text: 'Troubleshoot verification\nIf Verify & connect won\'t go green, it\'s almost always DNS. Work through these.\nPlan availability Starter and above.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Checklist', anchor: '#checklist', text: '1. Give it time. DNS changes propagate on a TTL — wait a few minutes and press Verify & connect again. Aglyn resolves your record through public DNS resolvers, so a change your registrar shows as saved can still take a while to be visible.\n2. Read the message. A failed verify tells you what it found: either the record it saw and the target it expected, or that no record exists yet. That\'s usually the whole diagnosis.\n3. Match the record to the name.\n- A subdomain (www.example.com) needs a CNAME to sites.aglyn.app.\n- A bare apex (example.com) needs an ALIAS/ANAME to sites.aglyn.app — an apex cannot carry a CNAME, and Aglyn verifies it by the addresses it resolves to.\n- If your registrar offers no ALIAS/ANAME, use an A record to 216.198.79.1 instead. It verifies the same way. If an apex that used to work has stopped resolving, check this address is still the one in your zone — an ALIAS never needs that check, which is why it\'s the first choice.\n4. Remove conflicting records. Delete any old A/AAAA/CNAME records for the same host that point elsewhere. Two cases bite hardest:\n- An apex with a wrong CNAME (some DNS hosts allow one) never falls through to the A-record check — remove the CNAME so the A record can be evaluated.\n- A stale A record left over from a previous host answers alongside your ALIAS and wins unpredictably — delete the old A record outright.\n5. Disable proxying temporarily. If your DNS provider proxies traffic (e.g. an orange-cloud toggle), the record resolves to the proxy\'s addresses instead of Aglyn\'s. Turn it off until verification succeeds.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Verified but not serving?', anchor: '#verified-but-not-serving', text: 'Verification and attachment are separate steps under one button, and the chip next to your domain says which one you are waiting on — see the chip table for all of them. The three that come up most:\n- "— issuing certificate" is not a problem. DNS is right and the domain is attached; the certificate takes a few minutes. Press Check status rather than reconnecting. A security warning in the browser during this window is expected and goes away on its own.\n- "— ownership check needed" means your domain is registered to another account on our hosting platform. The card prints a TXT record — add it at your registrar exactly as shown, then press Re-attach. Nothing else will release the domain.\n- "— not attached" means the domain is saved on your site but not on the serving platform. Press Retry attachment. If it keeps returning, the domain is held somewhere else and support needs the domain name to release it.\nIf connecting answers "That domain is already connected to another site", the domain is attached to a different Aglyn site — every domain can serve only one. Disconnect it there first.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'The site loads for some people and not others', anchor: '#the-site-loads-for-some-people-and-not-others', text: 'That is almost always two records answering for the same name — typically an A record left behind by a previous host sitting next to a correct ALIAS. DNS hands out one or the other, so it looks fine every time you try it.\nAglyn names the offending records: Verify & connect warns about addresses that are not ours, and the card keeps showing them under the chip afterwards, even while the domain is live. Delete them at your registrar; nothing needs reconnecting once they are gone.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Still stuck?', anchor: '#still-stuck', text: 'Confirm the record resolves from your machine (dig www.example.com CNAME or dig example.com A), then press Verify & connect again.\nTwo different checks run, and it helps to know which one you are reading. Verify & connect is the one that decides whether a domain may be connected at all, and it runs only when you press it. Check status asks the serving platform what the domain is doing right now — including whether DNS still points here — so a record you changed after connecting shows up there rather than needing a disconnect and reconnect.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Related', anchor: '#related', text: '- Connect a domain' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: '', anchor: '', text: 'Menus & navigation\nReal navigation needs more than a row of links. The Navigation group in the element picker ships menu elements with the interactivity built in — no code, no raw JSON:\n| Element | What it does |\n| Dropdown Menu | A nav item that opens a dropdown of links — click-toggles out of the box, interactions do the rest. |\n| Mega Menu | A SaaS-style wide panel with a free-form slot for columns of links and promos. |\n| Drawer | A slide-in panel (left or right) with a slot for anything — the mobile menu building block. |\n| Menu Button | A hamburger icon button that opens/closes a drawer. |\n| Mobile Nav | A one-insert preset: menu button + drawer + inline desktop links, responsive wiring included. |\n| Dropdown Panel | A primitive-built hover panel — Stack + Button + hidden panel with the hover interactions pre-wired and editable. |\nAll of them render closed on the live site until the visitor interacts, and the canvas mirrors that: menus show just their trigger and drawers a slim placeholder. Select the element — or anything inside it — and it expands in place so its contents stay selectable and editable; click elsewhere and it collapses again.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Dropdown menu', anchor: '#dropdown-menu', text: 'Insert Dropdown Menu, set its Label, and drop screen links (or anything else) inside. Its only attribute is Label — how the menu opens is not an attribute:\n- By default, clicking the nav item toggles the menu. No configuration needed; the menu also closes on outside clicks and Esc .\n- Everything else is an interaction — e.g. When hovered → Open a menu on the menu element itself gives you a hover menu, and any other element can open, close, or toggle any menu.\nMenus opened by a hover interaction close themselves once the pointer leaves the nav item and its panel, with a short grace period so the pointer can travel between the two.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Mega menu', anchor: '#mega-menu', text: 'Insert Mega Menu inside your nav bar. Its panel is a normal canvas slot — the preset starts you with three columns of links, but rows, images, and promo cards all work. Attributes:\n- Panel width — Fit content, Wide (720px), or Full width (edge-to-edge under the nav item).\nIt opens exactly like the dropdown: click-toggle by default, and the classic SaaS hover behavior is one interaction — on the mega menu element, When hovered → Open a menu (the target defaults to the element itself). Hover-opened panels close on pointer leave automatically.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Drawer & menu button', anchor: '#drawer--menu-button', text: 'The Drawer slides in from the page edge and holds any canvas children — typically a vertical stack of screen links. It opens three ways:\n1. A Menu Button element. Clicking it toggles the page\'s first drawer — no configuration at all (which is why the Mobile Nav preset works with zero wiring). Its only attribute is Accessibility label; how it targets a drawer is not an attribute.\n2. An interaction with the Open / Close / Open-close a drawer actions (below) — on the Menu Button itself when a page has several drawers and you need to point it at a specific one, or on any other element.\n3. The built-in close button, backdrop click, or Esc — closing is always handled for you.\nDrawer attributes: Slides in from (left/right) and Width. The canvas renders the drawer inline at its configured width, so its links and headers stay full-size and editable.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'The Mobile Nav preset', anchor: '#the-mobile-nav-preset', text: 'Insert Mobile Nav (Navigation group) into your nav bar\'s toolbar and you get a working responsive pattern immediately:\n- a Menu Button — hidden on desktop,\n- an inline link row — hidden on mobile and tablet,\n- a Drawer with a vertical link stack, already answering the button.\nSwap the placeholder links for your screens and you\'re done. The show/hide wiring is plain visibility styling, so you can retune the breakpoints per element afterwards.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'The Dropdown Panel preset', anchor: '#the-dropdown-panel-preset', text: 'The menu elements above are purpose-built components. Dropdown Panel is the same result assembled from primitives — insert it and you get:\n- a wrapper Stack (position: relative) holding\n- a trigger Button, and\n- a panel Stack positioned under the trigger, three link columns inside, already set to Hide on published site so it starts closed on the live site (the canvas starts it closed too — open it with the eye on its hierarchy row when you want to design it).\nThe difference from hand-building: the hover choreography arrives pre-wired. Inserting the preset creates two real interactions on the wrapper, enabled immediately and listed on its Interactions panel like any you\'d author yourself:\n1. When hovered → Show the panel, with Close on Esc and Close on outside click.\n2. When hover ends → Hide the panel with a 250ms delay, so the pointer can travel from trigger to panel.\nBecause they\'re ordinary interactions and ordinary elements, everything is editable: restyle the panel, change the delay, swap the trigger for an icon button, or delete one interaction and wire your own. Use it when you want full styling control that the Mega Menu\'s panel attributes don\'t reach — and see the walkthrough\'s from-scratch recipe for the same pattern built by hand.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Interactions for menus', anchor: '#interactions-for-menus', text: 'The props panel\'s Add interaction system understands menu choreography (interactions guide):\n- Triggers: When clicked…, When hovered…, When hover ends…, When scrolled into view…\n- Actions: Show / Hide / Show-hide an element (pick the target from a list of canvas elements), Open / Close / Open-close a menu (drives a Dropdown or Mega Menu; picking defaults to the element itself when it is a menu, or the page\'s first menu), and Open / Close / Open-close a drawer (defaults to the element itself when it is a drawer, or the page\'s first drawer).\n- Frequency: new interactions default to Every time so toggles keep working; the legacy once per page view and the per-session / per-visitor / cooldown caps are still there for announcements.\nThree patterns cover most menus:\n- Hover menu — on the Dropdown/Mega Menu element itself: When hovered → Open a menu. Leaving the nav item and its panel closes it automatically — no hover-ends interaction needed.\n- Custom hover reveal — on the trigger element: When hovered → Show an element (your panel), plus a second interaction When hover ends → Hide an element.\n- Custom hamburger — on any button or icon: When clicked → Open/close a drawer (or a menu).\nStart hidden To make a show-target start hidden, open its ⋮ menu — on its Hierarchy row or on the canvas — and choose Start hidden until an interaction shows it. The live site hides it from the very first paint, and so does the canvas, so you are designing what a visitor sees.\nSelecting the element, or anything alongside it inside its container, opens it on the canvas for as long as it is selected, so you can work on it. That is a canvas-only preview: it is never saved and never changes what the published site does.\nUnder the hood this is the aglyn-hidden class, which you will see on the element\'' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Responsive visibility', anchor: '#responsive-visibility', text: 'Styles → Visibility hides the selected element on whole device bands:\n- Hide on mobile (under 600px)\n- Hide on tablet (600–899px)\n- Hide on desktop (900px and up)\nUse it to hide the desktop link cluster on small screens and show a menu button instead. Bands are range-scoped, so hiding one never changes how the element displays on the others.\nCanvas preview Pick a device in the artboard preview switcher and the canvas renders at that width — bands apply, the Mobile Nav swaps to its menu button, and breakpoint-scoped styles resolve for that device. In Fluid Responsive mode the canvas follows the real browser window instead. See responsive styling for how breakpoint-scoped styles behave on the canvas.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Related', anchor: '#related', text: '- Walkthrough: build a mega menu with hover interactions\n- Interactions & custom HTML\n- Responsive styling & custom CSS\n- Screens & layouts' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: '', anchor: '', text: 'Add a locale\nPublish your site in another language by adding a locale variant.\nPlan availability Paid. This is multilingual v1.' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: 'Steps', anchor: '#steps', text: '1. Add a locale (e.g. es, fr) to your site.\n2. Aglyn creates locale variants of your content, sharing the same structure as your default language.\n3. Translate the screens\' text for that locale.\n4. Publish. Aglyn emits hreflang tags so search engines serve the right language to each visitor.' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: 'Tips', anchor: '#tips', text: '- Keep structure identical across locales — translate the words, not the layout.\n- Add a language switcher so visitors can choose their language.' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: 'Related', anchor: '#related', text: '- Language switcher\n- SEO toolkit' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: '', anchor: '', text: 'Add a language switcher\nOnce you\'ve added a locale, give visitors a language switcher so they can pick their language.\nPlan availability Paid.' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: 'Steps', anchor: '#steps', text: '1. Add the language switcher to a screen or your shared layout (so it appears site-wide).\n2. It lists your active locales and links each visitor to the matching variant of the current page.\n3. Publish.' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: 'Tips', anchor: '#tips', text: '- Put the switcher in your layout header/footer so it\'s available on every page.\n- Pair it with hreflang (emitted automatically) so both people and search engines land on the right language.' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: 'Related', anchor: '#related', text: '- Add a locale' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: '', anchor: '', text: 'Multilingual\nReach a wider audience by publishing your site in more than one language.\nPlan availability Paid. Multilingual is available on paid tiers.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'Locale variants', anchor: '#locale-variants', text: 'Create locale variants of your content so each language has its own version, while sharing the same structure.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'hreflang & discovery', anchor: '#hreflang--discovery', text: 'Aglyn emits hreflang tags so search engines serve the right language to the right visitor.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'Language switcher', anchor: '#language-switcher', text: 'Add a language switcher so visitors can move between locales themselves.\nHow-tos\n- Add a locale\n- Add a language switcher\nThis is multilingual v1.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'Related', anchor: '#related', text: '- SEO toolkit\n- Screens & layouts' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: '', anchor: '', text: 'Create a redirect\nSend an old or alternate URL to the right screen.\nPlan availability Paid.' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: 'Add a rule', anchor: '#add-a-rule', text: '1. Open the redirect manager page.\n2. Enter the source path (the URL to redirect) and the destination.\n3. Save. The rule is validated on save, with chain-loop and screen-collision checks so it can\'t loop or shadow a real screen.\nThe published site enforces redirect rules during route resolution, so the redirect takes effect on the live site immediately.' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: 'Read hit metrics', anchor: '#read-hit-metrics', text: 'Each rule tracks sampled hit metrics. Use them to:\n- Confirm a redirect is actually being used.\n- Find rules with zero hits that you can safely delete.' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: 'Related', anchor: '#related', text: '- Migration patterns\n- Redirects overview' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: '', anchor: '', text: 'Migration patterns\nRedirects earn their keep during change. Here are the patterns you\'ll reach for most.\nPlan availability Paid.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Renamed a screen', anchor: '#renamed-a-screen', text: 'When you change a screen\'s slug, add a redirect from the old path to the new one so existing links and search results keep working.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Consolidated pages', anchor: '#consolidated-pages', text: 'Merging two pages into one? Redirect the retired path to the survivor. The screen-collision check keeps you from redirecting a path that\'s still a live screen.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Moved a site into Aglyn', anchor: '#moved-a-site-into-aglyn', text: 'Recreate your highest-traffic old URLs as redirects to their new Aglyn screens. Use the hit metrics to spot old URLs you missed — if a rule is getting traffic, people still rely on it.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Avoiding loops', anchor: '#avoiding-loops', text: 'The chain-loop check blocks redirects that would send visitors in circles (A→B→A). If a save is rejected, look for an existing rule that already redirects your destination.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Related', anchor: '#related', text: '- Create a redirect\n- Screens & layouts' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: '', anchor: '', text: 'Redirects\nThe redirect manager sends old or alternate URLs to the right place — essential when you rename screens or migrate a site.\nPlan availability Paid. The redirect manager is a paid feature.' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Manage redirects', anchor: '#manage-redirects', text: '- Create, edit, and delete redirect rules from the redirect manager page.\n- Rules are validated on save, with chain-loop and screen-collision checks so a redirect can\'t send visitors in circles or shadow a real screen.\n- The published site enforces redirect rules during route resolution.\nWho can manage redirects A redirect changes what the live site serves at an address, so it takes a publishing role — Editor or Admin. The Author role can see the redirects page but cannot add, change or remove a rule. See Teams & roles.' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Sending visitors to another site', anchor: '#sending-visitors-to-another-site', text: 'A destination can be an internal path (/pricing) or an absolute https:// URL — useful for vanity domains and campaign links.\nBecause an off-site destination sends your visitors somewhere you don\'t control, the published site only follows one after a publishing role has saved the rule. A rule with an external destination that nobody has confirmed shows a not serving badge on the redirects page and is skipped until an Editor or Admin opens it and saves. Internal destinations are never affected.' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Metrics', anchor: '#metrics', text: 'Each rule tracks hit metrics (sampled), so you can see which redirects are actually used and prune the ones that aren\'t.' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Match modes (v2)', anchor: '#match-modes-v2', text: 'Rules match one of three ways:\n- Exact path — the original mode; /old-page only.\n- Path prefix — /blog catches /blog and everything under it (/blog/post-1), but not /blogging.\n- Regular expression — anchored to the whole path, with capture groups substituted into the destination: pattern /product/(\\d+) and destination /products/item-$1 sends /product/42 to /products/item-42. Invalid patterns are rejected at save and can never take the site down.\nWhen several rules match, the lowest priority number fires first. Use the inline tester at the bottom of the redirects card to paste a path and see exactly which rule (if any) catches it — it runs the same matcher the live site uses.\nHow-tos\n- Create a redirect\n- Migration patterns' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Related', anchor: '#related', text: '- Screens & layouts\n- Site protection & error pages' },
  { path: '/building-sites/screens-and-layouts/layouts', title: 'Layouts', heading: '', anchor: '', text: 'Layouts\nA layout is the shared frame a screen renders inside. It is not a page of its own and never has a URL: it has a slot, and whatever screen you bind to it renders in that slot. For the pages themselves, see Screens.\nPlan availability Free. Every plan can create layouts and nest them.' },
  { path: '/building-sites/screens-and-layouts/layouts', title: 'Layouts', heading: 'What a layout is', anchor: '#what-a-layout-is', text: 'A layout holds the furniture many screens have in common — header, navigation, footer, a cookie banner, a site-wide search box. Bind a screen to a layout in the Besigner and the layout chrome wraps the screen both in the editor and on the published site.\nBecause the chrome lives in one document, changing it changes every screen bound to it at once. That is the point, and it is also the thing to keep in mind before you publish: see Versions & scheduled publishing.' },
  { path: '/building-sites/screens-and-layouts/layouts', title: 'Layouts', heading: 'Nested layouts', anchor: '#nested-layouts', text: 'A layout can render inside another layout. Set Renders inside on a layout\'s detail page and its chrome is wrapped by the outer layout\'s, exactly as a screen is wrapped by its own — so site-wide furniture can live in one place while a section keeps a more specific frame around it.\nA screen inherits the whole chain: bind it to the inner layout and it renders inside that, which renders inside the outer one, up to five layouts deep.\nA layout can never sit inside itself, or inside a layout already nested within it — that would be a loop with no outermost frame to render. The picker only offers layouts that are legal choices, so you cannot select one by mistake.' },
  { path: '/building-sites/screens-and-layouts/layouts', title: 'Layouts', heading: 'Used by', anchor: '#used-by', text: 'A layout\'s detail page has a Used by card listing everything that renders inside it, so you can see what a change or a deletion would reach:\n- screens bound to it, published or not, and\n- layouts nested inside it — deleting the outer one unwraps every screen underneath those too.\nA layout used by neither is genuinely unused.' },
  { path: '/building-sites/screens-and-layouts/layouts', title: 'Layouts', heading: 'Layouts vs. reusable components', anchor: '#layouts-vs-reusable-components', text: 'Both let you build something once and use it in many places, and they are not interchangeable:\n| | Layout | Reusable component |\n| What it is | A frame with a slot | A subtree you insert as an instance |\n| How a screen uses it | Binds to it; the layout wraps the screen | Inserts one or more instances anywhere in its own tree |\n| How many per screen | One chain, outermost first | As many instances as you like |\n| Good for | Header, nav, footer, site chrome | A card, a call-to-action, a pricing block |\nIf the thing wraps your content, it is a layout. If the thing is content you want to repeat, it is a reusable component.' },
  { path: '/building-sites/screens-and-layouts/layouts', title: 'Layouts', heading: 'Related', anchor: '#related', text: '- Screens\n- Versions & scheduled publishing\n- Reusable components\n- Menus & navigation' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: '', anchor: '', text: 'Screens & Layouts\nScreens are your pages. Layouts are the shared frames those pages render inside. Reusable components are the repeatable pieces you drop into either. Templates are saved starting points you can build from. Each one has its own page — start with the question you have.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Which one do you want?', anchor: '#which-one-do-you-want', text: '| You want to… | Go to |\n| Add a page, change its URL, or check your screen allowance | Screens |\n| Put a header, nav or footer around many pages at once | Layouts |\n| Build a card or block once and repeat it | Reusable components |\n| Start from a saved page, layout or whole site | Your templates library |\n| Publish, roll back, or schedule a version | Versions & scheduled publishing |\nPlan availability Free for core screens and layouts. Higher tiers raise caps on screens, versions, and reusable components.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Bindings & variables\n- Site protection & error pages\n- SEO toolkit' },
  { path: '/building-sites/screens-and-layouts/screens', title: 'Screens', heading: '', anchor: '', text: 'Screens\nA screen is a page of your site. It has a title, a URL slug, and a place in a hierarchy that decides the address visitors reach it at.\nThe screen hierarchy maps directly to your URL paths:\nPlan availability Free for core screens. Higher tiers raise the cap on how many screens a site can publish.' },
  { path: '/building-sites/screens-and-layouts/screens', title: 'Screens', heading: 'Screens & routing', anchor: '#screens--routing', text: '- Each screen has a title and a URL slug. Aglyn normalizes slugs and keeps a site routing map.\n- Screens form a hierarchy: pick a parent and the child inherits a nested path (/services/pricing). Changing a slug or parent cascades safe rewrites across the map, with cycle guards so you can\'t create a loop.\n- Reorder the hierarchy with drag-and-drop in the screens list.\n- The screens list shows each screen\'s Published date, and the screen\'s detail page shows Date published. Both stay empty until the screen goes live, and clear again if you unpublish it (including a scheduled unpublish) — so the column tells you what\'s live, not what exists.' },
  { path: '/building-sites/screens-and-layouts/screens', title: 'Screens', heading: 'What counts against your screen allowance', anchor: '#what-counts-against-your-screen-allowance', text: 'Your plan\'s screen limit counts the screens that are pages of your site — the ones a visitor can reach at an address of their own. Some screens you design are not pages, and those don\'t count:\n| Screen | Counts? | Why |\n| A page you publish at a slug | Yes | It has a URL of its own. |\n| A collection\'s list template | Yes | /{collection} renders that exact screen. |\n| A collection\'s entry template | No | One screen composes every entry; it has no address of its own. |\n| An error screen you\'ve assigned | No | It renders on addresses that matched nothing. |\n| An email you design | No | It\'s sent, never served at a URL. |\n| A screen you\'ve deleted | No | Deleting frees the slot straight away. |\nThe rule behind the table is one question: does the screen occupy a URL of its own? So an error screen that is also still published at its own address — say a 404 screen you published at /404 while designing it — is a page, and it counts until you remove that address. The Error pages card tells you when that\'s the case and offers the one-click Remove address; the screen carries on rendering for its status code afterwards.' },
  { path: '/building-sites/screens-and-layouts/screens', title: 'Screens', heading: 'Error & maintenance screens', anchor: '#error--maintenance-screens', text: 'You can design custom 404 / 401 / 403 / 503 screens and turn on maintenance mode. See Site protection & error pages.' },
  { path: '/building-sites/screens-and-layouts/screens', title: 'Screens', heading: 'Related', anchor: '#related', text: '- Layouts — the shared frame a screen renders inside\n- Versions & scheduled publishing\n- The Besigner\n- Bindings & variables\n- SEO toolkit' },
  { path: '/building-sites/screens-and-layouts/versions-and-publishing', title: 'Versions & scheduled publishing', heading: '', anchor: '', text: 'Versions & scheduled publishing\nScreens, layouts, and reusable components all keep versions. A version is a named snapshot of the saved document; exactly one version of each is published — the one your visitors get.' },
  { path: '/building-sites/screens-and-layouts/versions-and-publishing', title: 'Versions & scheduled publishing', heading: 'The versions dialog', anchor: '#the-versions-dialog', text: 'Open the version name in the Besigner\'s app bar to see the Versions dialog, with each version\'s created/updated times and a Published chip on the live one.\n- New version saves a named snapshot of the current saved document (prefilled "Copy of …" — rename it to something meaningful).\n- Open switches the Besigner to that version. Viewing an old version never publishes it.\n- Delete versions you no longer need — the published version can\'t be deleted, and the one you have open must be closed first.' },
  { path: '/building-sites/screens-and-layouts/versions-and-publishing', title: 'Versions & scheduled publishing', heading: 'Publish & roll back', anchor: '#publish--roll-back', text: 'Publish on any row makes that version the live one — which is also how you roll back: publishing an older version moves the live pointer, destroys nothing, and is symmetrical, so rolling forward again is the same click.\nA save is not a publish. Saving updates the version you have open; publishing is what changes the live site. Publishing a layout version reaches every screen bound to that layout, so check its Used by card first — see Layouts.' },
  { path: '/building-sites/screens-and-layouts/versions-and-publishing', title: 'Versions & scheduled publishing', heading: 'Scheduled publishing', anchor: '#scheduled-publishing', text: 'Schedule publishes a version automatically at a chosen future time; the row then shows a "Publishes …" chip you can clear to cancel.\nIf a scheduled publish comes due on a plan that no longer includes scheduling — after a downgrade, say — it is skipped and shown as skipped on the screen\'s page, never silently dropped, so you can dismiss it or upgrade and reschedule.' },
  { path: '/building-sites/screens-and-layouts/versions-and-publishing', title: 'Versions & scheduled publishing', heading: 'Plan requirements', anchor: '#plan-requirements', text: 'Gating is enforced where you click:\n- Creating versions requires Pro or above — on a lower tier the editor answers "Versioning requires a Pro plan — see Billing to upgrade" instead of opening the name dialog.\n- Scheduled publishing requires Business or above.\n- A version is snapshotted from the saved document, so the editor asks you to save the canvas first rather than silently capturing (or losing) unsaved edits.' },
  { path: '/building-sites/screens-and-layouts/versions-and-publishing', title: 'Versions & scheduled publishing', heading: 'Related', anchor: '#related', text: '- Screens\n- Layouts\n- Reusable components\n- Live co-editing' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: '', anchor: '', text: 'SEO Toolkit\nThe SEO toolkit helps your pages rank and share well. Set metadata per screen, and Aglyn emits the right tags, sitemap, and structured data automatically.\nPlan availability Free for core SEO fields; richer structured data ships for published sites.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Per-screen SEO', anchor: '#per-screen-seo', text: 'Every screen\'s detail page has an SEO card with three fields:\n- Search title — up to 60 characters, published exactly as you type it.\n- Search description — up to 155 characters, the meta description.\n- Social image — the picture shown when the page is shared. Press Choose image to pick one from your media library (or the organization\'s shared library); Clear puts the site default back.\nFill them in and press Save SEO — it saves independently of the canvas, so you can update metadata without touching the design. The published site emits these into the page head, deduping descriptions so you never get conflicting tags.\nThe social image is a media pick, not a URL you type. That is deliberate: a picked asset is stored by identity, so moving it into a folder or replacing it with a new version keeps every card that references it working.\nAnything you leave blank falls back sensibly: the description falls back to the screen\'s own description and then the site\'s, and the social image to the site-wide one.\nHow a page title is built\nA search title you write is the whole title — nothing is appended to it. That is what lets you keep every page inside the 60 characters a search result shows, and say the brand once rather than twice.\nA page with no search title of its own is titled from its name — the screen\'s display name, a blog post\'s headline, a collection\'s name — joined to the site Title with your Separator:\n| Page | Rendered title |\n| Search title About Aglyn — one platform for the open web | About Aglyn — one platform for the open web |\n| Screen named Contact, no search title | Contact – Acme Widgets |\n| Neither | Acme Widgets |\nYour brand still travels with every share regardless: the site title is published as og:sitename on every page.\nSite-wide defaults\nSetup → SEO holds' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Search engine visibility', anchor: '#search-engine-visibility', text: 'You decide what search engines are allowed to index, at two levels.\nThe whole site\nSetup → SEO → Search engines has a Discourage search engines from indexing this site switch. Turn it on while you stage a launch — the site stays live and anyone with a link can still reach it, but:\n- robots.txt refuses every crawler (Disallow: /) and names no sitemap\n- sitemap.xml is served empty (valid but with no URLs, so search consoles read "nothing here" rather than an error they retry)\n- every page carries a noindex robots meta tag — links are still followed, but the page is not listed\nWhile it is on, a warning banner follows you through the console on every page of that site. That is deliberate — a site missing from Google weeks after launch is almost always this switch, left on and forgotten.\nTurning it off restores everything within about a minute. Search engines take longer: re-indexing a site is their schedule, not yours, so allow days.\nrobots.txt and noindex answer different questions. Disallow asks a crawler not to fetch a page; noindex asks it not to list one. Aglyn sends both, because a page linked from somewhere else can be listed without ever being fetched — and a crawler that obeys the disallow never sees the noindex that would have stopped it.\nA single page\nUse the page\'s own Visibility, in Page Access on the screen\'s detail page. Only Public pages are offered to search engines. Unlisted, Password protected and Members only pages are all kept out of search results and out of the sitemap, while staying reachable to whoever has the link or the credentials.\nUse the site-wide switch while nothing is ready, and per-screen Unlisted once you\'re launching page by page — the switch also covers pages you haven\'t created yet, which per-screen visibility cannot.\nnoindex is a reque' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Sitemap & robots', anchor: '#sitemap--robots', text: 'Aglyn generates sitemap.xml and robots.txt for your site automatically, so search engines can crawl your site correctly. The sitemap always names your site by its real address (your custom domain when you have one), and includes:\n- every published screen whose visibility is Public — template screens (blog list/ entry templates, product page templates) are excluded, since their real URLs are the entries and products they render;\n- your product and catalog collection URLs, once a product-page or collection-page template is set;\n- your content collections — each collection\'s list URL and its published entries. A scheduled entry joins the sitemap once its publish time passes.\nThe sitemap is cached for a few minutes, and every publish refreshes it immediately — so a freshly published page never waits on the cache.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Social cards', anchor: '#social-cards', text: 'Every published page emits Open Graph and Twitter metadata: title, description, canonical URL, site name, and — once an image is set — og:image with its og:image:width and og:image:height.\nWhich image a page uses is decided in this order:\n1. the entry\'s cover image, for a blog or collection entry;\n2. the screen\'s own social image, from its SEO panel;\n3. the site default, from Setup → SEO;\n4. nothing.\nThe first three make the page share as a large card (twitter:card: summarylargeimage). Only the fourth falls back to the small image-less summary card, which is why setting a site default is worth doing once.\nSize. 1200×630 is the size every network crops well. Aglyn reads the real dimensions off the media record and publishes them, so previews reserve the right shape before the image finishes loading — it does not assume a size, so a different ratio is described honestly rather than stretched.\nAddresses. Card images are always published as absolute URLs on your site\'s own domain (your custom domain when you have one). A crawler fetches the image without a page to resolve a relative path against, so a relative address is a blank card.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Structured data', anchor: '#structured-data', text: 'Published sites emit JSON-LD for blogs, the site, and breadcrumbs, giving search engines rich context about your content.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Analytics integration', anchor: '#analytics-integration', text: 'Add your Google Analytics ID to track traffic alongside Aglyn\'s built-in analytics.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Related', anchor: '#related', text: '- Analytics\n- Content collections & blog' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: '', anchor: '', text: 'Design custom error screens\nWhen something goes wrong, visitors should still see your site. Design custom error screens for each status.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'The error screens', anchor: '#the-error-screens', text: '| Status | Picker label | When it shows |\n| 404 | 404 · Not found | The URL doesn\'t match any screen. |\n| 401 | 401 · Members only | A members-only screen, requested by a signed-out visitor. |\n| 403 | 403 · Forbidden | Reserved for future access rules — nothing serves it yet. |\n| 503 | 503 · Maintenance | Shown on every page while maintenance mode is on. |' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Design one', anchor: '#design-one', text: '1. Create a screen for the status, in Screens, and design it in the Besigner like any other screen — add your header/layout, a helpful message, and a link home.\n2. Assign it. Go to Setup and scroll to the Error pages card. Each status has its own picker — 404 · Not found, 401 · Members only, 403 · Forbidden, 503 · Maintenance — listing every screen on the site. Choose your screen in the matching picker.\nStep 2 is the one that\'s easy to miss: designing a screen does not make it an error page on its own. Until it\'s picked in the Error pages card, the status renders the Built-in fallback page, which is what every picker is set to until you change it.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'What the built-in fallback gives you', anchor: '#what-the-built-in-fallback-gives-you', text: 'The fallback is not a blank error page. It renders under your site\'s theme and carries your logo, links to your site\'s public top-level pages, a search box (on the 404) and a footer — so a visitor who lands on a missing address can always get somewhere.\nWhat it cannot do is show the header, navigation and footer you designed: those live in the screen you built them on, and on a 404 that screen is precisely the one that wasn\'t found. Its page links come from your published pages, and only the public ones — an unlisted, password-protected or members-only page never appears there.\nAssigning a designed screen is still the better answer for any site that cares how this moment looks. The fallback is the floor beneath it.\nAssigned error screens are automatically kept out of search results, so a 404 page can\'t itself turn up in a search.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Error screens are free', anchor: '#error-screens-are-free', text: 'An assigned error screen doesn\'t count against your plan\'s screen allowance. Nothing about it is a page of your site: it renders on addresses that matched nothing, so it has no URL of its own — the same reason a collection\'s entry template doesn\'t count. See what counts against your screen allowance.\nThere\'s one thing to know, and it\'s the reason you don\'t need to publish the screen at all:\nDon\'t give it an address An error screen that is also published at its own address — a 404 screen you published at /404 so you could preview it, say — is a page, so it counts like any other page until you remove that address.\nIf you\'ve already published one, the Error pages card says so and offers Remove address. Removing it frees the allowance slot and the screen carries on rendering for its status code, which is the only place it was ever meant to appear.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Tips', anchor: '#tips', text: '- Put a search box or navigation on your 404 so visitors can recover.\n- Keep the 503 lightweight — it shows when the site is under maintenance.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Related', anchor: '#related', text: '- Maintenance mode\n- Password-protect a screen' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: '', anchor: '', text: 'Maintenance mode\nNeed to pause your live site while you make changes? Maintenance mode serves your designed 503 screen to visitors until you switch it back.' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: 'Turn it on', anchor: '#turn-it-on', text: '1. Open Setup for the site and scroll to the Error pages card — the same card that assigns your error screens. It sits below the site details, logo and business details.\n2. Switch on Maintenance mode — show the 503 screen on every page. It confirms with "Maintenance mode on — visitors see the 503 screen".\n3. Visitors now see your 503 error screen on every path.\n4. When you\'re done, switch it back off and the site returns.\nIf you haven\'t assigned a 503 · Maintenance screen, maintenance mode still works — but visitors get Aglyn\'s plain built-in notice ("This site is undergoing maintenance. Please check back shortly.") rather than anything on-brand. Design and assign the 503 first.' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: 'Tips', anchor: '#tips', text: '- Design the 503 screen first (see custom error screens) so maintenance mode shows something on-brand.\n- Tell visitors when you\'ll be back — a simple line on the 503 goes a long way.' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: 'Related', anchor: '#related', text: '- Design custom error screens' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: '', anchor: '', text: 'Site Protection & Error Pages\nControl who can see your pages and what visitors see when something\'s not available.\nPlan availability Included on every plan. Per-screen visibility, page passwords, custom error screens and maintenance mode are not tier-gated.' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Where these controls live', anchor: '#where-these-controls-live', text: 'The three features on this page are set in two different places, and neither is the screens list:\n| What you want | Where it is |\n| A screen\'s visibility (public, unlisted, password, members-only) and its page password | The Page Access card on that screen\'s own page |\n| Error screens for 404 / 401 / 403 / 503 | The Error pages card in Setup |\n| Maintenance mode | The same Error pages card in Setup |' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Per-screen passwords', anchor: '#per-screen-passwords', text: 'Protect individual screens with a password, so only people with the code can view them. You can also set a custom not-found screen for missing pages.' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Custom error screens', anchor: '#custom-error-screens', text: 'Design your own 404 / 401 / 403 / 503 screens in the Besigner, so error pages match your brand instead of showing a generic message.' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Maintenance mode', anchor: '#maintenance-mode', text: 'Flip your site into maintenance mode to show a designed 503 while you work, then switch it back when you\'re ready.\nHow-tos\n- Password-protect a screen\n- Design custom error screens\n- Maintenance mode' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Related', anchor: '#related', text: '- Screens & layouts\n- Redirects' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: '', anchor: '', text: 'Password-protect a screen\nLock a single screen behind a password — useful for drafts, client previews, or gated content, without setting up full membership.' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: 'Steps', anchor: '#steps', text: '1. Open Screens and click the screen you want to protect. The screens list has no visibility column — the control is on the screen\'s own page.\n2. Find the Page Access card and set Visibility to Password protected.\n3. A Page password field appears. Type the password and click Save. Once one is set, the field reads "A password is set — save a new one to change it."\n4. Publish. Visitors are prompted for the password before they can view the screen.\nThe other visibility options on the same card are Public (anyone with the link, listed in navigation and offered to search engines), Unlisted (reachable by URL only, kept out of search results and the sitemap), and Members only. Password-protected and unlisted screens are both kept out of search results.\nPassword attempts are limited to 10 per minute per screen, per visitor address, so the password can\'t be guessed by brute force. Someone who trips it is asked to wait a moment and try again. The limit counts per address, so a shared office connection tripping it won\'t lock out anyone else — but if a whole team is unlocking the same screen at once, expect the occasional retry prompt.' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: 'Password vs. members-only', anchor: '#password-vs-members-only', text: '| Password | Members-only |\n| One shared secret | Individual accounts |\n| No sign-up needed | Visitors sign in / sign up |\n| Best for one-off gating | Best for ongoing member areas |\nFor account-based access, use a members-only area instead.' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: 'Related', anchor: '#related', text: '- Custom error screens\n- Members-only areas' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: '', anchor: '', text: 'Add search to your site\nAdding search is a matter of placing one element. The search page and matcher are built in.\nPlan availability Included on every plan.' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: 'Steps', anchor: '#steps', text: '1. In the Besigner, open the elements drawer and add the Search Box (under Forms) to a screen — or to your shared layout so it appears site-wide.\n2. Optionally set the box\'s Placeholder text in the Attributes panel.\n3. Publish. Submitting the box sends visitors to your site\'s /search page with their query.\nThat\'s the whole setup — there\'s no search setting to switch on and no index to build.' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: 'Tips', anchor: '#tips', text: '- Put the Search Box in your header layout so it\'s reachable from every page.\n- Search covers dataset records and blog entries, so well-structured content and clear titles make results more useful.\n- Dataset records only surface when a published screen repeats over that dataset — build a listing screen for anything you want to be findable.' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: 'Related', anchor: '#related', text: '- Site search overview\n- Datasets & dynamic content' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: '', anchor: '', text: 'Site Search\nGive visitors a Search Box to find content across your site. Aglyn ships a built-in search page — there\'s nothing to configure, enable, or index.\nPlan availability Included on every plan, free tiers too.' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'How it works', anchor: '#how-it-works', text: 'The Search Box element is a simple form: a visitor types a query and submits it to your site\'s built-in /search page, which renders the matching results. There\'s no JavaScript and no external search service — the page reads your published content directly when the visitor searches.' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'What it searches', anchor: '#what-it-searches', text: 'A search matches the query as a case-insensitive substring across three kinds of content:\n- Screens — the screen\'s name, description, and SEO title and description.\n- Blog & collection entries — published entries\' title, excerpt, and body (see collections).\n- Dataset records — a record\'s dataset values. A record only appears in results when a published screen repeats over that dataset, so the result can link to a real page.\nResults are listed in that order (screens, then entries, then records), up to 50 matches. There\'s no relevance ranking — matching is a straight substring test — so clear titles and descriptions make results more useful. The /search results page is excluded from search engines, and search is a reserved screen slug.' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'Configure it', anchor: '#configure-it', text: 'The Search Box exposes one setting — its Placeholder text. There are no scope, result-limit, or styling options; the box inherits your site theme.\nHow-tos\n- Add search to your site' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'Related', anchor: '#related', text: '- Datasets & dynamic content\n- SEO toolkit' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '', anchor: '', text: 'Build a blog\nAglyn\'s blog is built on collections — a collection holds your entries, and its pages are first-class designed pages: the list at /{collection} and each entry at /{collection}/{entry} render through your site\'s theme and shared layout, and can be fully designed in the besigner via template screens.\nPlan availability Free to start; content features scale with your tier.' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '1. Create a collection', anchor: '#1-create-a-collection', text: 'In Content, create a collection for your posts. Manage entries from the console.\nDelete a collection\nDelete collection sits in the Collections & Entries toolbar, beside Categories and New entry, and acts on the collection currently picked in the Collection dropdown. It is a site admin action: if your role on this site is editor or viewer the button is not there at all, and an org role on its own does not grant it — the check reads your role on this site. Ask a site admin, or have one raise your role in Members.\nAglyn refuses the delete while anything still depends on the collection, and the dialog tells you which of these it is before you can type anything:\n- A template screen still points at it. The message names the screen and which picker holds it — "Blog" is still the source for "Blog index" (list template). Set that collection\'s List template screen or Entry template screen back to the built-in option first. Deleting it while a published page renders from it would leave that page with nothing to draw.\n- It still has entries. The message gives the count — "Blog" still has 12 entries. Delete them from the entries table first, one at a time; deleting a collection never removes published entries for you.\nOnce nothing depends on it, type the collection\'s display name exactly — the name, not the slug, and capitalisation counts — and confirm. Deleting removes the collection, its category list, and its template pointers. Your screens are not deleted (they keep their design and simply stop being template screens) and nothing in the media library is touched. The /{collection} and /{collection}/{entry} routes stop resolving on the live site within about a minute; there is no publish step.\nNo undo There is no trash and no restore. A deleted collection comes back only from your' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '2. Write entries', anchor: '#2-write-entries', text: 'Add rich blog entries with images, a live preview, and scheduling so posts publish at the right time.\nNew entry, or clicking any row in the entries table, opens that entry on its own page. The page has its own address, so you can bookmark an entry you\'re mid-way through or paste the link to a colleague and they land on the same one. Back to entries — or your browser\'s Back button — returns to the list; if the entry has edits you haven\'t saved, you\'re asked before they\'re dropped.\nEach entry carries, besides the title, excerpt, cover image, and markdown body:\n- Category — a single bucket (e.g. Guides) used for filtering and related posts, picked from the collection\'s category list (see below), never typed free-form.\n- Tags — comma-separated labels (e.g. nextjs, seo).\n- Author — the entry\'s byline: an author record from the Authors tab, a one-off custom byline, or the site\'s own publisher entity when both are blank. See Authors.\n- SEO title / SEO description — search & social overrides; they fall back to the title and excerpt when blank.\nScheduling\nThe same three publication controls live in two places, so you can decide when a post goes live without leaving what you\'re doing: the entry row\'s actions menu in the list, and a Publication panel at the bottom of the entry\'s own page.\n- Publish / Unpublish — takes the entry live, or pulls it back, immediately.\n- Schedule… — pick a Publish at time in the future (the past is refused). The status chip reads Scheduled with the local time, and the entry goes live once that time passes — applied on the next site refresh, so there\'s no manual step and its status flips to published on its own. A scheduled entry joins the sitemap and RSS feed at the same moment.\n- Edit published date… — sets the date the entry claims it was published, ' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '3. Design the pages with template screens', anchor: '#3-design-the-pages-with-template-screens', text: 'Each collection has two template pickers in Content:\n- List template screen — renders /{collection}. Drop the Collection Entries block on it: its children repeat once per published entry, with {{entry.}} tokens substituted per entry. The default card ships title, date, excerpt, and a Read more link, so dropping it in works instantly.\n- Entry template screen — renders /{collection}/{entry}. Use {{entry.}} bindings and the Entry Body block, which renders the entry\'s markdown as themed headings, paragraphs, lists, links, and images.\nTemplate screens go through the normal published pipeline — site theme, shared layout, reusable components, variables — exactly like any other screen (the same mechanism as commerce product/collection templates).\nBlog blocks\nBesides Collection Entries and Entry Body, three entry-page blocks are available in the block library:\n- Entry Meta — an author · date · category line plus tag chips, with an optional round avatar in front of it. On an entry template it fills itself in from the entry being rendered, so drop it on and it works; each part can be hidden with its Show switch. Typing into Author / Date / Category / Tags overrides what it would have shown — including the {{entry.author}} / {{entry.date}} / {{entry.category}} / {{entry.tags}} bindings, which still work and are still what the block\'s preset seeds. Date format picks how the published date reads — Site default (8/9/2026), Month and year (Aug 2026), Short date, Long date or ISO. It applies to the date the block fills in for itself; a date you typed in by hand is left exactly as typed. Avatar takes any image from the media library (usually your brand mark) and renders it 36px and round; blank shows no avatar. The avatar is chosen on the block, not per author — entries carry an author n' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '4. Publish & syndicate', anchor: '#4-publish--syndicate', text: 'Publish the collection. Blog pages join the site\'s sitemap automatically, and each entry\'s uses its SEO title/description (falling back to title/excerpt) and its cover image as the social card.\nAglyn also generates an RSS feed per collection, at:\ne.g. https://acme.com/blog/rss.xml. This is the URL to link — it names no site, so it keeps working if you connect a custom domain later, and it is the one to put behind a "Subscribe" link.\nThe same feed answers on the explicit form, if you need to point at another site\'s:\nhost accepts your site\'s platform origin (acme.aglyn.app), your custom domain (acme.com), or the bare subdomain (acme), and collection is the collection\'s slug.\nItems carry the entry\'s title, link, publish date, excerpt, and its category and tags as feed categories, newest first. Link it from your own footer or share it with aggregators. Feed readers also find it on their own: every collection page — the list, each paginated page, each category, and each entry — declares the feed in its page head, so pasting your blog\'s own address into a reader subscribes it to the feed.' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: 'Tips', anchor: '#tips', text: '- Schedule entries ahead of time and let Aglyn publish them for you.\n- Pair the blog with the SEO toolkit — entries emit JSON-LD for rich results.' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: 'Related', anchor: '#related', text: '- Save a template\n- Datasets & dynamic content\n- SEO toolkit' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: '', anchor: '', text: 'Templates, Blocks & Content\nBuild faster by starting from something. Aglyn gives you site templates, a section & block library, and a blog with content collections.\nPlan availability Free to use the starter gallery and block library. Some templates and content features scale with your tier.' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Site templates & starter gallery', anchor: '#site-templates--starter-gallery', text: '- Spin up a new site from the starter template gallery, which instantiates published screens for you. Starters are copied into your site\'s own template library, so you can edit and version them like any other template.\n- Save a site as a template from Setup → Site template, which publishes it to the marketplace — see save & share a template. Browsing and installing marketplace templates happens in the Start from a template picker, opened by the Templates button on the Screens, Layouts and Components lists.' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Section & block library', anchor: '#section--block-library', text: 'Drop in pre-built sections and blocks from the library instead of assembling every page from primitives — a fast way to build common layouts.\nThe library is a first-class group in the Besigner: open INSERT → New Element (or the components drawer) and the Sections & Blocks category sits at the top of the list, ahead of the primitive element groups. Every entry inserts a ready-made subtree with sensible props — drop it in, then edit text and styles in place.\nThe library ships these sections:\n| Block | What it inserts |\n| Nav Bar | App bar + toolbar with brand text and three screen links, in page flow (switch its Position attribute to Sticky for a pinned header) |\n| Hero | Centered headline, tagline, and call-to-action button |\n| Feature Grid | Three selling-point columns that wrap on small screens |\n| Image + Text | Image beside a heading, paragraph, and link button |\n| Testimonials | Three customer quote cards |\n| Pricing Table | Three plan columns with features and plan buttons |\n| FAQ | Question-and-answer list with a heading |\n| Call to Action | Accent-colored band with a heading and button |\n| Contact Section | Heading plus a working name/email/message form |\n| Announcement Bar | Accent strip with a message and link |\n| Image Gallery | Three-across image row |\n| Footer | Semantic with brand, screen links, social icons, and copyright |\nBlocks are ordinary elements once inserted — nothing is locked. Screen links resolve against your site\'s screens (pick targets in the link\'s attributes), the contact form submits like any form, and social icons appear once you add profile URLs.' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Content collections & blog', anchor: '#content-collections--blog', text: '- Create collections managed in the console.\n- Publish a blog with rich entries (images, preview, scheduling) and an RSS feed.\n- Use entry-template screens with {{entry.}} bindings to render each collection item.\nHow-tos\n- Build a blog\n- Save & share a template' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Datasets & dynamic content\n- SEO toolkit' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: '', anchor: '', text: 'Save & share a template\nTurn a site you\'ve built into a template others can start from — or start your own site from the marketplace gallery.\nPlan availability Free to use the starter gallery; sharing scales with your tier.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Start from a template', anchor: '#start-from-a-template', text: 'Open the starter template gallery and install a template. It lands in your templates library as one page template per page — publishing nothing until you choose which pages you want. Aglyn\'s own starter templates still create their pages straight away, since you pick those when a site is empty.\nWhere to find it\nTemplates sits next to the create button on three lists, and each one offers templates of its own kind:\n| List | What the picker offers |\n| Screens | Page templates, plus Aglyn\'s starter sites and marketplace templates |\n| Layouts | Layout templates |\n| Components | Component templates |\nStarter sites and marketplace templates are whole-site page bundles, so they appear only on Screens — a layout or component picker would have nothing to do with them.\nUse the filter icon in the dialog\'s header to search by name, description or category.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Save your site as a template', anchor: '#save-your-site-as-a-template', text: 'Saving a whole site is not done from the screens list — it lives in Setup.\n1. Open Setup for the site and find the Site template card, under the basic details.\n2. Click Publish as template.\n3. Fill in Template name, Description, Category (e.g. Portfolio, Restaurant) and Price (USD, 0 = free), then publish.\nThis captures every published screen plus the theme, and publishes it to the marketplace — so it is a share, not a private snapshot. Re-publishing bumps the version. Add a preview image afterwards from Manage → Marketplace.\nSaving a single page instead\nTo reuse one page rather than a whole site, use the ⋮ row menu on the Screens list and choose Save as template. Layouts and Components have the same row action. These save into your own templates library and are not published anywhere until you publish them separately.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Tips', anchor: '#tips', text: '- Templates are a fast way to reuse a proven layout across client sites.\n- Combine with the section & block library for page-level reuse without a whole template.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Related', anchor: '#related', text: '- Build a blog\n- Templates, blocks & content' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: '', anchor: '', text: 'Your templates library\nTemplates are saved starting points. A template is inert: nothing in your library is on your live site until you deliberately use it. That is the whole point of the library — it means installing something from the marketplace can never publish pages to a site you are running.\nFind it at Templates in a site\'s navigation, alongside Screens, Layouts and Components — the three things a template can produce.\nA template is a copy, not a live link: once you use one, the result is yours outright and editing the template never changes what you already made. If you want one edit to update every place a thing appears, you want a reusable component. If you want one frame around many pages, you want a layout.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'The three kinds', anchor: '#the-three-kinds', text: '| Kind | What it holds | What you get from it |\n| Page | A screen\'s content | A new screen, unpublished |\n| Component | An element tree | A reusable component, or a drop onto a screen |\n| Layout | Page chrome — header, footer, navigation | A new shared layout |' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Installing from the marketplace', anchor: '#installing-from-the-marketplace', text: 'Installing a marketplace template adds it to your library and publishes nothing. A site template arrives as one page template per page it contains, so you choose which of them you actually want, and when.\nThis is deliberate: browsing and installing should never be able to change a site that real people are looking at. If the template was designed around a particular theme, that theme travels with it rather than being applied to your site.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Saving something as a template', anchor: '#saving-something-as-a-template', text: 'Look for Save as template:\n- Screens list — saves the page\'s published content\n- Layouts list — saves the layout, including its content slot\n- Components list — saves the component definition\nA page template captures the published version of a screen. If a screen has never been published there is nothing to capture, and Aglyn will tell you to publish it first rather than saving an empty template that fails later.\nThe original is never touched. Saving a template copies it.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Using a template', anchor: '#using-a-template', text: 'Use creates something new from the template — the template itself stays in your library, so you can use it as many times as you like.\n- A page template asks for a name and an address, then creates the page and publishes it. If the address is already taken, Aglyn adds a number rather than overwriting the page that\'s there.\n- Component and layout templates just create the component or layout; there is no address to pick.\nIf a template defines placeholders, you\'ll be asked to fill them in first — the values are substituted into the content as it\'s created. A template might use {{who}} in its copy and ask you for "Who".\nNothing you create is linked back to the template afterwards. Editing a page will never change the template, and updating a template will never change pages you already made.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Where a template came from', anchor: '#where-a-template-came-from', text: 'Every template shows a badge:\n- Saved here — you created it on this site\n- Marketplace — installed from a marketplace listing, with its version\n- Starter — one of Aglyn\'s first-party starter templates\nThat badge is set by Aglyn, not by whoever made the template, so a listing cannot claim to be something it is not.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'First-party starters', anchor: '#first-party-starters', text: 'Aglyn\'s starter sites (Landing Page, Business, Portfolio, the two Shop starters) are ordinary templates in your library — not a separate, locked-down kind. Every site gets its own copy, so you can open a starter in the besigner, edit it, keep versions of it, and use it to create pages exactly like a template you saved yourself. They carry the Starter badge, and they don\'t count against your plan\'s template allowance.\nA multi-page starter arrives as one template per page (the Shop starters are five), and Start from a template still shows them grouped as one card that creates all of the pages at once.\nYour Templates list groups them the same way: one row per starter, labeled with its page count, and its actions act on all of those pages — Use creates every page, and Delete removes every page. Open the row to see the pages individually; each one is an ordinary template you can edit, use or delete on its own from there.\nBecause your copy is yours, editing a starter is safe: Aglyn will not overwrite it later. Delete one you don\'t want and it stays deleted.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Templates are per-site', anchor: '#templates-are-per-site', text: 'A template lives on the site you saved it to. That keeps a template next to the screens, layouts and components it was built from.\nMarketplace plugins and add-ons work differently: those install once for the whole organization and apply to every site, and a site can override the organization\'s choice for itself.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Deleting', anchor: '#deleting', text: 'Deleting a template removes it from your library. Anything you already created from it is unaffected — a page made from a template is a normal page, with no ongoing link back to it.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Related', anchor: '#related', text: '- Save & share a template — publishing a whole site as a template for other organizations to install' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: '', anchor: '', text: 'Edit your theme\nYour theme controls how the whole site looks — applied consistently across every screen and previewed live as you edit.\nPlan availability Free.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Open the editor', anchor: '#open-the-editor', text: 'Go to Setup → Theme editor. Changes render in a live preview so you see them immediately.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Set colors and fonts', anchor: '#set-colors-and-fonts', text: '- Choose your palette and typography.\n- Fonts load through a Google Fonts URL builder.\n- Configure both light and dark schemes — published sites apply the visitor\'s system scheme automatically.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'It follows you into the Besigner', anchor: '#it-follows-you-into-the-besigner', text: 'The theme you set here is supplied to the Besigner canvas, so what you design previews under the real site theme in both light and dark.\nYour palette also powers the Besigner\'s color pickers: every color field offers your theme\'s colors as references first (Primary, Background, Surface, Text…), each swatch previewing its light and dark resolutions. Elements colored by reference re-color automatically when you adjust the theme — or when the visitor\'s scheme flips. See scheme-scoped colors.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Tips', anchor: '#tips', text: '- Set both schemes — a site that only looks right in light mode breaks for dark-mode visitors.\n- Prefer theme color references over fixed hex values when styling elements; references adapt per scheme, fixed colors don\'t (though the Besigner can scope custom colors per scheme too).\n- The theme also styles screen previews and published pages, so there\'s one source of truth.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Screens & layouts' },
  { path: '/building-sites/theme-builder/overview', title: 'Theme Builder', heading: '', anchor: '', text: 'Theme Builder\nThe theme builder controls how your whole site looks — colors, fonts, and light/dark schemes — applied consistently across every screen.\nPlan availability Free. Theming is core to every site.' },
  { path: '/building-sites/theme-builder/overview', title: 'Theme Builder', heading: 'Edit your theme', anchor: '#edit-your-theme', text: '- Open the theme editor under Setup.\n- Set your palette and typography; changes render in a live preview.\n- Configure both light and dark schemes — published sites apply the visitor\'s scheme automatically.\n- Fonts load via a Google Fonts URL builder.\nThe theme you set here is supplied to the Besigner canvas too, so previews match the live site.\nHow-tos\n- Edit your theme' },
  { path: '/building-sites/theme-builder/overview', title: 'Theme Builder', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Screens & layouts' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: '', anchor: '', text: 'Bookings & Scheduling\nBookings turn your site into a scheduling tool: define services, publish your availability, and let visitors book time — with optional payment and automatic reminders.\nPlan availability Paid. Paid bookings use Stripe; reminder emails are included.\nPaid services need Stripe connected first A paid booking is a destination charge into your own Stripe account, so the booking widget cannot take money until Stripe Connect onboarding is finished and Stripe reports charges enabled. Until then a visitor who picks a paid service is told "Payments are not set up yet" and the slot is not held. Free services are unaffected — they never touch Stripe. Connect your account from the Payments card on the Products hub; see Commerce.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Set up bookings', anchor: '#set-up-bookings', text: '1. Define services (what can be booked, duration, price).\n2. Configure availability — the windows when slots are offered.\n3. Add the booking widget to a screen as a canvas element.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Taking bookings', anchor: '#taking-bookings', text: '- Visitors pick a slot through the booking widget; the booking API records it.\n- For paid services, Stripe collects payment and a slot hold prevents double-booking during checkout.\n- Reminder emails go out automatically ahead of the appointment — see below.\n24-hour reminders {#reminders}\nEvery confirmed booking gets one reminder email roughly a day before it starts. A background pass runs each hour and mails the bookings that are then 23–25 hours out, so a reminder lands about 24 hours ahead rather than at an exact minute.\nA booking is reminded once. The pass records that it has sent, so a booking is never mailed twice, and these do not go out for canceled bookings or for bookings taken without an email address.\nThe reminder uses your designed booking reminder email template if you have one, and your own brand if your plan includes white-labeling; otherwise it sends a plain text reminder naming the service and the time.\nWhere to see it. The Upcoming bookings card shows 24-hour reminders · N due in the next pass · N already sent, counted with the same rule the sender uses — so it is the queue that will actually be drained, not an estimate.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Payments and fees', anchor: '#payments-and-fees', text: 'Money for a paid booking goes to you, not to Aglyn. The charge is created on your connected Stripe account, and Aglyn takes its platform fee out of it as the Stripe Connect application fee — the same way a storefront sale works.\n- A booking is priced as a service, which bills at your plan\'s digital transaction rate: 5% on Starter, 3% on Pro, 2% on Business, 1% on Scale, and 0% from Advanced up. It is the same rate and the same ladder as digital products — bookings are not charged separately or additionally.\n- The fee is taken on the service price only. Stripe\'s own processing fee is separate and comes out of your account as usual.\n- Your current rate is shown on the Payments card of the Products hub, and the full ladder is on the plans page.\nService tax\nPaid bookings charge no tax by default, and that stays true for every site that does not change it.\nA service is not goods: the sales-tax rate configured for your store is a goods rate, and whether a service is taxable is a different question with frequently the opposite answer. So Aglyn does not apply your store\'s sales rate to an appointment. Instead, Commerce → Settings → Taxes → Service tax is where you set your own rate for it.\nWhen you set one, Aglyn adds it to the booking charge as its own receipt line using the label you choose, and records the amount and the regime on the booking. It is always your own rate — Stripe Tax is never asked to compute it, because it has no service tax code for this and would apply a goods rate to an appointment.\nThe platform fee is charged on the service price, never on the tax.\nAglyn does not provide tax advice Aglyn applies the rate you enter and records what was charged. It does not determine whether service tax applies to you, at what rate, or where it should be paid. Confirm your' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Manage', anchor: '#manage', text: 'Use the console bookings page to see and manage upcoming appointments.\nCanceling and refunding {#canceling-and-refunding}\nCanceling a booking reopens the slot. For a paid booking, canceling also refunds the visitor through Stripe — the button reads Cancel and refund and tells you the amount before you confirm.\n- The refund pulls the money back out of your account and returns Aglyn\'s platform fee on it, so a refunded appointment costs you nothing in fees.\n- If the refund fails, the booking is not canceled. The appointment stays on the list and the message says what went wrong, so you never end up with a canceled slot the visitor was never paid back for.\n- Refunding is site-admin only, because it moves money.\n- Bookings paid before this was supported have to be refunded from the Stripe dashboard instead — the console will say so, and will remind you to tick Reverse transfer so the amount comes back from your account rather than Aglyn\'s.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Related', anchor: '#related', text: '- Commerce\n- Events calendar\n- Email campaigns' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: '', anchor: '', text: 'Product catalog\nThe catalog (AGL-276) is the foundation of Aglyn commerce: every storefront block, checkout, and order line points back at these documents.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Products, options, and variants', anchor: '#products-options-and-variants', text: 'A product is what you manage; a variant is what a customer actually buys. Products define up to 3 options (like Size or Color, each with up to 25 values), and the products hub expands them into a variants matrix — up to 100 variants per product, each with its own SKU, barcode, price, compare-at price, weight, image, and inventory count.\n- Types: physical (shippable), digital (delivered as downloads), or service.\n- Status: draft (invisible to visitors), active, or archived.\n- Pricing: a variant with a compare-at price above its price shows a sale badge on storefront blocks.\n- Inventory: leave blank for untracked, 0 means sold out — the same semantics the original product block used. Stock is not tracked on a digital or service subscription-only product: nothing decrements it, on the first charge or on any renewal, so the field is disabled there. A physical subscription tracks normally — every paid cycle decrements one unit per box shipped — and Both — buyer chooses keeps tracking on the one-time sales.\nProducts created with the earlier single-price product block are lifted into this model automatically as a single default variant — nothing breaks and no migration step is needed.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Billing modes and subscriptions', anchor: '#billing-modes-and-subscriptions', text: 'Each product\'s Billing setting picks how buyers pay:\n- One-time purchase (default) — a normal order.\n- Monthly / Yearly subscription — buyers subscribe instead of buying once; the product page prices as $X/mo or $X/yr, the buy button reads Subscribe, and an optional free trial (in days) can precede the first charge. An active subscription is what members-only content checks.\n- Both — buyer chooses — the product page shows a one-time / subscribe toggle (same price either way, at the interval you pick) and defaults to one-time. The choice is validated server-side against the product: a one-time sale here is a plain order, while the subscribe choice creates a recurring subscription exactly like a subscription-only product.\nSelling subscriptions (including the subscribe side of Both) requires a plan with storefront subscriptions (Business and above). Subscription billing applies to the product page\'s direct checkout — cart checkouts always charge one-time.\nWhether a subscription moves stock follows the product\'s Type. A physical subscription decrements one unit per paid cycle — the first charge and every renewal each create an order on the Subscription channel and take the box off the shelf, so the stock field stays live and low-stock alerts apply. A digital or service subscription never moves stock, and the stock field is disabled there; any number already saved is kept and shown, but it does not cap subscribers and will not change on its own. A saved 0 still stops new subscribers, so clear it (Clear stock on the notice in the editor) if that is not what you want. On a Both product the stock field stays live, because the one-time sales do decrement it.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Categories and tags', anchor: '#categories-and-tags', text: 'Categories are hierarchical (each may have a parent) and slugged for URLs. Tags are free-form labels. Both drive storefront filtering and smart collections.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Collections', anchor: '#collections', text: 'Collections group products for landing pages and storefront blocks:\n- Manual collections are an ordered, hand-picked list.\n- Smart collections define rules — match by tag, category, price, name, or product type, with all or any semantics — and membership updates automatically as products change. Draft and archived products never appear.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Slugs', anchor: '#slugs', text: 'Products, categories, and collections each have a host-unique slug used in storefront URLs (/products/{slug}, /collections/{slug}). Slugs are lowercase letters, numbers, and dashes.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Google Merchant Center feed', anchor: '#merchant-center-feed', text: 'Your catalog is also published as a product feed for Google Merchant Center. The address is on the Store settings card under Commerce → Settings: a read-only Google Merchant Center feed URL field with a Copy feed URL button beside it.\nIn Merchant Center, add it under Products → Feeds as a scheduled fetch. Merchant Center then re-reads the URL on the schedule you set there, so catalog changes reach it without another upload.\nWhat the feed contains:\n- One item per active product. Draft, archived, and deleted products never appear. Items are per product, not per variant — the price is the lowest price across the product\'s variants.\n- Per item: the product id, name, description (its name again if the description is empty), a link to /products/{slug} on your store, the product\'s first image if it has one, the price in USD, an availability value, and the condition new.\n- Availability is outofstock when a tracked stock count has reached zero and the product does not allow backorders. Everything else — including untracked stock — is instock.\n- Up to 500 products. A larger catalog is not fully represented in the feed.\nTwo things worth knowing before you submit it:\n- Use the URL the card gives you. Each item\'s link is built from the address the feed was requested on, so submitting the wrong one puts the wrong domain on every product in Merchant Center.\n- The URL appears once the site has an address — a subdomain or a custom domain. Until then the card says so rather than showing a partial URL.\nThe feed needs no credentials to read, and it carries only what your storefront already shows publicly. Responses are cached for an hour, so a price or stock change can take that long to appear in a fetch.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Related', anchor: '#related', text: '- Commerce overview\n- SEO — products emit structured data and join the sitemap automatically.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: '', anchor: '', text: 'Commerce\nAglyn commerce sells from your own Stripe account: buyers pay you directly, and Aglyn collects a per-sale platform fee set by your plan (see Billing & plans — higher plans reduce fees to 0%).\nPlan availability Paid. Starter sells up to 100 products (2% physical / 5% digital fee); Pro and Business raise limits and remove fees.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Products hub', anchor: '#products-hub', text: 'The Products page is the catalog manager:\n- Products with up to 3 options and 100 variants each — per-variant SKU, barcode, price, compare-at (sale badge), weight, and stock. See Product catalog.\n- Categories & collections — a category tree plus manual and smart (rule-based) collections with a live match preview.\n- CSV import/export in the Shopify column dialect, with a dry-run report — switching from Shopify is a file upload.\n- Payments — Stripe Connect onboarding status and your plan\'s fee ladder.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Inventory', anchor: '#inventory', text: '- Per-variant stock; blank = untracked, 0 = sold out.\n- Oversell policy per product: stop selling or allow backorders.\n- Low-stock alerts notify managers once per threshold crossing.\n- Adjustment history with reason codes (sale, restock, correction…).\n- Locations split stock across warehouses/storefronts (plan-capped); adjustments and POS sales bucket per location.\n- Reserved in checkout holds units for a shopper who has reached the payment page, so the last one cannot be sold twice.\nReserved stock {#reserved-stock}\nWhen a shopper reaches the payment page, the units in their basket are reserved — the next shopper is offered what is left, not the same unit. It is what stops two people paying for the last one.\nYour stock count does not move when a unit is reserved. A reservation is a promise, not a sale, and the count means what is on the shelf. The products list names the difference instead: 3 (1 reserved) is three units on the shelf with one of them spoken for, so two are available to buy right now.\nA reservation is released when the shopper pays (the count moves then), when they abandon the checkout, or after 31 minutes, whichever comes first. A checkout page left open expires on its own, so nothing stays reserved by someone who walked away.\nTwo cases reserve nothing, deliberately: a variant with no stock tracking has no number to reserve against, and a product set to allow backorders is one you have told us to keep selling past zero.\nSales at the register are not affected — the till never refuses a sale, because the shelf in front of the cashier is the truth.\nStock movements {#stock-movements}\nInventory → Stock movements is the history behind every tracked count — the answer to "the shelf says four and the console says six, what happened?"\nFive things write to it and ' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Gift cards & store credit', anchor: '#gift-cards', text: 'Gift cards lists every card your store has issued, what is left on each one, and what that adds up to. Business plan and above.\nCards arrive two ways:\n- A shopper buys one. A gift-card purchase mints a card with a code at the moment the payment settles.\n- You issue one by hand. Enter an amount and, optionally, an email address and the code is created and mailed to that person. This is the goodwill gesture and the service-recovery path — a refund you would rather keep as store credit.\nBalances apply automatically at checkout; a shopper enters the code and the card is drawn down by what the order uses. Search the list by code or by recipient email to find one.\nOutstanding balance is a liability, not revenue The outstanding total at the top is money customers have already paid you and have not yet spent. It is store credit you owe against future orders, and it belongs on the liability side of your books — not in a sales figure. Cards are counted at zero or above, so a card that has somehow gone negative cannot flatter that total downward.\nVoiding a card zeroes whatever is left on it. The holder can no longer redeem it and the action cannot be undone, so you are asked to confirm the remaining amount first.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Recovery & alerts', anchor: '#recovery-and-alerts', text: 'Two queues the storefront fills and Aglyn drains for you, both visible so you can see they are moving.\nAbandoned checkouts — a shopper who reached checkout, entered their email and left. Aglyn emails them once, with a link back to the cart they had built, about fifteen minutes after that checkout has been idle for an hour. A checkout that gets completed stops reminding itself, and one that is never completed is given up on after seven days. The card shows how many are due a reminder, how many are still inside the first hour, and how many have already been reminded, with the most recent few named. Pro plan and above.\nBack-in-stock alerts — anyone who used "Notify me when it\'s back" on a sold-out product is emailed once its stock goes above zero. The count of shoppers waiting is a demand signal worth restocking against. Available on every plan that includes commerce.\nBoth are read-only here on purpose. Sending is the scheduled job\'s to do, and a "send now" button would race it for a reminder you cannot un-send.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Orders', anchor: '#orders', text: 'Every paid checkout becomes an order with a sequential number, line-item snapshots, totals, and a timeline:\n- Statuses: pending → paid → fulfilled (or partially) → delivered, with cancel/refund exits guarded by a status machine. The seven of them, and the labels the console shows, are in Statuses and channels.\n- Fulfill with tracking, print packing slips, add internal notes.\n- Refunds (full or partial) go through Stripe and reverse the platform fee. Refunding needs the admin role and organization-wide membership — a workspace owner or admin, or a member given access to every site. A collaborator invited to this one site is an admin of the site, which is enough to run the till and fulfill orders but not to send money back out of the business.\n- Chargebacks are shown apart from refunds. When a shopper disputes a charge with their bank, the order gets a Chargeback open badge and the list warns you with the date Stripe needs your evidence by — answer it in the Stripe dashboard, because an unanswered dispute is decided for the shopper. If the dispute is lost the money is reversed, the order reads Charged back rather than Refunded, and the buyer loses the downloads, membership and verified-purchase review a refund would have withdrawn. A dispute you win reverses nothing. Filter the list by Disputes to find either.\n- Draft orders: build an order in the console and send the buyer a payment link (Shopify parity). Requires an active plan with commerce — see the note below.\nThe Orders screen {#orders-screen}\nOpen your site\'s Products hub and choose the Orders tab. Before your first sale the tab is an invitation rather than a table: it explains where orders come from and offers Draft order, so you can invoice a customer you already have. The filters and Export CSV appear once there' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Shipping & taxes', anchor: '#shipping--taxes', text: '- Shipping zones own countries (\'\' = rest of world); rates are flat, free-over-subtotal, or subtotal/weight tiers; optional local pickup.\n- Taxes: manual per-region rates (state beats country, VAT-style inclusive pricing supported) or Stripe Tax automatic calculation; products can be tax-exempt.\nLodging tax on reservations\nA stay is not goods. The sales-tax settings above configure a goods rate resolved against an address; occupancy (lodging/hotel) tax is a separate regime with its own rates, its own registration and its own return, so reservations do not use them.\nCommerce → Settings → Taxes → Lodging tax is where you set your own rate for it. It is off by default — leave it blank and reservations charge no lodging tax, exactly as before.\nWhen you set a rate, Aglyn adds it to the reservation charge as its own receipt line using the label you choose, and records the amount and the rate on the reservation. It is always your own rate: Stripe Tax cannot compute occupancy tax from a reservation session, so a store using Stripe Tax for goods still sets this one by hand.\nAglyn does not provide tax advice Aglyn applies the rate you enter and records what was charged. It does not determine whether lodging tax applies to you, at what rate, or where it should be paid. Confirm your obligations with a qualified tax professional.\nDeposits. A reservation usually charges a deposit rather than the whole stay, and the rate is applied to the amount actually charged — the deposit. Aglyn does not decide whether your jurisdiction wants occupancy tax on the full stay at booking, on the deposit, or at check-out. If tax is due on more than the deposit, collect the difference the way you collect the rest of the balance.\nStorefront sales tax\nAnalytics → Storefront sales tax shows what your store' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Dropshipping', anchor: '#dropshipping', text: 'Assign a supplier to a product and paid orders route automatically — by email and/or HMAC-signed webhook — with a token link the supplier uses to post tracking back, which fulfills the order. Pro plan and above.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Related', anchor: '#related', text: '- Product catalog\n- Billing & plans\n- Bookings & scheduling' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: '', anchor: '', text: 'POS & reservations\nPlan availability POS requires Pro or above. The number of registers a site can run at once follows your plan — Pro 1, Business 2, Advanced 5 — plus any additional register seats you\'ve assigned to that site. A seat is bought once for the workspace and then placed on one site, so buying one does not raise the limit everywhere; see Assigning register seats. Opening more browser tabs does not give you more registers; each sale runs through a register you\'ve created.' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'Registers', anchor: '#registers', text: 'Create your registers under Commerce → Settings → POS registers — one per till or device that takes in-person payments. Give each a name (and, if you use inventory locations, the location it sells from). Every POS sale is tagged with its register so you can reconcile end-of-day takings per till. Your plan caps how many registers you can run; add more with the register add-on in Billing. If you downgrade below your register count, the extra registers (newest first) stop taking payments and show Over plan limit until you remove them or upgrade again — none are deleted.' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'The register', anchor: '#the-register', text: 'Open /{site}/pos in the console for a touch-first register. Pick which register you\'re on at the top of the panel (skipped automatically when you have only one):\n- Product grid — tap to add; products with variants show quick chips.\n- Barcode scanners — any keyboard-wedge scanner works: it types the code into the search box and presses Enter, which adds the exact SKU/barcode match. No drivers or pairing needed.\n- Payments — cash (with change calculation), card via QR (the customer scans and pays on their phone; the sale completes automatically), or charge to room for checked-in reservation guests. Stripe Terminal readers can replace the QR step later without changing the flow.\n- Receipts print through the browser\'s print dialog — any receipt printer with a system print driver works. Set the paper size to your roll width once and the browser remembers it.\nPOS sales create normal orders tagged pos, decrement the same inventory as your online store (per location if you use locations), and appear in the orders list under the channel filter.\nPlatform fees at the register\nYour plan\'s platform fee is charged on the sale, not on how it was paid — the rate is the same whether the customer hands you cash, scans the QR, or charges it to their room. What differs is only how it reaches us:\n| Tender | How the fee is collected |\n| Card (QR) | Deducted from your Stripe payout for that sale |\n| Cash | No payout to deduct from — added to your next monthly invoice |\n| Charge to room | Same as cash: added to your next monthly invoice |\nThe customer never pays the fee, and the amount Due on the register is the same on every tender. On plans with a 0% fee there is nothing to collect either way. See Billing & plans for your plan\'s rates.\nSelling past the count\nIf a line is for more units than ' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'Reservations', anchor: '#reservations', text: 'For stays (cabins, rooms, rentals):\n1. Add resources on the Products page — nightly rate, weekend multiplier, minimum nights, deposit percent, and free-cancellation window.\n2. Drop the Reservation widget on any screen in the besigner and point it at the resource id. Guests pick dates, see a live quote, and pay the deposit (or full amount) at checkout.\n3. Manage stays from the Reservations card: check in, check out (with a folio summary if the guest charged store purchases to the room), walk-ins, no-shows, and cancellations.\nDeposits need a plan with commerce Taking a reservation deposit is a sale, and it is checked against your plan at the moment a guest tries to pay — not just when you added the widget. On a plan without commerce the widget still renders but checkout answers "Reservations are not enabled". Enabling the plugin is your switch; including commerce is your plan\'s. See downgrading.' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'Related', anchor: '#related', text: '- Commerce overview\n- Product catalog' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: '', anchor: '', text: 'Glossary & naming conventions\nAglyn\'s vocabulary grew through a couple of migrations, so several words name the same thing at different layers. This page is the canonical map (codified in AGL-443). For definitions of every product term — screens, nodes, plugins, workflows, and the rest — see the Term reference; this page is specifically the ruling on the four contested words.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'The hierarchy', anchor: '#the-hierarchy', text: '' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Organization (org)', anchor: '#organization-org', text: 'The entity. One subscription, one members roster (owner / admin / editor / viewer), one isolation boundary in Firestore (orgs/{orgId}), one plugin switchboard (enabledPlugins), org-scoped shared data (datasets, contacts, media, installs). Every current API, type, and permission is org-named: AglynOrganization, resolveOrgPermissions, getOrgForHost, the console\'s /org/ section.\nRule: new code that touches the entity says org.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Workspace', anchor: '#workspace', text: 'The same entity, in the user\'s language. "Your workspace" is what we call an organization in UI copy and user docs — Slack-style, including the {slug}.aglyn.com workspace subdomain. It intentionally never names a collection or a type.\nRule: workspace appears in UI copy and docs only, never in code identifiers.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Tenant', anchor: '#tenant', text: 'Two meanings — this is the word to be careful with:\n1. The published-site runtime (current, correct use): apps/tenant is the app that renders customers\' live sites, and the shared @aglyn/tenant- libraries serve that side of the platform. "Multi-tenant" in architecture prose uses this sense: the org is the tenancy boundary.\n2. A historic alias for the org\'s billing doc (now removed): before the organizations migration, billing lived at tenants/{uid}. The collection is retired and, as of AGL-444, so are the alias identifiers — AglynTenant is now AglynOrgBilling, useCurrentTenant() is useCurrentOrg() (returning org), the plugin-page tenant prop is org, and the Tenant permission/entitlement types are Org. The persisted strings went in AGL-445, while the platform was still pre-launch: Stripe billing metadata is keyed orgId, host docs carry only orgId/memberRoles, and the users.{uid}.tenants map is gone. No tenant-spelled data remains to migrate.\nRule: "tenant" means the site runtime, full stop. Code that means the entity says org and types it AglynOrgBilling.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Tenant vs. host — not the same thing', anchor: '#tenant-vs-host--not-the-same-thing', text: 'These are the two most-confused terms because both relate to published sites:\n- A host is one site: hosts/{hostId}, with its own domain or subdomain, screens, media, and member-role projection. An organization owns many hosts ("3 of 15 sites"). In UI copy a host is called a site.\n- The tenant app is the runtime that serves every host: one Next.js deployment that resolves the incoming hostname to a host doc (hostIndex), loads that host\'s org, and renders its published screens.\nSo: an org (workspace) owns hosts (sites); the tenant app serves them. A request to bakery.example.com is resolved to a host, whose org decides plugins/entitlements, rendered by the tenant app.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Quick reference', anchor: '#quick-reference', text: '| Term | Layer | Names in code | Use for new work |\n| Organization / org | Data model, APIs, permissions | orgs/{orgId}, AglynOrganization, resolveOrg | ✅ the entity |\n| Workspace | UX / docs | — (copy only) | ✅ user-facing copy |\n| Tenant (runtime) | Published-site side | apps/tenant, @aglyn/tenant- | ✅ that side of the platform |\n| Tenant (billing alias) | Removed (AGL-444/445) | none — identifiers and persisted strings are both gone | ❌ don\'t reintroduce |\n| Host / site | One published site | hosts/{hostId}, AglynHost | ✅ host in code, "site" in copy |' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: '', anchor: '', text: 'Term reference\nEvery term you\'ll meet in Aglyn, defined in a sentence or three, with links to the page that covers it in depth. For the rules about which word to use where (org vs. workspace vs. tenant vs. host), see the Glossary & naming conventions — this page is the vocabulary, that page is the ruling.\nJump to a group: Platform & accounts · Sites & content · The node tree · Besigner (the editor) · Plugins & marketplace · Data & logic · Automation & marketing · Commerce · Billing & plans\nEvery term below is a heading, so the table of contents on the right lists them all alphabetically within each group.' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Platform & accounts', anchor: '#platform--accounts', text: 'Organization (org)\nThe account entity: one subscription, one team roster, one plugin switchboard, one data-isolation boundary. Everything you own in Aglyn — sites, datasets, media, installs — belongs to an organization. In code and APIs this is always org. → Glossary, Teams & roles\nWorkspace\nThe same entity as an organization, in the product\'s user-facing language — "your workspace", including the {slug}.aglyn.com workspace URL. Workspace never names anything in code; it\'s the word the UI uses for your org. → Glossary\nTenant\nThe published-site runtime: the single deployment that takes any incoming domain, resolves it to one of your sites, and renders its published screens. "Tenant" always means this serving side of the platform — it is not another word for organization. → Glossary, Architecture & multi-tenancy\nHost\nOne site, as the data model sees it: its subdomain or custom domain, its screens and layouts, its media, its member-role projection. An organization owns many hosts. In UI copy a host is called a site. → Glossary\nSite\nThe user-facing word for a host — what you create, design, and publish. "3 of 15 sites" on your dashboard is counting hosts. → Create a site\nConsole\nThe builder application where you sign in and do everything: manage your workspace, design screens in the Besigner, configure plugins, view billing. → Console tour\nStaff console\nThe internal, staff-only area of the console (organizations directory, release flags, plugin review queue, audit log). Invisible without the staff claim. → Staff console\nMember\nA person on an organization\'s roster, holding one of the built-in role tiers — admin, editor, or viewer — org-wide or scoped to specific sites. → Teams & roles\nCustom role\nAn owner-defined named permission set that can be assigned in place of the buil' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Sites & content', anchor: '#sites--content', text: 'Screen\nOne page of a site: a slug, publish state, and a designed node tree. Screens can nest (parent/child slugs) and can bind to a shared layout. → Screens\nLayout\nShared site chrome — app bar, footer, navigation — designed once and rendered around every screen bound to it. → Layouts\nSlug\nA screen\'s URL segment. Nested screens compose their ancestors\' slugs into the full path. → Screens\nVersion\nAn immutable snapshot of a screen\'s (or layout\'s) node tree. You edit a draft version; publishing points the live site at a version. Scheduled publishing flips the pointer at a set time. → Publish your first screen\nRedirect\nA rule that forwards one path to another on your published site — for migrations, renamed pages, or vanity URLs. → Redirects\nError screens\nDesignable screens served for 404/401/403/503 instead of a generic error page. → Error screens\nMaintenance mode\nA host-level switch that serves the designed 503 screen on every path while you work. → Maintenance mode\nLocale\nA language your site serves (e.g. en, es). Multilingual sites pick a default locale and can render a language switcher. → Multilingual\nSite template\nA snapshot of screens, layouts, and content that can be applied to a new site — yours to save and reuse, or installed from the marketplace. → Site templates\nTheme\nThe site-wide design system — palette, typography, spacing, component styling — edited in the theme builder and applied to every screen. → Theme builder\nCustom domain\nYour own domain attached to a site in place of the default subdomain, with guided DNS verification. → Custom domains\nSubdomain\nThe default address every site gets on the platform\'s serving domain, before (or alongside) a custom domain. → Custom domains' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'The node tree', anchor: '#the-node-tree', text: 'The rendering model shared by the editor and the published site. Every designed screen is a tree of nodes; the renderer walks it with a family of components named like the parts of a tree.\nNode\nThe atom of a design: { $id, componentId, props, sx, nodes }. Each node names the registered component that renders it, carries its props and styling, and lists its child node ids. A screen version stores its whole design as a map of nodes. → Besigner overview\nTree\nThe node hierarchy of one screen or layout — what you see in the Besigner\'s hierarchy panel and what the renderer walks to produce the page. → Drag-and-drop hierarchy\nTree root\nThe renderer\'s entry point: takes the root node and mounts the walk, letting hosts (the editor, the published site) swap in their own trunk, stem, branch, or leaf implementations.\nTrunk\nThe first hop of the walk — renders the root node through the current stem. The editor substitutes its own trunk to add design-time behavior without touching the production renderer.\nStem\nThe per-node resolver: looks up a node\'s componentId in the component registry and renders it, recursing into the node\'s children.\nBranch\nRenders a node\'s children in order — the fan-out step between a parent node and its child stems.\nLeaf\nThe terminal wrapper that actually mounts a node\'s registered component with its resolved props. Each leaf tags its DOM with the node id, which is what the editor\'s selection and drag-and-drop hang on to.\nComponent\nA registered, renderable building block (button, section, product card…) a node can reference by componentId. Component ids are persisted in screen documents, so they are never renamed. → Besigner overview\nComponent bundle\nA named set of components a plugin registers together for the canvas — the base MUI bundle plus whatever featur' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Besigner (the editor)', anchor: '#besigner-the-editor', text: 'Besigner\nAglyn\'s visual designer — the editor where you build screens, layouts, and designed emails by composing the node tree on a live canvas. → Besigner overview\nCanvas\nThe live design surface inside the Besigner: your screen rendering for real, with selection, drag-and-drop, and inline text editing layered on top. → Besigner overview\nHierarchy panel\nThe tree view of the current screen\'s nodes — select, reorder, and reparent from the structure instead of the canvas. → Drag-and-drop hierarchy\nDrawer\nThe Besigner\'s component palette: registered components, presets, and installed marketplace components, ready to drag onto the canvas. → Besigner overview\nBinding\nA token in designed content that resolves to live data at render time — dataset fields, variables, page context. → Bindings' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Plugins & marketplace', anchor: '#plugins--marketplace', text: 'Plugin\nA self-contained feature package that extends the console, the Besigner canvas, the published site, or the server APIs — without touching core code. First-party features and marketplace submissions use the same system. → Plugins overview\nAdd-on\nThe user-facing word for optional capability on top of your plan — installed plugins and purchasable extras, managed from the Marketplace (Installed tab). → Plugins overview\nSurface\nThe part of the product a plugin registers into: the console client, the site (canvas + published pages), or the server tiers. A plugin declares which surfaces it provides. → Plugin manifest\nConsole extension\nEverything a plugin adds to the console shell — nav items and pages, dashboard cards, settings sections, widgets, providers. → Extension points\nWidget\nA plugin component rendered into a named shell zone (dashboard footer, org settings, listing detail…). → Injection zones\nInjection zone\nA named slot in the console shell that plugin widgets can target. The guaranteed zones are a typed catalog; custom zones are open strings. → Injection zones\nPlugin manifest\nThe generated loader table mapping plugin ids to their import entry points per app — the only sanctioned place plugins are referenced by the apps. → Manifest & envs\nEnabled plugins\nThe per-organization switchboard deciding which plugins load for a workspace. Enablement, plan entitlement, and release flags gate together. → Plugins overview\nFeature flag\nA plugin\'s plan-entitlement gate: the extension names the flag, and the shell only serves it when the org\'s plan (or overrides) grants it. → Billing & plans\nRelease flag\nA staff-controlled rollout switch (off / staff / percentage / on) evaluated per workspace — how features ship dark and roll out gradually. → Feature flags & releases\nPlugin ' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Data & logic', anchor: '#data--logic', text: 'Dataset\nA structured, org-scoped data collection with a typed schema — the backing store for dynamic content, forms, and commerce. → Datasets\nRecord\nOne row of a dataset. → Datasets\nField\nOne typed column of a dataset\'s schema. Plugins can register custom field types that ride on the built-in storage types. → Model builder\nRelation\nA link between datasets (reference fields), letting records point at records. → Relations\nContact\nA person captured into your workspace\'s audience — from forms, commerce, or manual entry. → Contacts\nSegment\nA saved filter over contacts, used to target campaigns and automations. → Contacts\nMedia library\nPer-site uploaded assets with folders, tags, CDN delivery, and generated variants. → Media\nVariable\nA named site-level value (text, number, toggle) referenced from bindings and logic — change it once, it updates everywhere it\'s used. → Bindings\nFunction (fx)\nA site-level computed expression — inputs, conditions, and operations that produce a value bindings can consume. Edited from the Besigner\'s ƒx panel and the Logic page. → Bindings\nForm\nA designed input block on a published page whose submissions flow into the forms pipeline (and from there to contacts, workflows, and notifications). → Forms' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Automation & marketing', anchor: '#automation--marketing', text: 'Event\nSomething that happened on a site or in the workspace — a form submission, an order, a booking — that automations and workflows can react to. → Workflows & actions\nWorkflow\nA configured sequence of actions that runs when its trigger event fires, with run logs to audit each execution. → Build a workflow\nAction\nOne step inside a workflow — send an email, call a webhook, update a record. → Actions builder\nAutomation\nClient-side reactive behavior on the published site (show, hide, trigger on visitor activity), configured in the marketing tools and executed by the site runtime. → Marketing overlays\nOverlay\nSite-wide attention elements — the announcement bar (persistent top strip) and the popup (triggered by delay, scroll, or exit intent, with optional email capture). → Marketing overlays\nExperiment\nAn A/B test on a screen: visitors are assigned variants and engagement is tracked so a winner can be promoted. → Marketing overlays\nEmail campaign\nA one-off or automated email send to contacts or a segment, with delivery and engagement tracking. → Email campaigns\nDesigned email\nAn email document built in the Besigner — the same node tree, rendered to email-safe markup. → Designed emails\nMerge tag\nA personalization token in an email or overlay ("first name", "order total") resolved per recipient at send time. → Email campaigns' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Commerce', anchor: '#commerce', text: 'Commerce\nThe commerce plugin family: catalog, storefront components, cart and checkout, orders, discounts, and analytics. → Commerce\nProduct\nA sellable catalog item — physical, digital, or service — with variants, pricing, and inventory. → Catalog\nOrder\nA completed purchase with its line items, payment state, and fulfillment history. → Commerce\nPOS\nPoint of sale — in-person checkout from the console against the same catalog and inventory. → POS & reservations\nBooking\nA scheduled appointment or reservation taken through the bookings plugin\'s services, availability, and slots. → Bookings' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Billing & plans', anchor: '#billing--plans', text: 'Plan\nThe subscription tier an organization is on. Entitlements resolve from the plan at read time; workspaces without a plan run dark-launch (ungated). → Billing & plans\nEntitlement\nA capability or limit granted by the plan — feature switches and quotas — optionally overridden per organization by staff. → Billing & plans\nQuota\nA numeric entitlement (sites, datasets, storage) checked at the point of use, with warnings as you approach the limit. → Billing & plans\nSeat\nA team-member allowance. Plans include seats; addon seats can be purchased up to a per-plan maximum. → Teams & roles\nMetered usage\nConsumption billed monthly in arrears (storage, delivery) with a live estimate shown before it lands on an invoice. → Billing & plans' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: '', anchor: '', text: 'Contacts CRM\nThe Contacts CRM is a single list of the people who interact with your site. Aglyn builds it automatically from everything they do, so you always have an up-to-date view of your audience.\nRolling out The Contacts page in the console isn\'t available yet — it\'s a release-flagged feature being finished for Contacts CRM v1, so there\'s no Contacts tab in your workspace and nothing to switch on.\nCapture is already running, though. Contacts are ingested from forms, member sign-ups, orders and bookings today, and you can read them over the REST API in the meantime — nothing is lost while you wait. Audience-band overage is not billed while the page is unavailable.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'Unified ingestion', anchor: '#unified-ingestion', text: 'Contacts are ingested from across your site:\n- Form submissions\n- Site members (sign-ups)\n- Orders from commerce\n- Bookings from scheduling\nDuplicate signals from the same person are unified into one contact.\nEvery tier includes an audience band — a number of contacts. Only the Free tier\'s band is a hard limit; paid tiers never drop a record, and growth past the band meters as overage. That overage is not billed while the Contacts page is unavailable. See Billing & plans.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'The contacts page', anchor: '#the-contacts-page', text: 'Once the page is switched on, it will let you:\n- Browse the list of contacts.\n- Open a profile drawer to see a contact\'s details and history.\n- Add tags and notes.\n- Export to CSV.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'Segments', anchor: '#segments', text: 'Group contacts into segments — reusable audiences you can target directly in email campaigns.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'Related', anchor: '#related', text: '- Email campaigns\n- Forms & lead capture' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: '', anchor: '', text: 'Import & export\nDatasets round-trip through CSV and JSON, so you can edit data in bulk elsewhere and bring it back.\nPlan availability Starter and above (datasets need the data store).' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Export', anchor: '#export', text: 'Export a dataset\'s records to CSV or JSON — useful for backups, bulk edits in a spreadsheet, or moving data into another tool. The CSV and JSON buttons on the data toolbar export the whole dataset, not the page of records currently on screen.\nWhat you get {#export-contents}\n- Every record, in a stable order that is the same on every export of the same data.\n- Every field in the model, in model order — the CSV\'s header row is the field ids, and the JSON is an array of objects keyed by the same ids. A field with no value comes out empty rather than being omitted.\n- Values in their portable form, which is the form the importer reads back: dates as ISO-8601, coordinates as latitude, longitude, lists and references comma-joined, and map fields as JSON. That is what makes the round-trip lossless.\nThe file is named after the dataset. Nothing is filtered out — a search or sort you have applied in the table does not narrow the export.\nLarge datasets {#large-exports}\nThe server streams the file rather than assembling it in your browser, so the size of the dataset is not the limit it used to be. Two things follow:\n- The button reads Exporting… while it runs. A large dataset takes a while; leave the page open until the download starts.\n- The download is checked before it is saved. The server states how many records it is sending, and if fewer arrive — a dropped connection mid-transfer — the export is refused with "Export incomplete" and nothing is saved. Run it again. A short file is otherwise perfectly well-formed and gives you no way to notice it is short.\nRecords added while an export is running may or may not be included; the count is taken when the export starts.' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Import', anchor: '#import', text: 'Import CSV or JSON back into a dataset. Imports are validated against the model on the way in, so malformed rows are caught rather than silently corrupting your data.\nUpsert on a key field\nPick a "Match on field" in the import dialog to de-duplicate: rows whose key value (say, an email) matches an existing record update it in place instead of appending a duplicate, and repeated keys within the same file collapse to the last row. Only genuinely new rows count against your record limit.' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Tips', anchor: '#tips', text: '- Export first to get the exact column shape, edit that file, then re-import.\n- Keep reference fields pointing at valid record ids so relations survive the round-trip.' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Related', anchor: '#related', text: '- Build a data model\n- Relations' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: '', anchor: '', text: 'Build a data model\nA model is the shape of a dataset — its fields and their types. Records are validated against it, so your data stays clean.\nPlan availability Starter and above. Free plans have no data store; add-ons raise the dataset cap.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Define the model', anchor: '#define-the-model', text: '1. In Data, create a dataset and open the schema dialog.\n2. Add typed fields — text, number, date, reference, and more.\n3. Save. The model is stored on the dataset, and records are validated against it on the way in.\nDisplay name vs reference ID\nEvery field has two names:\n- Display name — the human label shown in the record editor, table headers, and anywhere the field appears. Rename it any time.\n- Reference ID — the stable key used in bindings ({{item.referenceid}}), form field mappings, and CSV import/export.\nWhen you create a field, the Reference ID auto-fills from the display name (for example, Roast preference → roastpreference). Edit it in the same dialog to set your own — handy when you want a short, code-friendly key that differs from the label. Once the field is created the ID is fixed: records, bindings, and forms all point at it, so it can\'t change without orphaning that data. Pick it deliberately, then rename the display name freely afterward.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Edit records', anchor: '#edit-records', text: 'Open the typed document editor to add and edit records. Each field renders the input for its type (a date picker for dates, a number field for numbers, and so on), which keeps data consistent.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Tips', anchor: '#tips', text: '- Model the data first, then bind it — a clean model makes repeatable components and bindings straightforward.\n- Give fields a description in the schema dialog — it appears as a hint in the record editor, as a tooltip on table headers, and under the field\'s name in the schema dialog itself. See naming & describing fields.\n- Use a reference field to link records; see relations.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Related', anchor: '#related', text: '- Relations\n- Import & export\n- Datasets overview' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: '', anchor: '', text: 'Datasets & Dynamic Content\nDatasets are your structured content: a typed model plus the records that fill it. Screens read from datasets to render dynamic, repeatable content, and forms write new records back in.\nDatasets belong to your organization, not to a single site — every site in the organization shares the same collections. Manage them from the organization Data page (next to Media in the organization tabs), or from any site\'s Data page; both edit the same data. Dataset limits, storage, and add-ons are billed at the organization level.\nPlan availability Starter and above. Free plans have no data store; higher tiers raise the dataset and record caps, and extra-dataset add-ons are available.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Model builder', anchor: '#model-builder', text: 'Define a model in the schema dialog with typed fields (text, number, date, reference, and more). The model is stored on the dataset itself, and records are validated against it on every server-side write.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Typed documents', anchor: '#typed-documents', text: 'Edit records in the typed document editor — each field renders the right input for its type, so data stays clean.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Relations', anchor: '#relations', text: 'Fields can reference other records, including many-to-many relations, letting you model real structures (posts ↔ authors, products ↔ categories).' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Query layer', anchor: '#query-layer', text: 'A dataset query layer powers both the editor and screen bindings, so the same data is available to design-time previews and the live site.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Repeatable components', anchor: '#repeatable-components', text: 'Bind a component over a dataset to repeat it per record — a list, grid, or gallery driven by your data. The Besigner shows a repeat badge so you know a component is data-driven.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Who a dataset is shared with', anchor: '#who-a-dataset-is-shared-with', text: 'Datasets belong to the workspace, not to a single site, so one dataset can drive pages on every site you run. When that isn\'t what you want, the Sharing control on each dataset decides which sites can see it:\n- All sites — everyone in the workspace, on every site. The default, and what every existing dataset already uses.\n- This site only — the dataset is usable on one site and invisible everywhere else.\n- Selected sites… — pick the sites that share it, up to 30.\nThis matters most for agencies. If you run three internal sites alongside twelve client sites, your rate card can be shared with the internal three and stay invisible to the clients — including to the client collaborators you have invited, who will not see it in the Data page, the pickers, or anywhere else.\nSharing is enforced on the server, not just in the console. A site cannot render a dataset it hasn\'t been shared with even if a page explicitly asks for it by name.\nA few consequences worth knowing:\n- Narrowing sharing can empty a live page. If a published page repeats over a dataset and you remove that site, the page renders with no rows. The console warns before saving a change that takes a site\'s access away.\n- Reference fields need both sides. A reference from one dataset to another only resolves on sites that can see both, so the target\'s sharing has to cover the source\'s.\n- Limits are workspace-wide. Your dataset and record allowances count everything the workspace owns, whether or not you can see it all. Sharing decides visibility, not billing.\n- Deleting is a workspace action. A dataset shared with more than one site can\'t be deleted from a single site\'s Data page — narrow its sharing instead, or delete it from the workspace Data page.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Import & export', anchor: '#import--export', text: 'Datasets round-trip via CSV and JSON: export your records, edit them elsewhere, and re-import with validation on the way in.\nA whole-site export includes the datasets and media that site can see, and nothing else — an agency exporting a client site gets that client\'s data only. On restore, everything comes back shared with the site you restored into, not with whatever it was shared with before. Widen it afterwards if you meant to share it. That direction is deliberate: a bundle can be restored into a different site or a different workspace entirely, and quietly re-publishing one client\'s data across another\'s sites would be far worse than an extra click.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Related', anchor: '#related', text: '- Forms & lead capture\n- Bindings, variables & functions\n- Content collections & blog' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: '', anchor: '', text: 'Relations\nReal data is connected — posts have authors, products have categories. Relations let a record reference other records.\nPlan availability Pro.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Reference fields', anchor: '#reference-fields', text: 'Add a reference field to a model to point at records in another dataset (or the same one). For example, a post can reference its author.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Many-to-many', anchor: '#many-to-many', text: 'Relations support many-to-many, so a record can link to several others and vice versa — a product in many categories, each category holding many products.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Using relations', anchor: '#using-relations', text: 'The dataset query layer resolves related records for both the editor and screen bindings, so you can render a record together with the things it links to.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Tips', anchor: '#tips', text: '- Point references at a stable model — renaming fields is safe, but restructuring a related model affects everything that references it.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Related', anchor: '#related', text: '- Build a data model\n- Import & export' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: '', anchor: '', text: 'Events Calendar\nThe Events Calendar is a schedule your workspace edits in the console and your visitors read on the site. Each event carries a time, a place, an organizer, a description and a cover image, and stays invisible until you publish it.\nPlan availability Add-on. The Event Calendar is a flat monthly add-on that covers the whole workspace on any paid plan — buy it on Billing → Add-ons (see Add-ons). Until it\'s enabled the Events page explains the add-on, and the Event List element renders nothing on your site.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Manage events', anchor: '#manage-events', text: 'The console Events page lists your site\'s events, newest start first. Add event opens the editor; each event has:\n- Title — required.\n- Starts and Ends — a start time is required; leaving the end blank (or setting it before the start) gives the event one hour.\n- Location and Organizer — both optional, and both shown next to the date.\n- Cover image URL — optional thumbnail, shown beside the event.\n- Description — optional detail paragraph.\nSet published / Set to draft flips an event\'s status, shown as a chip in the list. Delete removes an event from your site.\nDrafts never leave the console The public listing filters to published events on the server, so a draft is never sent to a visitor\'s browser — it\'s a safe place to stage next month\'s schedule.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Show events on a screen', anchor: '#show-events-on-a-screen', text: 'Events reach visitors through the Event List canvas element (Data display category) — drop it on any screen in the Besigner and set:\n- Heading — a title above the list; empty hides it.\n- Show — Upcoming (default) or Past events.\n- Max items — how many to render (default 10).\nUpcoming lists the next events by start time; past lists the most recent first. The list is served through the public events API and cached briefly at the CDN, so a newly published event can take about a minute to appear.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Search engines', anchor: '#search-engines', text: 'Every rendered event emits schema.org Event JSON-LD — name, start and end, place, organizer, description and image — so search engines can show your events as rich results. Nothing to configure; see SEO for the rest of your site\'s structured data.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Related', anchor: '#related', text: '- Add-ons\n- Bookings & scheduling\n- SEO & structured data' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: '', anchor: '', text: 'Forms & Lead Capture\nForms let visitors send you information — contact requests, sign-ups, lead capture. Submissions land in your inbox and can flow straight into a dataset and your contacts CRM.\nPlan availability Free for basic forms and the inbox. Higher tiers raise submission and dataset caps.' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Reading submissions from code', anchor: '#reading-submissions-from-code', text: 'Everything on this page describes the console inbox. The same submissions are available over the REST API — list them, mark each one read as your integration processes it, and delete them once they\'re archived elsewhere. That read flag is what stops a nightly sync from pushing the same lead twice.\nSee Form submissions in the API reference, or start from Your first API call.' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Build a form', anchor: '#build-a-form', text: '1. Drop form components onto a screen in the Besigner (fields, submit button).\n2. Configure the fields and the submit behavior.\n3. Publish — the form posts to Aglyn\'s submit API.\nPer-visitor rate limit Submissions are capped at 10 per minute per site, per visitor address. A visitor over the limit gets a short retry delay, not a permanent block. It\'s per address, so one spammer can\'t lock out everyone else — but bulk-importing through your own public form will trip it. Use datasets for imports instead.\nThat per-address limit is one of several protections in front of your form — see Spam and abuse protection.\nMonthly allowance per plan\nEach tier includes a monthly form-submission allowance, counted per site:\n| Plan | Submissions / month |\n| Free | 20 |\n| Starter | 200 |\n| Pro | 1,000 |\n| Business | 10,000 |\n| Scale | 50,000 |\n| Advanced | 100,000 |\n| Agency & Enterprise | Unlimited |\nOn Free, that allowance is a hard wall: at the cap, further submissions are declined — the visitor sees the form\'s error message rather than a fake success. On every paid tier it is a band, not a wall: submissions past the included count keep working and bill as metered overage, the same way storage and API requests do, because a dropped submission is a lost lead. Either way the count resets with the calendar month (UTC), and the billing page\'s usage meters warn you at 80% before you get there.\nUnlimited on Agency and Enterprise means exactly that about the plan: nothing meters your submission volume and nothing cuts you off for buying too small a tier. It is not a promise that the endpoint will take any number of requests from anyone — every site, on every plan, sits under the anti-abuse ceiling below.\nA single submission can carry up to 20 fields and about 10 KB of text — plenty for any rea' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Spam and abuse protection', anchor: '#spam-and-abuse-protection', text: 'A published form is a public endpoint on the open internet — that is the point of it. Three things stand in front of it, and none of them asks your visitors to prove they are human:\n- A honeypot field. Every Aglyn form carries an input that humans never see and never fill. A bot that fills it in gets an ordinary-looking success and nothing is stored — it learns nothing and keeps wasting its time.\n- A per-address rate limit. The 10-per-minute limit above, enforced across all of our servers rather than per instance, so it still holds when traffic is spread out.\n- A per-site monthly ceiling. Below.\nThere is deliberately no CAPTCHA and no attestation check on the submit endpoint. A challenge in front of a lead-capture form is paid for by every real visitor so that a bot doesn\'t get through, and it costs conversions. Whether that trade is the right one is an open question we have not settled — see Trust & security for the same statement from the reviewer\'s side. Until it changes, the ceiling is what bounds the damage.\nThe per-site monthly ceiling\nSeparate from your plan allowance, each site has a monthly ceiling on how many submissions the endpoint will accept at all. It is abuse containment, not a quota: you are not metered against it, it is not something to plan capacity around, and no legitimate site reaches it. It sits at ten times your plan\'s included allowance, or 5,000, whichever is larger — and at 1,000,000 on the unlimited tiers — so it is always far above the volume you actually bought.\nIf a site does cross it:\n- Further submissions are refused for the rest of the calendar month, and a refused submission is not billed. It is turned away before the billing counter moves, so a flood cannot add anything to your invoice — not even the part that was refused.\n- Nothing i' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Field types', anchor: '#field-types', text: 'Each Form Field has a type that controls what visitors see and what is submitted:\n| Type | Visitor sees | Submitted value |\n| Text (default) | Single-line input | The text |\n| Email | Email input | The address |\n| Multiline | Multi-row text area | The text |\n| Dropdown | Select menu | The chosen option |\n| Radio choice | One radio button per option | The chosen option |\n| Checkboxes | One checkbox per option | All ticked options, joined with , |\n| Star rating | Five stars | The number of stars (e.g. 4) |\nDropdown, radio, and checkbox fields take their choices from the field\'s Options setting — enter one choice per line (or separate them with commas). Blank entries are ignored. The Required? switch works per type: a required checkbox group needs at least one box ticked.\nLabels and placeholders\nEvery field has a Label — the visible name of the input, and the one screen readers announce. A field can also carry a Placeholder: a grey example inside the empty input, such as you@company.com or "Tell us about your setup". Set one and the label moves above the box so both are readable at once; leave it empty and the label keeps its floating behavior.\nA placeholder is a hint, never a substitute for the label — it vanishes the moment a visitor starts typing, and a field labeled only by its placeholder is unusable with a screen reader. Text, email, and multiline fields show it inside the input; a dropdown displays it until a choice is made; radio, checkbox, and rating fields ignore it. Clearing the setting removes the hint.\nExample: a quick survey\nBuild a feedback survey with four fields:\n1. A Star rating field named satisfaction, labeled "How satisfied are you?".\n2. A Radio choice field named visit-frequency with options First time, Monthly, Weekly.\n3. A Checkboxes field named top' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'After submit', anchor: '#after-submit', text: 'The form\'s After submit setting controls what a successful submission does:\n| Outcome | What the visitor sees |\n| Show the success message (default) | The form is replaced by your Success message |\n| Redirect the visitor | The browser navigates to a screen you pick (rename-safe — slug changes never break it) or, with no screen picked, to a Redirect URL (a same-site path like /thanks or an https URL; anything else is ignored) |\n| Reveal a hidden element | An element you pick from the canvas — hidden on the published page until then — appears in place of the form |\nFor the reveal outcome, drop the follow-up content (a thank-you block, a download link, an embedded video) anywhere on the screen, then select it as the Element to reveal. It stays hidden for visitors until the form is submitted; in the Besigner it stays visible so you can keep editing it. If a redirect target can\'t be resolved (the screen was deleted, the URL was rejected), the form falls back to the success message.\nExample: grow an email list from a signup form\nCombine an outcome with a conditional automation:\n1. Add a Checkboxes field named subscribe with one option, Yes, keep me posted.\n2. Set After submit to Redirect the visitor and pick your /thanks screen.\n3. On the Workflows page, add an action on formSubmission with the condition "A field is not empty" → subscribe and the step Enroll in a list, picking your email audience.\nVisitors who tick the box are added to the list (and can be targeted by email campaigns); everyone lands on the thank-you page.\nNeed a finer net? Conditions chain with AND/OR — e.g. enroll only when subscribe is ticked and plan equals Pro, or when either of two topic boxes is ticked.' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Where submissions go', anchor: '#where-submissions-go', text: '- Inbox — every submission is captured; open it in the console\'s mail reader dialog.\n- Datasets — bind a form to a dataset (Write to dataset on the Form element) and each submission is also appended as a record. The inbox always gets its copy, and each submission\'s own detail dialog carries chips saying where it went — including saying nothing about a dataset when the record wasn\'t created.\n- Contacts — form submissions are one of the ingestion sources that build your contacts list.\nThe inbox\nThe site\'s Inbox page collects everything visitors send, in three tabs — Submissions, Members & leads, and Campaigns. The Form Submissions table reads as a list of people, not of forms: From, Message, Received, and the row actions.\n- From shows the sender — a colored initials avatar and their name, with the form name as a caption underneath (the Form element\'s Form name attribute, so name your forms distinctly: "Contact", "Newsletter", "Survey"). The avatar\'s color is derived from the name, so one sender keeps one color on every machine.\n- Unread submissions are bold with a dot at the left of the row. There is no "New" chip — bold text and a chip saying New are the same fact twice. Site managers also get an in-app notification per submission.\n- Received is relative — now, 18m, 3h, 2d, 4w, 7mo. Hover it for the absolute date and time; the detail dialog carries the absolute time too. An inbox is scanned for recency, and a locale timestamp makes you do the subtraction.\n- Click a row to read it — every field the visitor filled, labeled — and it\'s marked read; Mark unread puts it back.\n- Delete removes a submission permanently (it asks first).\nWho a submission is "from" {#who-a-submission-is-from}\nA form is yours to define, so there is no guaranteed name field. The sender is resolved fr' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Related', anchor: '#related', text: '- Datasets & dynamic content\n- Contacts CRM\n- Email campaigns' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: '', anchor: '', text: 'Media Library & CDN\nThe media library stores your images, video, and files, keeps them organized, and serves them quickly. Media plugs into components like Image and Video and into the theme\'s favicon.\nPlan availability Free with storage quotas. CDN delivery with WebP variants is on every plan, free included; large video uploads and higher storage are gated by plan.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Organize', anchor: '#organize', text: '- Arrange media in a folder hierarchy. Folders appear as cards in the grid (folders first, before files) as well as in a side rail — open one to browse into it, and use the breadcrumb to step back out.\n- Drag and drop to reorganize: drag a file (or a whole selection) onto a folder to move it in, drag a folder onto another to nest it, or drop onto a breadcrumb to move items up and out. Nesting depth and name-collision rules are enforced automatically.\n- Move to folder… shows the full path, not just the folder name — Blog / Covers and Press / Covers are two different destinations and the menu says so. The same paths appear in the detail drawer\'s Folder field.\n- Big moves are safe to interrupt. Moving a large selection relocates the stored objects one at a time, so the library keeps working through it and tells you how far it has got. If it cannot finish everything, it reports the real split — Moved 7 of 19 — 12 could not be moved — and leaves the files that did not move selected, so clicking Move again picks up exactly where it stopped. Nothing is lost either way: a file is only ever in one folder, its URL keeps working, and a repeat move of a file that already arrived does nothing.\n- Filter by type, date, and size, search, and sort the library.\n- Search covers everything you authored, not just file names — alt text, description, tags, folder name and your own custom metadata values are all searchable. Results update as you type, and ✕ (or Esc) clears the box.\n- Wildcards: mock--noshadow.png matches a whole family of files. is any run of characters, ? is exactly one, and a wildcard pattern matches the whole value.\n- Search one field: tag:hero, name:logo, alt:product, desc:landing, folder:brand, or a custom field by key — meta.campaign:spring. Combine them with plain words' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Upload', anchor: '#upload', text: '- Upload images, video (MP4, WebM, QuickTime), PDFs, ZIP archives and documents (Word, Excel, PowerPoint, CSV, RTF, plain text, Markdown and JSON). Click Upload media, or drag files straight from your desktop onto the library — dropped files land in the folder you have open.\n- Documents and archives are stored and served exactly as you uploaded them — nothing is opened, extracted or converted. Macro-enabled Office files (.docm, .xlsm, .pptm) are not accepted.\n- Rename, replace the file behind an asset, and edit images in place. Replace is available from the asset\'s details drawer and straight from the card\'s overflow menu.\nSize and plan limits\n| Upload | Cap | Plan |\n| Images | 15 MB per file | Every plan |\n| PDFs | 25 MB per file | Pro and above |\n| Documents (Word, Excel, CSV, RTF, text, Markdown, JSON) | 25 MB per file | Pro and above |\n| Presentations (PowerPoint) | 50 MB per file | Pro and above |\n| ZIP archives | 50 MB per file | Pro and above |\n| Video | 200 MB per file | Pro and above |\nAny file over 3 MB automatically uses signed-URL uploads, so big files go straight to storage without tying up the console. Folders nest up to 5 levels deep.\nUploads are checked for what they are — but not scanned for malware\nEvery upload is checked structurally before it is stored:\n- the bytes have to match the type the file claims to be, so a program renamed invoice.pdf is refused rather than stored and served from your domain;\n- programs and installers are refused under any file type or name;\n- a Word, Excel or PowerPoint file carrying macros is refused, including one renamed from .docm to .docx.\nA refused upload names the reason in the message that appears in the library, and nothing is stored or counted against your storage.\nThis is not a virus scan. These checks establish t' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Deliver over CDN', anchor: '#deliver-over-cdn', text: 'Every plan serves media via a CDN with automatic WebP variants, so images load fast and cache well.\nURLs are stable\nA media URL is keyed to the asset, not to its bytes or its location. That means the link you copied stays correct when you:\n- Replace the file — every screen, layout, and content entry that embeds it serves the new image immediately, with no re-linking.\n- Move it between folders — organizing your library never breaks a live page.\nSo replacing a logo across a whole site is one upload, not a hunt for every reference. Links copied before this behavior shipped keep working too.\nPage elements point at the asset, not at a link\nWhen you place an image with Browse media, the element records which asset you chose rather than a link to it. You never have to copy or paste a path, and the element keeps working through folder moves, file replacements, and any future change to how we deliver media. Copy URL is still there for pasting a link somewhere outside Aglyn.\nYou can also type any external image URL into the field by hand — useful for hotlinking an image hosted elsewhere. Images placed before this shipped keep rendering exactly as they did.\nWhat hotlinking means for your visitors {#hotlinking-and-your-visitors}\nHotlinking is a supported feature and we do not intend to remove it, but it has a consequence worth knowing before you rely on it: your visitor\'s browser fetches that file from that host directly, and we do not proxy it. Aglyn never sits in the middle of the request, so the host you named receives the visitor\'s IP address, their browser user-agent and the address of the page they are reading, and it can set its own cookies on them.\nThat makes it your choice rather than ours, and it follows that:\n- The host is not on Aglyn\'s subprocessor list, and it never w' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Who an asset is shared with', anchor: '#who-an-asset-is-shared-with', text: 'Workspace media is shared across every site by default. The Shared with control narrows that, with the same three choices as datasets — All sites, This site only, or Selected sites…. You\'ll find it in three places:\n- on a single asset, in its details drawer;\n- on a selection — tick several files and use Shared with… in the toolbar;\n- on a folder, from its ⋮ menu, which offers to apply the same sharing to the files inside it and its subfolders (it names the count, so you know what you\'re about to change).\nA folder applies its sharing when you save it — files keep their own setting afterwards, so moving a file into a "Client A" folder later does not re-share it. Narrowing a file that sites are already using names those sites first and asks you to confirm. Only workspace owners and admins can change sharing.\nA new folder starts shared with All sites, so it appears everywhere the moment you create it — or with the site you were working in, if your workspace has been set to make new resources site-scoped by default. That default is Default sharing for new data and media, at the top of the workspace\'s Media page; it applies to new datasets as well as new files, and changes nothing that already exists. If the Shared with dialog ever opens on "Not shared with any site", that folder or file has no sharing stored at all: it is hidden from every site, and any file inside it turns up under No folder there. Pick a value and save to fix it.\nIn the media picker\'s Organization (shared) tab, a site sees only the assets it may use. An agency\'s internal artwork stays out of the client sites\' pickers entirely.\nSharing controls discovery, not secrecy Sharing decides which sites may find and use an asset, and stops the CDN serving a restricted asset to a site it isn\'t shared with. It does no' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Private files', anchor: '#private-files', text: 'Private is a separate switch from sharing, and it answers a different question:\n| | Question it answers |\n| -- | -- |\n| Shared with | Which of your sites may use this file? |\n| Private | May anyone fetch these bytes at all? |\nA private file:\n- has no public URL — the normal media link does not exist for it, and Copy URL is hidden on it in both the card menu and the drawer,\n- loses any public URL it already had. Turning Private on revokes the file\'s public address at the moment you confirm it, so a link you copied and sent last month stops working too. That is the part people expect and the part that is easy to get wrong: a switch that only stopped new links would leave the one already in circulation serving the file forever,\n- cannot be placed on a page; the picker refuses it and says why,\n- is viewable and downloadable in the console by people who can already see it, through a temporary link that stops working after about fifteen minutes.\nTwo menu items do that last part, and they are not interchangeable:\n- Copy temporary link (organization library, organization-wide members) puts a fifteen-minute link on your clipboard — for handing to one person, once, now. Nothing in Aglyn renews it, so it is a trap in a document or a page: what you paste stops working while the page still looks fine.\n- Download file saves the bytes. Aglyn mints a fresh link for that click, so the expiry never reaches you.\nCopy URL being hidden rather than disabled is deliberate: there is no permanent address to hand over, and a copied link that 404s is worse than no button.\nThat expiry is the point. A normal media URL, once shared, works forever and there\'s no way to take it back. A private file\'s link dies on its own, so a link pasted somewhere it shouldn\'t have been is a short problem instead of ' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Approved image hosts', anchor: '#approved-image-hosts', text: 'Most images on your site are ones you uploaded here, and those always work. But you can also point a block at an image that lives somewhere else by pasting its URL — a photo on your own CDN, say, or an image your supplier hosts.\nThose are worth being deliberate about, for a reason that is easy to miss: when a visitor opens a page with an external image on it, their browser fetches that image directly from the other site. So that site sees your visitor\'s IP address and which page they were on, whether or not you have any relationship with them. It is a real disclosure, and it is one you are making on your visitors\' behalf.\nSo your site keeps a list of the external hosts it is allowed to load images from, under Admin → Security → Approved image hosts. Add a host and images from it load normally. Leave it off the list and browsers refuse it.\nYou do not have to think about this for anything you upload — your own media is always allowed, and so is your site\'s own address.\nAdding a host {#adding-an-approved-image-host}\nEnter the host on its own, with no https:// and no path:\n- cdn.example.com allows exactly that host.\n- .example.com allows every subdomain of it, which is what most image CDNs need because they give each account its own.\nIf you paste a URL into an image block for a host you have not approved, the editor tells you so while you are editing, rather than letting you publish a page whose image is blank for everyone but you. The warning names the host, so approving it is a copy and paste.\nWhen an image does not appear {#approved-image-host-troubleshooting}\nIf an image shows in the editor but not on the published page, an unapproved host is the first thing to check. Open the page, right-click the missing image, and the browser console will name the host it refused.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Reference', anchor: '#reference', text: 'The details behind the screens above, for anyone wiring media into their own code.\nVariant widths {#variant-widths}\nAglyn generates WebP variants at 320, 640 and 1280 pixels wide when an image is uploaded. Those three are the whole set — there is no arbitrary resizing service behind the CDN URL.\nAdd ?w= to a CDN URL to ask for one: …/api/media/cdn/org:{orgId}/{mediaId}?w=640. A width the asset does not have generated is not an error and not a resize — the original bytes are served instead, so a ?w=200 request answers with the full-size file. Check the drawer\'s delivery line to see which widths a given file has.\n?download=1 on the same URL makes the response save rather than open in a tab. Both parameters are read after every access check, so neither widens what is served, and both are part of the cache key, so they cannot bleed into each other.\nTag limits {#tag-limits}\nTags are stored lower-cased and de-duplicated. A tag longer than 40 characters is dropped, and a file keeps at most 20 tags — entries past the twentieth are dropped rather than replacing an earlier one.\nOver the API\nMedia is read-only over the REST API: file names, sizes, dimensions, tags, folders, and both URL forms. See the Media API resource, including what it does not return.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Components', anchor: '#components', text: '- Image — place and bind images from the library.\n- Video — embed uploaded video.\n- Favicon picker — choose the site favicon from your media.\nEverywhere you pick media — the Image and Video components, the logo and favicon pickers, and the organization logo field — the same media picker opens, with This site and Organization (shared) tabs so you can pull from either library without leaving the dialog.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Related', anchor: '#related', text: '- Bindings\n- SEO toolkit (Open Graph & Twitter images)\n- Media API resource — reading the library from your own code' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: '', anchor: '', text: 'Domain providers\nAglyn hands out hostnames. A workspace gets {slug}. , a published site gets {subdomain}. , and a customer can connect shop.acme.com of their own. Something has to make each of those resolve, and on a self-hosted install that something is not a hosting vendor\'s API — it is a driver you choose.\nThis page is the runbook. Environment variables is the per-variable reference for the same system; keep it open beside this one rather than reading one instead of the other. This page answers which driver, and what do I have to build; that page answers what does this variable do.' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: 'Which driver', anchor: '#choosing', text: 'Answer these about your own setup, in order. The first "yes" is your driver.\n1. Are you deploying to Vercel? → vercel. The two projects — console and tenant — are the driver\'s configuration.\n2. Do you intend to let customers connect their own domains? → webhook. This is the only driver on a self-host that can register a name you do not already own, because registering somebody else\'s shop.acme.com means touching your proxy, and only you know how to do that.\n3. Otherwise: does one wildcard DNS record and one wildcard certificate cover every name you serve? → wildcard. This is the ordinary Docker answer.\n4. Are hostnames handled entirely outside the product — a platform team\'s own DNS pipeline, or an install that only ever uses path routing? → none, or leave it unset.\nUnset, the deployment detects: vercel when VERCELTOKEN is present, none otherwise. An explicit value always wins, none included — switching a driver off while its credentials are still in the environment means it. An unrecognized value logs [domain-provider] unknown AGLYNDOMAINPROVIDER and falls back to detection, so a typo cannot silently disable domains.\nDetection never picks wildcard The wildcard driver reports a name as serving without checking anything — there is nothing to check, because your DNS record and certificate either cover the apex or they do not. Inferring it from an apex somebody merely configured would put a green chip beside an address that resolves nowhere. Claiming to serve a name is your assertion, so it takes your explicit setting.\nWhat each driver cannot do {#limits}\n| Driver | Cannot |\n| wildcard | Register a customer\'s own domain. No wildcard covers somebody else\'s apex. It also cannot see such a name to report on it, and cannot un-serve one of the names it does cover. |\n| webhook |' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: 'The `wildcard` path, end to end', anchor: '#wildcard', text: 'Four things have to be true, and the driver checks none of them — it takes your word for all four. Do them in this order.\nThe worked example below uses the shape .env.selfhost.example ships with:\n| Value | Serves | Container |\n| NEXTPUBLICCONSOLEURL=https://console.example.com | The console | 127.0.0.1:4200 |\n| NEXTPUBLICWORKSPACEDOMAIN=example.com | Workspace subdomains, {slug}.example.com | 127.0.0.1:4200 |\n| NEXTPUBLICTENANTDOMAIN=sites.example.com | Published sites, {subdomain}.sites.example.com | 127.0.0.1:4500 |\nNote that a workspace subdomain is served by the console container and a site subdomain by the tenant container. They are two wildcards pointing at two upstreams, not one.\n1. DNS {#wildcard-dns}\nOne record per apex you serve, plus the console\'s own name:\nAdd AAAA records alongside if you serve IPv6. If your proxy sits behind a load balancer with a hostname rather than an address, use CNAME for the wildcards and an ALIAS/ANAME for anything at an apex.\n2. Certificates {#wildcard-certificates}\nOne certificate per wildcard, and a wildcard certificate can only be issued over a DNS-01 challenge — HTTP-01 cannot prove control of a whole apex. That means your ACME client needs credentials for your DNS provider\'s API. This is the step that surprises people; budget for it.\nA wildcard covers exactly one label .example.com serves a.example.com. It does not serve a.b.example.com, and it does not serve example.com itself — and a certificate issued for .example.com covers exactly the same set.\nThis is why two apexes need two records and two certificates, and why the driver matches one label rather than "ends with the suffix". The looser test would report a.b.example.com as serving and your visitor would meet a TLS error before you did.\n3. The proxy rules {#wildcard-proxy' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: 'The `webhook` contract', anchor: '#webhook', text: 'Aglyn POSTs three operations to one endpoint you run and takes its word for the answer. What is behind it is entirely your business: Caddy\'s admin API, a Traefik dynamic-configuration file, a cert-manager Certificate, a registrar\'s API, or twenty lines of shell.\nThis is the extension point rather than a module path the app imports, because a module path does not survive the product: both apps are bundled by Next, so a path resolved at runtime is not in the bundle, and an operator running a built image has no build step in which to add one. A webhook needs no rebuild.\nPut this endpoint on your own network The request carries the bearer token and the names of your customers\' domains, and the reply decides whether the console tells someone their site is live.\nThe request {#webhook-request}\nPOST to your URL, with Content-Type: application/json and — only when AGLYNDOMAINWEBHOOKTOKEN is set — Authorization: Bearer . When it is unset the header is omitted entirely rather than sent empty.\n| Field | Values |\n| action | attach, detach or status. |\n| scope | console — the admin app, its workspace subdomains and any white-label console domain. tenant — published sites and customers\' own domains. |\n| domain | Always lowercased, trimmed, and with any trailing dot removed. |\n| redirectTo | Present only when the name should forward rather than serve. Always a bare hostname. |\nredirectTo is a registration, not a special case: create the name carrying the redirect, or point an existing entry at the target. Two things in the product send it — a site\'s platform subdomain forwarding to that site\'s custom domain, and the secondary names of a multi-name white-label console domain forwarding to the primary. Aglyn reduces the value to a bare hostname before the wire and refuses to send anythin' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: 'When no driver is configured', anchor: '#unconfigured', text: 'This is a supported state, not a broken one. A deployment can legitimately have names handled entirely outside the product, and the correct behavior there is silence rather than a failure logged on every signup forever.\nWorkspace subdomains. The attach returns skipped and the organization is created anyway — the console is path-routed and {console}/{slug} is the canonical form, so a workspace with no subdomain is fully usable. The console still advertises {slug}. , so that name has to resolve some other way or it will not load. The deployment says so once per process, not once per signup:\nA customer\'s custom domain. /api/domains/attach answers 501:\n> Domain attachment is not configured on this deployment (no domain provider —\n> set AGLYNDOMAINPROVIDER).\nThe same 501 is given whether there is no driver at all or a driver that does not manage this particular name — which is honest, because from the customer\'s side those are the same situation. The customer sees an info toast, the domain sits behind a red alert saying it is not attached, and a Retry attachment button that cannot succeed until the deployment can register the name.\nThe site serves anyway. The Firestore claim on the domain is written before the refusal, and the tenant runtime resolves an unrecognized hostname against that claim. So on wildcard or none:\n1. Point the customer\'s DNS at your reverse proxy.\n2. Route that hostname to the tenant container by hand.\n3. The site is served.\nWhat the refusal actually costs is the canonical redirect. A host carrying cnameAttachmentPending is not treated as having a live custom domain, so the platform subdomain keeps serving the site rather than forwarding to the custom domain, and both addresses serve the same pages until the flag clears.' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: 'Status states', anchor: '#status-states', text: 'attach answers "did the registration succeed", which is a weaker question than "is this name serving". A domain can be registered and serve nothing — ownership unproven, DNS not pointed, certificate not issued — and all three follow a perfectly successful attach. status is the question the console actually renders.\n| State | What it means | Visitors sent there? | Your move |\n| serving | Registered, routed, certificate covers it. | Yes | Nothing. |\n| certificate-pending | Accepted and routed, but no certificate exists yet, so the name answers with a TLS error. | No | Wait. If it never clears, look at your ACME client. |\n| ownership-pending | The provider is holding the name until a challenge record is added. verification carries the record and is shown to the customer. | No | The customer adds the record at their registrar. |\n| dns-misconfigured | The provider\'s own DNS check says the records do not point here. conflicts names foreign records answering for it. | No | Fix the records; remove any conflicting ones. |\n| not-attached | The name is not registered on this deployment at all. | No | Attach it — or find out which deployment holds it. |\n| skipped | No driver, or a driver that does not manage this name. | Yes | Nothing, unless you meant to manage it. |\n| unknown | The probe could not answer. | Yes | Nothing on its own. Look for a pattern. |\nWhy unknown counts as serving A status probe that could not answer is not evidence of a problem. Treating it as one would strand every live domain on a deployment whose driver has no status API to ask — which is most of them, wildcard included. The failure mode of the other choice is far worse: every customer\'s working site going dark in the console because your endpoint restarted.\ncertificate-pending is the one people expect to ' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: 'Migrating between drivers', anchor: '#migrating', text: 'Every domain variable is read at runtime, so switching drivers is an env change and a restart — not a rebuild. (NEXTPUBLICWORKSPACEDOMAIN and NEXTPUBLICTENANTDOMAIN are the exception, and you are not changing those here.)\nwildcard → webhook, to start selling custom domains {#migrating-webhook}\nThe usual move. Everything the wildcard covered still has to work afterwards, which is the part worth planning.\n1. Stand up the endpoint and test it with curl before Aglyn ever sees it — an attach, a status, and a detach against a throwaway name.\n2. Teach it your wildcard apexes. Once the driver is webhook, every name goes through it, workspace subdomains included. Those names are already served by your wildcard, so the endpoint should recognize them and answer already-exists for attach and serving for status, rather than writing a per-name route it does not need:\nAnswering skipped for them is also correct and costs nothing — it is what the wildcard driver itself did.\n3. Switch and restart:\n4. Re-attach the domains that were refused while you had no driver for them. Nothing does this for you: the completer cron only probes, so a domain that was never registered stays not-attached forever. Open each affected site\'s domain settings and press Retry attachment. New connections go through the new driver from the moment it is live.\nwebhook → wildcard, or to none {#migrating-down}\nSet the value and restart. Names your endpoint registered do not disappear — they are in your proxy\'s configuration, and Aglyn will simply stop asking about them. Customer domains outside your wildcard will start reporting unknown rather than a real state, and new ones will be refused with the 501 above.\nBe explicit rather than removing credentials: AGLYNDOMAINPROVIDER=none wins over a VERCELTOKEN that is still' },
  { path: '/developers/domain-providers', title: 'Domain providers', heading: 'Related', anchor: '#related', text: '- Self-hosting — the full runbook, including which addresses this install calls its own and the reverse-proxy rules.\n- Environment variables — the per-variable reference for everything on this page.\n- Custom Domains — what a site owner sees at the other end of all this.' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: '', anchor: '', text: 'Building feature plugins\nAglyn features that add both console surface and site components ship as a single library (AGL-277) — never merged into the core mui plugin, which stays purely component and theme definitions for the Besigner and hosts.\nPlugins live directly under libs/plugins/{feature} (moved out of the old .../ui/ nesting in AGL-395) and publish as @aglyn/plugins-{feature}. A plugin keeps its Besigner component, its console page, and both registration functions in the one lib — the console half is a separate registerConsole() export, so the shell can register nav + pages at app load without pulling in the Besigner canvas bundle.\nSharing app hooks. A relocated console page can\'t import console-app hooks. Genuinely reusable ones move into a shared lib the plugin can import — e.g. useFirestoreCollection, useFirestoreDoc, and useHostOrgId now live in @aglyn/tenant-feature-instance, and HubTabs in @aglyn/shared-ui-next (the app keeps thin re-export shims).\nReaching app-only UI (media browser). Some app UI can\'t move — the media library is coupled to the org/session context. Instead of importing it, a plugin consumes it through a context: MediaPickerContext / useMediaPicker() in @aglyn/aglyn exposes pickMedia(): Promise<PickedMedia\n| null>. The shell mounts the app\'s ConsoleMediaPickerProvider (which owns the real dialog) around every plugin page, so a plugin component just calls pickMedia() and gets the chosen asset — see the commerce product editor. This is the escape hatch for the dependency cascade a naive promotion would hit.' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'The UI half', anchor: '#the-ui-half', text: 'Build a bundle with defineUiFeatureBundle from @aglyn/aglyn (the plugin-manager registration API, AGL-415) and register it the same way the mui bundle registers itself. The bundle automatically declares a dependency on the mui bundle, so primitives and theming load first.\nComponent and bundle ids are persisted componentId and pluginId are stored in screen documents. Never rename them — when a component moves between bundles, keep the old ids resolving (the mui plugin\'s legacy-id aliases are the precedent).' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'The console half', anchor: '#the-console-half', text: 'Export a ConsoleExtension and register it at console startup. The console shell renders the nav items and their pages from the registry — and applies the featureFlag entitlement gate itself, so an extension can\'t bypass plans. A feature plugin adds a menu item to the host app bar and a new page without editing any core console file (AGL-394).\nA nav item that carries a Component becomes a full page: the shell\'s generic host route (apps/console/app/(app)/[orgSlug]/hosts/[host]/[...pluginSlug]/page.tsx) mounts it under the active host, wires the breadcrumb/header, resolves the featureFlag entitlement, and passes it in as entitled.\nThe page component receives ConsolePluginPageProps — { hostId, entitled, org, permissions, releaseFlag, basePath, sections, section, segments } — so it stays free of console-app hooks. org is the resolved org billing doc the shell already loaded, so the page can run its own checkEntitlement/checkQuota (e.g. per-plan limits) without the app\'s org/session hooks:\nHow the shell consumes the registry\n1. apps/console/constants/register-console-plugins.ts calls each plugin\'s registerConsole() at import time; app imports it so the registry is populated before any nav renders. This registers only the console half — never the Besigner canvas bundle — so plugin canvas code stays out of the general console bundle.\n2. hostNavTabItems splices listConsoleNavItems() into the host tab strip. Nav gating is unchanged: an item\'s navTabId maps to a release flag, so staff still preview flagged-off surfaces. The strip itself is built by useSecondaryNav() from the current route and rendered once by app/(app)/layout.tsx — a plugin never passes tabs to a page, and pages have no nav props to set (AGL-754/755).\n3. The generic [orgSlug]/hosts/[host]/[...pluginSlug] route res' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Routed sections (AGL-2501)', anchor: '#routed-sections-agl-2501', text: 'A surface can be a hub of real URLs instead of a tab strip. Declare sections on the nav item and each becomes a route at ${href}/${section.id}:\nThe shell resolves the URL and hands the page back:\n- section — the id the URL names, or undefined on the surface\'s own href. It is always one of the declared ids: the shell 404s an id it does not recognize rather than falling back to the first section, so the page needs no branch for a section it does not have.\n- sections — the declared list with an absolute href per section and the release verdict already applied to visible. Feed it straight to HubSections; a plugin cannot compute visible itself, because release flags live in scope:app.\n- basePath — the surface\'s absolute path, e.g. /acme/hosts/shop/products.\n- segments — everything beneath basePath. segments[0] is section; anything after it belongs to the section, so a section may own deeper routes (…/orders/ord123) without another registry change.\nThe surface\'s own href (/products) names no section. Redirect it to the first visible one rather than rendering that section in place — rendering it would pay for its reads on a URL that is about to be replaced.\nWhy routes rather than tabs. A tab strip mounts every panel, so every panel\'s Firestore listens open on load and the reader is looking at one of them. The commerce console was the worst case: one load issued 32 listens with a ceiling of 4,462 documents to render one tab. A URL per section makes "mount only what is open" structural instead of a flag somebody has to remember — and a section becomes linkable, the back button walks sections, and which one is open is a fact about the URL rather than state kept in sync with it.\nsections is optional, and omitting it is not a lesser option — it means the surface is one page. A nav ' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Loading: org-gated and dynamic (AGL-417)', anchor: '#loading-org-gated-and-dynamic-agl-417', text: 'Apps never import @aglyn/plugins-. plugins.config.json maps plugin ids to packages and register entry points; tools/scripts/generate-plugin-manifests.mjs emits the per-app loader manifests (plugins..generated.ts) — the ONLY sanctioned plugin references outside libs/plugins (an nx scope:app boundary rule enforces this). At runtime the core plugin loader activates the plugins in org.enabledPlugins (AGL-416, org settings → Plugins): console surfaces behind the providers gate, site/canvas surfaces behind the editor/tenant suspense gates, API handlers lazily on first dispatch with a per-request org gate (a disabled plugin\'s API 404s for that workspace).\nEach first-party plugin is additionally release-flagged (AGL-422, FirstPartyPlugin.releaseFlag): a flag staff turn off in the console Feature Flags page subtracts the plugin from every workspace\'s effective set — nav, editor, published sites, and API — with the usual staff preview bypass. Register a flag for any new plugin (registry + Remote Config template + the catalog entry).' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Extending beyond pages: slots, providers, runtimes, hooks (AGL-418/419)', anchor: '#extending-beyond-pages-slots-providers-runtimes-hooks-agl-418419', text: '- Widgets — ConsoleExtension.widgets render into named shell slots via the app\'s PluginWidgetSlot. The guaranteed zones (and the props each receives) are the exported CONSOLEWIDGETSLOTS catalog (AGL-433): hostActivity, hostDashboard, commerceGlance, orgData, besignerFunctions, marketplaceListing, orgAddons, dashboardFooter, orgSettings, hostSettings, and the staff-only adminOrgDetail.\n- Providers — ConsoleExtension.providers mount around every console page (e.g. marketplace\'s AI-assist provider).\n- Site runtimes — registerSiteRuntime components run on every rendered tenant page (marketing\'s overlays/experiments/automations), reading back the props their server enricher wrote.\n- Site-page hooks — /server entries register redirect resolvers, page resolvers (commerce PDP/PLP), and enrichers into the tenant loader.\n- Billing webhook hooks — registerBillingWebhookHandler receives the platform Stripe events (commerce orders, booking payments, marketplace purchases live in their plugins).\n- Permissions (AGL-435) — registerPluginPermissions([{key, label, defaults: {admin, editor, viewer}}]) contributes role-resolved keys: they ride every resolved permission set (ConsolePluginPageProps. permissions, API-side resolution), and custom roles override them key-by-key. Reference adopter: commerce\'s managePos.\n- Scheduled jobs (AGL-435) — registerPluginJob({pluginId, name, intervalMinutes, handler}) on the /server surface; the deployment\'s scheduler POSTs /api/plugins/run-jobs (shared PLUGINJOBSSECRET header, 501 when unconfigured) and due jobs run with error isolation. Keep handlers idempotent and bounded. Reference adopter: bookings\' expire-stale-holds.\n- Custom field types (AGL-434) — registerCustomFieldType({name, pluginId, label, baseType, Input, validate}) adds a named field type' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Remote bundles: the trusted realm tier (AGL-420)', anchor: '#remote-bundles-the-trusted-realm-tier-agl-420', text: 'Marketplace plugins normally run sandboxed in the cross-origin PluginFrame. Listings a staff member has reviewed and signed (trust: \'realm\' + an Ed25519 signature over the bundle\'s sha256 on the version doc) instead load INTO the app realm and use every registry above — first-party-grade extensions installed per workspace, no repo change.\n- Build with tools/plugin-loader/realm/rollup.config.mjs: your react, react/jsx-runtime, and @aglyn/aglyn imports compile to lookups on globalThis.AGLYNPLUGINHOST (the app\'s own singletons), so the emitted bundle imports nothing. Export register(host) for client surfaces; registerApi() for server handlers.\n- Publish through the marketplace pipeline, install (pins {version, sha256}), then staff grant trust via POST /api/admin/sign-plugin.\n- The console loads an org\'s realm installs before the shell renders; published sites load them post-hydration (additive runtimes — first paint never waits on a marketplace CDN). Every load verifies the sha256 pin and the platform signature and fails closed; revocations is the hard kill switch.\n- Server handler bundles are additionally gated by PLUGINREMOTESERVER=enabled + a per-deploy PLUGINREMOTESERVERBUNDLES allowlist, default off everywhere.\nFull trust chain, env matrix, and walkthrough: docs/PLUGINLOADING.md in the repo; a runnable demo lives at tools/plugin-loader/realm/demo.' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'The server half (API routes)', anchor: '#the-server-half-api-routes', text: 'A feature\'s server logic — Next.js API routes backed by firebase-admin — moves into its plugin the same way, through the API-route registry (AGL-396), the server counterpart to the ConsoleExtension registry.\nEach Next app ships one catch-all dispatcher that imports a server-only registration module (registerPluginApis()) and resolves the request path against the registry. Both apps are on the App Router (app/api/[...pluginApi]/route.ts, AGL-408/410); the same PluginApiHandler runs unchanged in either. The dispatcher runs the handler through the runLegacyHandler adapter (@aglyn/aglyn/server, AGL-407), which bridges the Web Request/Response to the framework-light (req,res) contract:\nNamed API routes win over the catch-all, so URLs are preserved: to migrate /api/events/list, delete the named route file and register the handler — the dispatcher serves the same URL. Import the plugin\'s /server entry only from the dispatcher\'s registration module (server code); the client barrel must never pull it in, or firebase-admin leaks into the browser bundle. Reference: libs/plugins/events-calendar/src/lib/server.ts.\nBoth Next apps carry a dispatcher. The tenant (site-facing) app registers via registerTenantPluginApis; the console (authoring) app has its own dispatcher + registerConsolePluginApis, and plugins expose a separate registerConsoleApi() for console-only handlers (staff/merchant ops, cron jobs) so each app registers only what it serves. A migrated route keeps its /api/... URL in whichever app owned it.\nRaw-body routes. On the App Router a handler reads the raw body directly (request.text()/arrayBuffer()), so webhooks (Stripe billing/webhook, Svix email/events) and size-capped uploads need no bodyParser config — the old Pages Router export const config exceptions are gone; byt' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Project setup', anchor: '#project-setup', text: 'Scaffold a new first-party plugin instead of hand-copying one (AGL-425):\nThat generates the complete libs/plugins/my-plugin library (correctly tagged, with register entries per surface and a passing spec), registers it in plugins.config.json + the tsconfig aliases, re-runs the manifest codegen, and prints the two manual follow-ups (catalog entry + release flag). Marketplace/marketplace authors start from tools/plugin-loader/realm/template instead — a standalone npm package that builds a host-ABI realm bundle.\nConventions the scaffold already applies:\n- Tag new plugin libs with exactly ["aglyn:addons"] — nothing else (AGL-409). This single tag is a plugin\'s whole module-boundary identity: as a dependency target no core scope\'s allowlist reaches it, so nx lint rejects any core lib importing @aglyn/plugins- (the app can run without the plugin). As a source, the aglyn:addons rule still lets a plugin import any lib and other plugins. Do NOT add scope:lib/scope:aglyn back — that reopens the hole (every lib carries scope:lib).\n- Plugins are wired in only through the generated loader manifests (plugins.config.json → plugins..generated.ts, AGL-417); core libs and app feature code must never import a plugin.\n- Plugin libs may import @aglyn/plugins-mui for primitives; nothing may import a feature plugin from @aglyn/plugins-mui (that direction is the anti-pattern this rule exists to stop).' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Reference implementations', anchor: '#reference-implementations', text: '- Events calendar (libs/plugins/events-calendar) — the reference: its whole console page lives in the plugin (AGL-313/394).\n- Bookings (libs/plugins/bookings) — the second full extraction (AGL-395): the booking canvas component moved out of plugins-mui and the bookings manager out of the app; the page reads plan limits via the org prop + checkQuota.\n- Redirects (libs/plugins/redirects) — a console-only plugin (AGL-395): redirects enforce server-side (ISR), not through a canvas component, so it exports only registerRedirectsConsole() and ships no UI bundle — nothing to register in the tenant/besigner. The minimal shape when a feature has console surface but no site component.\n- Logic (libs/plugins/logic) — console-only (AGL-395): variables + no-code functions and the reference-integrity audit. It also exports shared tooling — the where-used dialog and its fetch util, plus the variable/function cards — which the app\'s workflows surface and besigner ƒx button import from @aglyn/plugins-logic. Always-on (not release-flagged).\n- Contacts (libs/plugins/contacts) — console-only (AGL-395): the unified contacts list, segments, and profile drawer. A whole self-contained page relocated with just the layout wrapper + inline FeatureGate stripped (the shell supplies both); reads the contactsPerHost quota off the org prop.\n- Inbox (libs/plugins/inbox) — console-only (AGL-395): form-submissions reader, site members + leads, and the borrowed Orders and Campaigns tabs. Depends on @aglyn/plugins-commerce + @aglyn/plugins-email — a plugin can compose tabs from other plugins the same way the app did.\n- Marketplace (libs/plugins/marketplace) — console-only, multi-page (AGL-395): the plugin owns the hub page and its cards + useMarketplaceActions, but the listing/publisher detail pages stay as' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: '', anchor: '', text: 'Console extensions & site surfaces\nTask-ordered recipes; the deep semantics live in Building feature plugins and the API reference.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a console page', anchor: '#add-a-console-page', text: '1. Export a registerConsole() that calls registerConsoleExtension with a navItems entry carrying a lazy Component.\n2. The shell serves it at /[hostId]/ , wires breadcrumbs/header, resolves the featureFlag entitlement, and passes ConsolePluginPageProps { hostId, entitled, org, permissions }.\n3. Need data? Use @aglyn/tenant-feature-instance hooks (useFirestoreCollection, usePluginConfig, …) — never console-app hooks.\n4. First-party: add the register fn to your plugins.config.json entry under console and re-run the manifest codegen (the scaffolder did both if you used it).' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a widget to a shell zone', anchor: '#add-a-widget-to-a-shell-zone', text: 'Pick a zone from the catalog, then:\nYour component receives the zone\'s documented props. Multiple plugins can target one zone; the shell renders all of them.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Wrap every console page (providers)', anchor: '#wrap-every-console-page-providers', text: 'providers: [MyProvider] mounts around every console page once the registry is populated — the marketplace plugin\'s AI-assist provider is the reference. Providers receive the org billing doc as tenant.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a canvas component (Besigner + published sites)', anchor: '#add-a-canvas-component-besigner--published-sites', text: 'Use defineUiFeatureBundle on your site surface — components get schemas + presets and appear in the Besigner drawer. Component ids are persisted in screen documents; never rename them. The editor and the published site both suspend until your site surface registers, so the canvas never renders unregistered components.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a site runtime', anchor: '#add-a-site-runtime', text: 'A runtime renders on every published page of workspaces that enable your plugin — overlay engines, analytics beacons, experiment runners:\nPair it with a server enricher (registerSitePageEnricher, /server) that writes the props slice your runtime reads back from page. Enricher errors are isolated — your slice drops, the page survives. Cross-plugin wiring belongs in bootstrap (), which runs after every plugin in the batch has registered.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- Nav item missing: the plugin isn\'t enabled/released for the workspace, or the register fn name in plugins.config.json drifted (the loader logs missing register fn).\n- Widget renders nowhere: check the slot name against the catalog — unknown slots render only where an app mounts a custom PluginWidgetSlot.\n- Canvas blank in the editor: your component registered on the console surface instead of site — the editor gates load site.' },
  { path: '/developers/plugins/guides/examples', title: 'Worked examples', heading: '', anchor: '', text: 'Worked examples\nThe best examples are the shipping plugins — each one is the reference implementation of a pattern. Generated skeletons stay fresh by construction: node tools/scripts/create-plugin.mjs sample --surfaces console,tenantApi scaffolds a complete, test-passing plugin you can read and delete. First-party plugin libs are deliberately not duplicated as "example" libs — they would rot, and the scaffolder and the live plugins can\'t. The one checked-in example is the sandbox marketplace plugin below, which exists because the sandbox contract has no first-party equivalent to read.\n| Pattern | Read this | Why |\n| Console-only plugin | libs/plugins/redirects | The minimal shape: one nav item + page, server-side enforcement, no canvas bundle |\n| Full-stack feature | libs/plugins/commerce | Pages, widgets, canvas components, page resolvers, APIs, billing hooks — everything at once |\n| Site enricher + runtime pair | libs/plugins/marketing | Server enricher writes page props; the registered runtime reads them back |\n| Plugin→plugin composition | libs/plugins/inbox | Composes tabs from commerce + email — the dependency direction plugins are allowed |\n| Site canvas components | libs/plugins/bookings | Canvas component + console manager + APIs + a config schema (maxDaysAhead) and a scheduled job |\n| Custom field type | libs/plugins/marketplace (rating) | Pure-data type + client Input, registered from both surfaces |\n| Plugin permissions | libs/plugins/commerce (managePos) | Per-tier defaults riding every resolved role set |\n| Marketplace realm bundle | tools/plugin-loader/realm/demo (+ EXPLAINED.md) | The standalone track, narrated line by line |\n| Marketplace starter | tools/plugin-loader/realm/template | What you actually copy to begin |\n| Sandbox marketplace plugin | exam' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '', anchor: '', text: 'Build your first plugin\nTwo tracks share the same registries. First-party plugins live in this repo under libs/plugins/ and load through the generated manifests; marketplace plugins are standalone bundles published to the marketplace. This walkthrough does marketplace end-to-end and notes the first-party deltas.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '1. Scaffold', anchor: '#1-scaffold', text: 'The marketplace starter gives you src/index.js (the entry contract), manifest.json, a build config that compiles your react / @aglyn/aglyn imports into host-ABI lookups, and a README that becomes your marketplace listing docs. The first-party scaffolder generates the whole Nx library, wires plugins.config.json, and prints the two manual follow-ups (catalog entry + release flag).' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '2. Write the entry', anchor: '#2-write-the-entry', text: 'Every registry in the API reference is available on host.aglyn; the zones catalog lists where widgets can render.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '3. Develop against a live workspace', anchor: '#3-develop-against-a-live-workspace', text: 'Start the console/tenant dev server with the dev-loop variable and refresh after each rebuild:\nThe bundle loads unverified (localhost only; the whole path is compiled out of production builds). The browser console logs dev realm bundle loaded (UNVERIFIED): my-plugin. If a change doesn\'t stick, clear the Next dev cache (rm -rf apps/console/.next/cache) — inlined env values live in it.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '4. Verify', anchor: '#4-verify', text: 'The same checks the publish API enforces, run over the bundle\'s parse tree: entry exports, no leftover static imports, no eval/Function/computed access on a global, no import() it cannot resolve, size — and every network call diffed against your manifest\'s capabilities.network, which is why the manifest goes in too. It lists every area it checked, so you can tell a pass from a check that never ran, and prints the bundle\'s sha256 — the content pin every install verifies.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '5. Publish', anchor: '#5-publish', text: 'Publish from Marketplace → Publish (choose A plugin (upload a bundle)) or the API — the bundle plus manifest.json fields and your listing content (README, logo, screenshots, links, license, categories — see the publisher handbook). New listings enter the review queue as submitted; staff list (or verify ✅) them before they appear in browse. Publishing requires a marketplace profile, a Pro plan, and payouts onboarding for paid listings; there\'s a daily publish cap.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '6. Install, enable, load', anchor: '#6-install-enable-load', text: 'A workspace admin installs from the marketplace: the install pins your exact {version, sha256}, enables the plugin on the org switchboard, and it loads on the next visit — sandboxed by default, or into the app realm once staff have signed the version (trust: \'realm\'). Upgrades are explicit re-pins; your published artifacts are immutable, so nobody\'s pinned install can change underneath them.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '7. Uninstall', anchor: '#7-uninstall', text: 'Marketplace → Installed → Uninstall, or the Uninstall button on the listing\'s own detail page (Uninstall org-wide for an org-scope install), removes the pin and the switchboard entry. Data your plugin created stays untouched — reinstalls pick up where they left off. Design for that: namespace your documents and tolerate finding old ones.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- Nothing loads: check the browser console for the loader\'s reason — sha mismatch (stale artifact URL), missing/invalid signature (not realm-signed yet — expected for sandbox-tier), host ABI mismatch (rebuild against the current template), or the plugin isn\'t in org.enabledPlugins.\n- Blank widgets / hook errors: your bundle carries its own React. Realm bundles must import react only through the template\'s build config (host-ABI lookups) — run the verifier; leftover static imports fail it.\n- Publish 422: the response lists exactly which static check failed.\n- Works in dev, not after publish: the dev loop skips verification; the published path doesn\'t. Run the verifier locally first.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: '', anchor: '', text: 'Trusted realm bundles\nMarketplace plugins run sandboxed by default (cross-origin iframe, capability bridge). The realm tier is for plugins the platform has reviewed and signed: they load into the app realm and use every registry first-party plugins use. This guide is the operator + publisher view; the architecture is docs/PLUGINLOADING.md in the repo.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Build against the host ABI', anchor: '#build-against-the-host-abi', text: 'Use the template\'s build config: your react, react/jsx-runtime, and @aglyn/aglyn imports compile to lookups on globalThis.AGLYNPLUGINHOST — the app injects its own singletons there, which is what keeps your components on the app\'s React and your registrations in the app\'s registries. Export register(host) (client surfaces) and, only if you truly need server handlers, registerApi(). Declare hostAbi in your manifest; a bundle built for another generation never loads.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'The chain that runs before a byte executes', anchor: '#the-chain-that-runs-before-a-byte-executes', text: '1. Content pin — the install doc\'s sha256 must match the fetched bytes (immutable content-addressed artifacts).\n2. Platform signature — Ed25519 over the sha, granted by super staff after review; verification fails closed.\n3. Kill switch — a revocations/{listingId} doc beats everything.\n4. ABI check — declared hostAbi must equal the host\'s generation.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Granting trust (staff)', anchor: '#granting-trust-staff', text: 'Admin → Plugin reviews has a Listed plugins — realm trust section: every listed and verified plugin with its recent versions, each showing a Realm-trusted or Sandboxed chip and a Latest marker, with per-version Grant realm trust and Revoke realm trust buttons. Trust is granted to a specific reviewed version, not to the listing — a newer version stays sandboxed until it is reviewed and granted in turn.\nBoth actions are super-staff only and adminAudit\'d. The equivalent API is POST /api/admin/sign-plugin { listingId, version }, with { action: \'revoke\' } to revoke; a hard-kill still needs a revocation doc. Signing requires PLUGINTRUSTPRIVATEKEY on the console deployment — generate the pair with tools/scripts/generate-plugin-trust-key.mjs.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Where realm bundles load', anchor: '#where-realm-bundles-load', text: '- Console: before the shell renders, from the org\'s trusted installs.\n- Published sites: post-hydration (additive — first paint never waits on a marketplace CDN).\n- Server (rare): only on deployments with PLUGINREMOTESERVER=enabled plus a per-deploy listingId@version allowlist; every load is audited.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Key rotation', anchor: '#key-rotation', text: 'generate-plugin-trust-key.mjs → resign-realm-plugins.mjs (re-signs every granted version with the new key, --dry-run first) → deploy the new public keys → retire the old private key. Re-sign before the public-key swap so nothing stops loading mid-rotation.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- Loads in dev loop, not from the marketplace: dev loop skips verification. Check the browser console for the loader\'s reason — usually "missing signature" (not signed yet) or "sha256 mismatch".\n- AGLYNPLUGINHOST is not set: your bundle executed outside a host surface — the console gate and site effect set the ABI before loading; don\'t import the bundle yourself.\n- Server bundle didn\'t register: the dispatcher logs which chain link failed (not realm-trusted, built for host ABI N, fetch, signature) and skips — check the deployment logs and the allowlist entry.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: '', anchor: '', text: 'Server APIs, webhooks & jobs\nEverything here lives on your plugin\'s /server entry and runs inside the apps\' [...pluginApi] dispatchers.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'An API route', anchor: '#an-api-route', text: '- Served at /api/my-plugin/ping on the app(s) whose manifest lists your register fn (tenantApi, consoleApi, or both). Declare apiPrefixes: ["my-plugin"] in plugins.config.json.\n- Gating is automatic: requests carrying a hostId (query or JSON body) 404 when the target workspace has your plugin disabled or its release flag is off. Handlers still self-check entitlements (checkEntitlement/checkQuota with the org doc) for plan gating.\n- Settings: getPluginConfig(orgId, pluginId, { hostId }) returns your declared defaults merged with the workspace\'s values and then the site\'s overrides. Pass hostId whenever the request has one — without it the site\'s override is silently ignored while the console still shows it. See Plugin configuration.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Webhooks with signature verification', anchor: '#webhooks-with-signature-verification', text: 'PluginApiRequest.rawBody carries the unparsed payload:' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Platform billing events', anchor: '#platform-billing-events', text: 'Your handler receives the platform\'s Stripe events (with requestHost for callback URLs). Throwing propagates to a 500 and Stripe redelivers — write idempotent handlers.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Scheduled jobs', anchor: '#scheduled-jobs', text: 'The deployment\'s scheduler POSTs /api/plugins/run-jobs with the x-plugin-jobs-secret header (PLUGINJOBSSECRET); due jobs run error-isolated, and last-run marks persist across cold starts. Keep handlers bounded (limits, no unbounded scans) — they share the API process.\nLockdown — lockdown is required\nA job runs on platform credentials with no visitor, no session and no org, so none of the gates that cover the request paths are anywhere near it. A site can be locked for maintenance, non-payment, abuse or a legal takedown, and a beat that kept emailing its customers or moving its stock would be acting for a site the platform has taken off the air.\nSo every registration declares what it touches, and the runner injects the verdict:\n| lockdown | Means | The runner hands your handler |\n| -- | -- | -- |\n| { scope: \'per-host\' } | The job acts for sites. | A working gate — ask it for every host you touch. |\n| { scope: \'platform\', reason: \'…\' } | Nothing a lock could be about. | A gate that throws if asked, so a wrong declaration fails loudly. |\nTwo rules the platform\'s own jobs follow, and yours should:\n- Take the gate you are given. Calling pluginJobHostGate() yourself works at runtime but is refused by the coverage guard: a job free to mint its own gate is free to declare platform and never meet the check that the declaration is true. (The x-cron-secret doors that drive a pass by hand are the exception — they have no runner to hand them one.)\n- Skip, do not drop. A lockdown is a pause, not a cancellation. Leave the row exactly as it was — unstamped, undeleted, its retry count untouched — so the work lands on the first beat after the lift.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- 404 on your route: path prefix not in apiPrefixes, plugin disabled for the target workspace, or its release flag is off (staff bearer tokens bypass for preview).\n- Webhook signature failures: you parsed body instead of verifying rawBody.\n- Job never runs: PLUGINJOBSSECRET unset (route 501s) or the scheduler isn\'t POSTing; the route\'s response lists every registered job and what ran.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: '', anchor: '', text: 'Plugins & Marketplace\nPlugins extend Aglyn with new components and capabilities. You install them from the organization marketplace (Marketplace in the org navigation), configure them per site, and they run sandboxed so they can\'t compromise your site.\nThe marketplace lives at the organization level rather than inside each site. Its own Navigation panel lists Browse All and Installed; publishers additionally get Upload / Publish, Publisher Profile, Listings, Payouts and Sales.\nMarketplace is now purely the market. Turning plugins on and off for the workspace moved out to its own Plugins section in the org navigation, next to Marketplace. Installed remains as a convenience for uninstalling something you just installed — every row links through to Plugins.\nPlan availability Free to install marketplace plugins; some plugins and marketplace monetization features are paid.\nNew to this? This page is the reference. If you\'d rather be walked through it click by click — find something, choose which sites get it, install, upgrade, remove — start with Install your first marketplace item.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Install & upgrade', anchor: '#install--upgrade', text: '- Open Marketplace in the organization navigation and Browse the listings. Browse is a catalog: cards link to the detail page, which is the only place an install happens, and a confirmation dialog names exactly where it will land before anything is written.\n- When you install a plugin, choose where it applies: All sites (organization-wide — including sites you add later) or Selected sites (a specific subset). Only plugins and dataset schemas install org-wide; components, templates, layouts, themes and email templates are site-scoped, so "All sites" installs them onto every current site and does not cover sites added later. The listing\'s What\'s included box says which of the two you are looking at.\n- Installs are version-pinned, and you can upgrade deliberately.\n- Installed plugins appear as named entries in the Besigner drawer, alongside built-in components.\n- Manage what you have from the marketplace\'s Installed section: every marketplace install, with upgrade, uninstall, and share-with-organization actions. A listing\'s own detail page also carries Uninstall (or Uninstall org-wide) once you have it installed.\n- Turning a plugin on or off is the Plugins section, not Marketplace. Plugins in the organization navigation lists Installed from the marketplace and Built in, each row with its switch, its release state, and a link through to that plugin\'s own settings. If you are hunting for a switch, that is where it is.\n- Rating a listing needs a verified email and an organization that actually installed it; commenting is open to any signed-in user.\n- Installing enables the plugin for the workspace automatically; uninstalling disables it once no site keeps its own pin. Uninstalling never deletes the data a plugin created — reinstall and it picks up where it left off.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'What a browse card shows', anchor: '#browse-card', text: 'Every card in Browse All carries the same four claims, so two listings side by side are comparable:\n- A price chip, always. A paid listing shows the price — $29 — and a free one shows the word Free. There is no such thing as a card without a price chip: a missing chip would read as an oversight next to the $29 beside it, which is the one thing "free" must not look like. The card\'s button repeats the price for a paid listing you don\'t own yet: View details · $29.\n- A star rating, with its count. Stars plus the average and the number of ratings in brackets — 4.8 (12). The count is never dropped, because "5.0" from one rating and "5.0" from forty are not the same claim.\n- Not yet rated, in words, when nobody has rated it. An unrated listing draws no stars at all, and silence reads as "zero stars" rather than "no ratings yet".\n- Version, publisher and installs — v3 · by @handle · 41 installs — plus the Reviewed badge when the version on offer has passed review.\nThe listing\'s own page repeats the price chip and the rating in its header, where the install decision is actually made. On that page an unrated listing shows nothing rather than the "Not yet rated" wording.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'What\'s included', anchor: '#whats-included', text: 'A listing page carries a What\'s included box. Aglyn generates it from the listing — it is not publisher copy, so it cannot promise something the install does not do, and it says nothing about how much content is in there.\nThe first row is what the install physically produces, which depends on the type:\n| Type | The row reads |\n| Plugin | A plugin, sandboxed on its own origin with a per-plugin CSP |\n| Component | An editable component you can place on any screen |\n| Template | Editable screens you can rework in Besigner |\n| Layout | An editable layout you can apply to any screen |\n| Dataset schema | A new empty dataset with its fields already defined |\n| Email template | An editable email design you can send campaigns from |\n| Theme | A theme applied to the site you choose |\nThen, in order, up to four more rows:\n- Where it lands. Plugins and dataset schemas install org-wide — Installs org-wide, covering sites you add later. Everything else is site-scoped and says so: Installs per site — new sites are not covered automatically. That row is marked as a note, not a tick, because it is a limit you are being told about rather than something you are getting.\n- Review — This version passed marketplace review — only when the version on offer is approved. A new release from the same publisher starts without it.\n- The license, when the publisher set one: Licensed MIT.\n- Price and updates. A paid listing reads A one-time purchase — updates to this listing are included; a free one reads Free, including every future update. Either way, updates are not a second charge — but they are still deliberate, not automatic.\nWhat the box will never tell you is how many screens or blocks a template contains. Aglyn collects no manifest of that, and counting it would mean inventing a number, so th' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'What the badges on a listing mean', anchor: '#what-the-badges-on-a-listing-mean', text: 'Two badges can appear on a listing, and they say different things. Read them as two separate claims, because that is what they are (AGL-1121).\n| Badge | What Aglyn is claiming | What it survives |\n| Verified publisher | A human at Aglyn confirmed who the publisher is, and that their listing describes what their code does. | A version bump. It is a claim about the publisher, not about any particular release. |\n| Reviewed | A human at Aglyn read these exact bytes — the version currently on offer — against a required checklist. | Nothing. It is re-earned per version, so a new release starts without it. |\nSo a new release from a verified publisher shows Verified publisher but not Reviewed, and that is honest rather than a gap: we vouch for the person, and nobody has read this particular code yet.\nNeither badge is a security guarantee. Every plugin runs in the same sandbox with the same limits whether it is badged or not, and installability is identical — a listed plugin is installable by every workspace regardless. The badges tell you how much human attention this listing has had, not whether the code is safe.\nA listing with neither badge is not necessarily suspect; it may simply be new. It does mean nobody at Aglyn has looked at it, so read the publisher and the docs before installing.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'How plugins run', anchor: '#how-plugins-run', text: '- Each plugin loads into a sandboxed PluginFrame host runtime, isolated by origin.\n- A manifest + sandbox bridge protocol defines what a plugin can do.\n- A host-mediated network bridge lets plugins make network calls without direct access to your environment.\n- See Sandbox security model for what that isolation actually enforces — including the per-plugin network policy — if you\'re writing one.\n- Your workspace decides which plugins are enabled at all, and a site admin can narrow that further per site from the site\'s Admin → Plugins page. A plugin disabled for a site disappears from that site\'s navigation, editor, published pages, and API — other sites in the workspace are unaffected, and a site can never enable a plugin the workspace has switched off.\n- The site\'s Admin → Plugins page lists both kinds in two groups — what ships with the platform, and what the workspace installed from the marketplace — because which one a row is is the first thing you need to know before switching it. A marketplace plugin gets the same per-site switch as a built-in one.\n- Most plugins are on for a site unless it turns them off. User Accounts is the exception: it is off until a site turns it on, because it is the one that decides whether the site serves /signin, /signup and /recover — and a sign-in page on a marketing site is worse than a missing one. See Member accounts for what the switch does.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'When one plugin depends on another', anchor: '#when-one-plugin-depends-on-another', text: 'Some plugins cannot run without another one. User Accounts is the case that exists today: its Members blocks and its membership/ API handlers ship inside the Commerce bundle, so User Accounts with Commerce switched off is a site that still routes /signin while nothing can answer the sign-in request.\nSwitching off a plugin something else depends on therefore asks first. The dialog names every dependent, says what disabling each one does to a site that is already published, and offers Cancel or Continue and disable those too:\n- Cancel writes nothing and the switch stays where it was.\n- Continue disables the plugin and every dependent in a single save, so a half-applied cascade cannot happen.\n- Dependents are followed transitively — if C needs B and B needs A, switching off A names both.\n- Re-enabling does not undo a cascade. Turning the plugin back on later does not switch its dependents back on; re-enable each one yourself.\nTwo consequences are possible and the dialog distinguishes them, because they are very different decisions:\n| The dependent | What disabling it does |\n| Registers site components (Commerce, Bookings, Email, Events Calendar, Marketing) | Elements already placed on published pages stop rendering. For a single site the dialog counts them. |\n| Serves routes (User Accounts, Redirects, Workflows) | Published pages keep rendering, but the routes or rules it serves stop. |\n| Console-only (Contacts, Data, Inbox, Logic, Marketplace) | It leaves navigation and the editor. Published pages are unaffected. |\nCounts come from scanning the published version of each screen, layout and component, and are capped — where the scan hits its cap the dialog says "at least". Drafts are not scanned.\nThe warning covers built-in plugins only First-party plugins declare what they' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Configure', anchor: '#configure', text: 'A plugin declares the settings it takes, and the console renders the form. A workspace sets a value once and every site follows it. See Plugin configuration.\nThis is the same for a marketplace plugin. A published manifest may carry a config block declaring the plugin\'s fields and their defaults, and the console renders it from the pinned manifest — the same form, the same workspace-default and per-site-override behavior, with nothing for the publisher to build. See Plugin manifest.\nSettings for one site {#configure-site}\nA site that needs a different answer overrides that one field and keeps inheriting the rest — including later changes the workspace makes to the fields it did not override. So the same plugin behaves differently on each site without the author writing any inheritance of their own.\nEach field on a site\'s plugin page says which state it is in, shows the workspace\'s own value beside it, and offers a one-click way back to inheriting. Editing a field is what overrides it; reverting deletes the site\'s value rather than storing a copy of the workspace\'s, so the site resumes following.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Publish your own', anchor: '#publish-your-own', text: 'The publish + install pipeline lets developers ship plugins to the marketplace with version pinning. The marketplace also supports paid listings, Stripe Connect payouts, and a publisher ledger.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Related', anchor: '#related', text: '- Install your first marketplace item — the click-by-click walkthrough of everything on this page\n- The Besigner\n- Site templates & block library\n- Building feature plugins — the developer guide to every extension surface\n- Repo docs: docs/PLUGINLOADING.md (loading architecture and trust tiers) and docs/PLUGINPLATFORMGAPS.md (competitive analysis and the v2 roadmap)' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: '', anchor: '', text: 'Publish a plugin\nThis page covers the mechanics; the complete marketplace guide — review process, listing authoring, versioning, payouts — is the Publisher handbook.\nBuilt something reusable? Publish it to the marketplace marketplace so other Aglyn users can install it — free or paid.\nPlan availability Publishing is open to developers; paid listings use Stripe Connect for payouts.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'The publish pipeline', anchor: '#the-publish-pipeline', text: 'Plugins go through a publish + install pipeline with version pinning, so installs are reproducible and upgrades are deliberate:\n1. Package your plugin against the manifest + sandbox bridge protocol (see Plugins overview).\n2. Verify locally: node tools/scripts/verify-plugin-bundle.mjs dist/plugin.bundle.mjs — the publish API enforces the same checks.\n3. Publish a version to the marketplace: Marketplace → Publish → "A plugin (upload a bundle)" → Publish a plugin… — a page at / /marketplace/publish/plugin where you upload the bundle and its manifest.json, choose who can install it, and set the listing details, repository URL and price. What you type is kept as a local draft until you publish; the files are not, so re-choose them. You confirm a short pre-publish checklist — repository, license, data disclosure, network hosts, testing — which is recorded against that exact bundle and shown to the reviewer. Uploads publish sandboxed; staff review lists (and may sign) them.\n4. Installers get that pinned version and choose when to upgrade — ship updates by bumping the manifest version and uploading again.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Private plugins', anchor: '#private-plugins', text: 'Not everything you build is for sale. When you upload a bundle, Who can install this offers:\n- Anyone — publish to the marketplace. The default. Listed for every workspace once a reviewer approves it.\n- Only this organization — private plugin. Never listed in the marketplace, for anyone, and installable only by your own sites.\nPrivate is a choice about audience, not about trust. A private plugin still executes on Aglyn infrastructure and still reaches the host ABI, so it goes through the identical pipeline: the same review queue, the same reviewer checklist, the same bundle verifier, and the same super-staff signature if it ever needs realm trust. It is not a way to ship unreviewed code.\nPrivate plugins are always free — nobody else can install them — and you reach yours from Marketplace → Listings, not from Browse.\nA private plugin can go public later from that same Listings tab. The bytes were already approved, so it needs no re-review; it does need what any marketplace listing needs first — a description, a README, and a license. Going back to private is always available.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Paid listings', anchor: '#paid-listings', text: 'You can list a plugin as paid:\n- Payments run through Stripe Connect.\n- Earnings are tracked in a publisher ledger.\nThe Sales card reports net paid out — what actually reached your Stripe account. It is the pre-tax listing price less the platform fee, which is the fixed amount Stripe transfers to you on each sale.\nThree things it deliberately is not:\n- Not what the buyer paid. Buyers are charged sales tax on top of your price. Aglyn collects and remits that tax under its marketplace-provider registration, so it is never part of your share. The card shows what buyers paid, the tax and the platform fee beside your payout so the four reconcile.\n- Not gross minus the fee. The fee is calculated on the pre-tax price, so subtracting it from the tax-inclusive gross would count the tax as your earnings.\n- Not counting refunds or chargebacks. A refunded sale and a lost dispute leave the payout total; the amount pulled back out of your account is shown on its own line so a total that shrank can be reconciled.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Your publisher profile', anchor: '#your-publisher-profile', text: 'Your publisher profile is a storefront: its own page in the marketplace listing everything you\'ve published, reachable from the Publisher card on any of your listings and from the by @handle link on every browse card. Buyers who like one of your plugins use it to find the rest, so the handle, display name, and bio you set are worth the same care as a listing.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Tips', anchor: '#tips', text: '- Bump versions intentionally — installers stay on their pinned version until they upgrade.\n- Keep the manifest\'s declared capabilities minimal; the sandbox enforces them.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Related', anchor: '#related', text: '- Plugins & marketplace' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: '', anchor: '', text: 'Publisher handbook\nEverything a marketplace publisher needs. The developer side (building the bundle) is the first-plugin guide; this is the marketplace side.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Before your first publish', anchor: '#before-your-first-publish', text: '1. Publisher profile (Marketplace → Profile) — your handle and display name appear on every listing. Publishing is organization-owned: the listing belongs to your organization, not your personal account.\n2. Publisher agreement (Marketplace → Profile) — accept it once, on behalf of the organization. See The publisher agreement.\n3. Plan: publishing requires a Pro plan.\n4. Payouts (paid listings only): complete Stripe Connect onboarding from Marketplace → Payouts. The platform fee is 20% (30% on free plans).' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'The publisher agreement', anchor: '#the-publisher-agreement', text: 'Your organization — not you personally — is the publishing party, so the organization accepts the Marketplace Publisher Agreement once, from Marketplace → Profile. Only an owner or admin can accept it, because only they can bind the organization, and we record who accepted it and when.\nYou can read the agreement in full at aglyn.com/legal/marketplace-publisher-agreement, alongside the rest of the legal center. The version in force is stated at the top of that page, and it is the same string the panel records against your acceptance.\nIt is a different thing from the pre-publish checklist, and they are not interchangeable:\n| | Publisher agreement | Pre-publish checklist |\n| About | The relationship | The bytes in this bundle |\n| Scope | Your organization | One version |\n| Asked | Once, and again when the terms change | Every publish, including a republish of the same version number |\nThe summary shown above the accept button is the part that tends to surprise people later — the license you grant us to host, verify and distribute; what you warrant about each version; that you cannot recall code already installed; that we can disable a version everywhere without notice if it looks dangerous; that review is a safety screen and not an endorsement; and that on paid listings we process the sale, pay your share into your own Stripe Connect account less a platform fee, and collect and remit sales tax — while refunds, chargebacks and support on your artifacts stay with you. Read the full agreement before accepting.\nIf we change the agreement, publishing stops until someone who can bind your organization reads and accepts the new version. An older acceptance is never carried forward — that is the whole reason the agreement is versioned. Nothing already published is affected, and re' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Where to publish from', anchor: '#where-to-publish-from', text: 'Publishing lives at the organization level — Marketplace → Publish. Pick a source site, then what to publish:\n- A component — a reusable component from that site.\n- A layout — a published layout from that site.\n- A dataset schema — the field model of one of your organization\'s datasets. Records are never published — only the structure travels.\n- An email template — a transactional email you\'ve designed for that site (only emails that already have a saved design are offered).\n- This entire site — its published screens and theme, as an installable template.\nDataset schemas are the one exception to the source-site picker: datasets belong to the organization rather than to a site, so the picker is hidden and the schema publishes from the org directly.\nThe per-site shortcuts still exist for convenience — the Publish actions on a site\'s Components and Layouts pages, and Publish as template on the Setup page — and open the same listing form.\nWhat installing each type does\nInstalling never changes a running site. What that means per type:\n| Type | Where it lands | Live immediately? |\n| Component | The site\'s components | Yes, once you place it |\n| Layout / Site template | The site\'s Templates library | No |\n| Plugin | An org or per-site version pin | Yes |\n| Dataset schema | A new, empty dataset in the org | Yes (it\'s new) |\n| Email template | A draft version of that email | No |\nTwo details worth knowing before you publish one:\n- A dataset schema installs as a brand-new dataset every time; it never merges into an existing one, since a schema change over existing rows would reinterpret live data. reference fields are relinked to the installing organization\'s datasets by display name, and any that can\'t be matched are degraded to plain text — the installer is told which ones.\n- ' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Publishing a version', anchor: '#publishing-a-version', text: 'Run the local verifier first — the publish API enforces the same checks and rejects with the exact problem list:\nThe verifier parses your bundle rather than reading it as text, so it sees what a source scan could not: property access computed at runtime on globalThis/window/document, the Function constructor reached through .constructor(), and import() with a specifier it cannot resolve. All of those are refused.\nDeclare every origin you call. The verifier collects your fetch, XMLHttpRequest, WebSocket and sendBeacon calls and diffs them against capabilities.network in your manifest; an origin you call but do not declare fails the publish. This is the same list your plugin\'s CSP is built from, so an undeclared call would have been blocked at runtime anyway — failing here means you find out at publish time instead of in production. A URL your code only knows at runtime cannot be checked, so it is reported as a warning and a reviewer will ask about it.\nCalling through a local name does not change the answer: const f = fetch, const d = globalThis.fetch and const {fetch: h} = globalThis are all resolved back to fetch, and a URL kept in a constant — a plain string, a template, or a concatenation of them — is read rather than shrugged at. What is not read is a name that gets reassigned, shadowed by a parameter or declared twice; there the value at the call site would be a guess, so the call is reported as a URL known only at runtime.\nIf you hand a URL to a helper the checker cannot follow, it says so rather than reporting no network calls — so declare the origins your plugin talks to and the row goes quiet on its own.\nPass the manifest (as above, or leave it beside your bundle or one level up) or the network checks can only warn locally while the publish API still rejects.\nIt' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Review: what happens after you publish', anchor: '#review-what-happens-after-you-publish', text: 'New plugin listings enter the queue as submitted and don\'t appear in public browse until staff list them. Reviewers see your listing content, declared capabilities, and a fresh static-verification run. Outcomes:\n- Listed — publicly browsable.\n- Verified publisher ✅ — a badge on you, not on any one release. See below.\n- Rejected — you\'re notified with the reason; fix and republish.\n- Realm trust (separate, rare): staff may additionally sign a version so it runs in the app realm instead of the sandbox — first-party-grade placement for plugins that earn it.\nThe two badges, and what each one promises\nThe marketplace shows two separate claims, because they answer different questions and conflating them would let one vouch for the other:\n| Badge | What it means | Scope |\n| Verified publisher | A human at Aglyn confirmed who you are and that your listing describes what your code does. | The publisher. It survives a version bump. |\n| Reviewed | A reviewer completed the checklist against these exact bytes ({version, sha256}). | That one version. |\nPublishing a new version clears the Reviewed badge and puts the release back in the queue — including on a listing whose publisher is already verified. That is deliberate: the badge is a statement about code someone read, so it cannot follow code nobody has.\nYour Verified publisher badge is unaffected by a version bump. Buyers see both, so a new release from a verified publisher reads honestly: we vouch for you, and we have not read this release yet.\nUntil a version is Reviewed, its listing page carries the standard "review the publisher and docs before installing" note. Being a verified publisher does not remove it — the plugin still runs sandboxed either way.\nSpeed the review up: a real README, a license, sane capabilities (request o' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Private plugins', anchor: '#private-plugins', text: 'Choose Only this organization under Who can install this when you upload, and the listing becomes private: never browsable in the marketplace by anyone, and installable only by your own organization\'s sites. That last part is enforced when the install is requested, not by hiding the page — knowing a private listing\'s id gets a stranger nowhere.\nPrivate changes the audience, not the bar. Your bundle still runs on Aglyn infrastructure and still reaches the host ABI, so it goes through the same queue, the same reviewer checklist, the same static verifier, and the same super-staff signature if it ever needs realm trust. Staff see private submissions in the queue marked Private.\nPrivate plugins are always free, and you find yours under Marketplace → Listings rather than in Browse — View opens the same detail page you install from.\nGoing public later takes no re-review: the bytes were already approved, and who may install them was never part of that approval. It does ask for what any marketplace listing needs first — a description, a README, and a license — via Make public on the Listings row. Going back to private is always available and takes effect immediately.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Authoring your listing', anchor: '#authoring-your-listing', text: 'Your listing IS your storefront — it renders on the detail page every buyer sees. Editable at publish time or any time after, no republish needed: open Edit listing on your own listing\'s detail page (the whole page becomes the editor), or use the Edit action on Marketplace → Listings.\n| Field | Guidance |\n| Name | The display name on every browse card and at the top of the detail page; ≤80 chars. A typo here is fixable without republishing — leaving it blank keeps the current name rather than clearing it. |\n| Description | The one-line summary under the name on browse cards; ≤500 chars. |\n| Body (About) | The main docs: what it does, setup, what it adds, data & permissions. Rich-text editor with headings, bold/italic, links, and inline images; ≤20k chars. |\n| Preview image | The hero shown on browse cards and at the top of the detail page — pick it from your media library. |\n| Logo | Square; pick from the media library or paste an https URL. |\n| Screenshots | Up to 6, from the media library or https URLs; the detail page shows a gallery with click-to-zoom. |\n| Categories | Up to 3 from the fixed taxonomy. |\n| License | Short label (e.g. MIT) — listings without one get flagged in review. |\n| Homepage / repository | Public links build trust; reviewers check them. The repository is asked for at publish and required — editing it here changes the listing, not what past versions declared. |\nBe explicit about data & permissions in the README: what your plugin reads/writes and every host in your manifest\'s network allowlist — unverified sandbox listings show buyers a risk disclaimer, and good docs are what overcomes it.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'What your listing can say about Aglyn', anchor: '#what-your-listing-can-say-about-aglyn', text: 'Your listing renders inside Aglyn\'s own console, on the page a customer is reading while they decide whether to upgrade. That is why this one has a rule attached: a plugin sold as "the cheap way out of Business" is doing its selling with our pricing page, not with your plugin.\nFine — say all of this:\n- What your plugin does, and how well it does it.\n- Which Aglyn plans or features it requires: "needs the Pro plan", "uses custom domains", "requires the datasets API".\n- Which plans or features it is compatible with, stated as fact.\n- What it costs, and what a buyer gets for it.\nNot fine:\n- Disparaging Aglyn or the platform ("Aglyn\'s built-in analytics are useless").\n- Stating or implying what an Aglyn plan costs or contains ("Business is $X for features you won\'t use", "the Pro plan caps you at 5 sites"). Plans and prices change; a listing that quotes them goes stale and misinforms buyers who trust it.\n- Comparing your price against ours ("half the price of an upgrade").\n- Naming, framing or marketing the plugin around avoiding, replacing or discouraging an Aglyn plan or upgrade — "Skip the upgrade", "Business features without the Business plan", "don\'t pay for Pro".\nThe line is simple: describe your plugin, not our pricing. If you need a customer to know they must be on Pro for your plugin to work, say exactly that — a requirement is a fact about your plugin, and it belongs in the listing.\nThis is §3(h) of the publisher agreement, you confirm it at every publish, and a reviewer checks the title, description and README against it. A listing that crosses it is rejected with the reason rather than quietly edited, so you get to fix your own words.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Versioning & updates', anchor: '#versioning--updates', text: 'Shipping a new version\nPublish new version on your listing — the button on the listing\'s own detail page, or the action in the row menu on Marketplace → Listings. It opens the same publish page bound to that listing, so you upload the new bundle and manifest and write a changelog rather than describing a listing you already own; name, description, README, license, repository and price arrive filled in from the listing and are yours to edit.\nWhat the page tells you, because it is the part worth knowing: the version that installs today keeps installing until a reviewer approves the new one. Nobody is upgraded onto unreviewed code, and nothing you publish can change a version somebody already has.\nTwo things it will stop you on:\n- A mismatched manifest id. An update is recognized by your publisher organization plus the manifest id — so a bundle carrying a different id would create a separate listing, not a new version. The page says so and refuses rather than letting you find out from a duplicate listing you cannot un-publish the bytes of.\n- The changelog confirmation. On an update the pre-publish checklist asks for it up front, because here we know it applies.\nWho can install it is fixed when the listing is created and a new version never changes it — change that from the listing itself.\n- Artifacts are immutable and installs pin {version, sha256} — you can never change the code a consumer runs; ship a new version instead.\n- Users update explicitly (an Update to vX action appears when your latestVersion passes their pin). Write a changelog every publish — it renders in the detail page\'s Version history card, where every published version is listed with its changelog, a Latest marker, and a Realm-trusted chip on versions that carry it. That card is what a cautious buyer re' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'How installs work (the buyer side)', anchor: '#how-installs-work-the-buyer-side', text: 'Browse is a catalog — cards link to the detail page, which is the only place an install happens. The buyer picks targets (all sites, selected sites, or org-wide for plugins), confirms a dialog that names exactly where the install lands, and the pin is written: your exact {version, sha256} pinned to the site or org, the plugin enabled for the workspace, loaded on their next visit. Buyers can uninstall from the listing\'s own detail page (Uninstall, or Uninstall org-wide for an org-scope pin) as well as from Marketplace → Installed — removing the pin and disabling it. Data your plugin created stays, so reinstalls resume cleanly. Paid listings require purchase before install; you see sales in your publisher ledger.\nThe detail page shows two install figures side by side: installs is the cumulative all-time total and only ever grows, while active counts the organizations and sites that currently hold a pin — it goes down when someone uninstalls. A big gap between the two is churn worth investigating.\nEvery listing shows its artifact type as a chip — Plugin, Component, Site template, Layout, Dataset schema, or Email template — so buyers know what they\'re getting before they open it. Dataset schemas and email templates read "Added (v1) · add again" rather than "Installed", because adding one creates a new dataset or a new draft email each time; re-adding is a legitimate action, not a no-op.\nRatings and comments: any signed-in user can comment on your listing; star ratings are reserved for verified-email accounts in an organization that actually installed it. The publishing organization can never rate or comment on its own listing.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Getting paid', anchor: '#getting-paid', text: 'One-time prices in whole USD: $0 (free), or $3 to $1000. Purchases flow through the platform\'s Stripe; your share (80%, or 70% on free plans) pays out via your Connect account. The Marketplace → Sales tab tracks every sale.\nYour share is calculated on the pre-tax price. Buyers also pay sales tax on top of it, which Aglyn collects and remits under its marketplace-provider registration — that money is never yours and is not part of your payout. The Sales tab reports net paid out, the amount that reached your Stripe account, with what buyers paid, the tax and the platform fee shown beside it.\nRefunds and lost chargebacks are excluded from that total: your share is pulled back from your Connect account, and the amount returned is listed separately.\nThe $3 minimum on paid listings {#low-prices-and-processing}\nA paid listing must be $3 or more. Type less than that into any publish form and the price field turns red, the hint says why, the publish button holds, and the publish route refuses it — the same figure in all four places.\nThe reason is the payment processor\'s per-transaction cost: a percentage of what the buyer pays (the price plus sales tax) plus a fixed amount per transaction. That fixed amount is what makes small prices uneconomic — it does not shrink with the price, while the platform\'s 20% cut does. At $1 processing the payment costs about $0.36, more than the $0.20 platform fee, so the sale loses money for the platform that has to settle it.\nThe minimum is not a round number picked for effect: it is the cheapest whole dollar at which the platform\'s cut covers the cost of collecting it, computed at the 20% take rate — the band that breaks even latest, so the number holds whichever plan you are on — and against the most expensive payment method a buyer may choose.' },
  { path: '/developers/plugins/reference/extension-points', title: 'Extension-point catalog', heading: '', anchor: '', text: 'Extension-point catalog\nThe surface matrix: what a plugin can extend, from which entry (barrel = client, /server = API process), and when it runs.\n| Extension point | Entry | Reaches | Runs |\n| Canvas components (defineUiFeatureBundle) | barrel (site) | Besigner + published sites | Editor gates / SSR-suspended page load |\n| Console nav + pages (ConsoleExtension.navItems) | barrel (console) | Console host area | After the org resolves, before the shell paints |\n| Widgets (ConsoleExtension.widgets) | barrel (console) | Named console zones (dashboard, org, settings, admin, besigner) | With their host page |\n| Providers (ConsoleExtension.providers) | barrel (console) | Around every console page | Once the registry is populated |\n| Site runtimes (registerSiteRuntime) | barrel (site) | Every published page | Client render, reading enricher props |\n| Redirect resolvers / page resolvers / enrichers | /server | Tenant page pipeline | Per request, in that order; enricher errors isolated |\n| API routes (registerPluginApiRoute) | /server | /api/ on both apps | Per request behind the org + release gates |\n| Billing webhook handlers | /server | Platform Stripe events | Per event; errors → redelivery |\n| Config schemas (registerPluginConfigSchema) | both | Settings UI + typed reads | Declared at module scope |\n| Custom field types (registerCustomFieldType) | both | Dataset schema/record editors + validation | Declared at module scope |\n| Permissions (registerPluginPermissions) | both | Every resolved role set | Declared at module scope |\n| Scheduled jobs (registerPluginJob) | /server | The platform job beat | When due, via /api/plugins/run-jobs |\n| Install preset mappers | barrel | Besigner drawer presets | On install-doc render |\n| Realm bundles (register(host) / registerApi()) | rem' },
  { path: '/developers/plugins/reference/injection-zones', title: 'Injection zones', heading: '', anchor: '', text: 'Injection zones\nRegister a widget with ConsoleExtension.widgets: [{ slot, widgetId, title?, Component }]; the shell renders it through PluginWidgetSlot. The guaranteed zones are the exported CONSOLEWIDGETSLOTS catalog — slot stays an open string so custom zones don\'t need a core release.\n| Zone | Where it renders | Props your widget receives |\n| hostActivity | Host dashboard + screen-view activity column | hostId, targetId?, header?, viewAllHref? |\n| hostDashboard | Host dashboard glance row, one card per capability | hostId |\n| commerceGlance | Host dashboard commerce summary | hostId |\n| orgData | Organization → Data page body | orgId, org |\n| besignerFunctions | Besigner ƒx panel | hostId |\n| marketplaceListing | Marketplace listing detail body | hostId, listingId, permissions |\n| orgAddons | Plugins & add-ons hub, installs section | hostId (the acting site) |\n| dashboardFooter | Bottom of the host dashboard | hostId |\n| orgSettings | Organization → Settings, below the tabs | orgId, org |\n| hostSettings | Host setup page, below the built-in cards | hostId |\n| adminOrgDetail | Staff admin org detail page (staff-only) | orgId |\nRules of thumb: widgets receive shell-resolved context as props and must not reach for console-app hooks; data access goes through @aglyn/tenant-feature-instance (useFirestoreCollection, useUser, usePluginConfig, …). A widget renders for a workspace only when its plugin is enabled and released — the shell never mounts widgets from unloaded plugins.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: '', anchor: '', text: 'Manifests, trust lifecycle & environment' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Plugin manifest (published with every version)', anchor: '#plugin-manifest-published-with-every-version', text: 'Validation is server-side (validatePluginManifest) — invalid manifests never publish. capabilities are enforced by the sandbox tier: the plugin origin stamps a CSP from network, the bridge drops undeclared props and events.\nconfig — settings without writing a settings screen\nA first-party plugin registers its settings schema by calling registerPluginConfigSchema at module scope. Your bundle cannot: it runs sandboxed on its own origin and never executes in the console process, so there is no moment at which that call could happen. Declaring config in the manifest is how you get the same thing.\nThe console reads it from the pinned manifest on the install, so the fields a workspace sees are the fields the version it installed declared. Your plugin reads the resolved values with usePluginConfig(orgId, pluginId) on the client or getPluginConfig(orgId, pluginId) on the server — the same two calls a first-party plugin uses — and gets the same two-level behavior for free: the workspace answers once, and any one site can override a single field and keep inheriting the rest.\nField type is one of string, number, boolean or select; a select needs options, and a number may set min/max. Anything else is dropped rather than rendered, at most 50 fields are read, and every default is coerced to its declared type — so a manifest cannot put a control the console does not have in front of a customer, and a mistyped default cannot become the value every site inherits.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Listing & version documents', anchor: '#listing--version-documents', text: '- marketplaceListings/{listingId} — public: displayName, description, categories[] (fixed taxonomy), logoUrl, screenshots[], readme (markdown), homepageUrl, repositoryUrl, license, priceUsd, latestVersion, installCount (cumulative installs ever), activeInstalls (installs live right now — the detail page shows both, e.g. 41 installs · 12 active), reviewStatus.\n- marketplaceListings/{id}/pluginVersions/{version} — server-only: sha256, objectPath, manifest, changelog, trust?, signature?. The buyer-safe subset (version/changelog/trust/hostAbi/date) is exposed by GET /api/marketplace/listing-versions.\n- Installs pin {version, sha256} at hosts/{hostId}/installs/{listingId} (host tier) or orgs/{orgId}/installs/{listingId} (org tier). Artifacts are immutable content-addressed objects: artifacts/{listingId}/{version}/{sha256}.bundle.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Review & trust lifecycle', anchor: '#review--trust-lifecycle', text: '- listed/verified (or legacy/absent) plugin listings appear in browse; everything else is owner-and-staff-only. Verified adds the ✅ badge.\n- Realm trust is separate and orthogonal: a super-staff signature over a version\'s sha256 (POST /api/admin/sign-plugin) sets trust: \'realm\', letting that version load into the app realm. The revocations/{listingId} kill switch beats everything.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Environment variables', anchor: '#environment-variables', text: '| Variable | Runtime | Purpose |\n| NEXTPUBLICPLUGINORIGIN | client + server | Dedicated plugin origin: serves /load (sandbox) and /artifacts/... (realm fetches) |\n| PLUGINARTIFACTSBASE | server | Optional server-side artifacts base override |\n| PLUGINARTIFACTSBUCKET | console server | Isolated bucket the publish flow writes to |\n| NEXTPUBLICPLUGINTRUSTPUBLICKEY | client | Ed25519 public key (base64 raw); when set, client realm loads require valid signatures |\n| PLUGINTRUSTPUBLICKEY | server | Same key, server loaders (mandatory there) |\n| PLUGINTRUSTPRIVATEKEY | console server only | Signing key (base64 PKCS8 DER) for the staff sign-plugin route |\n| PLUGINREMOTESERVER | server | enabled turns on remote server bundles (default off everywhere) |\n| PLUGINREMOTESERVERBUNDLES | server | Per-deploy listingId@version allowlist |\n| PLUGINJOBSSECRET | tenant server | Shared secret the scheduler sends to /api/plugins/run-jobs |\n| NEXTPUBLICPLUGINDEVBUNDLES | client, dev only | Unverified localhost bundle loading for the authoring loop; dead code in production builds |' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: '`plugins.config.json` (first-party contributors)', anchor: '#pluginsconfigjson-first-party-contributors', text: 'The single source mapping plugin ids to packages, register entry points per surface (site, console, tenantApi, consoleApi), and apiPrefixes. node tools/scripts/generate-plugin-manifests.mjs turns it into the four generated loader manifests — the only files allowed to reference @aglyn/plugins- outside libs/plugins (an nx boundary rule enforces this). The scaffolder (tools/scripts/create-plugin.mjs) maintains it for you; the manual follow-ups are the FIRSTPARTYPLUGINS catalog entry and the release flag (registry + Remote Config template).' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: '', anchor: '', text: 'Plugin configuration\nA plugin declares the settings it takes; Aglyn stores the answers and renders the form. You write no settings UI, and you never invent your own inheritance — a setting can be answered at three levels, and the platform resolves them the same way for every plugin.' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: 'The three layers', anchor: '#layers', text: '| Layer | Where it lives | Who sets it |\n| Schema defaults | Your code | You, the plugin author |\n| Workspace value | orgs/{orgId}/pluginSettings/{pluginId} | An org manager, in Plugins & add-ons |\n| Site override | hosts/{hostId}/pluginSettings/{pluginId} | A site admin, in that site\'s plugin settings |\nEach layer narrows the one before it, per key. A workspace sets a value once and every site it enabled the plugin on follows it; a site that needs a different answer overrides that one field and keeps inheriting the rest. One booking horizon across a chain, with the flagship branch taking bookings further out, is the shape this exists for.\nOnly the keys the site document actually holds are overrides. The site document is not a full copy of the config — it is a sparse patch.' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: 'Declare a schema', anchor: '#declare', text: 'There is no manifest field for this. A schema is registered in code, at module scope, from a file imported by both your client barrel and your /server entry — so whichever surface loads first, the schema is there.\nRegistration is idempotent and keyed by pluginId; registering again replaces the schema.\nField types {#field-types}\n| type | Editor | Coercion |\n| string | Text field | Anything that is not a string falls back. An empty string is a valid value and is kept. |\n| number | Number field | Must be a finite number, then clamped to min / max — a value outside the range is pulled to the bound, not rejected. |\n| boolean | Switch | Must be an actual boolean. "true" is not one. |\n| select | Dropdown | Must match one of options[].value. |\nlabel is required and description is optional help text under the field.\nvalidate is a cross-field hook run against the merged values before a save. Return an error string to block the save, or null to allow it.\nValues are not trusted The settings documents are client-writable by org managers and site admins, so every read coerces defensively. A value of the wrong type falls back rather than reaching your code — and keys your schema does not declare are dropped entirely, so a field left behind by an older version of your plugin cannot resurface as config.' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: 'Read the config', anchor: '#read', text: 'On the server, from a handler:\nPass hostId whenever you have one. Without it you get the workspace\'s answer and the site\'s override is silently ignored — which is worse than not having the feature: the console shows the number the operator typed while your handler keeps using the workspace\'s, a disagreement with no error and no surface that shows both sides. The site read is conditional and runs alongside the org read, so passing it costs no extra round trip.\nIn the console or another client surface:\nready is false until every document it needs has answered. Do not read config before then; it is the schema defaults, which is a plausible-looking wrong answer.\nWith no registered schema {#no-schema}\nBoth readers degrade rather than failing: you get the raw stored documents with the site\'s spread over the workspace\'s, key for key, and no coercion. That keeps a handler working when its schema module has not loaded, but it is not the behavior to design against.' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: 'Resolution, exactly', anchor: '#resolution', text: '1. Start from schema.defaults.\n2. Apply the workspace document, for declared keys only.\n3. Apply the site document, for the keys it actually holds.\n4. Coerce once, at the end.\nStep 4 is the subtle one. Because coercion happens last, a site override of the wrong type falls back to the workspace value it was trying to replace, not to the schema default. The other way round, one malformed site setting would silently discard a workspace answer the operator can see in their own console.\nA key is an override when it is present on the site document. undefined counts as absent — a form that writes { key: undefined } to mean "stop overriding" is doing the same thing as one that never wrote the key, and treating the two differently would make "revert to the workspace value" depend on which code path cleared it.\nClearing an override means deleting the field setDoc(..., { merge: true }) leaves an existing field exactly as it is when the new object omits it. A form that drops empty inputs therefore cannot clear anything by saving — the override survives, invisibly, and the site keeps ignoring a workspace value the operator has since changed.\nDeleting the field is the only write that returns a key to inherited. The console\'s own settings form does this behind its Inherited control.' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: 'What the console renders', anchor: '#console-ui', text: 'The Plugins & add-ons hub builds a form from your schema, so a plugin gets a settings UI without writing one. At site scope the same form marks each field Set for this site or Inherited, and offers a control to drop the override.\nWho may write which document is enforced by security rules, not by the form: the workspace document takes an org manager, the site document takes a site admin. Writes to either are frozen while the organization is suspended or the site\'s writes are frozen.\nNever put a secret in plugin config There is no secret field type and no redaction. Both documents are read client-side — the workspace document by any member of the organization — so anything stored here should be assumed visible to everyone in the workspace and present in the browser. API keys, tokens and signing secrets belong in the environment; see Manifests & environment.' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: 'API summary', anchor: '#api', text: '| Symbol | From | Purpose |\n| registerPluginConfigSchema(schema) | @aglyn/aglyn | Declare the settings. Idempotent per pluginId. |\n| getPluginConfigSchema(pluginId) | @aglyn/aglyn | The registered schema, or undefined. |\n| listPluginConfigSchemas() | @aglyn/aglyn | Every registered schema — what the console\'s hub enumerates. |\n| mergePluginConfig(schema, stored) | @aglyn/aglyn | Defaults merged with one document, coerced. |\n| resolvePluginConfig(schema, { org, host }) | @aglyn/aglyn | The full three-layer resolution. |\n| pluginConfigOverrides(schema, host) | @aglyn/aglyn | Which keys a site is answering for itself. |\n| validatePluginConfigValues(schema, values) | @aglyn/aglyn | Pre-save check: coerce, then run validate. |\n| getPluginConfig(orgId, pluginId, { hostId }) | @aglyn/aglyn/server | The resolved config for a request. |\n| usePluginConfig(orgId, pluginId) | client | Workspace-scope resolved config. |\n| useSitePluginConfig(orgId, hostId, pluginId) | client | Site-scope resolved config, plus overrides. |' },
  { path: '/developers/plugins/reference/plugin-config', title: 'Plugin configuration', heading: 'Related', anchor: '#related', text: '- Plugin-manager API reference\n- Manifests, trust lifecycle & environment\n- Building feature plugins' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: '', anchor: '', text: 'Plugin-manager API reference\nEverything a plugin registers goes through libs/aglyn/src/lib/plugin-manager, re-exported from @aglyn/aglyn (client + isomorphic) and @aglyn/aglyn/server (adds the server-only loaders). Hand-written by design: the surface is small and curated, and each entry needs semantics (ordering, caching, failure behavior) that generated signatures can\'t carry.' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Console extensions — `feature-plugins`', anchor: '#console-extensions--feature-plugins', text: '| API | What it does |\n| registerConsoleExtension(extension) | Declares everything a plugin adds to the console shell. Idempotent by pluginId (re-registration replaces). |\n| listConsoleNavItems() / resolveConsolePluginPage(href) | How the shell renders nav + serves plugin pages under /[orgSlug]/hosts/[host]/[...pluginSlug]. The resolver matches an exact href, or a declared section beneath one — longest href wins, prefixes match on a segment boundary, and a tie between two enabled plugins refuses. It answers { extension, navItem, section?, segments }. |\n| listConsoleWidgets(slot) | Widgets registered for a named zone — see Injection zones. |\n| listConsoleProviders() | App-level providers mounted around every console page. |\n| defineUiFeatureBundle(options, components) | Site/canvas component bundle; auto-depends on the base mui bundle. Component and bundle ids are persisted in screen docs — never rename. |\n| CONSOLEWIDGETSLOTS | The typed injection-zone catalog. |\nConsoleExtension fields: pluginId, displayName, featureFlag? (plan-entitlement gate the shell applies — extensions cannot bypass plans), navItems? (a nav item with a Component becomes a full page and receives ConsolePluginPageProps { hostId, entitled, org?, permissions?, releaseFlag?, basePath?, sections?, section?, segments? }), dashboardCards?, settingsSections?, widgets?, providers?.\nConsoleNavItem.sections? turns one surface into a hub of routes — each { id, label, navTabId? } becomes a URL at ${href}/${id}, and the shell hands the page section, sections (hrefs + release verdict), basePath and segments. An id nobody declared is a 404, never a fallback to the first section; a section\'s own navTabId ANDs with its nav item\'s, so a section is never reachable when its surface is not. Omitting sections keeps the ' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Loading — `plugin-loader`', anchor: '#loading--plugin-loader', text: '| API | Semantics |\n| createPluginLoader(manifest) | One loader per generated manifest; loads are cached per plugin, registrations once per plugin+surface. |\n| loader.ensure(ids, surfaces) | Loads + registers the given plugins\' surfaces. Returns a stable promise per (ids, surfaces) so React use() can suspend on it during SSR — the canvas never renders against an empty registry. Unknown ids are ignored (marketplace realm plugins load separately); alwaysOn entries activate regardless. |\n| loader.ensureAll(surfaces) | Every manifest plugin — the API dispatchers\' lazy-load-all. |\n| loader.pluginIdForApiPath(path) | Prefix-map fallback for the per-request org gate. |\nLifecycle: all register fns in an ensure batch run first, then each module\'s optional bootstrap () export runs (manifest order, once per plugin+surface, failures logged not fatal) — the sanctioned place for cross-plugin wiring. Plugins loaded by a later ensure bootstrap in that batch, so read registries lazily rather than snapshotting.' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Server APIs — `api-plugins` (`/server` only)', anchor: '#server-apis--api-plugins-server-only', text: '| API | Semantics |\n| registerPluginApiRoute(path, handler) | Registers an exact path under the [...pluginApi] dispatchers. Ownership is recorded at registration time for the per-request org gate — a disabled plugin\'s paths 404 for that workspace. |\n| PluginApiRequest | { method, query, body, headers, rawBody? } — rawBody carries the unparsed payload for Stripe/Svix signature verification. |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Site pipeline — `site-runtime`, `site-page-hooks` (`/server` for hooks)', anchor: '#site-pipeline--site-runtime-site-page-hooks-server-for-hooks', text: '| API | Semantics |\n| registerSiteRuntime({runtimeId, Component}) | Components rendered on every published page (overlay engines, experiment runners); they read back the props their server enricher wrote. |\n| registerSiteRedirectResolver(fn) | Runs before route resolution; first non-null redirect wins. |\n| registerSitePageResolver(fn) | Composes plugin-owned pages (commerce PDP/PLP). |\n| registerSitePageEnricher(fn) | Contributes page-prop slices; enricher errors are isolated — a broken plugin drops its slice, never the page. |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Stylesheets — `plugin-styles`', anchor: '#stylesheets--plugin-styles', text: 'Raw CSS your plugin ships, routed so the besigner canvas resolves it exactly as a published page does.\n| API | Semantics |\n| registerPluginStyles({pluginId, styleId?, css}) | Registers (or replaces) one stylesheet. Rendered as a plain at the site-content root of every surface — published tenant, editor Preview, and inside the besigner canvas\'s shadow root. |\n| unregisterPluginStyles(pluginId, styleId?) | Drops one sheet, or all of a plugin\'s. |\n| listPluginStyles() / subscribeToPluginStyles(fn) | The registry, and a change subscription. |\n| capturePluginStyles(pluginId, load) | Used by the realm loader; see below. |\nWhy you cannot just write to document.head. You can, and on a published page it works — but the besigner canvas renders site content inside a closed shadow root, which a document-level rule never reaches. Measured: the same rule that beats every MUI declaration on the published page has no effect at all on the canvas. So a plugin that styles itself that way looks one way in the editor and another way live.\nloadRealmPlugins therefore wraps each bundle\'s module evaluation and register() in capturePluginStyles, which picks up any the bundle appends to document.head — the shape import \'./styles.css\' compiles to in every bundler — and mirrors it into the canvas. The original element is left where the bundle put it, so CSS you ship for a console surface keeps working. Anything injected outside that window (lazily, or from a ) is not mirrored: call registerPluginStyles for those.\nCascade position. Plugin CSS is deliberately unlayered, while all MUI and author sx output sits in @layer mui. An unlayered normal declaration beats every layered one regardless of specificity, so a one-tag selector of yours outranks a MUI component default — by design, and identically on ' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Billing — `billing-webhook-hooks` (`/server`)', anchor: '#billing--billing-webhook-hooks-server', text: 'registerBillingWebhookHandler(eventTypePrefix, handler) — receives the platform Stripe events. Handler errors propagate to a 500; make handlers idempotent. Handlers run sequentially with no error isolation, deliberately: isolating them would trade a duplicated side effect for a dropped one, which is the worse trade on a money path.\nA handler may return { claimed: true } to tell the platform it recognized the event as its own — it found the order, the purchase, the booking. Returning nothing keeps the previous meaning ("not mine"), so existing handlers need no change. Every registered handler still runs after one has claimed; the claim is a report, never a dispatch rule.\nClaim your chargebacks The one event where this matters today is charge.dispute.. A dispute carries no metadata, so plugins self-select by joining on the payment intent — and a plugin that finds nothing looks identical to a plugin that failed. The console route raises a staff alert for any dispute nothing claimed, because that is money moving with no record of it anywhere. If your plugin owns disputes, claim the ones it handles, or every one of them will be reported as a platform fault.\nA 500 does not always mean a redelivery A throw that reaches the route after any dispatch has begun makes the platform hold its Stripe-event idempotency claim instead of releasing it, so the redelivery short-circuits as a duplicate and your handler is not run again — the failure is recorded on the claim and escalated to staff to reconcile by hand. Releasing the claim would let a redelivery re-apply whatever the failed dispatch had already committed (an inventory decrement, a gift-card balance, a coupon redemption), and those cannot be un-applied.\nA throw raised before any dispatch began still releases the claim and is red' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Enablement, flags, config, fields, permissions, jobs', anchor: '#enablement-flags-config-fields-permissions-jobs', text: '| API | Semantics |\n| resolveEnabledPlugins(org) | The org switchboard: absent field → all first-party; always-on unioned in; unknown (marketplace) ids kept. |\n| filterPluginsByReleaseFlags(ids, isFlagOn, {staffBypass}) | Subtracts release-flagged-off first-party plugins (AGL-422). |\n| registerPluginConfigSchema(schema) / mergePluginConfig / resolvePluginConfig / pluginConfigOverrides / validatePluginConfigValues | Per-plugin settings: declared once, generic form + typed reads everywhere, resolved across schema defaults → workspace → per-site override (AGL-428). Full contract: Plugin configuration. |\n| registerCustomFieldType(fieldType) / validateCustomFieldValue | Dataset field types riding existing storage types (AGL-434). |\n| registerPluginPermissions(list) | Role-resolved permission keys with per-tier defaults (AGL-435). |\n| registerPluginJob(job) / runPluginJobs(due?) | Scheduled jobs run by the guarded /api/plugins/run-jobs route (AGL-435). job.lockdown is required; the runner injects a PluginJobHostGate into every handler (AGL-2495). |\n| registerPluginJobHostLockdown(fn) / pluginJobHostGate() | How the HOST APP supplies the per-host lockdown verdict the job beat asks, and how a manual cron door mints the same gate (AGL-2495). |\n| registerPluginInstallPresetMapper(fn) | Maps marketplace install docs to besigner drawer presets. |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Remote bundles — `realm-plugins` (isomorphic), `realm-server` (`/server`)', anchor: '#remote-bundles--realm-plugins-isomorphic-realm-server-server', text: '| API | Semantics |\n| PLUGINHOSTABIVERSION / setRealmPluginHost(host) | The AGLYNPLUGINHOST ABI slot; the app composes it from its own React/jsxRuntime/registry singletons. |\n| verifyRealmBundle(bytes, install, publicKey?) | sha256 pin always; Ed25519 signature mandatory when a key is configured (fails closed). |\n| loadRealmPlugins(installs, {artifactsBase, publicKeyBase64}) | Fetch → verify → blob-URL import → register(host). Cached per listing@version; ABI mismatches refused; per-bundle failures logged and skipped. |\n| loadRemoteServerBundles(source) | Env-gated server tier (default OFF); returns what loaded so callers can audit. |\n| isCompatibleHostAbi(hostAbi?) | The ABI gate: undeclared = legacy (allowed with a warning). |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Sandbox — `plugin-bridge`', anchor: '#sandbox--plugin-bridge', text: 'The versioned postMessage protocol between the host PluginFrame and a sandboxed bundle: parseGuestMessage (origin/source/schema-validated), filterPluginProps (manifest allowlist), message types ready/init/ props/resize/event/fetch-request/fetch-response/error. The bridge never evals or grafts anything from the frame — sized output and named events only; network goes through the host-mediated fetch (server-side allowlist re-check).' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: '', anchor: '', text: 'Sandbox security model\nMarketplace plugins run sandboxed by default: in an iframe on a separate origin, with a Content-Security-Policy built from your own manifest. This page is what that means in practice, because most of it only becomes visible when something you wrote doesn\'t work.\nThe alternative tier — realm bundles, which run in the host realm — is covered in Realm bundles.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'A separate origin', anchor: '#a-separate-origin', text: 'Sandbox iframes are served from plugins.aglyn.com, not from the console or the site. That\'s a different origin, so the browser itself — not our code — is what stops a plugin from touching the host page\'s DOM, cookies, or storage.\nEverything a sandboxed plugin does to the outside world goes through the bridge: declared props in, declared events out. Undeclared props are dropped before your code sees them, and undeclared events are dropped before the host does.\nThe loader only allows framing from the console, .aglyn.app sites, and each site\'s verified custom domain — so your plugin renders on a customer\'s own domain exactly as it does on their aglyn.app address.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'Per-manifest network policy', anchor: '#per-manifest-network-policy', text: 'This is the one that surprises people.\nThe loader stamps a CSP whose connect-src is \'self\' plus exactly the origins you declared in your manifest\'s capabilities.network. A fetch to anywhere else is blocked by the browser.\nWith that manifest, fetch(\'https://api.example.com/…\') works and fetch(\'https://api.other.com/…\') does not.\nThe failure mode is a CSP error, not a 4xx A blocked request never reaches the network. You\'ll see a CSP violation in the browser console and a rejected promise — not an HTTP status. If a request "just fails" with no response, check your manifest\'s network list first.\nIf the manifest lookup fails for any reason, the loader falls back to \'self\' — the strict end. It never fails open.\nWhen you can\'t declare the origin\nDeclaring every origin up front doesn\'t fit every case — a URL the site owner configures, or an API that redirects across hosts. For those, use the host-mediated hostFetch escape hatch: the request is made by the host, subject to its own rules, and the response is handed back over the bridge. See Server APIs.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'Pinned, immutable artifacts', anchor: '#pinned-immutable-artifacts', text: 'Bundles are streamed from a private bucket at /artifacts/{listing}/{version}/{sha}.bundle, and every consumer verifies the sha256 before running a byte of it.\nInstalls pin {version, sha256}, so:\n- You can never change the code an existing install runs. Ship a new version.\n- A tampered artifact fails the hash check and doesn\'t execute.\n- "Update to vX" is always an explicit act by the person who installed it.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'What this means when you build', anchor: '#what-this-means-when-you-build', text: '- Declare network honestly and minimally. It\'s both your allowlist and a disclosure buyers read — an over-broad list costs you trust in review.\n- Test in the sandbox, not just locally. A plugin that works against a dev server with no CSP will hit the policy the moment it\'s published.\n- Document data & permissions in your README. Unverified sandbox listings show buyers a risk disclaimer; clear docs are what overcomes it.\n- Don\'t reach for realm trust to dodge the CSP. Realm trust is granted by Aglyn staff for a specific reviewed version, not on request.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'Related', anchor: '#related', text: '- Manifest & environments — the capabilities block.\n- Realm bundles — the trusted tier and how trust is granted.\n- Publisher handbook — review expectations.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: '', anchor: '', text: 'Self-hosting Aglyn\nAglyn is Apache-2.0 and the whole platform is public on GitHub. You can run it yourself with Docker on any infrastructure — a cloud VM, a VPS, or bare metal.\nWhat self-hosting v1 means You run the same code Aglyn\'s cloud runs, pointed at your own Firebase project (Google account required — the free tier is fine to start) plus your own Stripe and Resend keys. A fully vendor-neutral backend that removes the Firebase dependency is a separate roadmap track.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'The short version', anchor: '#the-short-version', text: 'There is no image to pull — you build it Aglyn publishes no Docker images, on any registry. docker compose up\n--build from a clone is the only supported path, and that is deliberate rather than pending: Next inlines every NEXTPUBLIC value into the client bundles when the image is built, and this deployment has 27 of them — your Firebase client config, your console URL and tenant apex, your brand name, and the operator and DMCA-agent details shown on your public abuse intake. An image built by someone else would ship their answers to all of those inside your bundles. If you find something claiming Aglyn offers prebuilt images, it is wrong.\nGive Docker more memory than it starts with Docker Desktop allocates 2 CPUs and 4 GB by default on macOS and Windows, and the Next production build does not fit in it — it is killed by the out-of-memory killer about ninety seconds in, with a message that never mentions memory:\nRaise it to 8 GB or more under Settings → Resources before you build. If you cannot, build the two images one at a time (docker compose build console, then docker compose build tenant) — up --build builds them concurrently and roughly doubles peak demand. Capping Node\'s heap does not help: Next builds with Turbopack, which allocates outside the heap --max-old-space-size bounds. Measured: 4 GB fails, 12 GB builds both in about six minutes (AGL-2437).\n- Console (the management app) on http://localhost:4200\n- Tenant runtime on http://localhost:4500 — a specific site is served at .localhost:4500; the bare port serves the demo tenant.\nDon\'t skip any of the three A stack that boots without the rules deployed is a stack whose data is not protected the way the application assumes. The rules scripts talk to Firebase\'s API directly with your service-account credentials — n' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'The full runbook', anchor: '#the-full-runbook', text: 'Every variable this deployment reads — what it drives, where to get its value, what shape it takes, and whether changing it needs a rebuild — is in Environment variables. Keep it open beside this page while you fill in .env.selfhost.\nThe complete, always-current runbook lives in the repository: docs/SELFHOSTING.md. It covers:\n1. Creating your Firebase project (Auth, Firestore, Storage, Realtime Database, and Remote Config) and minting a service account.\n2. Deploying the repo\'s security rules to your project with the bundled scripts.\n3. Filling in .env.selfhost — which values are baked into the client at image-build time versus read at runtime.\n4. Reverse-proxy setup for the console and the tenant runtime.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Who runs this install', anchor: '#who-runs-this-install', text: 'Two values are not optional in the way the keys below are, because leaving them out changes what your users and third parties are told about who is responsible for your site:\nThey name you on the public abuse intake (/api/report-abuse), the §512 counter-notice intake (/api/counter-notice), the lockdown 503, the media quarantine notice and the sanctions 451. These pages ship with the software and the first two are unauthenticated — a copyright holder or a browser vendor can reach them without an account.\nThere is deliberately no fallback to Aglyn\'s addresses. Earlier builds hardcoded them, which meant a self-hosted deployment published a DMCA intake directing statutory notices to Aglyn — about content Aglyn does not host and cannot remove. Unset now renders an explicit "not configured" state instead.\nBecause these are NEXTPUBLIC, they are compiled into the client bundles. Set them before docker compose build, not just before up.\nYour DMCA position is your own\nThe counter-notice flow, the 10–14 business-day put-back clock and the repeat-infringer strike ledger all work on your install. Aglyn\'s designated agent registration does not extend to you: §512(c)(2) makes registering an agent with the U.S. Copyright Office a precondition of the safe harbour rather than a formality.\nSo NEXTPUBLICOPERATORDMCAAGENT defaults to unset, unset means the product claims nothing, and NEXTPUBLICOPERATORDMCAAGENTREGISTERED must be exactly true before anything states a registration. Naming an agent never implies one.\nRegistering is only half the duty. §512(c)(2) also requires the agent\'s name, address, phone number and email to be available to the public through your service — a separate obligation the Copyright Office filing does not discharge. Set all four (NAME, ADDRESS, PHONE, EMAIL) and t' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Which addresses this install calls its own', anchor: '#addresses', text: 'The operator identity above says who you are. This section is about where your deployment lives, and it is the group most often left at its default — with the default being one of Aglyn\'s own hostnames.\nNEXTPUBLICTENANTDOMAIN — set this one first {#tenant-domain}\nThe apex your sites\' assigned subdomains hang off. A site whose subdomain is acme is served at acme. .\nUnset, it is aglyn.app — Aglyn\'s cloud. This is the single most consequential value on the page, because the damage is not confined to your own console. The same constant is what every published site uses to describe itself to the outside world:\n- on every page\n- /api/sitemap and /api/robots\n- item links in /api/collections-rss\n- /api/manifest\n- og:image\n- the origin an inbox-bound in email resolves against\nLeft at the default, your customers\' sites tell Google, every feed reader and every inbox that they live at an address you do not control and Aglyn does not serve for you.\nAGLYNTENANTHOSTCNAME — and its near-twin {#tenant-host-cname}\nThis is what the tenant runtime matches an incoming Host header against. A request for that name, or for anything under . , resolves to one of your published sites; anything else falls through to the custom-domain path. It has no default.\nThere is a second, similarly-named variable, and they are not the same one:\n| Variable | Read by | If unset |\n| AGLYNTENANTHOSTCNAME | The tenant runtime, to resolve incoming hosts | No apex matches, and every visitor falls through |\n| NEXTPUBLICAGLYNTENANTHOSTCNAME | The console, as the CNAME target it displays and verifies in the custom-domain wizard | Defaults to sites.aglyn.app |\n.env.selfhost.example carries both, on adjacent lines. Set both, to the same value. The first is consumed at image-build time, so it has to be in the env file bef' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Renaming the product', anchor: '#platform-brand', text: 'NEXTPUBLICPLATFORMBRANDNAME renames the product everywhere it names itself: browser-tab titles, the installable PWA, the relying-party name the operating system shows when someone saves a passkey, transactional email, and the / x-powered-by fingerprint on every site you publish. Unset, it is Aglyn.\n| Variable | Unset means |\n| NEXTPUBLICPLATFORMBRANDNAME | Aglyn |\n| NEXTPUBLICPLATFORMBRANDLEGALNAME | LLC — a US company form, so set it if you are not one |\n| NEXTPUBLICPLATFORMSUPPORTURL | Falls back to NEXTPUBLICOPERATORSUPPORTEMAIL as a mailto: before it ever falls back to Aglyn\'s support page |\nBrand images are not environment variables and are not meant to be: the favicon, app icons and social card are files under apps/console/public/static/images/brand and the matching tenant path. Replace them in your Docker build context.\nNEXTPUBLIC is baked in at build time Every variable on this page whose name starts with NEXTPUBLIC is compiled into the client bundles when the image is built. Changing one needs docker compose build, not a restart. A restart will appear to do nothing, which is the failure mode worth recognizing.\nThis is the deployment-level rename, and it is orthogonal to the per-organization white-label feature. The platform brand is what every organization on your install falls back to; white-label is a paid entitlement that lets one organization override it for itself. The two compose: on your deployment, a non-white-label organization renders your brand, not Aglyn\'s.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Optional keys', anchor: '#optional-keys', text: 'Beyond the Firebase blocks and the addresses above, most of what is left is optional, and a missing key disables its feature rather than breaking the stack. This is the index; Environment variables has the value shape, the default and the symptom for each one.\n| Feature | Keys |\n| Billing & commerce checkout | STRIPE — the secret key alone covers storefront checkout; plan checkout also needs the publishable key, the webhook secret and the STRIPEPRICE ids |\n| Transactional & campaign email | RESENDAPIKEY, USAGEEMAILFROM — the sender address gates all outbound mail, not just usage mail |\n| One-click unsubscribe | EMAILUNSUBSCRIBESECRET, which falls back to CRONSECRET |\n| Publishing that takes effect immediately | REVALIDATESECRET — without it a publish reports success and the live page stays stale for up to ten minutes |\n| AI assist | ANTHROPICAPIKEY, plus the spend caps beside it |\n| Scheduled jobs | CRONSECRET — the job routes stay dormant without it. See below for what that silently switches off |\n| Scheduled plugin jobs | PLUGINJOBSSECRET — without it no scheduled publishing and no booking-hold expiry ever runs |\n| Customer issue reports | LINEARAPIKEY and LINEARCUSTOMERREPORTSTEAMID — both required. See below |\n| The every-minute job beat | AGLYNJOBRUNNERURL, only if you deploy cloud/functions. See below |\n| The fifteen-minute console sweeps | AGLYNCONSOLEURL, only if you deploy cloud/functions. See below |\nScheduled jobs {#scheduled-jobs}\nThree separate mechanisms, and missing any of them is quiet rather than loud.\nCRONSECRET is the shared secret every scheduled route checks. Without it those routes answer 501 and do nothing — including audit archival, erasure runs, retention sweeps, booking reminders, abandoned-cart and restock mail, and, least obviously, scheduled' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Publishing your own documentation', anchor: '#docs-build', text: 'apps/docs is a standalone Docusaurus package. It is not part of docker compose; you build and publish it separately if you want your own documentation site. Skip this whole section if you do not.\nEvery value below is read at build time by docusaurus build, from that build\'s environment. They are not container runtime environment, and they are not NEXTPUBLIC — Docusaurus is not Next. Set them before the build, not after; the values are baked into the static output.\n| Variable | Unset means |\n| DOCSGATRACKINGID | No analytics tag is loaded at all |\n| DOCSERRORBEACONENDPOINT | The browser error beacon installs no handlers |\n| DOCSSTATUSTARGETS | /status probes nothing and says so |\n| DOCSSTATUSFALLBACKURL | /status names no independent monitor to fall back to |\n| DOCSURL | The canonical origin is https://docs.aglyn.com |\n| DOCSORGANIZATIONNAME | The footer copyright reads Aglyn LLC, followed by Aglyn\'s trademark attribution. Setting it replaces the name and drops the attribution — a rebranded build must not claim our marks. |\nThe rule to hold on to for the first three: unset means off, never ours. They previously defaulted to Aglyn\'s GA4 property, Aglyn\'s error collector and Aglyn\'s production health endpoints — so a published build reported your readers to us and told them our uptime was yours, which is a false all-clear during your own outage.\nDOCSSTATUSTARGETS is a comma-separated list of name|label|origin|description|path entries. A name and an origin are required; the description may be omitted and an empty label falls back to the name, so console||https://console.example.com is a valid entry:\nThe fifth field is the health path to probe, and defaults to /api/health. Point a target at a subsystem endpoint when the aggregate is not the signal you want a visitor to see —' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Honest limits', anchor: '#honest-limits', text: '| Area | Self-hosted behavior |\n| Firebase | Required — Auth, Firestore, Storage, RTDB, and Remote Config run in your project. |\n| Custom-domain self-service | Behind the domain driver. webhook registers a customer\'s domain automatically through your own proxy\'s API. wildcard cannot — nobody\'s wildcard covers somebody else\'s apex — so it answers 501 and you route the name by hand; the site still serves, because the domain claim is written before the refusal. DNS verification works everywhere. Per-driver detail. |\n| Custom-domain verification | The verify step requires an exact CNAME match, or an apex address match when the name carries no CNAME at all. There is a soft pass that accepts any CNAME, for local development where no DNS points at a tenant edge. It used to be enabled by the absence of a hosting vendor\'s environment variable — which a container never sets — so it was on in production on every self-host install, and any domain carrying any CNAME to anywhere verified. A user of your platform could claim a domain they do not control. It now keys on NODEENV, which both Dockerfiles set to production in the image that actually runs. If you run an image built before this fix, upgrade. |\n| Legal pages & clickwrap | The signup checkbox links Aglyn LLC\'s Terms and Privacy and records acceptance against Aglyn\'s document hashes. Nothing breaks, but the agreement is ours, not yours, and is not yet configurable. Replace it before running this for anyone but yourself. |\n| Marketplace | Visible by default, but backed by Aglyn\'s Stripe Connect platform. Browsing works; purchase and payout onboarding explain themselves only after a click. Turn releasemarketplace off in Remote Config if you don\'t want it. |\n| Wildcard published-site domains | Supported. The tenant runtime resolve' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Related', anchor: '#related', text: '- Environment variables — the complete per-variable reference\n- Domain providers — choosing a driver, the wildcard path end to end, and the webhook contract\n- White-label\n- Report an issue\n- Billing & plans' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: '', anchor: '', text: 'Environment variables\nThis is the per-variable reference for a self-hosted install. The setup order — Firebase project, security rules, indexes, TTL policies, reverse proxy — is in Self-hosting; read that first and keep this page open beside it while you fill in .env.selfhost.\nEverything here was read out of the source rather than copied from the template. Where a variable is absent from .env.selfhost.example, this page says so, because the template is what most operators actually fill in.' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Read this before you set anything', anchor: '#build-vs-runtime', text: 'Some of these are frozen when the image is built\nNext.js replaces the literal text process.env.NAME with its value at build time. It does that for three groups:\n1. Anything named NEXTPUBLIC, in both server and browser code.\n2. Anything listed in a next.config.js env block — with-aglyn.nextjs.config.js, apps/console/next.config.js and apps/tenant/next.config.js each declare one.\n3. Anything reachable from apps/console/middleware.ts, which is compiled into the edge bundle. The edge runtime has no request-time environment at all.\nFor every variable in those groups, changing the value in .env.selfhost and restarting the container does nothing. There is no error and no warning: the old value is literally compiled into the JavaScript that is running. You have to docker compose build again.\nOnly the dot form is substituted — the bracket form process.env[\'NAME\'] never is — so a variable read that way stays runtime-only even when its neighbors are not.\nEvery row carries a When column:\n| When | Meaning |\n| Runtime | Read on each request or at process start. Change it and restart the container. |\n| Build | Frozen into the image. Change it and run docker compose build before up. |\nAnd a Need column:\n| Need | Meaning |\n| Required | The deployment does not work without it. |\n| Feature | One named feature is off without it. The row says which, and what you see. |\n| Optional | A default applies. The row gives it. |\n| Aglyn-only | Read by the code but only meaningful on Aglyn\'s own hosted deployment. Leave unset. |' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Firebase — identity and data', anchor: '#firebase', text: 'Firebase is not optional in self-hosting v1: Auth, Firestore, Storage, Realtime Database and Remote Config are the platform\'s identity and data layer. Create a project at console.firebase.google.com and enable all of them.\nClient SDK config {#firebase-client}\nWhere to get these: Firebase console → Project settings → General → Your apps → add a Web app → copy the firebaseConfig object. Each field below maps to one key of it.\nEvery one is NEXTPUBLIC, so every one is Build. These end up in the browser bundle by design — Firebase web config is public, and access is controlled by your security rules, not by hiding these values.\n| Variable | Need | When | Value |\n| NEXTPUBLICFIREBASEPROJECTID | Required | Build | The project id, e.g. bramble-platform. Also the last of four sources the SAML SSO auth origin is derived from. |\n| NEXTPUBLICFIREBASEPUBLICAPIKEY | Required | Build | apiKey. Starts AIza…. |\n| NEXTPUBLICFIREBASEAUTHDOMAIN | Required | Build | authDomain, e.g. bramble-platform.firebaseapp.com. |\n| NEXTPUBLICFIREBASEDATABASEURL | Required | Build | databaseURL — Realtime Database, not Firestore. Presence and live collaboration use it. |\n| NEXTPUBLICFIREBASESTORAGEBUCKET | Required | Build | storageBucket, e.g. bramble-platform.firebasestorage.app. Bare bucket name, no gs://. |\n| NEXTPUBLICFIREBASEMESSAGINGSENDERID | Required | Build | messagingSenderId — a numeric string. |\n| NEXTPUBLICFIREBASEAPPID | Required | Build | appId, e.g. 1:123456789012:web:abc123def456. |\n| NEXTPUBLICFIREBASEMEASUREMENTID | Optional | Build | measurementId, G-XXXXXXXXXX, present only if you enabled Google Analytics on the Firebase project. Unset, Firebase Analytics is not configured and server-side conversion events carry no GA client id, so a purchase cannot be stitched back to the browser ' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'The addresses this install calls its own', anchor: '#addresses', text: 'This is the group most often left at its default, and several of the defaults are Aglyn\'s addresses. Every one is Build.\n| Variable | Need | When | Value |\n| NEXTPUBLICCONSOLEURL | Required | Build | Full origin of your console, no trailing slash: https://console.example.com. Feeds the tenant\'s fallback redirect, the edit-hint return allowlist, the auth-action link base and the CSP frame-ancestors list. Default https://app.aglyn.com, so unset sends a visitor who lands on an unresolvable host to Aglyn\'s console and builds password-reset links on it. |\n| NEXTPUBLICWORKSPACEDOMAIN | Required | Build | The apex organization workspaces hang off, bare: example.com. A workspace acme is advertised at acme.example.com. Point a wildcard .example.com at your console, or that URL does not resolve. |\n| NEXTPUBLICTENANTDOMAIN | Required | Build | The apex your published sites\' subdomains hang off, bare: sites.example.com. Defaults to aglyn.app — Aglyn\'s cloud — so leaving it unset makes your console display and link every one of your sites at an address you do not control, and makes each published site advertise that address as its canonical origin to search engines, feed readers and inboxes. |\n| NEXTPUBLICAGLYNTENANTHOSTCNAME | Required | Build | The CNAME target your console prints and verifies in the custom-domain wizard. Normally the same value as NEXTPUBLICTENANTDOMAIN. Default sites.aglyn.app. |\n| AGLYNTENANTHOSTCNAME | Required | Build | The same value again, without the prefix. This is the load-bearing half: the tenant middleware matches the incoming Host: header against it. Leave it blank and nothing matches, so every visitor to every published site is redirected to your console — the deployment looks broken rather than misconfigured. Inlined through apps/tenant/next.config.' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Your reverse proxy, the client IP, and geo', anchor: '#proxy', text: 'X-Forwarded-For: tell the product how many proxies you run {#xff}\n| Variable | Need | When | Value |\n| AGLYNTRUSTEDPROXYCOUNT | Recommended | Runtime | How many proxies sit between the internet and the container. One reverse proxy is 1, which is also the default. A CDN in front of your own proxy is 2. 0 means nothing is in front and forwarding headers are ignored entirely. Not a header index — you never have to work out which end of the list to count from. |\nEvery client address in the product is read through one reader, which takes the hop this number identifies and ignores everything to its left. With N proxies in front, the last N entries of x-forwarded-for were written by your proxies and are the only ones a caller cannot forge; the outermost of them recorded the address it actually saw, which is the visitor.\nSet this if you run more than one proxy\nnginx\'s usual proxysetheader X-Forwarded-For $proxyaddxforwardedfor appends. A request arriving with a header the client typed — X-Forwarded-For: 1.2.3.4 — leaves your proxy as 1.2.3.4, . At the default of one trusted proxy the product reads and the forged value is discarded, which is what you want. Configure 2 when a CDN sits in front, or the reader names your own proxy instead of the visitor — several visitors then share one rate-limit bucket and limits bite sooner than they should.\nToo high is the safer direction than too low: a chain shorter than the configured depth is clamped to its leftmost entry, which was still written by a proxy you trust.\nWhat this protects:\n- Authentication throttles — passkey sign-in (both ceremony steps), password-reset mailbombing, identifier resolution, storefront member login and member recovery.\n- Provisioning throttles — organization creation (the bot-farm control), site creation, scree' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Secrets this deployment signs with', anchor: '#secrets', text: 'Generate each with openssl rand -hex 32. All are runtime, all are server-only, and none of them may ever be prefixed NEXTPUBLIC.\n| Variable | Need | When | Value |\n| TOKENSIGNINGSECRET | Required | Runtime | Signs commerce download links, gift-card links, gated-video streams, media access and edit-hint tokens. Must be identical for console and tenant — compose shares one env file, so it is. The code fails closed: unset, it throws rather than issuing an unsigned link. |\n| MEMBERSESSIONSECRET | Required | Runtime | Signs the storefront member session cookie (30-day TTL). Unset or empty, a fresh random key is generated per boot, so members are signed out on every container restart and replicas disagree with each other. An empty value is treated as unset, not as a key. |\n| REVALIDATESECRET | Set it | Runtime | The shared secret the console sends when it asks the tenant runtime to drop a published page from cache. Easy to miss, because its absence is completely silent: unset, the console never sends the request at all and records the reason as not-configured: publishing reports success and the live page keeps serving the old HTML for up to 10 minutes and the old site documents for up to an hour. Set the same value on both containers. |\n| EMAILUNSUBSCRIBESECRET | Feature | Runtime | HMAC key over {hostId}:{email} for one-click unsubscribe links. Falls back to CRONSECRET; with neither set, campaign sends answer 501 and every unsubscribe link answers 400. |\n| CRONSECRET | Feature | Runtime | The shared secret every scheduled-job route checks — see Scheduled jobs. It is also the fallback unsubscribe key above, which makes rotating it a two-step operation: rotating it alone permanently breaks the unsubscribe link in every marketing email already delivered. |\n| PLUGINJOBSSECRET | ' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Stripe', anchor: '#stripe', text: 'Stripe is optional. Without it, commerce checkout and paid platform plans are unavailable and the rest of the platform runs.\nWhere to get these: dashboard.stripe.com → Developers → API keys for the two keys, Developers → Webhooks for the signing secrets, and Product catalogue → each price → its price id.\n| Variable | Need | When | Value |\n| STRIPESECRETKEY | Feature | Runtime | sklive… or sktest…. Enough on its own for storefront commerce checkout. |\n| NEXTPUBLICSTRIPEPUBLISHABLEKEY | Feature | Build | pklive… / pktest…. Needed for platform plan checkout; the secret key alone is not enough. |\n| STRIPEWEBHOOKSECRET | Feature | Runtime | whsec… for the endpoint you create at https://console.example.com/api/billing/webhook. Without it, webhook-driven state — subscription changes, payment settlement — is never applied: the money moves and your database never hears about it. |\n| STRIPEWEBHOOKSECRETTEST | Optional | Runtime | A second accepted signing secret so test-mode deliveries verify while live keys are in force. Each is tried in turn; the webhook route answers 501 only when all three secrets are unset. |\n| STRIPECONNECTWEBHOOKSECRET | Feature | Runtime | whsec… for the Connect destination, which feeds Connect readiness. Unset, those deliveries fail signature verification with 400 behind a green "Active" badge in the Stripe dashboard. |\n| STRIPEWEBHOOKURL | Optional | Runtime | The endpoint URL the billing health check expects to find registered in your Stripe account. Default is Aglyn\'s URL, so a self-host operator who leaves it unset gets a permanent endpoint-missing red on /api/health/billing. Must match the URL exactly as Stripe stores it. |\n| STRIPELIVEMODE | Optional | Runtime | Overrides whether this deployment considers itself the live one. Normally inferred from' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Email', anchor: '#email', text: 'Where to get these: resend.com → API Keys, and Domains to verify the domain you send from.\n| Variable | Need | When | Value |\n| RESENDAPIKEY | Feature | Runtime | re…. Without it every outbound send — invites, receipts, password resets, campaigns, security alerts — is an inert no-op. Nothing errors; mail simply does not arrive. |\n| USAGEEMAILFROM | Feature | Runtime | The single verified sender identity for all outbound mail, not just usage mail — it gates the "is email configured" check every sender consults. A bare address or Bramble . It has to be on a domain you verified in Resend, or Resend rejects the send. Unset, every sender no-ops or answers 501 with an actionable message; nothing throws. |\n| RESENDWEBHOOKSECRET | Optional | Runtime | Svix signing secret (whsec…) verifying Resend\'s delivery, open, click, bounce and complaint webhooks. Unset, that endpoint answers 501 and nothing is recorded: no open/click statistics, no bounce suppressions, and no per-recipient delivery history on the staff user page. |\n| RESENDREADAPIKEY | Optional | Runtime | A full-access Resend key, used only by the staff Import delivery history action to read already-sent mail into the per-recipient delivery log. Deliberately separate from RESENDAPIKEY, which is sending-scoped and answers every read with 401 restrictedapikey — a leaked sending key must not be able to enumerate everyone you have ever emailed. Unset, the import answers 501 and says so; the live webhook feed is unaffected. |\n| EMAILUNSUBSCRIBESECRET | Feature | Runtime | See Secrets. |\n| STAFFALERTEMAIL | Optional | Runtime | One internal inbox for platform-operations alarms — GDPR erasure due, Assist margin guard. One address, not a comma list. Unset, the alarms evaluate and mail nobody, with no error. |\nAlarm thresholds. Al' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Analytics and advertising', anchor: '#analytics', text: 'The advertising ids are Aglyn\'s own marketing funnel. Leave them unset.\nNEXTPUBLICADSCONVERSIONID, NEXTPUBLICADSSIGNUPLABEL and NEXTPUBLICADSSUBSCRIBELABEL identify a Google Ads account and two conversion actions inside it, so that Aglyn\'s own signup and subscribe events reach Aglyn\'s own advertising account.\nNEXTPUBLICMETAPIXELID, NEXTPUBLICLINKEDINPARTNERID and NEXTPUBLICGTMCONTAINERID are the same kind of value one step further: they build retargeting audiences, so a hardcoded one would put your users into Aglyn\'s advertising lists — a disclosure you never made about people we have no basis to hold. Your own advertising tags are your own business; set your own ids or leave every one of these blank.\nNothing is compiled in, and the code fires nothing when they are unset — no tag, no request. The half-configured case is handled too: an id with an empty label would produce a target Google Ads accepts and files against the account\'s default conversion, so the code returns nothing instead.\nThere is no default because analytics is permitted to emit on any production build including a self-hosted one. A hardcoded id would have every operator reporting their users\' signups into Aglyn\'s ad account. Leave them blank, or set your own.\n| Variable | Need | When | Value |\n| NEXTPUBLICADSCONVERSIONID | Aglyn-only / your own | Build | Google Ads conversion id, AW- plus digits. Google Ads → Goals → Conversions → the tag\'s id. |\n| NEXTPUBLICADSSIGNUPLABEL | Aglyn-only / your own | Build | The opaque conversion label for the signup action, from the same screen. Fires only when the id is also set. |\n| NEXTPUBLICADSSUBSCRIBELABEL | Aglyn-only / your own | Build | The conversion label for the subscribe action. |\n| NEXTPUBLICMETAPIXELID | Aglyn-only / your own | Build | Meta (Facebook/Insta' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'AI assist', anchor: '#assist', text: 'Where to get the key: console.anthropic.com → API keys. Bring your own; nothing is compiled in.\n| Variable | Need | When | Value |\n| ANTHROPICAPIKEY | Feature | Runtime | sk-ant-…. Powers the console Assist panel and the besigner\'s "Rewrite with AI". Without it both answer 501 and say they are not configured. The console panel is additionally behind the releaseassist flag, which is off by default in Remote Config. |\n| ASSISTMODEL | Optional | Runtime | The model id Assist calls. Default claude-sonnet-5. An id absent from the built-in rate table falls back to approximate rates, so cost telemetry and the margin alarm become estimates — and the prompt-cache minimum moves with the model, so a swap can silently stop caching. |\n| ASSISTFREEDAILYLIMIT | Optional | Runtime | Messages per free workspace per UTC day. Default 10. |\n| ASSISTENTITLEDMONTHLYLIMIT | Optional | Runtime | Messages per entitled workspace per month. Default 1000. |\n| ASSISTORGMONTHLYCOGSLIMITUSD | Optional | Runtime | Dollar ceiling per workspace per month, measured against metered cost rather than an assumed cost per message. Default 40. The literal word off removes the ceiling. Junk, empty, zero and negative values all read as unconfigured and take the default, so a typo can neither open the ceiling nor close it to $0. |\n| ASSISTORGMONTHLYCOGSALERTUSD | Optional | Runtime | Dollar figure at which a workspace\'s spend raises a staff margin alarm, below the hard ceiling. Default 25. Delivery needs STAFFALERTEMAIL and USAGEEMAILFROM. |\nMessage counting happens in a transaction before the model is called, so a refused request spends nothing. A workspace at the ceiling is refused rather than quietly downgraded to a cheaper model.' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Scheduled jobs', anchor: '#cron', text: 'Three separate mechanisms, and missing any of them is quiet rather than loud.\n| Variable | Need | When | Value |\n| CRONSECRET | Feature | Runtime | Shared secret every scheduled route checks, accepted as Authorization: Bearer or x-cron-secret: . Unset, every one of those routes refuses. openssl rand -hex 32. |\n| AGLYNJOBRUNNERURL | Feature (cloud functions) | Runtime | The tenant origin the every-minute beat POSTs: https://sites.example.com/api/plugins/run-jobs. No default, deliberately. |\n| AGLYNCONSOLEURL | Feature (cloud functions) | Runtime | The origin that serves your console — never one that redirects to it, because a redirect drops the POST body and the x-cron-secret header. No default, deliberately. |\nWhat CRONSECRET being unset silently switches off:\n- Scheduled campaign sends. You can schedule a campaign in the console, watch it be accepted, and watch its send time pass with nothing delivered and no error anywhere.\n- Audit archival, so the audit collection grows past its retention window and the retention promise goes quietly unkept.\n- Erasure runs, so personal data a customer asked you to delete is still there while the clock on that request runs.\n- Metered usage roll-up, so nothing is metered into Stripe and the monthly usage document is never written — which in turn means every usage budget is structurally unable to fire and the billing card permanently reads that the month has not been totalled.\n- Usage budget alerts and the monthly usage summary email.\n- Booking reminders, abandoned-cart mail and restock mail.\n- The weekly Firestore export, which is the restore point independent of managed backups.\n- Orphaned plugin-artifact reaping, which then accumulates unbounded.\n- Pending custom-domain completion, so a domain whose DNS has settled stays dark until s' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Plugins and the sandbox', anchor: '#plugins', text: '| Variable | Need | When | Value |\n| PLUGINARTIFACTSBUCKET | Feature | Runtime | The separate GCS bucket holding executable plugin bundles — the code refuses to store executable code in the app bucket. Unset, plugin publishing and artifact serving both answer 501. A bare bucket name. Note the bucket is invisible to the Firebase console; manage it in the Google Cloud console. |\n| PLUGINARTIFACTSBASE | Optional | Runtime | Origin the server-side remote-bundle loader fetches from. Falls back to NEXTPUBLICPLUGINORIGIN. Only relevant with remote server bundles enabled. |\n| NEXTPUBLICPLUGINORIGIN | Feature | Build | Full origin the plugin sandbox iframe and bundles are served from, and the entry added to the CSP frame-src. Must be a different origin from the app — the cross-origin boundary is the sandbox. Unset, realm plugins do not load and installed executable plugins render as nothing, because the CSP has no entry for them. |\n| PLUGINTRUSTPRIVATEKEY | Feature | Runtime | Signs realm trust grants. Base64 PKCS8 DER Ed25519, generated by tools/scripts/generate-plugin-trust-key.mjs. Unset, the grant action answers 501. Console only — never deploy it to a tenant runtime. |\n| PLUGINTRUSTPUBLICKEY | Feature | Runtime | The server-side verification key, base64 raw Ed25519. Required with remote server bundles enabled; unset there, no bundle loads at all — it fails closed rather than degrading to a hash check. |\n| NEXTPUBLICPLUGINTRUSTPUBLICKEY | Feature | Build | The same public key again, for browser-side verification of realm bundles. A mismatch with the server-side name refuses every bundle. |\n| PLUGINJOBSSECRET | Feature | Runtime | See Secrets. |\nDevelopment-only, and never to be set on a real deployment: NEXTPUBLICPLUGINDEV (exactly enabled, and hard-gated off when NODEENV=pr' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Who runs this install', anchor: '#operator', text: 'The reasoning is in Self-hosting → Who runs this install. The reference rows:\n| Variable | Need | When | Value |\n| NEXTPUBLICOPERATORNAME | Set it | Build | Your legal or trading name. Printed on the public abuse intake, the §512 counter-notice intake, the lockdown 503, the media quarantine notice and the sanctions 451. There is no fallback to Aglyn\'s name; unset renders an explicit "not configured". |\n| NEXTPUBLICOPERATORSUPPORTEMAIL | Set it | Build | The address those same pages tell people to write to. |\n| NEXTPUBLICOPERATORLEGALEMAIL | Optional | Build | A separate mailbox for legal and copyright notices. Defaults to the support address, so one mailbox is a complete configuration. |\n| NEXTPUBLICOPERATORLEGALORIGIN | Optional | Build | Where your own terms, privacy and DMCA pages live, no trailing slash. The signup clickwrap links here, and it governs which origin counts as a published legal document. |\n| NEXTPUBLICOPERATORDMCAAGENTNAME | Optional | Build | Designated agent\'s name. Both this and the address must be set before the block renders at all — a mailbox with no legal person or no physical address behind it is not a designation. |\n| NEXTPUBLICOPERATORDMCAAGENTADDRESS | Optional | Build | Physical address. |\n| NEXTPUBLICOPERATORDMCAAGENTEMAIL | Optional | Build | Agent email. Omitting it leaves that line out rather than inventing one. |\n| NEXTPUBLICOPERATORDMCAAGENTPHONE | Optional | Build | Agent phone. §512(c)(2) enumerates all four. |\n| NEXTPUBLICOPERATORDMCAAGENTREGISTERED | Optional | Build | Exactly true, and only if you have actually registered the agent with the U.S. Copyright Office. Naming an agent does not set it and nothing infers it. |\nNEXTPUBLICOPERATORLEGALORIGIN follows your origin, not your publication state The list of paths treated as publi' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Sales tax, and what to do if you are not in Texas', anchor: '#tax', text: 'The three variables below are the BOOTSTRAP. The control is in the console.\nWhere you file and the numbers you file under live in Staff → Platform settings → Sales tax filing, where changing them needs the super staff role and no deploy. Registering in a new state is an operator action, so it must not require an environment edit and a release.\nAGLYNTAXJURISDICTION, AGLYNTAXREGISTRATIONID and AGLYNTAXFILINGID are what a fresh install runs on before anybody opens that page: they fill in every field the console has not stored. Anything stored in the console wins, and the card names the layer each value came from — so a variable you set and then override is listed by name as not in force rather than quietly ignored. Clearing the stored record in the console hands these their layer back.\nUnset, and with nothing stored, the jurisdiction is US-TX and the identifiers are absent, so both surfaces read NOT CONFIGURED rather than printing anyone else\'s numbers.\nTexas is the one jurisdiction with a form this software knows. Everywhere else gets a return breakdown — what was collected, and where — labeled as raw material for filing by hand rather than as a return.\nTax collection and tax filing are different things in this product, and only one of them is portable.\nCollection is a real feature, and jurisdiction-neutral {#tax-collection}\nStorefront tax is configured per store, in the console, not by environment variable, and there is nothing Texas-specific about it:\n- Rates are { country, state?, pct } entries. country is any ISO 3166-1 alpha-2 code and state any subdivision; the most specific match wins, and a country-only rate covers the whole country.\n- Tax-inclusive pricing is supported, which is what VAT- and GST-style pricing needs.\n- Modes are manual, stripe or none. Under stri' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Caching, ISR, and running more than one replica', anchor: '#caching', text: 'Single-container is the supported shape.\nPublished pages are ISR-cached with a 10-minute window, site documents sit behind a one-hour render cache, and no shared cache handler is configured — so every replica keeps its own on-disk cache. Publishing POSTs /api/revalidate on the tenant, which busts the one replica that answered. The console reports an instant publish while every other replica keeps serving the old page for up to 10 minutes and the old documents for up to an hour.\nIf you scale out, either put a sticky-session proxy in front or fan the revalidate POST out to every replica yourself. Nothing errors in either case, which is what makes it worth knowing.\n| Variable | Need | When | Value |\n| REVALIDATESECRET | Set it | Runtime | See Secrets. Without it, no publish ever busts any cache. Set the same value on both containers: the console will not send the request without it, and the tenant endpoint answers 503 naming the variable rather than quietly doing nothing. |\nYour cache rules set your real takedown window\nSeveral endpoints send s-maxage with little or no browser max-age, on the assumption that a shared cache honors it — the per-host manifest and robots.txt at 5 minutes to an hour, sitemaps and feeds at 5 minutes, screen-node and commerce endpoints at 60–300 seconds. Behind a proxy that caches nothing they are simply recomputed per request: correct, slower, and several of them hit Firestore each time.\nThe consequence that is not about performance is media takedown. When staff disable a file, the reach of that action is derived from the media CDN\'s own cache directives, and the console prints those numbers to the person clicking the button: the origin stops serving it within about 15 seconds, a browser that already has it keeps it for up to 60 seconds, and a s' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Domains: how a hostname becomes reachable', anchor: '#domains', text: 'Registering a name used to be a call to Vercel\'s API, so a Docker install had no way to make a workspace subdomain resolve at all — it advertised a URL and skipped the registration. The hosting vendor is a driver now, and you pick one.\nThis section is the per-variable reference. Domain providers is the runbook beside it: how to choose a driver, the wildcard path end to end with worked Caddy and nginx configurations, a complete worked webhook endpoint, what each status state means for you, and how to migrate from one driver to another.\n| Variable | Need | When | Value |\n| AGLYNDOMAINPROVIDER | Optional | Runtime | vercel, wildcard, webhook or none. Unset, the deployment detects: vercel when VERCELTOKEN is present, none otherwise. An unrecognized value logs [domain-provider] unknown AGLYNDOMAINPROVIDER and falls back to detection. An explicit value always wins, none included — switching a driver off while its credentials are still in the environment means it. |\n| Driver | For |\n| vercel | Aglyn\'s own hosting, and anyone else on Vercel. |\n| wildcard | The ordinary Docker answer. A container behind a proxy that already answers for .example.com. |\n| webhook | Anything else — Caddy, Traefik, cert-manager, a registrar\'s API, a shell script. |\n| none | Names are handled entirely outside the product. Not an error state, and not something logged forever. |\nDetection never picks wildcard, and that is deliberate The wildcard driver reports a name as serving without checking anything — there is nothing to check, because the operator\'s DNS record and certificate either cover the apex or they do not. Inferring it from an apex somebody merely configured would have the console show a green chip beside an address that resolves nowhere. Claiming to serve a name is your assertion to make, ' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Documentation site build', anchor: '#docs-build', text: 'apps/docs is a standalone Docusaurus package. It is not part of docker compose; build and publish it separately if you want your own documentation site, and skip this section if you do not.\nEvery value here is read at build time by docusaurus build, from that build\'s environment. None is NEXTPUBLIC — Docusaurus is not Next.\n| Variable | Need | Value |\n| DOCSURL | Optional | The canonical origin your docs are served at. Canonical tags and the sitemap are built from it, so leaving it at the default makes your build claim docs.aglyn.com. |\n| DOCSORGANIZATIONNAME | Optional | Name in the footer copyright line. Default Aglyn LLC, followed by Aglyn\'s trademark attribution. Setting it replaces the name and drops the attribution. |\n| DOCSGATRACKINGID | Optional | Your own GA4 measurement id, G-XXXXXXXXXX. Blank loads no analytics tag at all. |\n| DOCSERRORBEACONENDPOINT | Optional | Where uncaught browser errors POST — e.g. https://console.example.com/api/errors. Blank installs no handlers. If you point it at your own console, set NEXTPUBLICDOCSORIGIN on that console to your docs origin so its CORS grant accepts you. |\n| DOCSSTATUSTARGETS | Optional | What /status probes, as comma-separated name\\|label\\|origin triples: console\\|Console\\|https://console.example.com,sites\\|Sites\\|https://sites.example.com. Blank probes nothing and says so. |\n| DOCSMETAPIXELID | Optional | Meta Pixel id for the docs site — digits only. Loads only for a reader whose consent record grants advertising; see the note below. Blank loads nothing. |\n| DOCSADSCONVERSIONID | Optional | Google Ads id, AW- plus digits. Rides the gtag.js the analytics tag already loaded rather than fetching a second copy. Same consent gate. Blank loads nothing. |\n| DOCSLINKEDINPARTNERID | Optional | LinkedIn Insight Tag partner' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Set by the image — do not put these in your env file', anchor: '#image-set', text: '| Variable | Set to | Why you must not override it |\n| AGLYNSTANDALONE | exactly 1, in the runner stage of both Dockerfiles | This is what tells the software it is a real deployment rather than a laptop. It gates the whole host-resolution switch, the canonical custom-domain redirect, and the CSP that drops Aglyn\'s own hostnames from your frame-ancestors. It is kept out of .env.selfhost.example on purpose: compose envfile overrides image ENV, so a line there would be a way to delete it and silently break serving. Only the string 1 counts — true and yes do nothing. |\n| NODEENV | production | Several safety relaxations key on "not production", the custom-domain verify soft pass among them. |\n| PORT | 4200 console, 4500 tenant | Compose publishes these on loopback. |\n| HOSTNAME | 0.0.0.0 | Listens inside the container\'s namespace. |\n| NEXTTELEMETRYDISABLED | 1 | No build telemetry leaves your machine. |\nStamping which build you are running {#build-stamp}\n| Variable | Need | When | Value |\n| COMMITREF | Optional | Build | An identifier for the build. /api/health reports it as commit, and client and server error reports and the staff config report all carry it. Best passed as a build argument, which changes per build: COMMITREF=$(git rev-parse HEAD) docker compose up --build. The build argument wins where both are set. Unset, the health body reports commit: null honestly rather than inventing one. The Dockerfiles read it in the build stage, so passing it at docker run is too late. |\n| BUILDID | Optional | Build | An explicit build id, checked before COMMITREF. Use it if you stamp builds with something of your own. |\n| PACKAGEVERSION | Set by the build | Build | Read from package.json at build time and reported by /api/health as version. Setting it in the environment does noth' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Development and Aglyn-internal variables', anchor: '#internal', text: 'Read by the code, but not operator configuration. Listed so that finding one in the source does not send you looking for a value to put in it.\n| Variable | What it is |\n| AGLYNTENANTDEMO | The tenant host id served when the request host is the console apex or localhost:4500. Default demo. Aglyn\'s own demo deployment. |\n| AGLYNCANARYSITEHOST, AGLYNCANARYMARKETINGHOST | Which hosts the render canary at /api/health/render renders. The site one falls through to AGLYNTENANTDEMO then demo, so an install with no demo host gets a canary reporting red on a host that was never meant to exist. The marketing one derives from your workspace domain and grades not-configured — a deliberate failure, not a pass — when it cannot. |\n| AGLYNTENANTHOSTID, AGLYNTENANTHOSTHOST, AGLYNTENANTHOSTHOSTNAME, AGLYNTENANTHOSTURL | Single-host tenant pinning, for a one-site deployment. Not used by the multi-tenant compose shape. |\n| AGLYNHOST, AGLYNHOSTNAME, AGLYNPORT, AGLYNPROTOCOL, AGLYNURL | Build-time origin overrides in the shared Next config. Leave at the defaults. |\n| AGLYNDISABLEBOOTWARMUP | Skips the tenant\'s boot warm-up. A debugging aid. |\n| CONSENTDEVCOUNTRY | On a non-production build only, the country the consent endpoint answers when no geo header is present — the default is US, so the implied-consent path is testable on a laptop. Hard-gated off when NODEENV=production, so it can do nothing on a real deployment. |\n| NEXTPUBLICAGLYNTENANTLOCALORIGIN, NEXTPUBLICAGLYNTENANTPREVIEWHOST | Where "Live" links point from a local or preview console. Both default to Aglyn\'s own addresses, which matters only on a preview build. |\n| NEXTPUBLICANALYTICSALLOWNONPROD | Development only. |\n| NEXTPUBLICPLUGINDEV, NEXTPUBLICPLUGINDEVBUNDLES, PLUGINREMOTESERVER, PLUGINREMOTESERVERBUNDLES | Local plugin de' },
  { path: '/developers/self-hosting-environment', title: 'Environment variables', heading: 'Related', anchor: '#related', text: '- Self-hosting — the setup runbook this reference belongs to\n- docs/SELFHOSTING.md — the repository runbook, with the Firebase and rules-deploy steps\n- .env.selfhost.example — the template you copy\n- White-label' },
  { path: '/enterprise/overview', title: 'Enterprise overview', heading: '', anchor: '', text: 'Enterprise overview\nEnterprise is the only plan that is not self-serve. It is quoted rather than listed, and it is the plan the pages in this section describe.\n| | |\n| Single sign-on | SAML SSO against your identity provider, optionally enforced so passwords stop working. |\n| Support commitments | A 24–48 hour first-response commitment measured in clock hours, and a named success manager. |\n| Availability & status | What we measure, what /status shows, and what we have not committed to. |\n| Security & compliance | The material a security review needs, including what we do not have. |' },
  { path: '/enterprise/overview', title: 'Enterprise overview', heading: 'What Enterprise does not change', anchor: '#what-enterprise-does-not-change', text: 'Worth saying plainly, because it is the usual assumption:\n- Quotas and features are entitlements, not plan names. An Enterprise workspace can have any combination of limits, and they are set per organization rather than implied by the tier.\n- The product is the same product. Enterprise is about how we contract, respond and authenticate — not a separate build.' },
  { path: '/enterprise/overview', title: 'Enterprise overview', heading: 'Getting Enterprise', anchor: '#getting-enterprise', text: 'Contact us — Enterprise is the one tier with no self-serve checkout, so the plan itself is arranged with us rather than bought from the billing page.\nEverything after that is yours to configure. Single sign-on in particular is set up by your own admins in Organization → Settings → Single sign-on: claim your domain, verify a DNS TXT record, exchange IdP metadata, rehearse enforcement, and activate. There is no provisioning step on our side and nothing to wait for.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: '', anchor: '', text: 'Security & compliance\nThe full write-up lives on Trust & security. It is written for the security review that precedes an enterprise purchase, and it is kept as one page on purpose — a reviewer should be able to send a single link rather than assemble an answer from several.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'What it covers', anchor: '#what-it-covers', text: '- What we do not have, first rather than buried: no SOC 2 report and no audit in progress, no ISO 27001 / HIPAA / FedRAMP, no third-party penetration test, no bug bounty.\n- Authentication, including SSO, and how sessions work.\n- Data handling — where data lives, what is encrypted, and who can reach it.\n- Availability, and the fact that there is no committed uptime percentage (see Availability & status).\n- How to report a security issue.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'Contract documents', anchor: '#contract-documents', text: 'Both are published pages — read them without asking anyone, and send them to your reviewers directly:\n- Data Processing Addendum — the processing terms, including the export and deletion obligations the product implements.\n- Subprocessor list — the authoritative one. The table on Trust & security is the engineering view of the same set and may lag it.\nOne thing that list does not contain, stated here so a reviewer does not have to infer it. It names the parties Aglyn engages. It does not name a host your own authors point at — a hotlinked image, or a url(...) in a stylesheet one of them wrote. Those requests go from your visitor\'s browser to that host directly and Aglyn does not proxy them, so the host is a recipient of your visitors\' data that only you can enumerate and disclose. It is a property of the builder rather than an omission from the register, and it is written up in full at Trust & security.\nNeither of those two is acceptance-pinned, so neither carries a version bump your people have to re-accept when it changes. The Terms of Service and the Privacy Policy are the opposite: each acceptance is pinned to a version and to the exact text published under it, and a new version is put back in front of every user. See below.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'When the Terms or Privacy Policy change', anchor: '#legal-reacceptance', text: 'Accepting the Terms accepts the Privacy Policy with them, as one versioned set. An acceptance is recorded against the individual — not against the workspace — with the version, a content hash of each document exactly as it was published at that version, the time from our clock, and which door the acceptance came through. Records are additive and immutable: a later acceptance adds a row rather than overwriting the earlier one, so the history of what a person agreed to, and when, stays intact.\nWhen we publish a new version, the next time that person opens the console they see a banner. It opens by acknowledging the acceptance we already hold and names the date they agreed, then says the documents have been updated and asks them to confirm. Where we can tell which of the two documents actually moved — by comparing the content hashes on their record against the ones published now — the banner names them; where that comparison cannot be made it says nothing rather than guessing. I agree records the new acceptance and the banner goes. It appears on every console page until it is answered, and it does not lock anyone out of the product in the meantime.\nA banner also appears for an account we hold no acceptance for at all — accounts created before we captured acceptance, and people who arrived through SSO or an invite without passing a consent control. The wording there is deliberately different, because the fact is different: it says we have no record of acceptance on this account and gives the usual reason, which is a gap in our records rather than anything the person failed to do.\nTwo consequences worth naming for a review:\n- Acceptance is per person, not per organization. Every member of your workspace is asked separately, because "the organization accepted" and "this perso' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'Why the gaps are listed first', anchor: '#why-the-gaps-are-listed-first', text: 'Because a reviewer needs them, and because a questionnaire surfaces them anyway — three weeks later, with more people in the thread. Leading with the absences is faster for both sides than leading with the controls.\nIf a certification is a hard requirement for your purchase, raise it at the start. We would rather tell you early that we do not have it than discover it at contract stage.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'Reporting a vulnerability', anchor: '#reporting-a-vulnerability', text: 'Security reports are read even though there is no bug bounty. The reporting route is on Trust & security.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: '', anchor: '', text: 'Single sign-on (SAML)\nSSO signs your team in against your own identity provider. It is an Enterprise feature, and once your organization is on Enterprise you set it up yourself in Organization → Settings → Single sign-on. There is no provisioning step on our side and nothing to wait for.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Setting it up', anchor: '#setting-it-up', text: '1. Verify your domain\nAdd each email domain your team signs in with. We give you a DNS TXT record to publish:\n| Record | Value |\n| aglyn-challenge.yourdomain.com | aglyn-domain-verification=… |\nPublish it at your DNS provider, then press Verify. DNS can take a few minutes to propagate; re-checking is safe and costs nothing.\nThis step is not a formality. A verified domain is what tells us to send that domain\'s sign-ins to your identity provider. If anyone could claim a domain without proving they own it, they could point your domain at their IdP and intercept your team\'s logins. So nothing else works until a domain passes, and we re-check the record rather than taking your word for it.\nPublic mailbox domains — gmail.com, outlook.com and the like — cannot be used. They are shared with millions of people outside your organization.\nLeave the TXT record in place after verification. We re-check it weekly, because a domain that changes hands should not keep routing sign-ins to whoever set it up first.\nIf the record stops answering, nothing happens to your sign-in. We do not remove a domain automatically, and a failed lookup on our side is never treated on its own as proof the record is gone — a DNS outage looks identical to a deleted record, and we would rather ask you than lock your team out.\nWhat happens instead: after the check fails three weeks running, we email your organization\'s owners and admins asking you to restore it. Your SSO keeps working the whole time. Removing a domain is always a deliberate act by you, in Organization → Settings → SSO, or by us with your agreement.\nSo if you migrate DNS providers, carry aglyn-challenge.yourdomain.com across with the rest of your records.\n2. Connect your identity provider\nThe settings page shows the two values your IdP asks for' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'How it works', anchor: '#how-it-works', text: 'Each SSO organization gets its own identity pool. Your users authenticate against your IdP, and their Aglyn accounts live in that pool rather than in the shared one. That isolation is the point — your directory governs who can sign in, and removing someone there removes their access here.\nSigning in goes through a dedicated route rather than the normal email/password form, so people arrive by way of your IdP.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Enforcement', anchor: '#enforcement', text: 'An organization can turn on SSO enforcement, which is a separate step from having SSO configured.\n- Configured, not enforced — SSO is available, and other sign-in methods still work.\n- Enforced — other sign-in methods are stripped from accounts in the pool. Passwords stop being an option, not merely a discouraged one.\nEnforcement is applied by a sweep over the pool. Rehearse it first — the settings page has a rehearsal that changes nothing and lists exactly which accounts would lose which sign-in methods. An account whose only way in is the method being removed is reported and skipped rather than orphaned.\nEnforcement cannot be undone by turning it off. We remove a linked credential; we do not keep a copy to put back. Anyone affected re-links for themselves.\nYou must keep one way in that does not go through your IdP\nEnforcing is refused until your organization has a way in that survives your identity provider failing. This is not a warning you can dismiss — the button stays disabled and the sweep will not run.\nThe reason is the failure it protects against. After enforcement, every account in your pool holds nothing but the link to your identity provider. If that provider stops answering — a lapsed signing certificate, an application deleted during a migration, a tenant moved — nobody can sign in, and we cannot let you back in either: your accounts live in your own pool and their only credential is the one that stopped working.\nThere are two ways to satisfy the requirement, and for most organizations only the first is available.\nAn owner who signs in outside your identity pool\nEnforcement sweeps your identity pool and nothing else. An organization owner whose account is not in that pool is not merely spared — the sweep cannot see the account at all, so no certificate, ap' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Consequences worth knowing before you switch', anchor: '#consequences-worth-knowing-before-you-switch', text: 'Passwords cannot be set for SSO accounts. The console refuses rather than silently doing nothing — your IdP owns the credential.\nSSO users are in a separate pool. This is the isolation working, but it has practical effects the platform has to account for explicitly: an SSO user is not returned by ordinary account lookups unless the lookup searches every pool. Staff surfaces label these accounts with the pool they belong to, so "can\'t find them" and "they\'re an SSO account" are distinguishable.\nSocial sign-in cannot be linked to an SSO account at all. Not automatically, and not by the user either — the option is not offered, and the account page says why. Your identity provider is the single gate you bought: you revoke there, you enforce MFA there, you offboard there. A personal Google account linked to a governed identity would be a way in that your directory can neither see nor revoke, so we do not allow one to be created.\nThis holds whether or not you have turned enforcement on. Enforcement decides whether we remove sign-in methods that already exist; it was never a license to keep handing out new ones in the meantime. Nothing about this can lock anyone out, because refusing to add a method never takes away a method someone already has.\nAn account in your pool is also simply not the same identity as the same email address signing in with Google elsewhere, so the two never merge.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Testing it', anchor: '#testing-it', text: 'SSO redirects cannot be exercised from localhost — the flow fails with a missing-initial-state error before it reaches your IdP. Test on a deployed environment.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Related', anchor: '#related', text: '- Signing in and sessions\n- Trust & security — the security posture behind an enterprise review' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: '', anchor: '', text: 'Support commitments\nEvery plan gets the community forum. Private ticket support starts at Pro — Free and Starter pay for product, not for our time.\nThe commitment below is a first response, not a resolution. It is what the Support tickets page shows you, and what the staff queue is ordered by.\n| Plan | Tier | First response | Named success manager |\n| Free | Community | Forum only | — |\n| Starter | Community | Forum only | — |\n| Pro | Standard | 7–14 business days | — |\n| Business | Business | 4–6 business days | — |\n| Scale | Business | 4–6 business days | — |\n| Advanced | Business | 4–6 business days | — |\n| Agency | Priority | 1–3 business days | — |\n| Enterprise | Dedicated | 24–48 hours | Yes |' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: 'Why Enterprise is in hours, not business days', anchor: '#why-enterprise-is-in-hours-not-business-days', text: 'It is the point of the tier. 24–48 clock hours runs through a weekend; "1–3 business days" does not. Read as business hours the Enterprise window would be 3–6 business days, which would make it slower than Agency above and invert the ladder.\nThere is a test asserting the ladder stays monotonic, so this cannot quietly regress into the wrong order.' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: 'What starts and stops the clock', anchor: '#what-starts-and-stops-the-clock', text: '- The clock starts when you open the ticket.\n- It stops on the first reply from the Aglyn team — write-once, so a later staff message does not reset or re-stamp it.\n- A reply from you does not stop it. If we have not answered yet, the commitment is still running.' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: 'Where to see it', anchor: '#where-to-see-it', text: 'Organization → Support → Support tickets, reached from Support in the org tabs or in your account menu. On a plan that carries tickets that is where Support opens; on Free and Starter it opens on the forum, with a link across. The page states your own commitment rather than a generic promise, so what you read there is what your plan actually carries.\nYour plan is per organization. If you belong to more than one, the commitment follows the workspace you are looking at — not your account.' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: '', anchor: '', text: 'Availability & status' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'The status page', anchor: '#the-status-page', text: 'docs.aglyn.com/status checks six things live, from your browser, when you load it — and again every minute while the page is open: the console, an end-to-end render of a real published page, the runtime that serves every published site, the marketing site, billing, and scheduled jobs.\nIt shows whether each surface is responding right now, in one of three words:\n| Word | What it means |\n| Operational | The service returned its own health report saying so. This is the only way a surface goes green. |\n| Degraded | The service answered and reported a problem, or returned an error. |\n| No reading | The check could not be completed — a blocked request, a network problem, or a reply the page cannot read. It is not treated as healthy, and it is not a claim that we are down. |\nThat third state is deliberate. From your browser a real outage and a captive wifi portal look identical, so the page says which of the three it actually observed rather than rounding either way.\nTwo limits worth knowing before you rely on it:\n- It covers the surfaces you use, plus billing and scheduled jobs. Those two are not part of serving: a published site keeps working while either is degraded, so a red card there means invoices or background work are affected and nothing else on the page is. Backups, abuse controls and our own error reporting are still not on the page — they are monitored continuously and separately, and none of them changes whether your site is serving.\n- It is not an independent monitor. It is served from a different deployment than the services it reports on, so a console outage does not take it down. It is not served from a different provider, so an outage broad enough to take out the whole platform could take the page with it. If /status does not load at all, treat that as a sig' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'There is no committed uptime percentage', anchor: '#there-is-no-committed-uptime-percentage', text: 'Stated plainly because procurement asks, and because a vague answer wastes everyone\'s time:\n> We have not published an uptime SLA.\nWe measure availability and intend to commit to a number backed by that data — rather than one chosen to close a deal. Until there is enough history to stand behind, there is no percentage to quote, and we would rather say so than publish a figure we cannot evidence.\nIf a committed availability figure is a hard procurement requirement today, that is worth raising early rather than late. See Trust & security for the same list from the reviewer\'s side.' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'Where the platform runs', anchor: '#where-the-platform-runs', text: 'Published sites and the console are served from a global edge network, with data in Google Cloud Firestore. A published page is served from cache and regenerated in the background, so a slow origin degrades to a stale page rather than an error.' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'Reporting an outage', anchor: '#reporting-an-outage', text: 'If something is down and /status disagrees, tell us — the status page checks reachability, which is not the same as everything working.\nOpen a ticket from Organization → Support → Support tickets. Response is governed by your support commitment; Enterprise is 24–48 clock hours.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: '', anchor: '', text: 'Aglyn Assist\nRolling out Aglyn Assist is being rolled out and may not be switched on for your workspace yet. Nothing needs configuring — the helper appears in the console as the rollout reaches you.\nAglyn Assist is the chat helper in the bottom-right corner of every console page. Ask it how to do something — publish a screen, connect a domain, set up shipping, invite a teammate — and it answers from this documentation, linking the exact docs section and the console page where you do it.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'What it can do', anchor: '#what-it-can-do', text: '- Answer how-to questions about building sites, publishing, domains, commerce, bookings, workflows, datasets, team roles, and billing.\n- Link you to the source — under each written answer is a Sources list naming the documentation sections it drew on, each one a link straight to that section. See Where an answer came from.\n- Guide you on the page you\'re on (Pro plans and up) — the assistant knows which console screen you\'re viewing and answers about that screen, rather than giving you a general answer you then have to translate.\n- Offer to take you to the right page (Pro plans and up) — when what you asked for starts somewhere else, it can show a card that opens that page for you. See Offers to open a page.\nAglyn Assist answers and directs — it doesn\'t change anything in your workspace. It can\'t edit your site, publish, or update settings, so there\'s nothing it can do by accident; you stay in control of every change.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Answers for beginners and developers', anchor: '#answers-for-beginners-and-developers', text: 'Every answer is written twice over, in one message.\nThe main answer is in plain words: what to click, in the order you\'ll click it, with nothing assumed about what you already know.\nUnderneath, when there\'s something technical worth adding — the URL of the page, the identifier in it, the field or API behind the screen — there\'s a collapsed Under the hood line. Open it if you want that detail; ignore it entirely if you don\'t. Nothing is hidden from you and nothing is explained at you.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Offers to open a page', anchor: '#offers-to-open-a-page', text: 'Sometimes the thing you asked about starts on a different screen. When the assistant knows which one, it shows a small card offering to take you there — with the values to use, when it has worked them out from your question.\nThe card only opens the page. It never fills in a form for you, never saves anything, and never makes a change on your behalf. You land on the normal screen, fill it in yourself, and press the button yourself — with all the usual permission checks in place. If you\'d rather stay where you are, choose No thanks and the card goes away.\nThis is deliberate. An assistant that could change your site by misunderstanding you would be a worse assistant, so it doesn\'t have that ability at all — not a setting that\'s switched off, but a capability it was never given.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Where an answer came from', anchor: '#where-an-answer-came-from', text: 'Every answer the assistant writes is followed by a short Sources line — Source when there is only one — listing the documentation sections it drew on. Each entry names the page and the heading within it, and clicking one opens that exact section.\nThis is there so you never have to take an answer on trust. If the reply is not quite what you needed, the source is usually the fastest next step: the page will have the surrounding detail that a short answer had to leave out.\nA link the assistant already put in the answer itself is not repeated in the list, so replies quoted straight from the documentation — which lead with the page name and link it — do not carry a duplicate.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Answers straight from the documentation', anchor: '#answers-straight-from-the-documentation', text: 'Most of what people ask the assistant — "how do I connect a domain", "where do I save a template" — is already written down on these pages. When your question clearly matches one of them, the assistant hands you that page\'s own words, with a link to the full page, instead of writing you a fresh answer.\nYou will recognize these replies: they open with the name of the page, quote it, and close by offering to go further if it missed what you meant.\nThere are two things worth knowing about them.\n- They are never a summary. The text is copied from the documentation exactly as written, so it cannot drift from what the page actually says. If the assistant is not confident which page answers you, it writes you a real answer instead of quoting a page that only looks close.\n- They do not count against your message limit, because they cost nothing to produce. Ask as many as you like.\nIf a quoted page did not cover what you meant, just ask again with more detail — the follow-up gets a written answer.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Message limits', anchor: '#message-limits', text: '- Free workspaces get a limited number of assistant messages each day, with answers and docs links.\n- Pro and higher plans get generous limits, page-aware guidance, and the offers to open a page described above.\nWhen a free workspace reaches its daily limit, the assistant says so and the counter resets the next day (UTC).\nAnswers quoted straight from the documentation are free and are not counted, so a workspace at its daily limit can still ask how-to questions.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Feedback', anchor: '#feedback', text: 'Every answer offers a thumbs-up / thumbs-down. Ratings tell us which answers — and which docs — need work, so rating answers directly improves the product.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Privacy', anchor: '#privacy', text: 'Conversations with Aglyn Assist are stored with your workspace so we can improve answers and documentation. See the privacy policy for details on how this data is handled.' },
  { path: '/getting-started/console-search', title: 'Search the console', heading: '', anchor: '', text: 'Search the console\nThe magnifier in the console app bar — or ⌘ K on a Mac, Ctrl K elsewhere — opens a search palette over whatever page you are on, including the Besigner.\nType at least two characters. Results are grouped by kind, and clicking one takes you straight to it.' },
  { path: '/getting-started/console-search', title: 'Search the console', heading: 'What it searches', anchor: '#what-it-searches', text: 'Everything below is searched within the site you currently have open, plus your sites across the workspace:\n| Group | What a row is | Where clicking it goes |\n| Sites | A site you belong to in this workspace | The site dashboard |\n| Pages | A screen on the open site | The screen\'s version view |\n| Emails | An email screen on the open site | The email in the Besigner |\n| Components | A reusable component | The component page |\n| Layouts | A shared layout | The layout page |\n| Templates | A site template | The template page |\n| Content | A content collection | The Content page |\n| Authors | A content author | The Content page |\n| Workflows | A workflow | The Workflows page |\n| Products | A product | The Products page |\n| Redirects | A redirect, matched on its source path | The Redirects page |\n| Services | A bookable service | The Bookings page |\nA group only appears if your plan includes it. On the Free plan there are no workflows, products, services or redirects, so those groups are neither shown nor searched.' },
  { path: '/getting-started/console-search', title: 'Search the console', heading: 'How matching works', anchor: '#how-matching-works', text: 'It matches any part of a name, not just the beginning. Searching layout finds "Main Layout"; so does lay, main, and main lay.\nRanking puts the closest match first: an exact name, then a name that starts with what you typed, then a word inside the name, then anything else. Pages and products can also be found by their slug or route, but a match on the name always ranks above a match on a slug.\nAccents are ignored, so cafe finds "Café".' },
  { path: '/getting-started/console-search', title: 'Search the console', heading: 'What it does not search', anchor: '#what-it-does-not-search', text: 'Being precise about this matters — an empty result should mean "you do not have one", not "search could not see it".\n- Orders, bookings and contacts are not searchable. They are found on their own pages, which have their own filters.\n- Media has its own, richer search on the Media page, including wildcards and searching by tag or custom field. See the media library.\n- Other workspaces. Search only ever covers the workspace named in the page address you are on.\n- Other people\'s sites. You only ever see sites you are a member of.' },
  { path: '/getting-started/console-search', title: 'Search the console', heading: 'Why a group sometimes says it was only partly searched', anchor: '#why-a-group-sometimes-says-it-was-only-partly-searched', text: 'To keep search fast and cheap, each group reads a capped number of items rather than your entire site. If a group is larger than that cap, the palette says so underneath the results — that line means there may be matches it did not look at, so try a more specific word.\nMost sites never hit the cap.\nIf a group could not be read at all, it says that too, in red. That is a different thing from "no matches", and it is worth retrying or reporting.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: '', anchor: '', text: 'The console tour\nThe console is where you manage a site. Here\'s what each part of the chrome does.\n1. App bar — the Aglyn console wordmark, notifications, and your account menu.\n2. Workspace switcher — jump between the organizations you belong to.\n3. Site sections — every area of the selected site (Dashboard, Screens, Media, Content, …).\n4. Site switcher — switch between the sites in your workspace.\n5. Page body — the selected section\'s cards and tables.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'The app bar', anchor: '#the-app-bar', text: '- Site switcher (left) — jump between the sites you belong to, search them by name with Find site…, or create a new one.\n- Breadcrumbs — show the current site\'s display name and where you are.\n- Screen switcher — a searchable dropdown for hopping between screens without leaving the editor: your recent screens by default, or type to find any screen or layout in the site by name. View all screens opens the full list.\n- Version dropdown (right, near your avatar) — pick or schedule a version to view.\n- Notifications — the bell shows an unread badge and drops down your 10 most recent notifications (form submissions, bookings, invoices, team changes), split across an Inbox tab (unread) and an Archive tab (already read). Mark all read clears the inbox, the gear opens your notification preferences, and View all opens the full paginated feed.\n- Account menu — your avatar opens it. The header shows your name and email with a gear to Manage Account, and the first row below repeats that destination as a labeled Manage account — a gear is not discoverable as a name. Then come Manage Team, Billing and Support, which appear only on a page that names a workspace and only for members whose role can reach those pages; Staff console (Aglyn staff only); a Documentation link that opens this docs site in a new tab; and Report an issue, directly under Documentation because "the docs didn\'t answer it" is the step before reporting it. Report an issue opens a form over the page you\'re on rather than navigating away — the page you were looking at is the most useful thing the report carries — and unlike the rows above it, it needs no particular role, no resolved workspace, and no paid plan: every signed-in member has it on every page. See Report an issue. Below that the menu holds the theme toggle' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'In-context help', anchor: '#in-context-help', text: 'Look for the small ? icons throughout the console — next to page titles, card titles, form fields, table column headers, and the Besigner\'s style and attribute panels. Hover one for a one- or two-line explanation, and click it (or the Open documentation link in the tooltip) to jump straight to the matching section of these docs in a new tab.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Primary navigation', anchor: '#primary-navigation', text: 'The tabs across the top of a site are its sections. Some are always present; the rest are contributed by the plugins your workspace has enabled — so two sites, or the same site before and after you enable a plugin, can show different tabs. Don\'t be surprised by a tab strip that doesn\'t match a screenshot exactly.\nThese four are where a new site\'s work happens:\n| Section | What\'s there |\n| Dashboard | The site at a glance — analytics and recent-signup summaries, and the ten most recent activity entries. |\n| Screens | The screen hierarchy — create, reorder (drag-and-drop), and open screens. This is where you build; start at Publish your first screen. |\n| Media | The media library — folders, images, video, and files. |\n| Setup | Basic details, SEO, tracking, theme, and emails. Each tab is deep-linkable — the ?tab= in the URL follows you, so you can bookmark or share the exact one. |\nAlongside them, and always present: Layouts and Components (the shared frames and reusable pieces screens are assembled from — see Screens & Layouts), Templates (saved starting points), Content (collections and blog entries), Users (the people who sign in to the site you\'re building, not your own team), and Analytics. Admin appears only if you\'re an owner or admin of the site; it holds per-site plugin settings, the custom domain, the site\'s security lists, the full activity log, and the danger zone.\nSections that come and go Tabs such as Data, Products, Logic, Workflows, Inbox, Bookings, Events, Redirects, Marketing and Marketplace are contributed by plugins and appear only where that plugin is enabled for your workspace (they\'re inserted after Analytics). If a section these docs describe isn\'t in your tab strip, that\'s usually why — enable the plugin under Organization → Plugins.\nContacts is t' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Editing vs. managing', anchor: '#editing-vs-managing', text: 'You can manage a screen (rename, schedule, view raw JSON) from its detail page without opening the editor. When you want to design it, open the Besigner.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'The Sites list', anchor: '#the-sites-list', text: 'All Sites is the front door of a workspace: one card per site, for the workspace currently selected in the switcher. A site you can reach in another organization isn\'t missing — it\'s behind the workspace switcher.\nEach card carries:\n- The site\'s display name as the title, with its hostname underneath as the subheader — the custom domain when the site has one, otherwise its name.aglyn.app address. Both are also listed inside the card, as Aglyn Domain and Custom Domain.\n- A status pill (below).\n- Visit, which opens the live site in a new tab, and Manage, which opens that site\'s dashboard in the console.\nThe status pill {#the-status-pill}\n| Pill | Hover tells you |\n| Live (green) | How many pages are published — "12 published pages." |\n| Draft (grey outline) | "Nothing published yet — visitors see the placeholder." |\n| Maintenance (amber) | "Every path serves the maintenance screen." |\n| Suspended (red) | "This site is serving a lockdown notice instead of content." |\nLive means exactly one thing: the site has at least one published page. Publishing writes the routing map the site is served from, and the pill is read off that map — so it costs no extra lookup on a list of a hundred sites, and it is not a health check. A site with a misconfigured domain still reads Live if it has published pages.\nHow the pill is decided {#how-the-pill-is-decided}\nReference detail, and the reason the pill is worth reading rather than glancing at: a site can be in several of these states at once, and the pill reports the first that applies, in this order.\n1. Suspended — the site record carries a suspension that hasn\'t ended.\n2. Maintenance — maintenance mode is on.\n3. Live — at least one published page.\n4. Draft — everything else.\nSo a suspended or maintenance site is never shown as Live, howe' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'A site\'s dashboard', anchor: '#a-sites-dashboard', text: 'Opening a site lands you on its dashboard. It\'s a place to glance at the site, not to edit it — every card is a summary with a link to the section that owns the detail:\n- Traffic — pageviews over a window you choose (14 days by default). View details opens Analytics.\n- Newest site users — the five most recent people who signed up on your site. View all opens Users.\n- Recent Activity — the ten most recent changes, each naming the thing that changed ("Saved the screen — Home") and linking straight to it. The full, paginated log lives under Admin → Activity.\nPlugins contribute the rest, so this list is a floor rather than an exact match for your own dashboard: Last campaign appears once you\'ve sent an email campaign, and Commerce where the commerce plugin is enabled and the site has products or orders. A brand-new site shows the same cards with empty states — "No pageviews recorded yet", "No activity yet" — which is what a first visit should look like.\nTwo things people expect here and won\'t find: role management lives under Users, and the announcement bar and promotional popup live under Marketing.\nVisit site, in the dashboard header, opens the published site in a new tab with the admin bar armed — the route from a site\'s own dashboard to the site itself, without going back out to the Sites list and in through a card action.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Next', anchor: '#next', text: '- Publish your first screen' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Workspace settings & notifications', anchor: '#workspace-settings--notifications', text: 'Organization-wide settings (name, workspace URL) live under Organization → Settings, which also holds Profile, API keys, Branding, Single sign-on, Ownership and Delete. Turning plugins on and off for the workspace is its own section, Organization → Plugins — Marketplace is for finding and installing new ones, not for administering what you already run:\nYour in-app notification feed — billing, publishing, workflow failures — lives under Notifications, with per-category mutes:\nAlerts on this device\nBelow the category mutes, three switches control how a new notification reaches you in this browser:\n- Unread count in tab title — badges the browser tab, e.g. (3) Aglyn, so you can see new activity from another tab. On by default.\n- Sound — a short chime when a notification arrives. On by default on a browser you haven\'t set it on before; a device where you already turned it off keeps your choice.\n- Desktop notifications — a system notification, shown only while the Aglyn tab is in the background (in the foreground, the bell and chime already tell you). Off by default; switching it on asks your browser for permission. If you previously blocked notifications for the site, re-allow them in your browser settings first.\nThese are per-device, not per-account: notification permission is granted per browser, so muting sound on your laptop leaves your other devices alone. The category mutes above are account-wide and apply everywhere.\nSend test alert plays the chime and, if you\'ve allowed them, fires a desktop notification — so you can confirm your setup works instead of discovering weeks later that you never heard a thing. The chime always plays, even with Sound switched off, so you can hear it before deciding.\nAglyn asks you in-app before triggering your browser\'s own permission pro' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: '', anchor: '', text: 'Create a site\nA site is one website you own in Aglyn — its screens, theme, data, domain, and settings. Everything you build lives under a site, and you can own several.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'Create your first site', anchor: '#create-your-first-site', text: '1. Sign in to the console.\n2. Open the site switcher in the app bar (top-left) and choose Create site.\n3. Give it a name. Aglyn generates a working subdomain immediately, so the site has a real address from the first moment — you can attach a custom domain later. The address resolves right away, but it has nothing to serve until you publish a screen at the site root, so a brand-new site answers its own URL with a not-found page. Starting from a starter template creates and publishes a home page for you; building by hand, that\'s your first screen.\n4. You land on the new site\'s Setup page (titled Host Setup), with tabs for Basic details, SEO, Theme, Custom Domain, Emails, and Activity. To start building rather than configuring, use the Screens tab in the site navigation — see Publish your first screen.\nName collisions Site names must be unique enough to generate a valid subdomain. If a name is taken, the console suggests an available variation.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'What a site contains', anchor: '#what-a-site-contains', text: '- Screens & layouts — the pages and the shared frames they render in.\n- Data — datasets, variables, functions, and workflows.\n- Media — images, video, and files, organized in folders.\n- Setup — theme, SEO, tracking, and emails under tabbed settings. The Site logo card (Details tab) sets your brand mark: it\'s shown on the live site\'s page-navigation loading overlay — a themed, blurred scrim with a progress bar. Without a logo, the loader shows your site name instead.\n- Billing — the plan and usage meters that gate features and quotas.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'Switching between sites', anchor: '#switching-between-sites', text: 'Use the site switcher in the app bar at any time. It lists your most recently used sites first; with more than a handful, type in the Find site… box to search every site you belong to by name, or choose View all sites. Your current site\'s display name appears in the breadcrumbs so you always know which site you\'re editing.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'Next', anchor: '#next', text: '- Take the console tour\n- Publish your first screen' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '', anchor: '', text: 'Publish your first screen\nThis walks through the core loop: create → design → publish.\nPublish from the editor You don\'t have to leave the Besigner to go live: the Publish button in the top-right of the editor publishes the version you\'re editing (and flips to Unpublish once the screen is live). Screens without a URL path yet are prompted to set one in Properties first.' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '1. Create a screen', anchor: '#1-create-a-screen', text: '1. Go to Screens and choose New screen.\n2. Set a title and a URL slug (e.g. about). Aglyn normalizes the slug and registers it in the site\'s routing map.\n3. Optionally pick a parent screen — children inherit a nested URL path (/services/pricing).' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '2. Design it in the Besigner', anchor: '#2-design-it-in-the-besigner', text: '1. Open the screen to launch the Besigner.\n2. Drag components from the drawer onto the canvas. Rearrange them in the hierarchy panel or directly on the canvas.\n3. Double-click text to edit it inline. Set component attributes in the inspector.\n4. Bind a shared layout if you want a common header/footer.' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '3. Preview and publish', anchor: '#3-preview-and-publish', text: '1. Use the artboard light/dark toggle to check both color schemes.\n2. Save the canvas. Saving writes your working version — it isn\'t publishing.\n3. Publish. The screen\'s slug is registered in the routing map and the page goes live on your site\'s domain.\nKeeping more than one version is a Pro feature Every screen is created with one working version, and Save updates that version on every plan — the core loop above needs nothing extra. Keeping more than one — named snapshots you can reopen, publish to roll back to, or schedule — requires Pro or above, and scheduling a version requires Business or above. On Free and Starter the editor answers "Versioning requires a Pro plan — see Billing to upgrade" instead of opening the name dialog. See Versions & scheduled publishing.\nThe Live button The Live button is environment-aware — in production it reflects your published saves so you can jump straight to the real page.' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: 'How fast changes go live', anchor: '#how-fast-changes-go-live', text: '- Publishing a screen refreshes its live page immediately — the very next visitor gets the new version, usually within seconds.\n- Publishing a layout or a reusable component refreshes every page that uses it the same way. When that fan-out is very large, the publish confirms that the remaining pages "update on their own within a minute" — and they do.\n- Saving is not publishing. A save writes your working version; the live site serves the published one. The one subtle case: if you edit the version that is currently live and press Save, the live site catches up on its own within about a minute — and because pages regenerate behind the scenes, you may need to refresh twice to see it.\n- Your site\'s sitemap.xml, robots.txt, and RSS feeds refresh within about five minutes (a publish refreshes the sitemap immediately).' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: 'Next', anchor: '#next', text: 'Explore the feature areas in the sidebar, or see What\'s New for the latest capabilities.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '', anchor: '', text: 'Build & publish a survey\nThis walkthrough strings together datasets, the Besigner\'s form elements, and publishing into one loop: model the responses → design the survey → publish → collect. By the end you have a live survey page whose submissions land in a typed dataset you can filter, sort, and export.\nPlan availability Forms and the inbox are available on every plan. Writing submissions into a dataset needs the data store, which unlocks on Starter and above.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '1. Create the dataset', anchor: '#1-create-the-dataset', text: 'Datasets belong to your organization, so every site can share them. Open the organization Data page (or any site\'s Data page — both edit the same data).\n1. Choose Add dataset. In the New dataset dialog give it a Name (say Survey responses) and an optional comma-separated starting list of Fields (satisfaction, visit, topics, comments). Create it.\n2. Select your new dataset in the Dataset dropdown and open Schema. The Schema dialog lists each field with its display name, generated field id, and a type chip.\n3. Use Add field / Edit to type the fields properly:\n- satisfaction → type Integer (the star rating submits a number).\n- visit → type Text (one radio choice).\n- topics → type Text (ticked checkboxes arrive joined with , ).\n- comments → type Text.\n4. Save schema.\nEach field\'s Display name is what you see in dialogs and table headers; the field id next to it (a slug generated once from the display name) is the stable key records store values under — the key {{item.fieldId}} bindings reference, and what a form field\'s Maps to schema field picker stores. Renaming the display name later never changes the id.\nModel first A clean schema now makes everything downstream typed: the record editor renders the right input per field, imports are validated, and quota-guarded writes reject junk. See the datasets deep-dive for the full type system.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '2. Add a screen for the survey', anchor: '#2-add-a-screen-for-the-survey', text: '1. Go to Screens and choose New screen.\n2. Title it Survey and give it the slug survey — that becomes its public URL path (https://your-site/survey).\n3. Open it in the Besigner.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '3. Insert a Form from the element picker', anchor: '#3-insert-a-form-from-the-element-picker', text: 'With the screen open, add the form:\n1. In the Elements panel choose Add Element (or right-click a node and pick Add element). The Choose element picker opens, grouped by category.\n2. Expand the Forms group. It contains the Form container, the Form Field element, and a ready-made Contact Form preset.\n3. Insert a Form. Then, with the Form selected, add one Form Field child per question (the picker\'s Form Field preset drops a field with sensible defaults).' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '4. Configure the fields', anchor: '#4-configure-the-fields', text: 'Select each Form Field and set its properties in the inspector:\n| Property | What it does |\n| Field name | The key the value is stored under in submissions (and in the inbox copy). |\n| Maps to schema field | Which of the dataset\'s schema fields this value is stored under. The dropdown lists the fields of the dataset chosen on the Form (see step 5) and stores the stable field id, so renaming the field later never breaks the mapping. Left on None, the value matches a dataset field by name instead. |\n| Label | The visible input label ("How satisfied are you?"). |\n| Placeholder | An optional grey hint inside the empty input ("you@company.com"). It is not a label — it disappears as soon as someone types, so always keep Label set. Radio, checkbox, and rating fields ignore it; a dropdown shows it until a choice is made. Clear it to remove the hint. |\n| Type | Text (default), Email, Multiline, Dropdown, Radio choice, Checkboxes, or Star rating. |\n| Options | Choices for dropdown, radio, and checkbox fields — one per line or comma-separated. Ignored by other types. |\n| Required? | Whether the field must be filled; a required checkbox group needs at least one box ticked. |\nPick the dataset first "Maps to schema field" lists the fields of whichever dataset the Form is pointed at — set the Form\'s Write to dataset (step 5) before mapping the fields, or the dropdown reads No dataset selected on the form.\nFor this survey:\n1. satisfaction — Type Star rating, label "How satisfied are you?". The five stars submit a number (4).\n2. visit — Type Radio choice, Options First time, Monthly, Weekly.\n3. topics — Type Checkboxes, Options Products, Support, Pricing. Visitors can tick several; the submission joins them with , .\n4. comments — Type Multiline for free-form feedback.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '5. Point the form at the dataset', anchor: '#5-point-the-form-at-the-dataset', text: 'Select the Form container itself and fill its properties:\n- Form name — identifies the form in your submissions inbox (Visitor survey).\n- Write to dataset — pick Survey responses from the dropdown, which lists your organization\'s datasets by display name. The form stores the dataset\'s id, so renaming the dataset later never breaks the binding. Submissions append a record; the inbox always keeps its own copy either way.\n- Submit label — the button text (defaults to Send).\n- Success message — shown in place of the form after a successful submit.\nRename-safe by id Both pickers bind by stable id: the Form stores the dataset\'s document id and each field\'s "Maps to schema field" stores the model field id. Rename the dataset or its fields freely — records keep landing. Unmapped values still match schema fields by name (field name = field id); values that match nothing are dropped from the record (the inbox copy still has everything). Forms built before the pickers keep working through their stored dataset name — shown as Write to dataset (legacy name) until you pick the dataset above and clear it.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '6. Publish', anchor: '#6-publish', text: 'Click Publish in the Besigner\'s top-right (it flips to Unpublish once live). If the screen has no URL path yet you\'re prompted to set one first. The survey is now served at /survey on your site\'s domain.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '7. Watch responses arrive', anchor: '#7-watch-responses-arrive', text: 'Every submission does three things:\n- appends a record to Survey responses — the Data page updates live;\n- files an inbox copy under the form\'s name (see Forms & lead capture);\n- fires the formSubmission automation event, so workflows and actions can react (send a thank-you alert, notify your team, write other datasets).\nOn the Data page, use Filter (satisfaction >= 4) and Sort (satisfaction desc) over the loaded records, and export everything with the CSV / JSON buttons.\nChart it Bind a container\'s Repeat over dataset to Survey responses and reference {{item.satisfaction}} inside it to render responses back onto a (members-only?) results screen. The deep-dive covers repeatables.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: 'Related', anchor: '#related', text: '- Datasets & schema deep-dive\n- Forms & lead capture\n- Publish your first screen\n- Workflows & actions' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '', anchor: '', text: 'Launch a coming-soon page while the rest of your site stays private\nYou have a domain, a half-built site, and a launch date. You want visitors to land on something deliberate — "here\'s what\'s coming, tell me when it\'s ready" — while the forty pages behind it stay out of Google until you\'re happy with them.\nThis walkthrough is the whole loop: build the page → make it home → hide the rest → collect signups → flip everything back on launch day. It\'s the same pattern Aglyn uses on its own site.\nPlan availability Everything here works on Free: screens, forms, the inbox, per-screen visibility, and the site-wide search switch. Writing signups into a dataset (step 4) needs the data store, which unlocks on Starter and above — the inbox copy is always kept either way.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '1. Build the coming-soon page', anchor: '#1-build-the-coming-soon-page', text: 'Create the screen first; you\'ll point your domain at it in step 2.\n1. Go to Screens → New screen. Title it Coming soon. Give it any slug for now — coming-soon is fine — you\'ll change it to / in the next step.\n2. Open it in the Besigner and put the essentials on it. A coming-soon page that only says "coming soon" wastes the visit. Aim for:\n- What\'s coming, and roughly when. One sentence and a month beats a countdown timer you\'ll have to move.\n- A notify-me form — see below.\n- How to reach a human. An email address or a contact link; people who arrive early are often the ones who most want to talk to you.\n- Links out — your documentation, your changelog, your social accounts, wherever you already post. These give an early visitor somewhere to go instead of bouncing.\n3. Publish the screen.\nThe notify-me form\nAdd a Form from the element picker with a single Form Field of type Email, and set the Form\'s Success message to something that confirms the signup ("Thanks — we\'ll email you when we open"). The Forms & lead capture page covers the form elements and every field property in full; the only thing that matters here is that you give the field a Field name you\'ll recognize later, such as email.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '2. Make it the home page', anchor: '#2-make-it-the-home-page', text: 'A screen\'s Slug decides the path it\'s served at, and the slug / means the home page. So swapping your home page is two slug edits.\nChange the slug, don\'t delete the screen Move your existing home page aside rather than deleting it. Its design, its content, and its version history are all worth keeping, and you\'ll want it back in step 5.\n1. Open your current home screen (Sites → your site → Screens → click the row). In the Publishing card, change Slug from / to something you\'ll recognize — home works — and choose Update route. The screen stays published, just at /home now.\n2. Open the Coming soon screen. Change its Slug to / and choose Update route (or Publish, if you haven\'t published it yet).\n3. Load your site. The coming-soon page is now what visitors get.\nA screen can be the home page or have a parent, but not both — if the slug won\'t take, check that the screen sits at the top level of your screens list.\nChanging a slug does not create a redirect Aglyn rewrites its own routing map when you change a slug, so links within your site keep working. It does not leave a redirect behind at the old path — that URL simply stops resolving. If the old path was public and people have linked to it, create the rule yourself with the redirect manager (a paid feature) — see Create a redirect.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '3. Keep everything else out of search', anchor: '#3-keep-everything-else-out-of-search', text: 'Your unfinished pages are still published and still reachable. Two controls decide whether search engines index them, and which one you want depends on how far along you are.\nWhile nothing is ready: the site-wide switch\nGo to Setup → SEO and turn on Discourage search engines from indexing this site. One switch, whole site:\n- robots.txt refuses every crawler (Disallow: /) and stops naming your sitemap\n- sitemap.xml is served empty\n- every page — including your coming-soon page — carries\nThis is the right choice while the site is a building site. It also covers pages you haven\'t created yet, which per-screen visibility can\'t: a screen you publish next Tuesday is indexable by default, so a site hidden page-by-page slowly un-hides itself as it grows.\nWhile the switch is on, a warning banner follows you through the console on every page of that site. That\'s deliberate, and it\'s the answer to the most common support question this feature creates — see step 5.\nOnce you\'re launching page by page: per-screen visibility\nWhen the site is mostly ready and you\'re releasing sections, turn the site-wide switch off and hide the stragglers individually. Open a screen (Screens → pick it) and use the Visibility dropdown in its Page Access card:\n| Visibility | Reachable by | In search |\n| Public | anyone | yes |\n| Unlisted | anyone with the link | no |\n| Password protected | anyone with the password | no |\n| Members only | signed-in members | no |\nUnlisted is the one you want for a finished-but-not-announced page: it stays live so you can share the link with a reviewer, and it\'s kept out of both search results and your sitemap.\nnoindex is a request, not a lock Unlisted and the site-wide switch ask search engines not to list a page. Well-behaved crawlers honor that; nothing stops a person w' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '4. Collect the signups', anchor: '#4-collect-the-signups', text: 'Every form submission is filed in your Inbox under the form\'s name, on every plan. That alone is enough to email people on launch day.\nTo get a list you can actually query, point the form at a dataset:\n1. Create a dataset on the organization Data page → Add dataset, called Launch signups, with a field for the address — email.\n2. Back in the Besigner, select the Form container and set Write to dataset to Launch signups in the Attributes panel.\n3. Select the email Form Field and set Maps to schema field to email.\nThat mapping is what makes the record land, and it\'s worth doing explicitly. The picker stores the dataset field\'s stable Reference ID, so renaming the field later never breaks it.\nLeft on None (match by field name), the value falls back to matching a dataset field whose Reference ID — the snakecase key beside each field in the Schema dialog, not its Display name — is identical to the form field\'s Field name. So a form field named email lands in a dataset field whose Reference ID is email with no mapping at all, while one named Your email silently doesn\'t.\nValues that match nothing are dropped from the record without failing the submission, and the same is true of a deleted dataset or an exceeded record quota — the append is best-effort by design, so a data-store problem never costs you a signup. The inbox copy always keeps everything, which is why it\'s the thing to check if a record looks wrong.\nThe survey walkthrough covers datasets, schema types and the form pickers in much more depth.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '5. Launch day: reverse every step', anchor: '#5-launch-day-reverse-every-step', text: 'Turning a site dark is easy to do and easy to forget. Here is the whole reversal — work down it, then verify with step 6.\n1. Allow search engines again. Setup → SEO → turn Discourage search engines from indexing this site off. The console banner disappears, and robots.txt, the sitemap and the page meta all return within about a minute.\n2. Set the hidden screens back to Public. The site-wide switch and per-screen visibility are independent — turning the switch off does not promote an Unlisted screen. Go through Screens and set each one\'s Visibility back to Public in its Page Access card. Anything you leave Unlisted stays out of search, silently and indefinitely.\n3. Swap the home page back. Open Coming soon, change its Slug to something else (coming-soon) and Update route — or Unpublish it if you\'re done with it. Then open your real home screen and set its Slug back to /.\n4. Verify — step 6. Don\'t skip it. Every step above is a setting that can be half applied, and the failure is silent.\n"Why is my site not on Google?" Nine times out of ten it\'s this feature, left on. Check, in order: the Setup → SEO switch, then each screen\'s Visibility. Then remember that re-indexing is the search engine\'s schedule, not yours — a site that was noindex for a month does not come back the afternoon you fix it. Allow days, and use Google Search Console to request indexing if you\'re in a hurry.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '6. Verify it actually worked', anchor: '#6-verify-it-actually-worked', text: 'Three things a crawler reads, and how to read them yourself. Run these against your real domain.\nrobots.txt — visit https://your-site/robots.txt, or:\nHidden looks like this — note that no sitemap is named:\nVisible looks like this:\nThe page\'s robots meta — open the page, View source, and search for robots. Or:\nA hidden page returns . A visible page returns nothing at all — no robots meta means "index me", which is the default.\nThe sitemap — visit https://your-site/sitemap.xml, or:\nThat counts the URLs you\'re submitting to search engines. It should be 0 while the site-wide switch is on, and after launch it should match your public pages. Any page you expect to see and don\'t is a screen still set to Unlisted.\nGive it a few minutes These three files are cached for about five minutes. If a change hasn\'t shown up, wait a beat and re-run rather than changing another setting.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: 'Related', anchor: '#related', text: '- SEO Toolkit — search engine visibility in full\n- Forms & lead capture\n- Build & publish a survey — datasets and form mapping\n- Site protection — when noindex isn\'t enough\n- Create a redirect' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '', anchor: '', text: 'Commerce end to end\nThis walkthrough runs the whole selling loop: catalog → storefront → checkout → orders → subscriptions. It links into the commerce reference rather than repeating it — the goal here is the end-to-end path.\nPlan availability Selling needs a paid plan (fees drop as you upgrade — see Billing & plans). Storefront subscriptions (including the subscribe side of "Both — buyer chooses") need Business and above.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '1. Connect payments', anchor: '#1-connect-payments', text: 'Aglyn sells from your own Stripe account via Stripe Connect. On the Products hub, the payments card walks you through Express onboarding; checkout stays disabled ("This site has not enabled payments yet") until Stripe reports charges enabled. Aglyn adds its per-sale platform fee automatically per your plan.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '2. Create products', anchor: '#2-create-products', text: 'On the site\'s Products page (Catalog tab), choose Add product. The editor dialog covers everything the catalog reference describes:\n- Basics — Name, Slug (/products/{slug}), Type (Physical / Digital / Service), Status (Draft / Active / Archived), description, tags, categories, media.\n- Options & variants — up to 3 options expand into a variants matrix with per-variant Price, Compare-at, SKU, Barcode, Stock, and Weight. Blank stock = untracked; 0 shows sold out.\n- Billing — how buyers pay:\n- One-time purchase (default) — a normal order.\n- Monthly subscription / Yearly subscription — the product page prices per interval and the buy button becomes Subscribe.\n- Both — buyer chooses — the product page shows a one-time vs subscribe toggle (defaulting to one-time); pick the Interval the subscribe side bills at. The buyer\'s choice is validated server-side against the product.\n- Any subscription mode reveals Free trial (days) — the trial precedes the first charge.\n- Digital delivery (digital products) — attach files from the media library, optionally versioned, with a per-order Download limit. Buyers always download the current files; uploading a new version re-delivers.\nSet the product\'s Status to Active — drafts are invisible to visitors.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '3. Design the storefront', anchor: '#3-design-the-storefront', text: 'Open a screen in the Besigner and add blocks from the Commerce group of the element picker:\n- Product grid — a responsive catalog grid. Its Show property scopes it to all products, a collection, a category, or a tag; set Columns, Sort, a cap, and optional visitor-facing filter chips. Cards link to /products/{slug}.\n- Product detail — gallery, variant picker, price (with sale badge, trial caption, and /mo·/yr when subscribing), Add to cart, and the buy button (Buy now / Subscribe, or the one-time-vs-subscribe toggle for "Both" products). Leave its Product slug blank on a template screen so it follows the URL. The Product page preset drops the whole commerce-standard page in one go: a Shop / {{product.name}} breadcrumb, the detail block, a You may also like strip, and product reviews.\n- Cart — two presets: a Cart button (app-bar icon with an item-count badge and a slide-out drawer — the badge updates live as blocks add to the cart) and a Cart page (inline, with coupon and gift-card fields). Both end in a Checkout button.\nCatalog search, filters, and sort\nThe Product grid carries a toggle per storefront catalog control, so a bare strip on the home page and a full shop page are the same block:\n- Search box — a debounced search field above the grid; matches product names, descriptions, and tags.\n- Category chips — one chip per product category (plus All), built from the categories you manage in the Products hub. Visitors tap to filter.\n- Sort select — newest, name, price low→high, price high→low, right-aligned above the grid.\n- Type filter — physical / digital / services chips, useful for mixed catalogs.\n- Price filter — a two-thumb price range slider, automatically bounded by the lowest and highest prices among the products currently showing (variant-priced products count b' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '4. What checkout does', anchor: '#4-what-checkout-does', text: 'Both buy buttons and the cart\'s Checkout redirect to Stripe-hosted Checkout, then back to your site with a success/canceled marker:\nPaying without leaving your site\nThere is a second checkout that keeps the shopper on your own pages: instead of sending them to checkout.stripe.com, the card form opens in place, below the Buy or Checkout button, styled with your site\'s theme. Leaving the store mid-purchase is one of the most common places a cart gets abandoned, so this exists to remove that step.\nRolling out. In-page checkout is off by default and is switched on per workspace by Aglyn staff (release flag In-page checkout). Until it is on for your workspace, checkout behaves exactly as described above — the redirect is what your shoppers see.\nNothing else about a sale changes when it is on, and that is deliberate:\n- The price, tax, shipping and any coupon are computed by the same code. The in-page form is the same Stripe Checkout Session as the redirect, just drawn by us instead of by Stripe — so the two cannot quote different totals.\n- Your order is still created by Stripe\'s webhook, never by the browser. If a shopper pays and immediately closes the tab, the order, the stock decrement, the receipt and the gift-card or license-key steps all still happen. If they pay and then refresh the page, none of it happens twice.\n- A declined card stays on the form. The basket, address and payment method the shopper already entered are kept, with the decline shown beside them, so they can try another card without starting over. Cards that ask for a bank verification step (3-D Secure) show that challenge in place.\n- Abandoned in-page checkouts are still recoverable and still feed the abandoned-cart emails, the same as an abandoned redirect.\nA shopper who cancels the in-page form is ret' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '5. Run orders from the console', anchor: '#5-run-orders-from-the-console', text: 'The Products hub\'s Orders tab lists every sale with product, period, status, and channel filters plus Export CSV and Draft order (build an order by hand and send a payment link).\nExport CSV writes the orders currently shown — the filters apply — as orders.csv, one row per order: date, product, amountUsd, feeUsd, customerEmail, coupon, orderId, status, channel, refundedUsd, netUsd. amountUsd is the gross charge, so subtract refundedUsd (or read netUsd) when reconciling against a Stripe payout. Orders with several line items name the first and count the rest, e.g. Blue Mug +2 more.\nOpen an order for the detail dialog — customer, line items, totals, timeline, and internal notes:\n- Fulfill… — enter a carrier and tracking number; the order moves to fulfilled and the buyer\'s account page shows the tracking. Mark delivered closes the loop, and Packing slip prints one.\n- Refund — confirms "Refund this order?", then refunds the buyer through Stripe (full or partial) and reverses the platform fee. Site-admin role only.\n- Cancel order — for orders that shouldn\'t proceed (does not auto-refund).\nStatuses move through a guarded machine: pending → paid → fulfilled → delivered, with cancel/refund exits — see the orders reference.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '6. Subscriptions & the Stripe portal', anchor: '#6-subscriptions--the-stripe-portal', text: 'Active subscriptions are recorded per site and surface in two places:\n- Buyers manage their own — the Customer account block\'s Subscriptions section has a Manage button that opens the Stripe Billing Portal (update card, cancel, see invoices).\n- You see each member\'s subscriptions in the member drawer on the site\'s Users page — what they subscribed to, the amount and interval, and the renewal date — and managers get a New subscriber notification carrying the amount on each signup, then a Subscription renewed notification carrying the amount on every cycle after it.\nWhat a subscription puts in Orders depends on the product\'s Type:\n- A physical subscription creates one order per paid cycle — the first charge included — on the Subscription channel, so every box has something to fulfill, pack and label against, and recurring revenue shows up in the Orders tab, the analytics card and the orders CSV alongside one-time sales. Each cycle\'s order also decrements the variant\'s stock (if tracked) and can trigger the low-stock alert.\n- A digital or service subscription is not an order, by design: it does not appear in Orders, in the analytics card or in the orders CSV, and it does not decrement stock — there is nothing to ship.\nEither way, what the subscriber pays is recorded on the subscription itself — each paid invoice, its period and its amount included, so a renewal is a record you hold rather than one only Stripe holds. The amount shown follows the latest cycle, so a price change, a tax change or a trial converting to a paid cycle is reflected rather than frozen at what the first charge was. Stripe keeps its own copy of every invoice, reachable from the Billing Portal.\nAn active subscription is also what members-only content can check for paid gating.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: 'Related', anchor: '#related', text: '- Commerce reference\n- Product catalog\n- POS & reservations\n- Member accounts' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: '', anchor: '', text: 'Datasets & schema deep-dive\nThis guide goes one level below the datasets overview: how the typed model actually works, what the limits are, and every path data takes in and out of a dataset.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Display names vs field ids', anchor: '#display-names-vs-field-ids', text: 'A dataset field has two names, and the distinction matters everywhere:\n- The display name is what you type in the schema dialog and what table headers and record editors show. Rename it freely.\n- The reference id is the stable key. It auto-fills from the display name when you create the field (Visit frequency → visitfrequency), and the schema dialog lets you edit it right there to set your own — for example a short, code-friendly key that differs from the label. Once the field is created the id is fixed and never changes. Records store values keyed by reference id — it\'s the key you use in {{item.referenceid}} bindings and what a form field\'s Maps to schema field picker stores.\nThe schema dialog shows both — each field row reads Display name · fieldId. The Reference ID input sits directly under Display name in the field editor; it follows the name as you type until you edit it, then keeps your value. The dataset itself likewise has a Singular name and a Plural name; the plural is the dataset\'s display name — the label its entry shows in "Write to dataset" and repeatable pickers (which store the dataset\'s id underneath, so renames never break the bindings).' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Naming & describing fields', anchor: '#naming--describing-fields', text: 'Open the schema dialog and Edit a field to change how it presents:\n- Display name — rename it freely, any time. The field id underneath never changes, so {{item.fieldId}} bindings, form field mappings, and stored records are all unaffected by a rename.\n- Description — a free-form note on what the field is for. When set, it follows the field around the console:\n- the schema dialog\'s field list shows it under the Display name · fieldId line,\n- the records table shows it as a tooltip on the column header,\n- the record editor shows it as the input\'s helper text (a validation error takes its place while present).\nBoth are trimmed on save, and a blank description is dropped rather than stored. Descriptions are console-facing documentation only — they never render on the published site.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'The typed model', anchor: '#the-typed-model', text: 'A dataset\'s model is a map of field definitions plus a display order. Each field definition carries its type, whether it\'s Required, an optional Description and Default value, validation (regex pattern, min/max length, an enum of Options), and — for reference fields — the target dataset and delete behavior.\nThe types you can author:\n| Type | Holds |\n| Text | Strings; optionally pattern-, length-, or enum-constrained |\n| Boolean | true / false |\n| Integer | Whole numbers |\n| Number | Floating-point numbers |\n| Date & time | Timestamps |\n| Coordinates | Latitude / longitude pairs |\n| List | Ordered arrays |\n| Reference | A link to a record in another dataset — see relations |\nPlugins can register custom field types, which appear in the type picker suffixed with the plugin id. Records are validated and coerced against the model on every server-side write.\nLegacy datasets Datasets created before typed models (a flat comma-separated field list) still work: the runtime derives an effective model where every column is an optional text field whose id equals the column name. Open the schema dialog and re-type the fields to upgrade — ids are preserved.\nReference fields configure what happens when a referenced document is deleted: Clear the reference (default) or Block the delete. Tick Allow multiple for many-to-many relations.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Record quotas per plan', anchor: '#record-quotas-per-plan', text: 'Dataset counts and records per dataset are entitlements of your organization\'s plan:\n| Plan | Datasets | Records per dataset |\n| Free | — (no data store) | — |\n| Starter | 3 | 1,000 |\n| Pro | 15 | 10,000 |\n| Business | 100 | 100,000 |\n| Advanced | 500 | 1,000,000 |\n- Creating datasets on Free is rejected with "Datasets require a Starter plan or higher."\n- Hitting the record cap surfaces "Record limit reached — see Billing to upgrade" in the console, and imports that would overflow are refused with the exact slot math.\n- Form submissions never fail on quota — if the dataset is full the record write is skipped silently, but the inbox copy is always kept.\n- Add-ons raise the dataset count beyond the base allowance, up to a hard per-plan ceiling.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Import & export', anchor: '#import--export', text: 'The Data page round-trips CSV and JSON:\n- Export — the CSV and JSON toolbar buttons download the loaded records with one column per model field.\n- Import — the Import records dialog takes pasted CSV (with a header row) or a JSON array. Columns match by field id first, then case-insensitively by display name; rows are validated against the model on the way in.\n- Upsert — pick a Match on field (upsert) key (say, an email field) and matching rows update records in place instead of appending duplicates. Only genuinely new rows count against the record quota.\nSee import & export for round-trip tips.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Repeatables', anchor: '#repeatables', text: 'Containers (like a Stack) have a Repeat over dataset property. Set it and the container\'s children become an item template, rendered once per record on the published site:\n1. Select the container and set Repeat over dataset to your dataset (stored by id, so renames never break it).\n2. Inside the children, reference record values with {{item.fieldId}} — e.g. {{item.name}}, {{item.price}}.\n3. Reference fields support one hop: {{item.author.name}} resolves the referenced record\'s field.\n4. Optionally set a Repeat limit, a Repeat filter (price , >=, <, <=, contains), and a Repeat sort (price desc).\nThe canvas doesn\'t expand rows while designing — it shows a repeat notice on the container ("children render once per record on the live site") so you design a single template. Up to 100 records render per repeatable.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Everything that writes records', anchor: '#everything-that-writes-records', text: '| Writer | How it behaves |\n| Console — Add record / record editor | Typed inputs per field; validated and quota-checked. |\n| Console — Import records | Bulk CSV/JSON with validation, upsert, and quota math. |\n| Forms — the Form element\'s Write to dataset | Appends on each submission. The dataset is bound by id (a dropdown; legacy forms still match by name) and each form field can map to a schema field by id via Maps to schema field, with name-matching as the fallback — so renames never lose data. Best-effort (quota-full submissions keep only the inbox copy). See the survey guide. |\n| Automations — the Write to a dataset step | Appends a record from a workflow/action run. |\n| Automations — the Update a dataset record step | Updates a matching record (by email) or appends when none matches. |\nAutomation steps live in the Do list of an action — see workflows & actions.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Deleting a dataset', anchor: '#deleting-a-dataset', text: 'Delete removes the dataset and every record in it, permanently — the confirmation tells you how many documents go with it. There is no undo and no retention window, so export first (CSV or JSON) if you might want the rows back. Deleting a single record from the table leaves the dataset itself alone.\nThe same applies to the two other things that hold records inside them: deleting an email list takes its enrolled subscribers, and deleting a collection takes the content entries published under it.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Related', anchor: '#related', text: '- Build & publish a survey\n- Datasets overview\n- Build a data model\n- Relations\n- Bindings, variables & functions' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: '', anchor: '', text: 'Install your first marketplace item\nThe Marketplace is where you add capability to Aglyn that you didn\'t build yourself: plugins, ready-made site templates, themes, layouts, components, dataset schemas and email templates. This guide walks the whole loop once — find, install, use, upgrade, remove — clicking every step.\nNo code, and nothing you can\'t undo. The only decision worth slowing down for is which sites it lands on, and step 4 is entirely about that.\nPlan availability Free to browse and install. Individual listings may cost money — the button says so before you buy. Publishing your own listing is a separate thing and needs Pro; see Publish a plugin.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Before you start', anchor: '#before-you-start', text: 'You need an organization with at least one site, and a role that can install. By default that\'s owner, admin and editor — installing is treated as content work, not an account setting. Viewers cannot, and a custom role can only if it carries the Install plugins permission.\nIf the Marketplace opens but the Install button doesn\'t, that\'s the role, not the plan — see Teams & roles.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Step 1 — Open the Marketplace', anchor: '#step-1-open', text: 'In the organization navigation (the top-level one, not a site\'s), choose Marketplace.\nIt\'s at the organization level on purpose. What you install is available to every site you choose, so it isn\'t a per-site setting, and you don\'t repeat the work for each site you run — the thing agencies and multi-site teams notice first.\nIts own navigation panel lists:\n- Browse All — the catalog.\n- Installed — what you already have, with upgrade and uninstall.\n- and, once you publish, the seller sections: Upload / Publish, Publisher Profile, Listings, Payouts, Sales.\nMarketplace is the shop; Plugins is the switch There is a separate Plugins section in the same organization navigation. That is where things get turned on and off — including Aglyn\'s own built-in plugins. Marketplace installs, Plugins toggles. If you are looking for a switch and can\'t find one, you\'re in the wrong section. More on the split.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Step 2 — Find something', anchor: '#step-2-browse', text: 'Browse All is a grid of listing cards you can search, filter and sort. Cards are a catalog only — clicking one takes you to its detail page, which is the only place an install can happen. You cannot install by accident from the grid.\nTwo things on a card are worth reading before you click into one:\n- The price chip. Every card has one. A paid listing shows $29; a free one shows the word Free, rather than leaving the corner empty for you to interpret.\n- The stars, and the number beside them. 4.8 (12) is twelve people\'s opinion; 5.0 (1) is one person\'s. A listing nobody has rated says Not yet rated instead of showing no stars.\nOn the detail page, read three things before anything else:\n1. The What\'s included box. Aglyn writes it from the listing itself, not the publisher, so it is the one description that cannot oversell. Its first row names what the install produces — a sandboxed plugin, an editable component, screens you rework in Besigner, a theme, or a new empty dataset with its fields already defined for a dataset schema, which is the reminder that records never travel: you get the shape, not somebody\'s data. The rows after it cover where it lands (step 4), review, license and updates. See What\'s included for every row it can produce.\n2. The badges. They make two different claims, and it\'s worth knowing which is which — see what the badges mean.\n3. The price. The header repeats the card\'s chip — $29, or Free — and the button spells out what pressing it does: a paid listing reads Buy for $29 rather than Install. Buying is one payment; the listing\'s updates are included in it.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Step 3 — Read the reviews, and know who can leave one', anchor: '#step-3-reviews', text: 'Ratings on a listing come only from people with a verified email whose organization actually installed it. Comments are open to any signed-in user. So a listing\'s star rating is a claim by users, and its comment thread is a claim by anyone — weight them differently.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Step 4 — Choose which sites get it', anchor: '#step-4-targeting', text: 'This is the step to read.\nOn the detail page you\'ll find an Install to dropdown with two options:\n| Option | What it means |\n| All sites | Everything in the organization. For a plugin, that includes sites you add later. |\n| Selected sites | Only the sites you tick. A Sites checklist appears underneath — tick at least one. |\n"All sites" does not mean the same thing for every kind of listing, and that is the whole reason this step exists:\n- Plugins and dataset schemas install organization-wide. A site you create next month gets them too.\n- Components, templates, layouts, themes and email templates are site-scoped. "All sites" copies them onto every site you have right now; a site you add later will not have them.\nYou will have seen this fact once already, in the What\'s included box further up the page — Installs org-wide, covering sites you add later, or Installs per site — new sites are not covered automatically. The helper text under the Install to dropdown is the same fact with your own numbers in it: for the site-scoped case it reads "Installs to all 4 sites. New sites won\'t get it automatically." Two wordings, one behavior — if they ever seem to disagree, the helper text is the one counting your actual sites.\n"Selected sites" only appears when there\'s a choice to make, so on a one-site organization you won\'t see it.\nEvery site here is a live site There is no staging site in Aglyn. Whatever you install is reachable by real visitors as soon as it\'s on a site. If you want to try something cautiously, install it to one site — ideally the quietest one — rather than to all of them.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Step 5 — Install it', anchor: '#step-5-install', text: 'Press Install (or Buy for $…). A confirmation dialog names the listing, its type, its version, and — in bold — exactly where it\'s going:\n> Install Bookings Pro (plugin, v2.1).\n> This will be installed to all sites.\nRead that bold phrase. It is the last chance to catch a mis-set target, and it is why the dialog exists.\nChoose Install. That\'s it.\nTwo things happen that are worth knowing:\n- The install is version-pinned. You have v2.1 and you keep v2.1 until you deliberately upgrade. A publisher shipping v2.2 tomorrow does not change your sites overnight.\n- A plugin is enabled for the workspace automatically. You don\'t have to go and switch it on after installing.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Step 6 — Use it', anchor: '#step-6-use', text: 'Where it shows up depends on what you installed:\n- Plugins add a named group to the Besigner\'s elements drawer, and often a page in the console navigation.\n- Components, layouts and templates appear in the drawer and in your site\'s templates library, badged Marketplace with the version they came from.\n- Themes apply to the site you chose.\n- Dataset schemas appear as a new, empty dataset under Data.\n- Email templates arrive as a draft email you can edit before sending.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Step 7 — Turn it off, or take it back off', anchor: '#step-7-off', text: 'Three different actions, often confused:\n| You want to | Where | What happens |\n| Stop it running, keep it | Plugins → its switch | Off everywhere in the workspace. Flip it back any time. |\n| Remove it from your sites | Marketplace → Installed → Uninstall, or Uninstall org-wide on an org-wide install. The listing\'s own detail page carries the same button. | The pin and the switchboard entry go. |\n| Update it | Marketplace → Installed, or the detail page\'s Update to v2.2 button | You move to the new version, deliberately. |\nUninstalling never deletes the data a plugin created. Reinstall it and it picks up where it left off. That is deliberate — an accidental uninstall shouldn\'t cost you a year of bookings — but it also means uninstalling is not how you erase data. For that, delete the data itself.\nDesign copied onto a site behaves differently, and the difference matters: a component or template you installed and then edited is now your copy. Uninstalling the listing doesn\'t reach into your screens and remove it, and updating shows you field by field what the publisher\'s new version would overwrite before it touches your edits.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'What to do next', anchor: '#what-to-do-next', text: '- Running several client sites? Run an agency workspace covers standardizing installs across sites, and automating the rest.\n- Want to build one? Build your first plugin is the developer half of this page — same product, written for someone who codes.\n- Selling one? Publish a plugin and the publisher handbook.' },
  { path: '/guides/install-your-first-plugin', title: 'Install your first marketplace item', heading: 'Related', anchor: '#related', text: '- Plugins & Marketplace — the reference: install scopes, badges, sandboxing, and the Marketplace/Plugins split.\n- Your templates library — where installed design lands, and how a marketplace copy is badged.\n- Teams & roles — who is allowed to install.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '', anchor: '', text: 'Build a mega menu with hover interactions\nA mega menu is the wide, multi-column panel that drops down from a nav item on big marketing sites. In this walkthrough you\'ll add one to your header, fill it with columns of links, and wire it to open on hover — all in the Besigner, without writing any CSS or JavaScript.\nYou can see the finished result on our demo site: hover Explore in the header of northwind-coffee.aglyn.app and a three-column panel (Coffee / Learn / Get in touch) drops open.\nPlan availability Every plan, including Free. A mega menu and its open/close behavior are basic interactions — pure in-page choreography with no server cost, so they\'re never gated. Only the powerful automation steps (analytics, overlays, custom JS, server actions) require Pro+. See interactions.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'What you\'ll build', anchor: '#what-youll-build', text: '- A Mega Menu nav item with a wide panel.\n- Three columns of screen links inside the panel.\n- A hover interaction so the panel opens when a visitor points at the nav item — and closes itself when they move away.\nPut the menu in your layout (not a single screen) so it shows on every page. Open your Main Layout in the Besigner to follow along; if you don\'t have a layout yet, see Screens & layouts.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '1. Insert the Mega Menu', anchor: '#1-insert-the-mega-menu', text: '1. In the Besigner, select your header\'s nav bar (the App Bar or its Toolbar) so the new element lands inside it.\n2. Open Add Element and expand the Navigation group.\n3. Insert Mega Menu. It arrives as a nav item labeled Menu with a starter panel of three link columns.\nOn the canvas the menu shows just its trigger — that\'s how it renders on the live site until a visitor interacts. Select the Mega Menu (or anything inside it) and the panel expands in place so you can edit its contents; click elsewhere and it collapses again.\nSet the label With the Mega Menu selected, set its Label in the inspector (for the demo it\'s Explore). Use the Panel width attribute to choose Fit content, Wide (720px), or Full width.\nThe label renders in the case you type it, so it sits beside plain nav links without shouting. If you want it uppercase, set Text transform in Styles → Typography on the Mega Menu itself and the trigger follows.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '2. Build the columns', anchor: '#2-build-the-columns', text: 'The panel is an ordinary canvas slot, so you compose it like any other section:\n1. The starter preset gives you three Stacks side by side — one per column. Select a column and set a heading (e.g. Coffee, Learn, Get in touch).\n2. Inside each column, drop Screen Link elements from the Navigation group and point each at a screen. Screen links store the screen id, not the URL, so renaming or re-slugging a page never breaks the menu.\n3. Add as many columns, links, images, or promo cards as you like — a mega menu panel takes any content.\nMenu links should render as links A Screen Link ships as a button by default, which is right for a call to action but wrong for navigation: it picks up button typography and the theme\'s uppercase transform, and it announces itself as a button to screen readers. Set Render as to Text link on the links inside a menu panel, a footer, or a body paragraph. The button-only attributes (Variant, Size, Full width) disappear when you do, because a link ignores them.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '3. Make it open on hover', anchor: '#3-make-it-open-on-hover', text: 'Out of the box, clicking the nav item already toggles the panel — no setup. To add the classic hover behavior:\n1. Select the Mega Menu element itself.\n2. In the inspector, open Add interaction.\n3. Set the Trigger to When hovered.\n4. Add the action Open a menu. Leave the target empty — it defaults to the element you\'re editing.\n5. Leave Frequency on Every time (the default) so the menu keeps working on every hover, not just once.\n6. Save. The interaction is enabled immediately and appears in the element\'s Interactions list with edit, enable/disable, and remove controls.\nThat\'s the whole wiring. A menu opened by hover closes itself when the pointer leaves the nav item and its panel, with a short grace period so the pointer can travel between the two — you don\'t need a separate When hover ends interaction.\nPick the target by clicking Any interaction that targets an element (open a menu, show/hide, open a drawer) lets you pick the target by clicking it on the canvas and confirming — no CSS selectors to write. A "define a custom selector" option is there as a secondary escape hatch.\nPrefer primitives? Insert the Dropdown Panel preset\nIf you\'d rather build the same pattern from plain elements — a Stack wrapper, a Button trigger, and an absolutely-positioned panel you style freely — insert Dropdown Panel from the Navigation group instead. It arrives with the whole hover choreography already wired as ordinary interactions: show on hover (with Close on Esc and Close on outside click) and hide on hover leave with a 250ms grace delay. Edit or delete them on the wrapper\'s Interactions list like anything you authored yourself.\nThe menus & navigation reference covers when to reach for the preset versus the Mega Menu element.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '4. Add a mobile drawer (optional)', anchor: '#4-add-a-mobile-drawer-optional', text: 'A wide hover panel is a desktop pattern. For small screens, pair it with a slide-in drawer:\n1. Insert Mobile Nav (Navigation group) into your toolbar. You get a Menu Button (hidden on desktop), an inline link row (hidden on mobile), and a Drawer already wired to the button — clicking the button toggles the drawer with zero configuration.\n2. Swap the drawer\'s placeholder links for your screens, and design the drawer panel however you like — it\'s a normal canvas slot.\n3. Under Styles → Visibility, confirm the mega menu\'s nav cluster is hidden on mobile and the menu button is hidden on desktop.\nSee menus & navigation for the full element reference.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '5. Test and publish', anchor: '#5-test-and-publish', text: '1. Use Test in the interaction dialog to confirm the open/close behavior against the canvas.\n2. Open Preview and hover the nav item — the panel opens and closes exactly as it will on the published site, without publishing anything.\n3. Toggle the artboard device preview and light/dark scheme to check the panel at different sizes.\n4. Click Publish.\nOpen your live site and hover the nav item — the panel drops open, and moving the pointer away closes it.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'How it works under the hood', anchor: '#how-it-works-under-the-hood', text: 'You never touch selectors or state, but here\'s the model:\n- Every menu and drawer renders closed on the live site and listens on a small command bus keyed by its node id.\n- An Open a menu step dispatches an open command to that bus; the menu element receives it and expands. Click-toggle, the hover interaction, and any other element that opens the menu all speak the same bus, so they compose without conflicting.\n- Hover-opened menus track the pointer and dispatch their own close when it leaves — which is why you only author the open.\nBecause it\'s all in-page DOM choreography, it runs on every plan and is never metered.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- The panel is always open in the editor. That\'s expected — selecting the menu or its contents expands it as an overlay under the nav item so you can edit it. It renders closed on the published site. Click empty canvas to collapse it, or open Preview to see it behave as published.\n- Hover does nothing on the live site. Confirm the interaction\'s Trigger is When hovered, the action is Open a menu, and the interaction is enabled (green switch on the Interactions list). Confirm you published after adding it.\n- The menu opens but won\'t close. Make sure you used Open a menu (which auto-closes on pointer leave), not Show an element (which needs a matching When hover ends → Hide interaction).' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'Related', anchor: '#related', text: '- Menus & navigation\n- Interactions & custom HTML\n- The Besigner\n- Screens & layouts' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '', anchor: '', text: 'Member accounts\nVisitors can become members of your published site — sign up, sign in, see their orders, and unlock members-only screens. This walkthrough covers the visitor side (built-in auth pages and the account block) and the console side (the Users page and the member drawer).\nPlan availability Member signups and the account block work wherever commerce does; gating screens to members needs the content-gating feature (Business and above) — see Members-only areas.\nMembers are not console users Site members are your site\'s audience, separate from the console teammates you invite to collaborate. Members sign in on your published site only, with a per-site session — they never see the console.' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '1. Turn User Accounts on for the site', anchor: '#1-turn-user-accounts-on-for-the-site', text: 'Member accounts are off by default, on every site. Until you switch them on, /signin, /signup and /recover do not exist on that site — they return a genuine 404, the same as any address you have not published.\nTurn them on at Sites → your site → Admin → Plugins, on the Site plugins card: flip User Accounts and press Save site plugins. It is a per-site switch, exactly like the other plugin toggles there, so one site in a workspace can have member accounts while another does not.\nWhy it defaults to off Most sites are marketing sites, and a sign-in page on a marketing domain is worse than a missing one: it looks like the place to type a password, while the real sign-in usually lives somewhere else entirely — a separate app domain, or your identity provider. Aglyn\'s own site is the example. Serving /signin there would invite people to enter console credentials on a page that is not the console. So the pages appear only when you say the site has members.\nSwitching User Accounts off again does not delete anything. Existing members, their profiles and their order history stay exactly where they are in Users; only the public pages stop being served. Switch it back on and everything is reachable again.\nSites that were already using member accounts when this switch arrived keep them — the switch was turned on for any site with members, a designated auth screen, or a members-only page.' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '2. The built-in sign-in and sign-up pages', anchor: '#2-the-built-in-sign-in-and-sign-up-pages', text: 'Once User Accounts is on, the site serves three ready-made routes — no design work needed:\n- /signup — "Create your account": name, email, and password (8 characters minimum). Submitting creates the member, signs them straight in, and returns them to your home page.\n- /signin — "Welcome back": email and password. The two pages cross-link ("New here? Create an account" / "Already a member? Sign in").\n- /recover — "Reset your password": a member enters their email and gets a reset link, then sets a new password at the same address.\nNew members automatically flow into your Contacts CRM and appear as leads; memberSignUp and memberSignIn automation events fire so you can trigger welcome actions.\nPasswords Member sessions are per-site, cookie-based, and last 30 days. A locked-out member can reset their own password at /recover; you can also send them a reset email from the member drawer (see Password help below).' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '3. Design an account page', anchor: '#3-design-an-account-page', text: 'For a richer home for members, add the Customer account block (found in the Commerce group of the element picker) to a screen — conventionally at the slug account, which is where commerce gates point anonymous visitors:\n- Signed out, the block shows sign-in / create-account tabs in place, with your configurable Signed-out heading above.\n- Signed in, it renders the member\'s profile with Sign out, plus sections for Orders (with status chips and tracking), Subscriptions (each with a Manage button that opens the Stripe Billing Portal), Downloads (digital purchases and license keys), and Addresses.\nGive the account page the same chrome as the rest of your site by binding a shared layout: in the screen\'s Properties, pick one under Shared layout — the appbar/footer are then maintained once for every bound screen (see screens & layouts).' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '4. Gate screens to members', anchor: '#4-gate-screens-to-members', text: 'To restrict a screen: open its version view, and in the Page Access card set Visibility to Members only, then publish. Anonymous visitors get a "This page is for members" prompt with sign-in / create-account links instead of the content (or your designed 401 error screen if you\'ve assigned one). The screen\'s content is never in the anonymous page source — members fetch it with their session after sign-in.\nFor one-off protection without accounts, use a per-screen password instead.' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '5. Manage members from the console', anchor: '#5-manage-members-from-the-console', text: 'The site\'s Users page has two cards: Site users (your members — this guide) and Users (console collaborators). The Site users card is searchable and paged, newest first, with Email, Name, Joined, and Status columns.\nClick a member to open the member drawer:\n- Profile — email, display name, and join date, with a Suspended chip when applicable.\n- Lifetime purchases — charged order totals minus refunds (pending and canceled orders excluded).\n- Orders — the member\'s payment history, newest first: order number, status, total, date, any refunded amount, and the Stripe payment reference. Needs the editor or admin role on the site.\n- Subscriptions — each with its renewal date and status chip.\n- Addresses — the member\'s saved addresses.\nSuspend & reactivate\nThe drawer\'s action button flips between Suspend member and Reactivate member, each behind a confirmation:\n- Suspend — the member can no longer sign in on the published site (they see an "account suspended" message), and their account page signs out on its next load. Orders, subscriptions, and history are all kept.\n- Reactivate — restores access with the member\'s existing password.\nBoth actions are recorded in the site\'s activity log.\nPassword help\nThe drawer\'s Password section gets a member back into their account. This is their sign-in for this site only — it has nothing to do with any Aglyn console account the same person might also have.\n- Send password reset email — emails the member a link to the site\'s /recover page. The link works once and expires after an hour, and their current password keeps working until they use it. This is the option to reach for. Capped at a few sends per hour to the same member, so a stuck retry loop can\'t flood their inbox.\n- Set a password directly — replaces the member\'s password with one y' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: 'Related', anchor: '#related', text: '- Members-only areas\n- Commerce end to end\n- Contacts CRM\n- Site protection & error screens' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: '', anchor: '', text: 'Run an agency workspace\nIf you build sites for other people — an agency, a freelancer with a roster, an internal team serving several brands — Aglyn is designed to be one workspace holding many sites, rather than one account per client. This page is the whole shape of that setup, in the order you\'d actually do it.\nIt\'s written for someone who has built one Aglyn site already. If you haven\'t, do Build your first site first — this page assumes you know what a screen and the besigner are.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'The mental model, first', anchor: '#the-model', text: 'Three words, and getting them straight up front saves a lot of confusion later:\n| Term | What it is | For an agency |\n| Organization | The billing and identity boundary. Owns the plan, the invoice, the members, the shared library. | You. One organization for your agency. |\n| Site (or host) | One published website with its own screens, domain, media and store. | One per client project. |\n| Workspace | What the console calls your organization when you\'re working in it. | Same thing as organization — you\'ll see both words. |\nThe consequence that matters: your plan\'s limits are per organization, and your access controls are per site. You buy 25 sites once; you decide separately who can touch which one.\nOne organization or one per client? Use one organization when the sites are yours to run: you hold the domains, you bill the client for a service, you\'re the one on call. That\'s the normal agency shape, and it\'s what the Agency plan is priced for.\nUse a separate organization per client when the client ultimately owns the account and you\'re only building it — they hold the card, the domain, and the risk. You then join their organization as a member and can leave cleanly.\nThe awkward middle — building in your workspace and later moving the site to theirs — is the one thing that isn\'t self-serve, so decide before you start. Ask support if you\'re not sure which side a project falls on.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 1 — Pick the plan by site count, not by features', anchor: '#step-1-plan', text: 'For agencies the binding limit is almost always how many sites you can publish, not which features you get. Check the site allowance on the plan table and pick from there.\nTwo things that change the arithmetic:\n- Extra sites are an add-on, so you don\'t have to jump a whole tier for one more client. They\'re cheaper per site on higher plans.\n- The platform fee on client storefront sales falls to 0% on higher plans. If your clients sell, that fee can dominate the subscription price — do that sum before choosing.\nUpgrades are instant, downgrades are not An upgrade applies immediately and prorates. A downgrade waits until the end of the period you already paid for, and $0 is due on the day you choose it. Plan seasonal capacity accordingly: dropping a tier in January doesn\'t reduce a January invoice. When each change takes effect.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 2 — Build your house style once', anchor: '#step-2-templates', text: 'The single biggest saving in agency work is not rebuilding the same footer.\n1. Build one site properly — nav, footer, contact page, legal pages, theme.\n2. Save it as a template from the site\'s settings. See Save a template.\n3. Start every new client from that template instead of from blank.\nTwo more things worth doing once:\n- Reusable components for the pieces you\'ll place on many screens within a site. Edit the component, every instance updates.\n- The organization media library for assets shared across clients — your own logo, stock photography you\'ve licensed, icon sets. Files there are available to every site in the workspace, so you upload once.\nKeep client assets in the client\'s site library The organization library is shared across every site. Client logos and photography belong in that site\'s library, not the shared one — otherwise the next project\'s media picker is full of the last client\'s brand.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 3 — Decide who can touch what', anchor: '#step-3-access', text: 'Aglyn has two shapes of teammate, and the distinction is the one agency-specific thing worth learning properly:\n| | Workspace manager | Site collaborator |\n| Sees | Every site in the organization | Only the sites you grant |\n| Costs | A manager seat | A collaborator seat on each site they can reach |\n| Use for | Your own staff | Contractors, and the client |\nThe Access column is where the difference shows: a manager reads All sites, a collaborator reads the number of sites they were granted. The line above the table counts the two separately, because only managers use a team seat.\nGive clients collaborator access, not manager access. A manager can see every other client\'s site, their content and their form submissions. That is usually a contractual problem, and it\'s not undone by anyone being careful.\nSteps:\n1. Organization → Team to add your own staff as managers — leave All sites ticked on the invite row.\n2. For a collaborator, invite them from the same page with All sites unticked, then use their Access cell to pick the sites and give each one a role. Access is granted per site from here, not from the site itself.\n3. Give a client who should draft but not go live the Author role on their site. It is the site role between Viewer and Editor: it can edit every kind of content — pages, layouts, components and collection entries — and it cannot publish any of it. No route, no live version, no scheduled publish, no published entry. It also cannot read the site\'s orders.\n4. Use custom roles for narrowing at the organization level — who may manage members, buy add-ons, or see billing.\nSeats are metered and enforced per plan, and both kinds are available as add-ons if you outgrow the included count. A pending invite holds a seat — the count is checked when you send it and aga' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 4 — Domains and handover', anchor: '#step-4-domains', text: 'Each site gets a free .aglyn.app subdomain immediately, which is what you build and demo on. Connect the real domain at launch.\nThe handover question is who owns the DNS, and it\'s worth settling in writing at the start of a project rather than at 5pm on launch day:\n- You hold the registrar — fastest to launch, and you can fix things. It also means you\'re the one a client has to ask to leave, which some clients dislike and some contracts forbid.\n- The client holds the registrar — slower (you\'ll be sending them records to paste), cleaner to hand over, and the honest default for most work.\nEither way the records are the same, and the site\'s setup page shows them. See Connect a domain.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 5 — Back up before you hand over', anchor: '#step-5-backups', text: 'Every site exports a full backup from its own settings. Take one:\n- before any large redesign, so "put it back how it was" is a real option;\n- at handover, and give the client a copy — it is theirs, and having it makes the relationship easier to end well;\n- before deleting anything. Deleting a site is immediate and permanent, with no hold period — unlike deleting an organization, which has one. There is no undo and we keep no copy.\nTake one from the site\'s Setup → Backup & restore. Datasets export separately to CSV from Content → Data, so a full handover is usually both.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 6 — Billing, and what to tell clients', anchor: '#step-6-billing', text: 'The invoice is yours, at the organization level. Aglyn doesn\'t bill your clients and doesn\'t split an invoice per site. However you charge them — retainer, per site, marked-up hosting — is between you and them.\nTwo things that are per site, and are the ones clients ask about:\n- Storefront platform fees come out of that site\'s own sales.\n- Usage meters (page views, storage, form submissions, emails) roll up to your organization total. A single client having a very good month can move your invoice, so watch the usage figures on the billing page rather than being surprised.\nSales tax is added on top of your plan price where applicable, calculated from your workspace\'s billing address — see Sales tax.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 7 — Automate the repetitive part', anchor: '#step-7-automate', text: 'Once you\'re running several sites, the console stops being the fastest way to do routine things. The REST API reads across one organization with one key:\n- Sites — enumerate every site in that organization and its domain, which is the basis of any status dashboard you build.\n- Form submissions — pull the leads from every site in the organization into one place, or into a CRM, and mark each one read as you go so the next run doesn\'t send it twice.\n- Orders and Products — for clients who sell.\n- Media — audit alt text across the organization\'s sites, or find what\'s filling your storage quota.\nStart with Your first API call, which walks through creating a key and making a request from scratch.\nA key never spans organizations API keys are minted per organization, and every endpoint is scoped to the organization the key belongs to. There is no key that reads across several.\nSo this step is only a single request if you took the one organization side of the choice in the mental model — clients as sites in your workspace. If you took the other side and each client owns their own organization, you need one key per client organization and your script loops over them. That is a real difference in effort, and it is the trade for the clean exit a separate organization gives you.\nOne key per purpose Create a separate key for each integration, scoped to the least it needs. A key that only reads form submissions can\'t be turned into a data breach across every site in the organization, and revoking one doesn\'t take the others down.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'A checklist you can reuse per project', anchor: '#checklist', text: 'This is a list to keep yourself — in your own tracker, or pasted into a project brief. The console does not track it for you.\n- [ ] Site created from your house template\n- [ ] Client added as a site collaborator, not a manager\n- [ ] Theme, logo, favicon set from the client\'s brand\n- [ ] Legal pages present (privacy, terms, cookie banner if needed)\n- [ ] Custom domain connected and verified\n- [ ] SEO basics: titles, descriptions, social image, sitemap reachable\n- [ ] Analytics visible to the client\n- [ ] Backup taken and a copy given to the client\n- [ ] Who holds the registrar, written down somewhere you\'ll find it' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Related', anchor: '#related', text: '- Teams, roles & membership\n- Site templates\n- Add-ons\n- Your first API call' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: '', anchor: '', text: 'Your first API call\nBy the end of this page you\'ll have made a real request to your own data and handled the errors properly. It assumes nothing — if you\'ve never used an API before, start at the top and follow along; if you have, skip to Step 3 and then read the API reference instead of the rest of this.\nEverything here uses curl, which is already installed on macOS and Linux and ships with Windows 10 and later. There\'s a JavaScript version of each step underneath.\nWhat you need\n- An organization on a plan that includes API access (Business or Advanced).\n- Permission to manage the organization — only owners and admins can create keys.\n- A terminal.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 1 — Create an API key', anchor: '#step-1-create-a-key', text: '1. Open the console and switch to the organization you want to use.\n2. Go to Organization → Settings → API keys.\n3. Choose Create API key.\n4. Give it a name that says what it\'s for — zapier-orders-sync, not key 1. The name is what you\'ll be looking at in six months deciding whether it\'s safe to revoke.\n5. Select its scopes. A scope is one permission. Grant the fewest that do the job: for this walkthrough, tick Datasets — read.\n6. Choose Create.\nCopy the key now. It\'s shown exactly once. Aglyn stores only a hash of it and genuinely cannot show it to you again — if you lose it, the fix is to revoke it and make a new one, which costs you nothing but a minute.\nA key looks like this:\nTreat it like a password The key carries your organization\'s access, not your personal login. Anyone holding it can do everything its scopes allow.\n- Never commit it to git. Put it in an environment variable or a secrets manager.\n- Never put it in a web page, a mobile app, or anything a browser downloads — a key in client-side JavaScript is a public key.\n- Use one key per integration, so you can revoke one without breaking the others.\nStore it in your shell for the rest of this page:' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 2 — Check that the key works', anchor: '#step-2-check-the-key', text: 'Before writing anything real, confirm the key is valid and see what it can do:\nThat\'s the whole handshake. Authorization: Bearer is how every request authenticates — there is no login step, no token exchange, no session.\nIf you get something else, jump to errors.\nDo this at startup in real code GET /v1/me is the cheapest way to fail fast with a clear message. An integration that checks its key on boot tells you "the key is wrong" at deploy time instead of "undefined is not a function" at 3am.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 3 — Your first request', anchor: '#step-3-your-first-request', text: 'List your organization\'s datasets:\nThree things to notice, because they\'re the same on every list endpoint:\n- data holds the results. Always an array, even with one result.\n- hasmore tells you whether there\'s another page. This is the only reliable end-of-list signal — see step 5.\n- object on each item names its type. Handy when you\'re logging.\nNow read records out of one of those datasets, using its id:\nYour data lives in values, keyed by field id — which is not the same as the display name you see in the console. Email address in the console is email here. The dataset\'s fields array tells you the mapping.\nIn JavaScript\nRead the error body before throwing. error.type is a stable machine-readable string; error.message is a sentence for a human. Branch on type, log message.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 4 — Write something', anchor: '#step-4-write-something', text: 'Writes need a write scope. Go back to the console, create a second key with Datasets — write, or add the scope when you create the key. Scopes have no hierarchy: datasets:write does not include datasets:read. A key that writes a record and then reads it back needs both, ticked separately.\nA new record returns 201.\nAbout that Idempotency-Key {#idempotency}\nIt\'s the header that makes retrying safe, and it is worth understanding on day one rather than after your first duplicate.\nThe problem it solves: you POST, the record is created, and then your connection drops before the response reaches you. You have no idea whether it worked. Retrying might create a second record; not retrying might lose the first.\nWith an Idempotency-Key, retrying is simply correct. Send the same key and:\n- if the original succeeded, you get 200 with the original record — not a duplicate;\n- if the original failed, the key is released, so a retry genuinely re-runs;\n- if the original is still running, you get 409 conflict — wait and retry.\n201 means created, 200 means replayed. That\'s how you tell them apart.\nUse a fresh UUID per logical operation — one key per record you intend to create, generated before the first attempt and reused across every retry of that attempt. Keys never expire, so a key really is single-use forever.\nThe full rules, including how it behaves on DELETE, are in Conventions → Idempotency.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 5 — Page through everything', anchor: '#step-5-page-through-everything', text: 'Lists come back in pages. To get everything, follow the cursor:\nTwo things that will bite you\n1. A short page is not the last page. Some endpoints filter rows out after reading a page, so data.length can be less than limit while hasmore is still true. A loop written as while (page.data.length === limit) stops early and looks like it worked. Loop on the cursor.\n2. Page 1 is not "the newest 25". Every list is ordered by id, not by date. There is no sort parameter and no filter on created. Paging start to finish gives you every item exactly once — that\'s what a full sync needs — but "give me today\'s records" is not a request this API can answer. Page everything and compare created yourself, or store the ids you\'ve already handled.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'The four errors you will hit', anchor: '#the-four-errors-you-will-hit', text: 'Every error has the same shape, and type is the field to branch on:\n| You see | It means | Do this |\n| 401 unauthorized | Key missing, mistyped, or revoked. | Check the header is Authorization: Bearer aglynsk…. A common cause is a shell variable that didn\'t expand — echo $AGLYNAPIKEY. |\n| 403 insufficientscope | The key is fine; it lacks a permission. code names the exact scope. | Create a key with that scope. You can\'t add a scope to an existing key. |\n| 403 planrequired | The organization\'s plan doesn\'t include API access — or, on commerce endpoints, doesn\'t include commerce (code: "commerce"). | Not transient. Don\'t retry — alert a human. |\n| 429 ratelimited | Over 120 requests/minute for this key. | Back off. Retry-After says for how long, and every response carries the remaining budget in its headers. |\nRetry 429 and 500. Never retry 401, 403, or 400 — nothing about them will change on the second attempt, and a loop that retries them turns a config mistake into a rate-limit ban.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Where to go next', anchor: '#where-to-go-next', text: '- API reference — every resource, every field, every error.\n- Conventions — pagination, ordering, errors, idempotency, in one place. Worth reading once, end to end.\n- Rate limits & usage — the 120/minute limit and how monthly usage bills.\n- Webhooks — for reacting to events, don\'t poll. Polling a list endpoint on a timer is the most common way to hit the rate limit.\nIf you\'re syncing a store, Orders and Products each carry a recipes section with the whole loop written out.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Related', anchor: '#related', text: '- Datasets & schema deep-dive — field ids, the typed model, quotas.\n- Billing & plans — which plans include the API.' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: '', anchor: '', text: 'Copy assist\nCopy assist drafts and rewrites text without leaving the Besigner.\nPlan availability Paid / env-gated (runs through a managed Claude route).' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: 'Use it', anchor: '#use-it', text: '1. Select a text-capable element (a headline, body text, a button label).\n2. Invoke copy assist on that text prop.\n3. Generate fresh copy or rewrite what\'s there, then accept the result.\nIt works on any canvas text prop, and blog entries can be drafted with AI too.' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: 'Tips', anchor: '#tips', text: '- Give it context in your prompt — the audience, tone, and goal — for better copy.\n- Treat output as a first draft; edit inline afterward with inline text editing.' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: 'Related', anchor: '#related', text: '- AI Generate Section\n- AI Assist overview' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: '', anchor: '', text: 'AI Generate Section\nWhere copy assist writes text, AI Generate Section builds structure — a whole section of components — directly on the canvas.\nPlan availability Paid / env-gated.' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: 'Use it', anchor: '#use-it', text: '1. Describe the section you want (e.g. "a three-column features row with icons and short blurbs").\n2. Run AI Generate Section.\n3. Aglyn adds a constrained subtree of real components to the canvas, which you then refine like anything else.\nThe output is constrained to valid components and placement, so it drops into your design cleanly.' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: 'Tips', anchor: '#tips', text: '- Generate a rough section, then adjust with drag-and-drop and inline text editing.\n- Combine with the section & block library for a mix of generated and pre-built blocks.' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: 'Related', anchor: '#related', text: '- Copy assist\n- The Besigner' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: '', anchor: '', text: 'AI Assist\nAglyn\'s AI assist helps you write and build faster, right inside the editor.\nPlan availability Paid / env-gated. AI features run through a managed Claude route.' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: 'Copy assist', anchor: '#copy-assist', text: 'Generate or rewrite text for any canvas text prop — headlines, body copy, button labels — without leaving the Besigner. Blog entries can be drafted with AI too.' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: 'AI Generate Section', anchor: '#ai-generate-section', text: 'AI Generate Section creates a constrained subtree of components directly on the canvas from a prompt, giving you a real starting layout you can then refine.\nMore detailed how-tos coming Prompting tips and examples are on the way.' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: 'Limits', anchor: '#limits', text: 'AI assist draws on the same monthly allowance as Aglyn Assist, so a workspace has one AI budget rather than a separate one per feature. Two limits apply:\n- A monthly message allowance per workspace. Every rewrite, blog draft and generated section counts as one message. The allowance is generous enough that ordinary editing never reaches it — it exists so a scripted client cannot turn one subscription into unbounded usage. When a workspace reaches it, the editor says so; contact support if you genuinely need a higher cap.\n- A short-term rate limit per person, which smooths bursts. If you see "Too many AI requests", wait a moment and try again.\nA request that fails before the model answers — an outage upstream — does not count against the allowance.' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: 'Related', anchor: '#related', text: '- The Besigner\n- Templates, blocks & content' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: '', anchor: '', text: 'Cookie consent\nIf your site uses Google Analytics or Google Tag Manager, Aglyn manages visitor consent for you. The control is real, not decoration: whenever a visitor\'s recorded state does not grant analytics, the script never loads — it is not loaded and then suppressed.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'How it works', anchor: '#how-it-works', text: 'Consent UI appears only on sites that use a consent-gated feature — today, a configured Google Analytics measurement ID or a Google Tag Manager container ID. Either one is enough. A site with neither has nothing to consent to, so its visitors never see anything.\nYour site\'s consent mode (Site setup → SEO → Cookie consent) decides how visitors are handled:\n- Geo-conditional (recommended, and the behavior when you have never touched the setting): visitors in prior-consent regions — the EU/EEA, the UK, and any visitor whose region cannot be determined — see a consent banner first, and analytics loads only after they allow it. Visitors everywhere else (for example the US) are tracked from their first visit with no banner; their state is recorded as implied consent, and the persistent Your Privacy Choices control lets them opt out at any time.\n- Opt-in everywhere: every visitor, everywhere, sees the prior-consent banner.\nThe banner offers Allow, Decline, and Preferences side by side — no dark patterns, and declining is one click, same as allowing.\nAdvertising is a second, separate question — and it is off until you turn it on. By default Aglyn asks your visitors about analytics and nothing else, and tells Google that advertising storage is denied for every visitor, in both directions. If you have Google Ads linked to your GA4 property and you need a basis for advertising storage, turn on Also ask visitors about advertising storage in Site setup → SEO → Cookie consent. The switch needs a Google tag of some kind — a measurement ID or a container ID — to do anything; there is no advertising storage to ask about without one.\nTurning it on grants nothing by itself. It adds a second question, with its own checkbox, to the banner and to the preferences panel, so that a visitor has ' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'What needs consent', anchor: '#what-needs-consent', text: 'Consent-gated — held back unless the visitor\'s recorded state grants analytics:\n- Google Analytics (your configured measurement ID) and every event Aglyn sends to it — see Google Analytics events.\n- Google Tag Manager (your configured container ID). The container is gated the same way and never more loosely, so it cannot be used to install a tag that runs before consent.\n- Core Web Vitals reporting. Page-speed metrics reach your property only through the same tag, and are discarded rather than held if consent is refused while a page is open.\n- Cross-visit A/B test identity: without an analytics grant, experiment variant assignment is remembered only for the visit (sessionStorage) instead of across visits.\n- Remembering the campaign a visitor first arrived from. Reading the campaign on the click itself needs no grant; keeping it across visits does.\n- Advertising storage (adstorage, aduserdata, adpersonalization), on sites that have turned the advertising question on. Where it starts depends on the visitor\'s region, and it is the same split analytics uses:\n- Prior-consent regions. The EU/EEA, the UK, and any visitor whose region cannot be determined see the banner first, and advertising storage is denied until they tick that specific box. Not objecting is never a yes here.\n- Everywhere else. Advertising runs from their first visit, alongside analytics, on the same implied basis — these visitors see no banner, and Your Privacy Choices is where they turn it off. That is the opt-out posture the Privacy Policy and the Cookie Policy both describe.\n- A visitor who declines, opts out, or arrives with a Global Privacy Control signal gets no advertising storage anywhere in the world. A refusal outranks the regional default; the default only ever fills a silence.\n- A visitor who cl' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Your Privacy Choices — the persistent control', anchor: '#privacy-choices--the-persistent-control', text: 'Whenever consent management is active, every page of your site shows a small Your Privacy Choices control. Visitors use it to change their state in either direction at any time — opt out after being tracked by default, or allow analytics after declining. If your site asks about advertising, that choice lives in the same panel, on its own checkbox. In geo-conditional mode this control is the only opt-out surface visitors in implied-consent regions see, which is why it is shown by the platform on every page rather than depending on your template.\nThe wording is deliberate and you should not expect it to be configurable. Once a site shares personal information for cross-context behavioral advertising, California\'s CPRA requires an opt-out link with that exact title, so Aglyn ships it as the title on every site rather than as a preference an individual site could get wrong.\nYou can also link any element (a footer link, for example) to #aglyn-consent — clicking it opens the same preferences panel.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Where the choice is kept', anchor: '#where-the-choice-is-kept', text: 'A visitor\'s choice is stored in their browser\'s local storage, under a key that includes your site\'s id. Three consequences worth knowing before you answer a visitor\'s question about it:\n- It is per site. A yes on one site is not a yes on another, even when the two share a preview address.\n- It does not expire. Nothing re-asks a visitor on a schedule. Clearing site data resets them to undecided, and they are then handled by your consent mode as if for the first time.\n- What was granted is re-derived from the recorded decision on every read, never trusted as a stored flag. That is why turning the advertising question off makes existing advertising grants stop counting immediately.\nWithdrawing consent removes the cookies too. When a visitor opts out or declines, Aglyn deletes the Google analytics and advertising cookies it can reach (ga, gid, gcl and their variants) across your domain and its parent, and tells any tag still resident on the page to stop measuring. A visitor who checks their cookie list after opting out sees them gone, which is the behavior to describe if one asks.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Global Privacy Control', anchor: '#global-privacy-control', text: 'Browsers can send the Global Privacy Control (GPC) signal. Aglyn honors it as an automatic opt-out: a visitor sending GPC is never tracked by default, in either mode, and their state is recorded as a GPC opt-out. If they explicitly allow analytics in Your Privacy Choices, that specific choice takes precedence over the blanket signal.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Previewing what visitors see', anchor: '#previewing-what-visitors-see', text: 'You configure from one country; your visitors come from many. In any screen\'s Preview, use the Consent preview picker (top right) to view your site as-if-from the EU, the US, an unknown region, or a GPC-sending browser — the real banner, driven by the real rules, with nothing saved. On a published page you can append ?aglynConsent=ask to any URL to see the prior-consent banner as an EU visitor would (this override can only ever show more consent UI, never less, so it is safe to share).' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Turn the banner off', anchor: '#turn-the-banner-off', text: 'The switch at the top of the Cookie consent card turns the whole tool off. That means Google Analytics loads for every visitor without being asked — do this only if you run your own consent solution, and remember you remain responsible for the consent your visitors\' jurisdictions require.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: '', anchor: '', text: 'Google Analytics events\nAdd your own Google Analytics measurement ID and your site sends events to your property, under your account, alongside Aglyn\'s own built-in pageview analytics. This page is the list: every event name, every parameter, and where it comes from.\nYou need this list before the data arrives, because GA4 will not show you a custom dimension you have not registered — and it cannot register one for a parameter it has never received.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'Turn it on', anchor: '#setup', text: 'Site → Setup → Tracking.\n| Field | Format |\n| Google Analytics measurement ID | G- followed by 4–16 letters and digits |\n| Google Tag Manager container ID | GTM- followed by 5–10 letters and digits |\nBoth are optional and independent. A value that does not match the format is ignored rather than injected, so a mistyped ID fails silently — check the field if nothing arrives.\nNothing is sent from a preview or a development server Tracking only runs on a production deployment. A site you are previewing sends no events at all, to your property or ours, so an empty GA4 report from a test run is expected rather than broken.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'What consent does to it', anchor: '#consent', text: 'The tag never loads for a visitor whose recorded consent does not grant analytics. This is structural, not a filter: with no tag on the page, every event below is dropped where it is raised, and nothing is queued for later. A visitor who grants consent halfway through a session starts being measured from that point, not retroactively.\nWhich visitors that covers depends on your consent posture — see Cookie consent. The short version: under the opt-in posture nobody is measured until they say yes, and under opt-out everyone is measured until they say no.\nYour Google Tag Manager container is gated the same way and never more loosely. A container that loads only after analytics consent cannot be used to install a tag that runs before it.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'Events GA4 collects by itself', anchor: '#automatic', text: 'Aglyn sends no pageview of its own. Your property gets GA4\'s automatic collection — pageview, sessionstart, firstvisit, userengagement — plus whatever enhanced measurement you have enabled in the property (scroll depth, outbound clicks, file downloads, and so on).\nEverything in the tables below is in addition to that.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'Engagement', anchor: '#engagement', text: '| Event | Parameters | Sent when |\n| generatelead | formname (string), formlocation (the page path) | A form is submitted successfully. formname is the form\'s name, or Form if unnamed; Newsletter for a newsletter signup block, Booking for a free booking, Popup for an overlay form. |\n| selectcontent | contenttype (always cta), contentid, surface (site) | A visitor clicks a call-to-action link. contentid combines the section, the link label and a plan= qualifier where the destination carries one; it falls back to the destination path so an unlabeled CTA is still counted. |\n| click | linkdomain (the destination hostname), linkid (when the link is identifiable), surface (site) | A visitor clicks a link to another domain. Same-host links are not sent — the destination\'s own pageview already counts them. |\n| aglynoverlay | overlayaction, overlayid | An overlay or popup is shown, dismissed or converted. |\n| aglynexperiment | experimentid, variantid, experimentaction (exposure or conversion) | A visitor is assigned to an A/B variant, and again when that variant converts. |\n| signup | method (always password) | A visitor creates a site member account. |\n| login | method (always password) | A site member signs in. |' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'Commerce', anchor: '#commerce', text: 'These come from the commerce and bookings features and follow GA4\'s standard ecommerce shape, so GA4\'s built-in ecommerce reports work without any mapping.\n| Event | Parameters |\n| viewitem | items: one entry with itemid and itemname |\n| addtocart | items; plus currency and value only when the item has a price. An unpriced item sends the pair not at all rather than sending zero. |\n| viewcart | currency, value (the server-calculated subtotal), items |\n| begincheckout | currency, value, items |\n| purchase | transactionid, currency, value (gross, excluding tax), shipping, items with itemid, itemname, price and quantity |\nThree things to know before you build a revenue report:\n- value on purchase excludes tax. There is no tax parameter, so a GA4 revenue figure will not match a tax-inclusive settlement report.\n- Items carry no itemcategory. Category breakdowns are not available from this data.\n- Refunds are not sent from the browser. Cancellations and refunds happen server-side and do not reach your property, so GA4 revenue is gross of them.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'Page speed', anchor: '#web-vitals', text: 'Core Web Vitals are reported as events named after the metric: LCP, CLS, INP and TTFB. Each carries:\n| Parameter | Meaning |\n| value | The metric delta, not the total. GA sums value, and summing deltas keeps a twice-reported metric\'s page total correct. |\n| metricid | An id unique to that measurement, for de-duplicating |\n| metricvalue | The metric\'s current value |\n| metricdelta | The change since the last report of the same metric |\n| metricrating | good, needs-improvement or poor, when the library assigns one |\n| surface | site |\nReport on metricvalue — averaging value will give you the average change, which is not a number that means anything.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'Your own events', anchor: '#authored-events', text: 'Any element on a screen can send an event you name yourself, via the Track an analytics event interaction step. It lands in the same property as everything above. See Interactions for the naming rules, the parameter limits and what gets stripped.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'What your property never receives', anchor: '#never-sent', text: 'Some measurement exists on Aglyn\'s side and is deliberately kept off your property:\n- Aglyn\'s own product events — workspace and site creation, publishing, billing and assistant usage. These go to Aglyn\'s console analytics, never to a site\'s property.\n- traffictype and contentgroup — internal-traffic marking and content grouping are applied only to Aglyn\'s own marketing site.\n- Advertising tags — Meta, Google Ads and LinkedIn tags are installed only on Aglyn\'s own marketing site. On your site the advertising machinery renders nothing and installs nothing.\n- Server-side events, including refunds and subscription cancellations. They are sent from the server with credentials that are not per-site, so there is no way to route them to your property.\n- The built-in pageview beacon. Aglyn\'s own Traffic card is fed by a first-party, cookieless request that is not GA4 and does not appear in your property.' },
  { path: '/marketing-and-automation/analytics/google-analytics', title: 'Google Analytics events', heading: 'Related', anchor: '#related', text: '- Analytics — the built-in Traffic card and per-screen figures\n- Cookie consent — what has to be true before any of this runs\n- Interactions — sending an event of your own' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: '', anchor: '', text: 'Analytics\nAglyn tracks how your site is doing out of the box — pageviews, referrers, devices, and per-screen traffic — so you don\'t need a third-party tool to see the basics.\nPlan availability Free dashboard traffic panel. Per-screen traffic and the screenAnalytics entitlement are Pro+.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Pageview tracking', anchor: '#pageview-tracking', text: 'A lightweight pageview beacon records visits into daily counters. The site dashboard shows a traffic panel summarizing your site\'s activity. Tracking is cookieless — no visitor IDs, no fingerprinting.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Visitors (approximate)', anchor: '#visitors-approximate', text: 'Alongside raw pageviews, the traffic panel shows an approximate visitor count. It is deliberately imprecise so it can stay cookieless: each browser tab counts once per day, so a visitor using two tabs — or returning on another day — counts again. Nothing links one day\'s visits to the next.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'The Traffic card', anchor: '#traffic-card', text: 'The Traffic card on a site\'s dashboard is the one most people read. Its range picker offers 7 days, 14 days, 30 days and 90 days, and defaults to 14.\nIt shows six figures for the window you picked:\n| Figure | What it means |\n| Page views | Total views in the window, with a growth figure beside it |\n| Visitors | The approximate count described above |\n| Avg / day | Page views divided by the days in the window |\n| Mobile / Desktop | The share of views from each, largest first |\n| Top page | The most-viewed path, with its view count |\n| Top referrer | Where most visits came from, with its count |\nWhat the growth figure compares against {#traffic-delta}\nThe +12.4% vs prior beside Page views compares the window you selected against the window of the same length immediately before it — 7 against the previous 7, 90 against the previous 90. Change the range and the comparison changes with it; hovering the figure says which one, in words.\nIt is green above zero, red below, and neutral at exactly zero.\nA first window shows no growth figure at all. When there is no prior period to compare against — a site published last week, asked for 30 days — Aglyn renders nothing rather than\n+100% or +0%, both of which would be claims it cannot support. The same rule applies to every delta in the product, including the ones on the Orders screen.\nPercentages in the device split are each rounded on their own, so they need not add to exactly 100. A device with no views is left out rather than shown as 0%.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Insights', anchor: '#insights', text: 'Dig deeper with top referrers and full device breakdowns over the same selectable ranges.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Campaign tracking (UTM)', anchor: '#campaign-tracking-utm', text: 'Links tagged with utmsource, utmmedium, and utmcampaign are broken down on the analytics page, so you can see which newsletters, ads, or campaigns actually bring visitors. Tag your links as you would for any analytics tool; Aglyn records the labels from the URL — nothing about the visitor.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Per-screen traffic', anchor: '#per-screen-traffic', text: 'Pro+ sites get a per-screen traffic panel on each screen\'s view page, with pageviews attributed to the screen and broken down by referrer and device — and a Screens table on the site\'s analytics page comparing pageview share across all your screens over a selectable window. Plan cards surface analytics as an upsell for lower tiers.\nTo find it: open a site, go to Screens, open a screen, open the version you want, and look for the Screen traffic (14 days) card.\nAverage time on a screen {#dwell-time}\nBeside Screen views, that card shows Avg. time on this screen — how long a visitor stayed before leaving it. It reads as 45s, 2m 04s or 1h 05m.\nThings worth knowing before you draw a conclusion from it:\n- It is an average over the visits that reported one, not over all views. A visitor whose tab is killed, or whose browser closes before it can send, reports nothing. The figure divides by the visits that were measured.\n- It is capped at 30 minutes. A tab left open all afternoon is counted as 30 minutes rather than as an afternoon, so one abandoned tab cannot dominate the average.\n- Visits under a second are ignored. A bounce through a redirect is not time on the page.\n- It appears only once there is something to average. A screen with no measured visits shows no figure at all — not a zero, not a dash.\n- Time is collected on every plan, including Free. Only reading it is Pro+, so the history is already waiting the moment an organization upgrades.\nAglyn stores a running total and a count of measurements per screen per day. It never keeps an individual visit\'s duration — that would be a behavioral record of a person, and the average is the whole of what the feature needs.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Google Analytics', anchor: '#google-analytics', text: 'Prefer your own tooling? Add a Google Analytics measurement ID under Site → Setup → Tracking and Aglyn injects it alongside the built-in tracking. There is a Google Tag Manager container field beside it, and both are gated on the visitor\'s analytics consent — the tag never loads for a visitor whose recorded state does not grant it.\nYour site then sends a defined set of events to your own property: form submissions, CTA and outbound clicks, the full ecommerce funnel, overlay and A/B events, and Core Web Vitals. Google Analytics events lists every one of them with the exact parameters it carries — read it before you build a report, because GA4 will not surface a custom dimension you have not registered.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Related', anchor: '#related', text: '- Google Analytics events\n- SEO toolkit\n- Billing & plans' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: '', anchor: '', text: 'Designed emails\nDesign campaign emails in the besigner — the same editor you use for pages — with an email-safe block set. There is no separate email editor to learn.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Create a template', anchor: '#create-a-template', text: 'On Marketing → Email, click New email template. That creates an email document and opens it in the besigner with the email blocks:\n- Email section — the 600px container with background and padding.\n- Email text — heading/subheading/body/caption styles; supports merge tokens.\n- Email rich text — formatted HTML (sanitized like the custom HTML block).\n- Email image, Email button, Email divider, Email spacer — the essentials, rendered in email-client-safe markup.\n- Email product — pick a product by id; its current name, price, and image fill in at send time (renames never break it).\n- Email custom HTML — raw table markup for advanced layouts, sanitized.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Styling email blocks', anchor: '#styling-email-blocks', text: 'The styles panel works on email blocks exactly as on page elements — your edits (fonts, colors, spacing) apply on top of each block\'s email-safe defaults.\nBecause email clients run no JavaScript, the attributes panel does not offer the Interactions section while an email document is open — use links (Email button, image links) for anything clickable.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Merge tokens', anchor: '#merge-tokens', text: 'Use these anywhere in text, rich text, or button links:\n| Token | Fills with |\n| {{contact.firstName}} | Recipient\'s first name |\n| {{contact.name}} | Full name |\n| {{contact.email}} | Email address |\n| {{site.url}} | Your site\'s base URL |\n| {{unsubscribeUrl}} | Signed unsubscribe link |\nUnknown tokens stay visible in the output so a typo shows up in your test send instead of silently rendering blank.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Send it', anchor: '#send-it', text: 'In the campaign composer, pick your template under Email design (stored by id — renaming the template never breaks scheduled sends). The plain-text message field disappears; the render pipeline produces inline-styled table HTML plus a plain-text alternative per recipient.\n- Send test to me delivers a proof to your own address without recording a campaign.\n- Scheduling and A/B experiments work exactly as with plain campaigns.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: '', anchor: '', text: 'Email Campaigns\nEmail campaigns let you reach the people in your contacts CRM. Build an audience, compose a send, and Aglyn handles delivery, caps, and unsubscribes.\nPlan availability Paid, with tiered send caps — how many emails you can send per period depends on your plan.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Send a campaign', anchor: '#send-a-campaign', text: '1. Build an audience — leads, site members, segments, or an email list.\n2. Compose the campaign from the Marketing page.\n3. Send — subject to your plan\'s send cap.\nYour monthly send cap {#monthly-send-cap}\nEvery plan includes a number of campaign emails per calendar month. The count resets on the 1st; it does not roll over.\nOnly campaigns count against it. Transactional mail — order confirmations, booking reminders, password resets, teammate invites, workflow notifications — is never refused by this cap on any plan. A busy month of orders cannot use up your campaign allowance, and reaching the cap never stops a receipt from reaching a buyer.\nYou can see where you stand in two places, without having to be refused first:\n- In the composer, under the recipient count: 340/500 campaign emails this month.\n- On the Billing page, as the Campaign emails (this month) meter, per site.\nThe cap is counted per site, so each site in your organization has its own allowance. One recipient is one email: a campaign to 200 people spends 200.\nWhen a send would take you past the cap, the composer says so while you are still writing rather than after you press Send. Upgrade your plan or shrink the audience.\nPersonalize with merge tags\nUse {{name}}, {{firstName}}, or {{email}} anywhere in the subject or body — they resolve per recipient at send time from the audience\'s stored details. Add a fallback with a pipe for recipients without a stored name: Hi {{firstName|there}}!.\nSee who it will reach, before you send {#recipient-count}\nAs soon as you pick an audience the composer counts it, and shows the count under the audience picker:\n> Recipients 1,240 · 12 unsubscribed\nThe number is not an estimate. It is produced by running the real send path with nothing written — the same audience resolution,' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Email lists', anchor: '#email-lists', text: 'Lists are static audiences shared across your organization\'s sites. Create them on the Marketing page, then grow them with the "Enroll in a list" automation step (e.g. on form completion) or popup email capture. Target any list from the campaign composer.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Experiments', anchor: '#experiments', text: 'Business plans can A/B test screens, sections, and emails from the Experiments card on the Marketing page: weighted variants, deterministic visitor assignment, a conversion goal, and per-variant exposure/conversion rates with a pick-the-winner flow.\nTwo ways to finish a test without watching it:\n- End date — past it, visitors get the default and stats stop accruing until you pick a winner.\n- Auto-declare winner — opt in with a minimum exposure count per variant and a confidence level (90/95/99%); once a challenger clears the bar (or every challenger confidently loses to the control), the experiment completes itself and serves the winner. Auto-completed tests carry a chip in the results dialog.\n- Screens & sections — variants pin a screen version; visitors are split deterministically and the winning version serves to everyone once you pick it. Start a section test straight from the Besigner\'s Interactions panel.\n- Emails — variants override the campaign\'s subject and/or body. Attach a running email experiment in the campaign composer; each recipient deterministically receives one variant (re-sends reach the same variant), sends count as exposures, and once a winner is picked every later send uses the winning copy.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Opens & clicks', anchor: '#opens--clicks', text: 'With the Resend webhook configured, campaign history shows opens and clicks per campaign, and clicks on A/B sends count as that variant\'s conversions — so the experiment results table fills in by itself.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Compliance', anchor: '#compliance', text: '- Every send includes an unsubscribe link, and the header mailbox providers look for — Gmail and Yahoo\'s one-click List-Unsubscribe.\n- Clicking it opens a confirmation page; only confirming actually unsubscribes. That matters because corporate mail scanners open every link in a message before the recipient sees it, and a link that unsubscribed on open would quietly shrink your list.\n- Unsubscribes are honored automatically so you stay compliant.\nSuppressions\nEmails ▸ Suppressions lists every address your campaigns skip, with the reason and the date:\n| Reason | What happened |\n| Unsubscribed | They clicked the unsubscribe link. |\n| Bounced | The mailbox does not exist. Recorded only for a permanent bounce — a full mailbox or a temporary server problem never suppresses anybody. |\n| Marked as spam | They reported a message. |\nThis is where the gap between a campaign\'s recipient count and what it actually sent comes from, and a rising Bounced count is the earliest sign a list is going stale.\nRemove puts an address back on your list — use it when somebody asks to be re-added, or when a suppression was recorded by mistake. Removing a bounced address means your next campaign will try a mailbox that has already said it does not exist, which mailbox providers hold against your sending reputation, so the confirmation names the reason before you do it.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Related', anchor: '#related', text: '- Contacts CRM\n- Forms & lead capture\n- Marketing overlays (email capture popups)' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: '', anchor: '', text: 'Marketing Overlays\nMarketing overlays are the announcement bars and popups that sit on top of your site to promote offers and capture emails — without touching your page designs. Manage them from your site\'s Marketing page.\nPlan availability Paid, gated by the marketingOverlays entitlement.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Announcement bar', anchor: '#announcement-bar', text: 'A site-wide announcement bar shows a message across every page — ideal for sales, notices, or launches. It\'s controlled centrally and gated by the marketing-overlays entitlement.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Promotional popups', anchor: '#promotional-popups', text: 'Popups give you more control:\n- Triggers — After a delay (a number of seconds), On scroll (a percentage of the page), or On exit intent.\n- Frequency capping — don\'t nag returning visitors. See below.\n- Scheduling — run a popup only during a campaign window.\nFrequency: how often a popup comes back {#frequency}\nIn the popup editor, Frequency offers two mutually exclusive choices.\nOnce per session shows the popup at most once for as long as the visitor keeps the tab open. Close the tab, come back tomorrow — or open your site in a second tab — and they see it again. This is the right choice for a popup tied to the visit rather than to the person: a first-order discount, a cookie or age notice, a "we\'re closed today" message.\nRe-show after a while takes a number of days — Re-show after (days), 7 by default — and hides the popup for that long after it is dismissed, across sessions and browser restarts. This is the right choice for a newsletter capture you do not want to ask twice for in a week.\nOnly one applies. Choosing Once per session hides the days field entirely, because a popup cannot be capped both ways.\nWhere the choice is remembered The cap is remembered in the visitor\'s browser, not on your site — per-session in session storage, per-days in local storage. A visitor who clears their browser data, or arrives in a private window, is a new visitor as far as the cap is concerned. If storage is unavailable altogether the popup falls back to showing at most once per page view.\nThe cap is also per popup, keyed to its content. Editing a popup\'s content resets its cap, so an edited popup is shown again to visitors who had already dismissed the old one.\nThe site-wide default popup has only the day cap The Once per session choice is on the multi-overlay editor, where you manage' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Multiple overlays, scheduling & page targeting', anchor: '#multiple-overlays-scheduling--page-targeting', text: 'The Marketing page manages any number of bars and popups, each with:\n- A schedule window (show from / show until) — run a bar only during a sale.\n- Page targeting — comma-separated paths, with /blog/ matching a whole section, plus a "never show on" exclude list.\n- An enable switch and a status chip (Live / Scheduled / Off).\nWhen several overlays match a page, the first bar and the first popup (by order) show. The single announcement bar and popup on the same page remain as your always-on default surfaces; configured overlays take priority over them.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Engagement stats', anchor: '#engagement-stats', text: 'Each overlay tracks its own lifetime views, clicks, and dismissals, shown in the Engagement column of the overlays table — so you can tell whether a bar earns its screen space. Dismissals persist per visitor: a closed bar stays closed until you edit its text.\nWith Google Analytics connected, the same events also land in your own GA property as aglynoverlay events (with the overlay id and action), so you can segment sessions by overlay engagement.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Related', anchor: '#related', text: '- Email campaigns\n- Contacts CRM\n- Billing & plans' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: '', anchor: '', text: 'Actions builder\nWhen you just need "when X happens, do Y", the actions builder is faster than a full workflow. It maps one event to one action.\nPlan availability Basic interactions are on every plan (including Free): menu and drawer open/close, show/hide an element, toggle a CSS class, sticky nav, navigation, and site alerts — pure in-page effects with no server cost and no metering.\nThe automations engine — server-side steps, custom JS, analytics events, and Marketing overlays — is Pro+, with metered runs. You build both in the same place; steps that need a higher plan are labeled in the editor.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Create an action', anchor: '#create-an-action', text: '1. Open the actions builder from Workflows.\n2. Choose the event (the trigger).\n3. Choose the steps to run in response.\n4. Save.\nThat\'s it — no multi-step logic to manage. Reach for a workflow when you need several steps, branching, or composition.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Triggers', anchor: '#triggers', text: 'Beyond server events (form submissions, page views, sign-ins, leads, bookings), actions can fire on visitor behavior in the page:\n- Scroll depth — the visitor scrolls past a percentage.\n- Scroll to / element visible — a CSS-selected element enters the viewport.\n- Element click — a CSS-selected element is clicked.\n- Exit intent — the pointer leaves toward the top of the window.\n- Time on page — a dwell-time threshold passes.\n- Page visit — the page loads.\nPage triggers can be limited to certain paths (/pricing, /blog/), and a Frequency setting controls re-fires: every matching pageview, once per session, once per visitor, or with a cooldown (a minimum number of minutes between fires for the same browser).\nOnly run when a field matches\nEvery action can carry a condition over the event\'s payload — for form submissions, that\'s the submitted field values. Pick an operator in the "Only run when" select:\n- A field is not empty — e.g. the subscribe checkbox was ticked.\n- A field equals… — an exact match (trimmed, case-insensitive), e.g. plan equals Pro.\n- A field contains… — a partial match, handy for checkbox groups that submit all ticked options joined with , (e.g. topics contains Pricing).\nWhen the condition isn\'t met the action is skipped, and the skip is recorded: the run history gets a Skipped row naming the field or fields whose condition stopped it — "Condition on subscribe, plan not met". That row is the answer to "why didn\'t my automation fire?", and it sits in the same place as the runs that did fire. A skip still doesn\'t count as a metered run: nothing executed, so nothing is charged.\nConditions are the no-code sibling of the free-text Filter expression; use whichever reads better (both must pass when both are set). One difference worth knowing: only a condition wri' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Steps', anchor: '#steps', text: 'Steps run in order and mix in-page effects with server-side work:\n- Basic in-page effects (all plans): open/close/toggle a menu or drawer, show/hide or toggle an element, add/remove/toggle a CSS class, make the navigation sticky, redirect, show a site alert. These are pure DOM choreography — they run everywhere and are never metered.\n- Advanced in-page effects (Pro+): show a popup or bar from your Marketing overlays, show custom HTML, track an analytics event, and run custom JS (Business).\n- On the server (Pro+): run a workflow, write to or update a dataset, send a webhook (Business), send an email, notify site admins, enroll the contact in a list, assign a campaign, fire a custom event to chain more actions.\nOn plans without the automations entitlement, an automation that mixes tiers still runs its basic in-page steps — the Pro+ steps are simply skipped until you upgrade.\nEvery reference (workflow, dataset, webhook, overlay, list, campaign) is picked from a list and stored by id — renaming things never breaks an automation. Deleting can, though, so the Logic page\'s Reference health card audits every automation, workflow, and computed-variable reference and lists any that point at something that no longer exists.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Run history', anchor: '#run-history', text: 'Every automation row has a Runs button. It opens Runs — your automation with a Recent runs table of that one automation\'s executions, in four columns:\n| Column | What\'s in it |\n| Time | The clock time of the run; hover it for the full date and time. |\n| Trigger | The event, in words — formSubmission shows as Form submitted. A custom event keeps the name you gave it. |\n| Result | Succeeded, Failed, or Skipped. |\n| What happened | For a run, what each step did, joined with ·. For a failure, the errors. For a skip, which condition stopped it. |\nSkipped is a result, not an absence — see Only run when a field matches. A run that fired but whose steps errored is Failed, and the errors are in the last column rather than in a log you have to go and find.\nAt the top of the Actions tab — and again on the Workflows tab, counting workflow runs — a line reads 1,284 action runs this month · 50,000 included: how many metered runs this site has used this calendar month, against the number your plan includes. This line is the only place action runs are counted for you — the billing usage meters meter workflow runs, not action runs. Watch it: once the month\'s runs reach the limit, triggered automations stop running rather than queueing or billing on. The line renders nothing at all while the counter or the plan is still loading — 0 runs this month on a site that has run thousands is the one reading that would make you stop debugging.\nWhat is and isn\'t recorded {#what-is-and-isnt-recorded}\nReference detail. Runs and skips are recorded on different rules, and the gaps are deliberate:\n- A skip on pageView is never logged. Page-view actions run on every visit to every published page, so a record per visitor per non-matching action would be a write storm, not a run history. A pageView run tha' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Interactions from the Besigner', anchor: '#interactions-from-the-besigner', text: 'Select any element in the Besigner and use the Interactions section of the attributes panel to attach a when clicked, when hovered, or when scrolled into view trigger to that exact element — no CSS selectors to write. Pairing a when hovered trigger with an open menu or open drawer step is how you build hover-to-reveal navigation, and — like all basic in-page effects — it works on every plan. The interaction is created disabled with a placeholder step; finish and enable it on the Workflows page. The same panel lists the element\'s existing interactions with an enable switch and a remove button — so you can pause or retire one without leaving the canvas — and offers "A/B test this section", which creates a draft section experiment for the element.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'When to use which', anchor: '#when-to-use-which', text: '| Use the actions builder | Use a workflow |\n| One event → one action | Several ordered steps |\n| Simple, no branching | Composes functions/variables |\n| Fastest to set up | More control |' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Related', anchor: '#related', text: '- Build a workflow\n- Webhooks' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '', anchor: '', text: 'Build a workflow\nA workflow is a sequence of steps that runs automatically when something happens on your site. This guide builds one end to end.\nPlan availability Pro+. Workflow runs are metered per tier.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '1. Open the workflows page', anchor: '#1-open-the-workflows-page', text: 'In the console, go to Data → Workflows and choose New workflow. Give it a name that describes the outcome (e.g. "Welcome new member").' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '2. Choose a trigger', anchor: '#2-choose-a-trigger', text: 'Pick the site event that starts the workflow — for example a form submission, a new member, or an order. The event\'s data is available to every step that follows.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '3. Add steps', anchor: '#3-add-steps', text: 'Add steps in order. Steps run through a pure step runner, so each step is predictable and repeatable. You can:\n- Reference variables and functions inside steps.\n- Compose an existing workflow inside a function or variable, and vice versa — workflows are composable.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '4. Save and test', anchor: '#4-save-and-test', text: 'Save the workflow. When the trigger fires, the workflow runs and each run counts toward your tier\'s metered allowance.\nAt the top of the Workflows tab, 12 workflow runs this month · 5,000 included reports the metered allowance you\'re spending. When the month\'s runs reach the limit, triggered workflows stop running — silently, without queueing and without billing on — so it\'s a number worth glancing at before you wonder why an automation went quiet.\nEach workflow row has a Runs button. It opens the run-history table described under Run history — Time, Trigger, Result, What happened.\nA workflow row reads Ran under What happened, or the error when it failed, with the time it took beneath.\nRuns recorded before this shipped are not in the table Workflow executions were written in a shape the table did not recognize, so anything that ran before AGL-2222 is filtered out of it. Those runs are not lost — the dashboard\'s Recent Activity card and Admin → Activity show every one of them, as "Workflow ran on formSubmission" with the duration appended and failures in red.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: 'Tips', anchor: '#tips', text: '- Keep steps small and named — a workflow reads like a checklist.\n- Watch your metered run count on the billing usage meters if a workflow runs on a high-frequency event.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: 'Related', anchor: '#related', text: '- Actions builder\n- Webhooks\n- Bindings, variables & functions' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: '', anchor: '', text: 'Workflows, Actions & Webhooks\nAutomate what happens on your site. Workflows run multi-step logic when something happens; the actions builder maps an event to an action; webhooks connect Aglyn to outside systems.\nPlan availability Basic in-page interactions (menu/drawer open-close, show/hide, class toggles, sticky nav, navigation, site alerts) are on every plan and never metered. The automations engine — server-side steps, analytics, overlays, and custom JS — is Pro+ with metered runs per tier. Webhooks are Business.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Workflows', anchor: '#workflows', text: '- Build workflows on the workflows page with a pure step runner.\n- Trigger them from site events, and compose functions and variables inside them.\n- Runs are metered per tier.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Actions builder', anchor: '#actions-builder', text: 'The actions builder turns an event into an action — event → action automation without code. Basic in-page effects (menus, drawers, show/hide, navigation) run on every plan; the server-side and advanced steps are Pro+ with metered runs.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Webhooks', anchor: '#webhooks', text: 'Outbound and inbound webhooks let Aglyn notify other systems and receive events from them. Webhooks are a Business-tier feature.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Run history and the run allowance', anchor: '#run-history', text: 'The Workflows and Actions tabs each open with a line reading 1,284 action runs this month · 50,000 included — the metered run allowance this site is spending. When a site reaches the month\'s limit, triggered automations stop running rather than queueing or billing on.\nEach row has a Runs button opening a four-column table — Time, Trigger, Result, What happened — with Succeeded, Failed and Skipped chips. The table is runs only: publishes, media saves and member changes stay in the site\'s general activity feed, where there is nothing to say Succeeded about.\nSkipped is the row that earns the table: an automation stopped by an unmet trigger condition is now recorded, naming the condition field, so "why didn\'t my automation fire?" is answered where the runs are. A skip is not a metered run. See Run history for what is and isn\'t recorded — page-view skips deliberately aren\'t — and Build a workflow for where workflow executions currently show up.\nMore detailed how-tos coming Recipes for common automations (notify on form submit, sync orders, etc.) are on the way.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Related', anchor: '#related', text: '- Build a workflow\n- Actions builder\n- Bindings, variables & functions\n- Billing & plans' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: '', anchor: '', text: 'Webhooks\nWebhooks connect Aglyn to the outside world. Outbound webhooks notify another system when something happens on your site; inbound webhooks let another system trigger something in Aglyn.\nPlan availability Business. Webhooks are a Business-tier feature.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Outbound webhooks', anchor: '#outbound-webhooks', text: 'Send an HTTP request to a URL you control when a site event fires — for example, post to a Slack endpoint or your own API when an order is placed.\n1. Add an outbound webhook and paste the destination URL.\n2. Choose the event that should fire it.\n3. Save. Aglyn calls your URL with the event payload each time it fires.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Inbound webhooks', anchor: '#inbound-webhooks', text: 'Expose an endpoint that external systems can call to trigger Aglyn — for example to kick off a workflow from a third-party tool.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Tips', anchor: '#tips', text: '- Pair an outbound webhook with a workflow when you need to transform data before sending it.\n- Treat webhook URLs as secrets — anyone with the inbound URL can trigger it.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Related', anchor: '#related', text: '- Build a workflow\n- Actions builder' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: '', anchor: '', text: 'Add-ons\nAdd-ons let you buy more of a specific thing without jumping a whole plan tier. They bill as extra line items on your existing subscription, prorate onto your current billing period, and take effect immediately.\nManage them on Billing → Add-ons (requires the billing.manage permission and an active plan subscription — add-ons ride your plan\'s subscription, so Free workspaces pick a plan first).' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'What you can add', anchor: '#what-you-can-add', text: 'Prices live on one page Per-unit add-on prices are on aglyn.com/pricing, and what YOUR workspace would pay is shown in Billing before you confirm. This page covers what each add-on does and how it is billed; restating the numbers here would just be a second copy to keep in step.\n| Add-on | What it does | How it is priced |\n| Manager seats | Workspace manager seats beyond the included count | Per seat, per month — cheaper on higher plans |\n| Collaborator seats | Per-site collaborator (teammate) seats beyond the included count | Per seat, per month — cheaper on higher plans |\n| Extra datasets | Additional shared datasets across the workspace | Per dataset, per month — cheaper on higher plans |\n| Extra sites | Publish more sites than your plan includes | Per site, per month — cheaper on higher plans |\n| POS registers | One extra point-of-sale register, assigned to one site | Flat per register, per month — the same on every plan |\n| Event Calendar | The event manager + calendar elements, workspace-wide | Flat per month — the same on every plan |\n- Prices are per unit per month. On annual billing, add-ons bill yearly alongside your plan (12× the monthly price) — a subscription has one billing interval.\n- POS registers also require a plan with POS (Pro and above), and each one is assigned to a specific site — see Assigning register seats.\n- Collaborator seats work the same way as POS registers: bought once for the workspace, then assigned to a site — see Assigning collaborator seats.\n- Event Calendar is a single workspace-wide toggle, not a per-site charge — see Events calendar.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'Assigning register seats', anchor: '#assigning-register-seats', text: 'Unlike every other add-on, a POS register seat is bought once for your workspace and then assigned to one site. Buying a seat does not raise the register limit everywhere — it adds one register\'s worth of capacity that you place where you need it.\nYour plan already gives every site a register allowance on its own (Pro 1, Business 2, Advanced 5). A seat is added on top of that, for the one site you assign it to.\nTo assign one, go to Billing → POS register seats, directly under Plan add-ons. The card shows how many seats you\'ve purchased, how many are assigned, and how many are unassigned, then lets you add or remove seats per site.\n- Seats are reassignable. Moving a seat between sites is immediate and costs nothing — you\'re not buying or canceling anything, just relocating capacity.\n- Taking a seat off a busy site doesn\'t delete anything. If the site is running more registers than it can after the move, the extra ones stay set up but stop taking sales until you assign seats back or remove them. The console warns you before the move, with the number affected.\n- Deleting a site returns its seats to the pool automatically, in the same action that removes the site. There\'s nothing to reclaim by hand.\n- You need the Manage billing permission to move seats, the same permission that buys them.\nIf every purchased seat is already assigned and a site needs another register, either move a seat off a site that isn\'t using it, or buy another seat under Plan add-ons.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'Assigning collaborator seats', anchor: '#assigning-collaborator-seats', text: 'Collaborator seats work exactly like register seats: a seat is bought once for your workspace and then assigned to one site. Buying a seat does not raise the collaborator limit on every site — it adds one site\'s worth of capacity that you place where you need it.\nYour plan already gives every site a collaborator allowance on its own. A purchased seat is added on top of that, for the one site you assign it to, up to your plan\'s per-site maximum. Past that maximum, more seats can\'t raise the limit and the only path is a plan upgrade.\nTo assign one, go to Billing → Site collaborator seats, directly under Plan add-ons. The card shows how many seats you\'ve purchased, how many are assigned, and how many are unassigned, then lets you add or remove seats per site. The same numbers appear on each site\'s own Collaborators card.\n- Seats are reassignable. Moving a seat between sites is immediate and costs nothing — you\'re not buying or canceling anything, just relocating capacity.\n- Nobody is ever removed for being over the limit. If a site has more collaborators than its limit — because a seat moved, a plan changed, or the limit was corrected — everyone on it keeps their access and stays signed in. The only effect is that the site can\'t take on another collaborator until it\'s back under. The console warns you before a move that would leave a site over, with the number affected.\n- Deleting a site returns its seats to the pool automatically, in the same action that removes the site. There\'s nothing to reclaim by hand.\n- You need the Manage billing permission to move seats, the same permission that buys them.\nIf every purchased seat is already assigned and a site needs another collaborator, either move a seat off a site that isn\'t using it, or buy another seat under Plan add-ons.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'How changes bill', anchor: '#how-changes-bill', text: '- Adding or removing units shows a prorated preview of today\'s charge before you confirm, and takes effect immediately.\n- Removing an add-on credits the unused time onto your next invoice.\nAdd-ons are not on the plan-switch schedule Add-on changes are always immediate and always prorated, in both directions. Plan switches are not: since Aglyn moved to end-of-cycle downgrades, a plan downgrade waits for your period end and charges $0 today, while only a plan upgrade is immediate and prorated. Removing an add-on still credits you today. See when each change takes effect.\n- Hard caps: seat and dataset add-ons stop at your plan\'s maximum (for example, Starter tops out at 5 workspace managers). Past the cap, the answer is a plan upgrade — the Billing page tells you when you\'re there.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'Plan switches and cancellation', anchor: '#plan-switches-and-cancellation', text: '- Switching plans keeps your add-on quantities and re-prices them at the new plan\'s rates. If the new plan doesn\'t sell one of your add-ons, it\'s removed and the switch confirmation says so. On an upgrade this happens today, in the same prorated update as the plan change. On a downgrade it happens on the effective date along with the plan — your add-ons keep running, at your current plan\'s rates, for the rest of the period you already paid for.\n- Canceling (or a subscription that dies after failed payments) ends your add-ons with the plan — they bill on that subscription, so entitlement enforcement stops counting them at the same moment the plan downgrades to Free.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'Related', anchor: '#related', text: '- Billing & plans overview\n- Downgrading, canceling & your data\n- Teams, roles & membership' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: '', anchor: '', text: 'Bandwidth\nBandwidth is how much traffic your published sites serve in a calendar month. Every plan includes an amount. What happens when you pass it is the part worth reading, because it is not the same on Free as it is on a paid plan.\nPlan availability Every plan has a bandwidth allowance. On a paid plan going past it is metered and billed, and your sites keep serving. On Free it is a hard stop: the site is paused until the start of the next month.' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: 'What each plan includes', anchor: '#what-each-plan-includes', text: '| Plan | Included bandwidth per month | Past the allowance |\n| Free | 5 GB | Sites are paused until the start of next month |\n| Starter | 50 GB | Keeps serving; the extra is billed |\n| Pro | 250 GB | Keeps serving; the extra is billed |\n| Business | 1,000 GB | Keeps serving; the extra is billed |\n| Scale | 2,500 GB | Keeps serving; the extra is billed |\n| Advanced | 5,000 GB | Keeps serving; the extra is billed |\n| Agency | 20,000 GB | Keeps serving; the extra is billed |\n| Enterprise | Unlimited | Nothing to pass |\nThe allowance is per organization, across every site in it — not per site. If you run four sites on one Business plan, they share the 1,000 GB.' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: 'Where to see your usage', anchor: '#where-to-see-it', text: '1. In the console, open Billing from the organization menu.\n2. Find the Usage card.\n3. Read the row labeled Bandwidth (this month, organization).\nThe meter resets on the first of each month, in UTC.\nYou do not have to be watching it. Organization admins get an in-app notification and an email at 80% of the allowance and again at 100%, once per threshold per month. What those messages say depends on your plan, and the difference is the point:\n- On a paid plan the 100% message reads "You\'re past your included monthly bandwidth — extra usage is now billed", and tells you the overage appears on your monthly invoice.\n- On Free it reads "You\'ve reached your monthly bandwidth limit", and points you at Billing to upgrade — because on Free there is no overage to bill, only a stop.' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: 'What a paused Free site looks like', anchor: '#paused', text: 'When a Free organization passes its band, its published sites stop serving pages and answer with a plain notice instead:\n> Over the monthly traffic limit\n>\n> This site has used all of the traffic included with it this month, so its pages are\n> paused until the start of next month. Nothing is wrong with your connection, and\n> nothing here has been removed.\nThree things are true about that page and are worth knowing before you see it:\n- Nothing is deleted. Your screens, media, datasets and settings are untouched. The console keeps working normally — only the public site is paused.\n- It clears itself. The pause is stamped with the month it belongs to. When the month turns over it stops applying, with no action from you and nothing to un-set.\n- Upgrading lifts it within about a minute. The check re-reads your plan every time, so a plan change releases the pause without waiting for the next month or for any sweep to run.\nSearch engines are told not to index the notice, so a pause does not cost you your rankings.' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: 'Why a site can go over before it is paused', anchor: '#timing', text: 'Usage is totalled where page views are already counted — the analytics beacon, on a sampled cadence — so a Free site can pass its band and keep serving for a few hundred more views before the pause takes hold. That is deliberate: the alternative is metering every single request, which would put a database read on every page of every site on the platform to answer a question only Free organizations can ever fail. The allowance is a monthly budget, not a per-second valve.\nA daily job re-checks the same thing organization-wide, so an organization running more than one site is still totalled across all of them.\nThe reverse is much faster still: an upgrade releases within roughly a minute.' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: 'Reducing bandwidth', anchor: '#reducing-bandwidth', text: 'Most bandwidth on a content site is images.\n- Turn on CDN delivery — it is on every plan — so images are served in WebP at the size the visitor\'s screen asks for. See Media library & CDN.\n- Replace oversized hero images. A 4 MB photograph scaled down in the browser still costs 4 MB of bandwidth every time someone loads the page.\n- Check Analytics → Traffic for a page that is unexpectedly popular; a single embedded video or a hotlinked asset can dominate a month.' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: 'Reference', anchor: '#reference', text: 'For developers and operators. None of this is needed to use the feature.\nHow usage is counted\nBandwidth is derived from page views rather than measured byte-for-byte at the edge. The platform uses a fixed estimate of 600 KB per page view and converts in both directions, so the meter you read in GB and the counters the analytics pipeline writes are the same number expressed differently. On Free, 5 GB works out to roughly 8,900 page views a month.\nPage views are read from the per-host analytics/{YYYY-MM-DD} documents that already exist for the Analytics screens — evaluating a cap adds no Firestore reads to the serving path.\nThe two mechanisms\nThere are two independent protections, and they behave differently. A description that mentions only one of them is incomplete.\n| | Bandwidth cap | Abuse ceiling |\n| Applies to | Free organizations only | Any plan |\n| Trips at | 1× the plan\'s band | 10× the plan\'s band (minimum 100,000 page views) |\n| Decided by | The analytics beacon, sampled — plus the daily usage job organization-wide | The analytics beacon, sampled |\n| Recorded on | orgs/{orgId}.bandwidthCap | hosts/{hostId}.bandwidthCeiling |\n| Enforced at | Edge middleware and the page loader | The page loader |\n| Latency | Minutes | Minutes |\n| Visitor sees | The "Over the monthly traffic limit" notice | The "This site is temporarily unavailable" notice, on Free only |\nThe abuse ceiling exists for runaway traffic — a scraper, a hotlinked asset, a loop. On a plan that meters overage it flags the site and pages staff but changes nothing a visitor sees, because that traffic is billed rather than refused. Only on a plan that cannot meter (Free) does it degrade what is served.\nThe cap is evaluated before the ceiling, so a Free site over its band reads the plan-limit wording rather ' },
  { path: '/workspace-and-billing/billing-and-plans/bandwidth', title: 'Bandwidth', heading: 'Related', anchor: '#related', text: '- Billing & plans\n- Storage overage\n- Analytics\n- Media library & CDN' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: '', anchor: '', text: 'Downgrading, canceling & your data\nChanging to a lower plan, canceling, or deleting are three different things with three different effects. The short version: downgrading and canceling never delete anything — only deletion does, and deletion is deliberate and reversible within a hold window.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'When each change takes effect', anchor: '#when-changes-take-effect', text: 'Plan changes are deliberately asymmetric, and knowing which direction you\'re going tells you what you\'ll be charged — and when. Nothing is taken from your card at the moment you change a plan or an add-on: the adjustment is written onto your next invoice, so a mid-cycle upgrade appears there rather than as a charge today.\n| You\'re doing | When it takes effect | What you are charged, and when |\n| Upgrading to a higher plan | Immediately | Nothing today. A prorated amount for the rest of the current period is added to your next invoice |\n| Downgrading to a lower paid plan | At the end of your current billing period | Nothing |\n| Canceling | At the end of your current billing period | Nothing |\n| Adding or removing an add-on | Immediately | Nothing today. Prorated onto your next invoice — removing one credits you back the same way |\nThe reason downgrades wait is simple: you already paid for the current period, so you keep everything you paid for until it runs out. There is no proration credit on a downgrade because there is nothing to credit — nothing changes today.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Downgrading to a lower plan', anchor: '#downgrading-to-a-lower-plan', text: 'A downgrade changes your entitlements — which features you can use and how much — but it does not remove anything you\'ve already created, and it does not take effect the moment you click.\nThe pending-downgrade window {#pending-downgrade}\nWhen you switch to a lower paid plan:\n1. Confirm the switch. The dialog states the effective date and that $0 is due today.\n2. Your current plan keeps running to the end of the period you already paid for. Every feature of the higher plan stays on the whole time.\n3. A chip appears on the Current plan card — "moves to \\{plan\\} on \\{date\\}" — so the scheduled change is visible every time you open Billing, not just in the confirmation you clicked past.\n4. On the effective date the plan changes and the lower price starts.\nChanging your mind {#keep-my-current-plan}\nWhile a downgrade is pending, the Current plan card shows Keep my current plan. Clicking it cancels the scheduled change, and the plan you\'re on simply continues at its normal price. You can also do this by switching to any higher plan — an upgrade cancels the pending downgrade and then applies immediately, in that order.\nCanceling your subscription while a downgrade is pending also drops the schedule, so the two never collide: you cancel from the plan you\'re on, not from the one you were scheduled to land on.\nWhat changes when the downgrade lands {#what-changes-on-a-downgrade}\nNothing is deleted. Every site, file, dataset, product, and team member you have keeps existing.\nWhat changes:\n- You can\'t create more past the new limit. If Pro includes 3 sites and you have 5, all 5 keep working — but you can\'t add a 6th until you\'re back under the limit or upgrade again. The same applies to datasets, team seats, products, POS registers, and storage.\n- Paid features you no longer have tur' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Canceling your subscription', anchor: '#canceling-your-subscription', text: '- Cancel any time. Your subscription runs to the end of the paid period — a chip on the Billing page shows the end date, and you can resume before it hits.\n- When the period ends, your organization resolves to the Free plan. This is the same as a downgrade: nothing is deleted, over-limit resources persist, and paid features turn off.\n- A failed payment doesn\'t cancel you immediately — your access continues while Stripe retries the charge (a past-due banner shows), and entitlements only drop to Free if the subscription actually lapses.\nWhat the Cancel button actually opens {#the-cancel-dialog}\nCancel subscription doesn\'t cancel on the first click. It opens a short dialog with up to four steps. We\'d rather tell you what\'s in it here than have it surprise you:\n1. "Why are you leaving?" — one choice from a fixed list (too expensive, missing features, not using it enough, switching to something else, technical problems, just pausing, something else) plus an optional comment box. This is the only required step, and the comment is genuinely optional.\n2. A downsell, if a smaller paid plan would still fit you. It names the plan and its price. No thanks, continue moves on.\n3. A winback discount, if you haven\'t used one before. It states the exact percentage and the exact number of months it lasts, because a discount whose end date you can\'t see isn\'t an offer. No thanks, continue moves on.\n4. The confirmation. This step also lists anything you\'ll be over the Free plan\'s limits on once the cancel lands — extra sites, datasets, seats — so the consequence is visible at the moment you decide, not afterwards.\nThings worth knowing about the offers:\n- Every step has a visible way past it. There is no step you can only leave by staying. Keep my plan on the last step closes the dialog and' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Deleting a single site', anchor: '#deleting-a-single-site', text: 'To remove just one site (not the whole organization), open the site\'s Admin → Danger zone and use Delete site. A site admin types the site name to confirm, and it\'s deleted immediately — its screens, media, and settings are permanently removed and its address stops resolving. Unlike an organization deletion there\'s no hold, so export a backup first (Setup → Backup & restore) if you might want it back. Your other sites and the organization are unaffected.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Deleting your organization', anchor: '#deleting-your-organization', text: 'Deletion is separate from canceling and is the only thing that removes your data. It\'s intentional and reversible for a short window:\n1. Request deletion — an owner starts it from the organization settings; you confirm by typing the organization name. Export anything you want to keep before you start (Setup → Backup & restore) — the hold is the window for it, and nothing is kept for you afterwards.\n2. A hold period follows the request. During the hold nothing is deleted and you can cancel the request to fully restore.\n3. After the hold, the organization — its sites, files, datasets, and account records — is permanently erased. This step is irreversible, and we keep no copy of the erased data. What we retain is an internal record that the erasure happened: which organization, when it was requested, and how many sites, members and credentials were removed.\nDeletion covers your organization\'s sites and their stored files and data. If you own an organization that still has other members, transfer or remove them first — a shared organization isn\'t deleted out from under its members.\nGDPR / right to erasure You can request erasure of your personal data at any time. Deletion permanently removes your records and leaves us with no copy of them — only a record that the erasure was carried out, which is itself kept for a limited period. Export anything you need during the hold. Contact support if you need an erasure completed outside the self-serve flow.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Related', anchor: '#related', text: '- Billing & Plans\n- Teams, roles & membership' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: '', anchor: '', text: 'Billing & Plans\nYour plan determines which features you can use and how much of each. Aglyn checks entitlements (can you use a feature) and quotas (how much) throughout the product, and shows usage meters so you always know where you stand.\nPlan availability Every site has a plan. Free, Starter, Pro, Business, Scale, Advanced, and Agency unlock progressively more, and Enterprise sits above them all.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Tiers & entitlements', anchor: '#tiers--entitlements', text: 'Prices live on one page Current prices — monthly, annual, transaction fees and per-unit overage rates — are on aglyn.com/pricing, and your own plan and next invoice are in Billing in the console. This page explains how billing WORKS; it deliberately does not restate the numbers, because a second copy is a copy that goes stale.\n| Plan | Commerce |\n| Free | Build & publish only — no selling |\n| Starter | Sell products, with the highest transaction fee of the paid tiers |\n| Pro | More products, a lower fee, POS, abandoned-cart recovery, reviews, dropshipping |\n| Business | More products again, a lower fee, subscriptions & paywalls, gift cards |\n| Scale | Higher product and site limits, lower fee again |\n| Advanced | Unlimited products, no transaction fee, high-volume commerce & API |\n| Agency | Many sites under one organization, white-label |\n| Enterprise | Unlimited everything, SSO, white-label, no transaction fee |\nTransaction fees are Aglyn platform fees on the sales you take through your site — storefront orders, paid memberships and paid bookings alike — separate from Stripe\'s payment-processing fees. Upgrading is the way to reduce them.\nEvery plan also includes an amount of monthly traffic — 5 GB on Free, rising to unlimited on Enterprise. Passing it is metered and billed on a paid plan, and pauses the site until the start of next month on Free. See Bandwidth for the table and for what a paused site shows a visitor.\nEnterprise\nEnterprise is the one tier you cannot buy from the Billing page. It has no list price — the plan, term, and invoicing are agreed with us, and we provision the organization directly. On top of everything in Agency it lifts every quota to unlimited and adds SAML / OIDC single sign-on, so your team signs in through your own identity provider.\nTo s' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Usage meters', anchor: '#usage-meters', text: '- The billing page shows meters for every quota — storage, bandwidth, datasets, seats, sends, and more — with redesigned plan cards.\n- A usage-cap banner appears site-wide at 80% and 100% of a quota, with an upgrade link.\n- Org admins also get an in-app notification when email sends, dataset count, data storage, or bandwidth crosses 80% or 100% — once per threshold per month, so nobody has to be watching the console to find out. The bandwidth message differs by plan, because what happens next differs by plan: paid organizations are told the extra is billed, Free organizations are told the site will be paused.\n- The monthly email allowance caps campaign sends. Transactional mail — password resets, invites, order confirmations, booking reminders and workflow notifications — is counted toward your usage but is never blocked by the cap, at any plan. Going over shows up as an overage on the usage rollup rather than as mail your customers never receive.\n- Usage is rolled up with a cost-plus estimate for metered features.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Storage overage', anchor: '#storage-overage', text: 'Each site includes a fixed amount of storage. On a paid plan, going past it is not a wall:\n- Uploads keep working. You are never stopped from adding files because you reached your included storage.\n- The extra storage is billed on your monthly invoice at our infrastructure cost plus 30% — the exact per-GB rate is on the pricing page and in Billing → Storage cap.\n- We tell you before it happens. You get an alert as you approach your included storage and another when you cross it, so the invoice is never the first you hear of it. See usage meters.\nIf you would rather uploads stopped\nSet a monthly storage cap in Billing → Storage cap. This is optional and off unless you choose it. Once a month\'s storage overage would pass the amount you set, new uploads are refused and you are never billed above that number.\nYou can change or remove the cap at any time, including while you are over your included allowance. Nothing is ever deleted — a cap only affects new uploads, and removing one takes effect immediately.\nFree plans are never billed for storage On the Free plan there is no storage overage at all. Your included storage is a fixed cap: uploads stop there, nothing is metered, and no amount of usage produces a charge — so there is nothing to cap and nothing to configure. Enterprise storage is unlimited, so it has no overage either.\nNo surprise bills Two things prevent one, and they work in different ways. The alerts at 80% and 100% of your allowance mean nobody first learns about overage from an invoice. The optional cap means anyone who wants a hard ceiling can have one, at a number they choose.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Usage budget', anchor: '#usage-budget', text: 'A usage budget is a monthly amount you choose, plus the percentages of it you want to hear about — the same shape as a Google Cloud billing budget. Set it in Billing → Monthly usage budget.\n- It warns, it never limits. Passing a budget sends a notification and an email. Nothing stops, no upload is refused, and your bill is unaffected. If you want usage to actually stop, that is the storage cap above — a different control, deliberately kept separate.\n- You choose the alert points. The default is 50%, 90% and 100%; you can set your own, including percentages above 100 so a runaway month keeps speaking. Up to six.\n- One alert per percentage per month. Crossing 50% tells you once, not once an hour. Climbing to the next percentage alerts again, and every percentage resets when the month does.\n- Both channels. Alerts arrive in the console notification menu and by email to your workspace owners and admins, so you do not have to be signed in to find out.\n- The figure is the invoice\'s own. Budget alerts quote the same metered total the billing page shows and the invoice charges — totalled once a day, so the first days of a month may show no total yet.\nChanging the amount clears the alert history for the month, so a budget you lower starts warning you against the new number straight away.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Seats', anchor: '#seats', text: '- Team seats (workspace-wide) and per-site collaborator seats are metered and enforced per tier — seats cover the people who build and manage your sites.\n- Buy paid seat add-ons to grow your team beyond the included seats — self-serve from Billing → Add-ons, alongside extra sites, datasets, POS registers, and the Event Calendar.\n- Site member accounts are not seats: visitors who sign up to your published site are unlimited on every plan.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Audience (contacts)', anchor: '#audience-contacts', text: 'Rolling out The Contacts page in the console isn\'t available yet. Contacts are still captured from your sites and readable over the REST API, and the Free band below still applies — but while the page is unavailable, paid audience overage is not billed. The rates below are what will apply once Contacts opens.\nYour contacts CRM — form fills, member sign-ups, buyers, and bookings unified into one people list — is priced as an audience band, not a hard cap:\n- Each tier includes a band: Free 100, Starter 1,000, Pro 10,000, Business 100,000, Scale 500,000, Advanced 1,000,000 contacts. Agency and Enterprise are unlimited.\n- On paid tiers, growing past the band never blocks or drops anything — extra contacts are metered overage on your monthly invoice, at a per-1,000 rate that falls as you move up the plans — see pricing for the current rate on your plan, per extra 1,000 contacts per month. Upgrading a tier is always cheaper than sustained overage.\n- On Free, the band is a hard limit: new visitors past 100 keep their member accounts and orders, but no CRM record is kept. The count of missed sign-ups is recorded and will be shown on the contacts page once it opens.\n- The billed count is your list size at the end of the month, not its size on any other day. Your list is a running total rather than a monthly tally, so a month has to be charged on one moment in it, and that moment is the last daily reading taken before the month closes. Contacts added after a month ends belong to the new month; contacts deleted after it ends do not undo the month that already ran.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Organization data', anchor: '#organization-data', text: '- Datasets are organization-scoped: counts and storage meter against your organization, not individual sites.\n- Each paid tier includes a number of datasets and an included data storage size (Starter 1 GB, Pro 5 GB, Business 25 GB, Scale 50 GB, Advanced 100 GB, Agency 500 GB).\n- Extra datasets are a monthly add-on whose price falls as you move up the plans; storage beyond the included size is metered overage, billed per GB-month on your monthly invoice.\n- The billed size is what you were storing at the end of the month, on the same basis as the audience band above: the last daily reading taken before the month closes. Clearing datasets after a month has ended lowers the next invoice, not the one for the month that just finished.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'API access', anchor: '#api-access', text: 'The customer REST API is a Business tier and above feature — mint scoped API keys and call the versioned /v1 endpoints from anywhere. Requests are metered per organization:\n| Plan | Included requests / month | Overage |\n| Business | 100,000 | Metered per additional 1,000 |\n| Scale | 300,000 | Metered, at a lower rate than Business |\n| Advanced | 1,000,000 | Metered, lower again |\n| Agency | 5,000,000 | Metered, the lowest per-unit rate |\n| Enterprise | Unlimited | — |\n- Requests past the included quota keep working and bill as metered overage on your monthly invoice — never a hard wall mid-integration.\n- The billing page shows an API requests meter, and the usage-cap banner warns at 80% and 100% of the included quota.\n- Only requests that pass authentication and the rate limit are counted — rejected calls (bad key, wrong plan, rate-limited) are never billed.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Payments', anchor: '#payments', text: 'Billing runs through Stripe. Paid features (commerce, bookings, campaigns) share the same Stripe integration.\nYour billing details live on the Billing page in the console, one card per thing you might want to change. Each card saves on its own, so editing your address never touches your tax ID and vice versa.\nPaying an outstanding invoice {#outstanding}\nIf a payment fails, the invoice stays open and the Billing page shows it with a Pay now button.\n- It works even if the subscription has already been cancelled. Dunning cancels subscriptions after enough failed retries; the invoice is still owed and still payable, and paying it does not require a plan.\n- Your bank may ask you to confirm the payment. That step is your bank\'s, not ours, and it appears for the same reason it does anywhere else.\n- We do not mark it paid because the button worked. The invoice updates when Stripe confirms the money arrived, so what you see is the settled state rather than an optimistic one.\n- The amount is the amount the invoice was issued for. Tax on an invoice is fixed when it is issued and is never recalculated later.\nWhat a plan will cost {#plan-total}\nBefore you subscribe, the Billing page quotes the plan you are looking at with tax included, taken from Stripe\'s own invoice preview rather than worked out here.\n- A total is only shown as final once tax has been calculated, which needs your billing address. Until then the page says so rather than showing a total that quietly leaves tax out.\n- A zero tax is explained, because a zero has several meanings: reverse charge applies and you account for the tax under your own registration; your account is registered as tax-exempt; or nothing is charged in your location.\n- Promotion codes are applied here. An invalid or expired code is refused immedi' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Related', anchor: '#related', text: '- Add-ons\n- Teams, roles & membership\n- Analytics' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: '', anchor: '', text: 'Manage Account\nManage Account is your personal account page, separate from your workspace and its team roster. Open it from the account menu (your avatar, top right) — click your name in the menu header, or the gear icon beside it.\nEverything here is yours alone: changing it follows you into every workspace you belong to. Workspace-level things — the team roster, roles, billing — live under Organization → Team and Billing instead.\nThe page is five tabs.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Account', anchor: '#account', text: 'Your primary email and how you sign in.\nThe email field here is read-only, with an Email verified or Email unverified chip beside it. It shows your primary address — the one Aglyn\'s sign-in record holds. To add other addresses, or to make a different one primary, use the Email addresses tab.\nSign-in methods\nBelow the email, every method linked to your account is listed:\n- Google — shows the connected Google address and a Disconnect button.\n- Email & password — carries a Required chip. Password sign-in is permanent: it\'s the method that always works, so it can\'t be disconnected.\nIf Google isn\'t linked yet, a Continue with Google button connects it. Linking both means you can sign in either way with one account — the same profile, the same workspaces, no duplicate account.\nYou can never remove your last sign-in method; the attempt is refused rather than locking you out. Closing the Google popup mid-flow simply cancels — nothing changes.\nIf your organization uses single sign-on Accounts that sign in through a company identity provider cannot link Google or any other method — the option is shown as unavailable, with the reason. That is deliberate, not a limitation we intend to lift.\nSingle sign-on exists so your organization\'s identity provider is the only gate: they revoke access there, require MFA there, and offboard people there. A linked personal Google account would be a way in that your IT administrators cannot see or revoke, which is the thing SSO is bought to prevent.\nIf your organization turns on SSO enforcement later, sign-in methods that were linked before are removed at that point, and any active sessions using them end. Your account is never left with no way in: if removing a method would orphan an account, it is skipped and reported to your administrators inst' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Email addresses', anchor: '#email-addresses', text: 'You can keep up to five addresses on one account — a work address and a personal one, say — instead of running two accounts.\nType an address into Add an email address and Aglyn emails a confirmation link to it. Until you follow that link the address is listed as Unconfirmed and does nothing at all: it cannot be used to sign in, it cannot receive an invitation, and it cannot become your primary. Confirming is the only thing that makes an address count, because following a link in an inbox is the proof that the inbox is actually yours.\nEach address in the list carries a Confirmed or Unconfirmed chip, and one carries Primary. The buttons beside a row change with its state:\n- Resend — on an unconfirmed address, sends a fresh confirmation link. Links expire after 24 hours; an expired one tells you to send a new one rather than quietly failing.\n- Make primary — on a confirmed address that isn\'t already primary.\n- Remove — on any address that isn\'t your primary.\nWhat each address does\nOnce confirmed, an address is two things and nothing more:\n- A way to sign in. Type any confirmed address on the sign-in page with your usual password and you\'re in. You don\'t have to remember which one the account was opened with.\n- A place an invitation can arrive. If a workspace administrator invites the address, you can accept it from the account you already have.\nYour primary address is the one that receives receipts, password resets, and account notices. It\'s also the address shown on the Account tab.\nAdding an address never joins you to a workspace This is the one thing people expect that is deliberately not true. Adding you@bigcompany.com to your account does not put you in BigCompany\'s workspace, and confirming it doesn\'t either.\nAccess to a workspace comes from an invitation somebody th' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Profile image', anchor: '#profile-image', text: 'Your avatar, shown in the account menu, on the workspace team roster, and beside your activity. Pick an image from the organization\'s media library or paste an https image URL.\nNever set one and Aglyn falls back to the photo your sign-in provider gave us, and then to your initials, drawn by Aglyn. Nothing about you is sent to an outside avatar service to work out what to show. The preview beside the field shows exactly what everyone else sees.\nClearing the field is different from never having set one. Emptying it and saving removes your picture and keeps it removed — signing in again does not put your provider\'s photo back. Save an image here again whenever you want that prefill returned.\nIf your company signs you in through its own identity provider and this is blank, that provider is most likely not sending a picture — many cannot, including Google Workspace SAML, which has no photo attribute to map. Set one here: the media library accepts an upload, or paste an https link.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Basic info', anchor: '#basic-info', text: 'Your first and last name. Saving also updates the display name your teammates see — the Team page, activity entries, and comments all pick it up.\nBoth are prefilled from however you signed up: the name you typed on the sign-up form, or the one your Google account or company identity provider sent us. Editing them here wins permanently — signing in again never re-applies the provider\'s version over your own. If your company signs you in through its own identity provider and these are blank, that provider is not sending a name; type one here.\nContact details\nPhone number, organization name, and your address.\nYour phone number is stored in international format — type it however you like, including (512) 555-0123, and it is saved as +15125550123. Include the country code for anywhere outside the US and Canada, since a bare national number cannot be matched to a country without guessing.\nCountry is the two-letter code (US, GB, DE). Stripe Tax cannot compute anything from a spelled-out country name, which is why the field insists.\nIf your company signs you in through its own identity provider, your address is prefilled from that directory only when the directory sends a street line. A provider that releases a city, region or postcode on its own leaves these fields empty for you to fill in: those parts are not an address anyone could post to, and Aglyn does not keep personal details it has no use for. As with your name, anything you type here wins permanently — signing in again never re-applies the provider\'s version, and clearing the address tells us to stop prefilling it altogether.\nWho can see this Your address and phone live on your personal account, visible only to you and to Aglyn staff. They are not copied onto your organization\'s member list — that list is readable by ' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Security', anchor: '#security', text: 'Change your password.\nThis tab appears only if your account has a password. A Google-only account has no password to change — connect Email & password from the Account tab first, and the Security tab appears.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Related', anchor: '#related', text: '- Signing in & sessions\n- Teams, roles & membership\n- Notifications' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: '', anchor: '', text: 'Report an issue\nFound something broken? Open the account menu in the top right and choose Report an issue. The dialog is available from every console page, and on every plan — including Free.' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: 'Is it Aglyn, or your own site?', anchor: '#is-it-us-or-your-site', text: 'This channel is for problems with Aglyn itself — the editor, the console, publishing, domains, billing. It is not the place to change something on a site built with Aglyn.\nThe line is not simply "platform versus content", so here it is in cases:\n| What you noticed | Where it belongs |\n| The heading on your About page is the wrong color, or says the wrong thing | Your site. Change it in the editor, or ask whoever builds the site for you. |\n| Headings render at the wrong size on every site you open | Aglyn. Report it. |\n| A page returns 404 after you renamed it | Aglyn. Report it. |\n| The contact form on your site emails the wrong address | Your site — that address is a setting on the form. |\n| The contact form never delivers, whatever address you set | Aglyn. Report it. |\nThe pattern: if changing it means editing your content or settings, it is yours. If it happens the same way regardless of what any one site contains, it is ours.\nIf you did not build the site and cannot change it, the people who can are whoever set the workspace up — an agency, a colleague, or whoever sent you your invitation. Aglyn cannot edit a customer\'s site on their behalf. Some workspaces put their own support link in the dialog; when one is configured, it appears as Get help with this site.\nStill unsure? Send it anyway. A report filed in the wrong place costs us a moment; a problem nobody hears about costs everyone more.' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: 'What to write', anchor: '#what-to-write', text: 'The dialog asks different things depending on what kind of report it is, because a bug and an idea need different answers. Pick the kind first.\nSummary — always required, one line, the way you would describe it to a colleague. It becomes the filed issue\'s title.\nIf something is broken {#a-bug}\nFour questions, all required. They are what turn a report into a fix:\n- What were you doing when it broke? — step by step, so we can follow along. This is the single most valuable thing you can write.\n- What did you expect to happen?\n- What happened instead? — quote any error message exactly.\n- Does it happen every time? — one click: every time, sometimes, once, or you have not tried again. It changes what we do first, so it is not optional.\nIf it is an idea {#an-idea}\nOne required question, and it is deliberately not "what should we build":\n- What are you trying to do that you can\'t? — the problem, not the feature. There may already be a way to do it, and where there is not, knowing the goal gets you a better answer than a specification would.\n- How do you handle it today? and If you already have something in mind are both optional.\nIf it is a question {#a-question}\n- What do you need to know? — required.\n- What have you already tried or read? — optional, and it saves us sending you back to a page you have read.\nQuestions take one extra step: before anything is filed, we check whether the documentation already answers you. If it does, the dialog shows the relevant pages, word for word, under This may already be answered — and nothing is filed. If that covers it you are done; if it does not, This didn\'t answer it — send anyway files the question as normal.\nSend report stays disabled until Summary and every required question for that kind have something in them.\nThe length caps {#l' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: 'What gets attached for you', anchor: '#what-gets-attached-for-you', text: 'You do not need to describe your setup. The report already carries:\n| Attached automatically | Why it helps |\n| The page you were on | Points straight at the surface, without a screenshot |\n| The site you were working on | Names the affected site, when you were on one |\n| Your workspace and plan | Says which features and limits were in play |\n| Your role | A bug that only bites one role is a different bug |\n| Which features were switched on | Recognizes a report against a surface still rolling out |\n| The app version and build | Says exactly which release you were running |\n| Your browser and window size | Separates a layout problem from a logic one |\n| A reference id | Ties your report to our server logs for that moment |\nYour name and email come from the account you are signed in with — there is nothing to fill in.\nNothing else is collected. No passwords, keys or session data are ever attached, your IP address is not recorded, and the workspace and site named on a report are only ever ones your own account can already reach.' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: 'Being contacted', anchor: '#being-contacted', text: 'The dialog ends with "You can contact me about this report", ticked by default. Untick it and we will still read and track the report; we just will not reply to you about it. Leave it ticked if the answer might need a back-and-forth — most bugs do.' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: 'Where it goes', anchor: '#where-it-goes', text: 'Reports land in a dedicated intake in Aglyn\'s issue tracker, kept separate from our own engineering backlog so that what customers report is read on its own terms rather than buried in internal work. You will see a reference like AGL-42 when it is filed; quote it if you follow up.\nA report is closed when you have an answer — not when the code merges. Those are different moments, and you are owed the first one.\nThis is not a support ticket A report is a defect we track. A support ticket is a conversation with the support team, carrying a first-response commitment on your plan.\nUse Report an issue for "this is broken" or "this should exist" — from any plan. Use Support when you need an answer from a person about your own account, and your plan includes tickets.' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: 'When it does not send', anchor: '#when-it-does-not-send', text: 'Whatever the reason, the dialog stays open with your text intact. A report that fails never costs you what you wrote — fix the cause and press Send report again, or close the dialog yourself.\nYou are filing faster than the limit {#rate-limits}\nTwo limits apply, per person, and a report has to pass both:\n| Window | Reports |\n| Per minute | 2 |\n| Per hour | 20 |\nExceeding either shows "You have filed several reports just now — try again shortly." — as a warning rather than an error, because nothing is wrong with the report, only with its timing. Wait out the window and send it again.\nThis is the message most often mistaken for a broken dialog. The two windows exist together deliberately: a per-minute limit on its own can be spread into a steady drip that still buries triage, so a burst and a drip are both capped.\nYour email address is not verified {#verified-email}\nFiling needs a verified email address. An account that has not confirmed its address is refused with "Verify your email to continue" and nothing is filed — the dialog gives no hint that this is about your account rather than about the report. Manage account shows an Email verified or Email unverified chip beside your address, which is where to check. Once the address is verified, the dialog works straight away.\nSomething went wrong on our side\nA report we could not file tells you so plainly, hands you a reference id you can quote to support, and leaves everything you typed in the open dialog. It is never reported back to you as sent. Retrying is safe.\nSelf-hosting Issue reporting is one of the optional integrations in a self-hosted install, switched on with LINEARAPIKEY and LINEARCUSTOMERREPORTSTEAMID — both listed in that page\'s Optional keys table, plus an optional LINEARCUSTOMERREPORTSPROJECTID if you separa' },
  { path: '/workspace-and-billing/report-an-issue', title: 'Report an issue', heading: 'Related', anchor: '#related', text: '- Support & community\n- Manage account\n- Console tour\n- Self-hosting' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: '', anchor: '', text: 'Signing In & Sessions\nSign in to the console with email & password or Google. A few behaviors are worth knowing about, especially if you work across devices or multiple organization workspaces.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Google sign-in', anchor: '#google-sign-in', text: '- On desktop, Google sign-in opens a popup window and returns you to the console when it completes.\n- On mobile browsers, the console uses a full-page redirect instead: you\'re taken to Google, sign in there, and land back on the console already authenticated. (Mobile browsers can\'t reliably hand a popup\'s result back to the opening page.)' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Sign-in methods', anchor: '#sign-in-methods', text: 'You can link both methods to one account, and then sign in either way — same profile, same workspaces, no duplicate account. Manage them under Manage Account → Account:\n- Continue with Google links Google to an account that signed up with a password.\n- Disconnect unlinks Google again.\n- Email & password is marked Required and can\'t be disconnected — it\'s the method that always works.\nYour last remaining sign-in method can never be removed, so there\'s no way to lock yourself out.\nSigning in with any of your addresses\nIf you keep more than one email address on your account, you can type any confirmed one on the sign-in page with your usual password — you don\'t have to remember which address the account was opened with. Unconfirmed addresses don\'t work here, and neither does an address on somebody else\'s account.\nSingle sign-on accounts are the exception. If your company signs you in through its own identity provider, no other method can be linked — see Manage Account for why, and for what happens to methods linked before your organization enabled enforcement.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Resetting your password', anchor: '#resetting-your-password', text: 'Forgot your password? From the sign-in screen, choose Account recovery and enter your email. We email you a secure reset link, then walk you through the rest:\n1. Request — enter your email on the account recovery screen and submit. We always show the same "check your email" confirmation, whether or not an account exists for that address (so the screen can\'t be used to probe who has an account).\n2. Email — open the message and follow the reset link. Links expire after a short while and can only be used once.\n3. Choose a new password — the link opens the reset screen, which confirms whose account it\'s for and asks for a new password (entered twice). Password rules match the sign-up screen.\n4. Done — once saved, head back to the sign-in screen and sign in with your new password.\nIf a link has expired or was already used, the reset screen offers to send a fresh one.\nIf you signed up with Google and have never set a password, there\'s nothing to reset — connect Email & password from Manage Account first.\nSelf-hosting Aglyn composes and sends the reset and verification emails itself, through your configured mail provider — you do not need to set a Firebase action URL, and the Firebase email templates are not used at all. Firebase still mints the one-time code; only the message and the link\'s host are Aglyn\'s, and the link is built from your own console origin.\nWhat you do still need: the console domain listed under Authentication → Settings → Authorized domains, and a working mail provider. If mail is unconfigured, account recovery still returns its usual "check your email" screen — deliberately, so the screen can\'t be used to probe who has an account — but no message goes out. Check your server logs for [auth/send-password-reset] email is not configured.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'One session across workspaces', anchor: '#one-session-across-workspaces', text: 'Signing in on the main console signs you in to every {org} workspace subdomain too — the session is shared at the parent domain, so hopping between workspaces never re-prompts for credentials. Signing out anywhere retires the shared session everywhere.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Automatic sign-out after inactivity', anchor: '#automatic-sign-out-after-inactivity', text: 'For security, an idle console session expires after 1 hour of no activity (in any open tab, on any of your workspace subdomains). When that happens you\'re returned to the sign-in screen, and the page you were on is preserved — after signing back in you resume exactly where you left off.\nActivity means any interaction: pointer movement, typing, scrolling, or touching. Active work in one tab keeps your other tabs alive too.\nInactivity is the only thing that ends a session early: a background tab losing its own authentication (a laptop waking from sleep, a suspended tab, a network blip) recovers silently from the shared session instead of signing you out everywhere. Only an explicit sign-out — yours, or a staff-initiated revocation — retires the shared session.\nSelf-hosting The idle window is configurable via the NEXTPUBLICAUTHIDLETIMEOUTMINUTES environment variable (default 60; set 0 to disable).' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'When the console asks you to sign in again', anchor: '#when-the-console-asks-you-to-sign-in-again', text: 'Sometimes a session stops working without ending. A tab left open overnight, a laptop that slept for a long weekend, or a sign-out somewhere else can leave the console holding credentials the server no longer accepts. The pages you already loaded keep rendering from their cache, so nothing looks broken — but anything the console tries to fetch comes back refused, and lists load empty.\nWhen that happens the console opens Sign in again to verify your device over whatever you were doing. You do not have to find a message and work out what to do about it: the dialog is the fix.\n- You stay where you are. No redirect, no lost page, and unsaved changes stay on screen behind the dialog.\n- Sign in with your usual method — your password, your Google or single sign-on account, or a passkey. The dialog closes and the data that would not load, loads.\n- Not now puts it away. The page stays usable and read-only-ish: what is already on screen is fine, but lists that failed will still be incomplete, and each of them offers Sign in again to bring the dialog back.\nIt is a real sign-in, not a confirmation. There is no way to dismiss your way back into a working session, because the session itself is what stopped working.\nOccasionally the console instead says it cannot reach your data and that signing in again will not help. That is a different problem — it is not your account and not your session, nothing has been deleted, and it usually clears on its own. Signing out at that point only makes it harder to diagnose, so don\'t.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Recent sign-ins', anchor: '#recent-sign-ins', text: 'When your account is signed in to from a device it has not been used on before, we email you: the device, the approximate location, the IP address, and the time. Manage Account → Security → Recent sign-ins is the list that email points at — every device that has signed in to your account, newest first, up to the last 50.\nEach row names the device as a summary of its browser and operating system ("Chrome on Windows"), and beneath it the approximate location, the IP address, when it was last used, and when it was first seen. Location and IP come from the network the request arrived on, so they are approximate — a mobile connection or a VPN can put you in a city you have never been to.\nA device here is a browser that holds a long-lived cookie we set when you sign in, not a fingerprint of your hardware. Clearing cookies, using a private window, or switching browsers therefore shows up as a new device, and the first device ever recorded on an account never triggers the email.\nWhen we do not email you\nWe do not send the alert for a device that signs in from the same IP address and the same operating system as a device already on your list, seen within the last 30 days. That is the shape of clearing your cookies, opening a private window, making a new browser profile, or using a second browser on the same machine — all the same person on the same computer, and an alert people learn to ignore is worth less than no alert.\nThree things bound it, because "same network" is not "same person" on an office or café connection:\n- the device is still recorded and still listed, marked with the reason no email was sent, so a sign-in is never invisible even when it is silent;\n- a device on a different operating system behind the same address always gets an email;\n- at most three alerts a da' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Passkeys', anchor: '#passkeys', text: 'Manage Account → Security → Passkeys lists every passkey on your account, when it was added and when it was last used, with Set up a passkey to add one and Remove on each row.\nPasskeys are additive. Adding one never weakens or replaces anything — your password and your sign-in providers keep working exactly as before — so losing an authenticator costs you a convenience, not your account.\nRemoving one\nUse Remove when a device is lost or stolen, or when you no longer want a particular key on the account. Removing a passkey:\n- stops that passkey signing in, immediately and everywhere;\n- does not sign you out anywhere. Sessions the passkey already started are ended by signing out of a device, which is a separate control;\n- does not touch your password or your other sign-in methods.\nYou can set the same device up again afterwards — removing a passkey frees it completely, rather than blocklisting it.\n"Blocked — possible credential copy"\nEvery authenticator keeps a counter that only goes up. If a passkey presents a counter that has gone backwards, that is the signature of a copied credential, so Aglyn refuses the sign-in and marks the passkey Blocked.\nA Blocked passkey stays refused. It is not a warning you can sign past, and it does not clear itself — the only signal there will ever be is the one regression, so throwing it away after a single refusal would throw away the detection. Sign in another way, then Remove the passkey and set the device up again if you still have it.\nRarely, an authenticator with a buggy counter can trigger this on a device nobody has copied. The remedy is the same, and it is the reason Remove exists next to it.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Downloading your data', anchor: '#downloading-your-data', text: 'Manage Account → Close account → Download my data gives you a machine-readable JSON copy of everything we hold about you: your profile and contact details, your workspace memberships, your passkeys, your public publisher handle, and the support messages you wrote. It is the same file we would send if you asked us in writing.\nIt is deliberately scoped to you. A workspace is shared, so your colleagues\' details are not in it — a support thread you took part in contributes only the messages you wrote yourself, not the replies. To take a whole workspace with you, use the workspace export below instead.\nIt never contains a secret. API keys, webhook secrets, password hashes and payment links are listed as present rather than reproduced, so the file tells you what exists without becoming something you can lose. An API key\'s identifier is withheld too, because that identifier is derived from the key itself.\nThat is decided by what a value looks like, not only by what the field is called — a credential is withheld whether it sits in a field named webhooksecret, one named supplierToken, or one named nothing in particular. A credential carried inside a URL is stripped out of the address while the address itself stays, so you can still see where your own files live. Ordinary content, prose, identifiers and content hashes are not touched: a list of names is a list somebody has to keep up to date, and the whole point of this file is that it does not quietly stop covering something.\nThe file opens with a coverage section naming every place we looked and what was done with each — including the two things that are deliberately not included, and why. If something you expected is missing, that section is where to check first.\nDownloading a whole workspace\nOwners and admins can export an en' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Closing your account', anchor: '#closing-your-account', text: 'Manage Account → Close account permanently deletes your personal account. It removes your profile and contact details, your avatar, your notifications, and your sign-in, and takes you off every workspace roster you\'re on.\nThis cannot be undone, and support cannot restore it.\nWorkspaces are never deleted by closing an account. A workspace outlives the person who created it, and deleting one as a side effect of someone closing their personal account would take its sites and data with it. So if you are the sole owner of a workspace, closing your account is refused until you hand that workspace over — the message names each one, along with whether it has an active subscription and how many other members it has. Transfer ownership from Team → Permissions, then come back here.\nBeing a member, editor, admin or site collaborator is never a blocker; only sole ownership is.\nYou\'ll be asked to confirm twice: once by proving it\'s you (your password, or a fresh sign-in through your provider), and once by typing DELETE. Both are required, and the confirmation of identity has to be recent — starting the flow and leaving it open for an hour will ask you again.\nSingle sign-on If your organization uses SSO, your account also exists in your identity provider\'s directory. Closing it here removes you from Aglyn; it does not touch your account with your identity provider, and an administrator there may be able to provision you again.' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: '', anchor: '', text: 'Support & community\nTwo ways to get help, each with its own page under Support: private support tickets with the Aglyn team, and a community forum shared with other Aglyn builders.\nOpen Support from Organization → Support, or from Support in your account menu. It lands on whichever channel your plan makes primary — the forum on Free and Starter, tickets from Pro upward — and each page links to the other, so you always have both.\nIf you were invited to a single site Support isn\'t part of a site collaborator\'s console. A ticket is a conversation between the organization and Aglyn — it isn\'t scoped to one site, and the thread is readable by the organization\'s team — so the console doesn\'t offer it to someone whose access stops at a single site.\nRaise anything you run into with whoever invited you. They can open a ticket, and because tickets belong to the organization rather than to the person who filed them, any of their teammates can carry the thread on.\nPlan availability The community forum is on every plan, including Free. Private support tickets start on Pro — Free and Starter are forum-only tiers.\nEach plan with tickets carries a first-response target, shown on the Support tickets page itself:\n| Plan | Tier | First response |\n| Free · Starter | Community | Forum only — no ticket channel |\n| Pro | Standard | 7–14 business days |\n| Business · Scale · Advanced | Business | 4–6 business days |\n| Agency | Priority | 1–3 business days |\n| Enterprise | Dedicated | 24–48 hours, plus a named success manager |\nEnterprise is measured in clock hours rather than business days, so a ticket opened on Friday is still answered over the weekend. The target is the upper bound of the range, measured to our first reply — not to resolution. See Billing & plans.' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: 'Support tickets', anchor: '#support-tickets', text: 'At Organization → Support → Support tickets.\nA ticket is a private conversation between your organization and Aglyn staff. Anyone in the organization can open one and follow the thread.\nOn Free and Starter this page explains where ticket support starts and points you at the forum instead — it never offers a New ticket button the server would refuse.\n1. Choose New ticket.\n2. Give it a Subject (up to 150 characters) and describe what\'s going on in the message body (up to 5,000 characters).\n3. Submit. The ticket appears in your list marked open, and Aglyn staff are notified immediately.\nOpen a ticket from the list to read the thread and reply. Each message shows who sent it, so a staff reply is always distinguishable from your own.\nTicket status\n- open — with you or with Aglyn; new replies from either side keep it open.\n- closed — resolved. Either side can close a ticket, and replying to a closed ticket reopens it automatically — you never need to file a duplicate to follow up on something you thought was finished.\nTickets belong to the organization, not to the person who opened them, so a teammate can pick up a thread while you\'re away. They stay in the list after closing as a record of what was asked and answered.\nWhat to include\nSupport answers faster with the specifics: the site and screen involved, what you expected versus what happened, and the exact error text if there is one. If it\'s about billing, say which plan and which invoice.' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: 'Community forum', anchor: '#community-forum', text: 'At Organization → Support → Community forum, and the page Free and Starter workspaces land on.\nThe forum is for questions other builders can answer, and for sharing what you\'ve made. Threads are visible to everyone with forum access across all organizations — so don\'t post anything private (account details, customer data, keys). That\'s what a support ticket is for.\nThreads are organized into four categories:\n| Category | For |\n| General | Anything that doesn\'t fit the others. |\n| Building | How-to questions about designing and shipping sites. |\n| Showcase | Show the site you built. |\n| Feedback | Product feedback and feature requests. |\nFilter the list by category, open a thread to read and reply, or start your own with a title and body (5,000 characters). Your display name and avatar are shown as the author.' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: 'Related', anchor: '#related', text: '- Billing & plans\n- Manage Account' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: '', anchor: '', text: 'Custom roles & permissions\nControl what each teammate can do with roles — named permission sets — plus optional per-member overrides.\nPlan availability Paid.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Create a custom role', anchor: '#create-a-custom-role', text: '1. On the organization Team page, find the Custom roles card and choose New role.\n2. Give it a name and set each permission to granted, denied, or inherit (inherit falls back to the member\'s org role default).\n3. Save, then assign it to members from the roster\'s Custom role column.\nThe permission catalog covers organization settings, the activity log, billing (view and manage separately), member management, site creation and deletion, organization data, marketplace publishing, and plugin installs.\nPermissions are enforced on the server — every one of them is checked by the API that performs the action, not merely used to hide a button — so a role reliably limits what a member can do, whichever route they reach it by. Members without billing or settings permissions don\'t see those tabs at all either.\nThere is deliberately no permission for marketing surfaces (announcement bars, popups, campaigns). Those belong to a site, not to the organization, and access to them follows the member\'s role on that site — see Site access. An organization-level toggle would suggest a control the model does not have.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Effective permissions', anchor: '#effective-permissions', text: 'Not sure what someone can actually do? Every member row has a Permissions viewer that resolves their org role defaults, custom role, and per-member overrides into the final yes/no grant list.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Per-member overrides', anchor: '#per-member-overrides', text: 'Need one person to have slightly more (or less) than their role? Apply a per-member override on top of the role instead of creating a whole new role for one exception.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Tips', anchor: '#tips', text: '- Model roles around jobs ("Editor", "Marketer"), not individuals.\n- Use overrides sparingly — too many overrides make access hard to reason about.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Related', anchor: '#related', text: '- Invite teammates\n- Members-only areas' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: '', anchor: '', text: 'Invite teammates\nBring collaborators into a site so they can build and manage alongside you.\nPlan availability Paid. Team seats are metered per tier; buy seat add-ons to grow. See Billing & plans.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Invite someone', anchor: '#invite-someone', text: '1. Open the organization\'s Team page and choose Add or invite.\n2. Enter their email and assign a role.\n3. What happens next depends on whether they already have an Aglyn account: already on Aglyn — they join right away and see the workspace on their next visit; new to Aglyn — we email them an invite to accept.\nPending invites\nInvites that haven\'t been accepted are listed with Resend (send the email again, for the address that lost it in a spam folder) and Revoke. A revoked invite\'s link stops working immediately.\nWho gets told\n- The person you invited gets the invite email. The confirmation you see says whether one actually went out — "email sent" versus "they\'ll see it when they sign in" — so a workspace with email delivery unavailable never leaves you assuming a message was delivered.\n- Your workspace\'s owner and admins get an in-app notification when an invite is created and again when it is accepted, so whoever sent it finds out it was taken up without re-checking the Team page. Both appear under Team & access in the notification bell, and can be muted there like any other category.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Accepting an invite', anchor: '#accepting-an-invite', text: 'If you\'re the one being invited, sign up or sign in with the address the invite was sent to — usually via Google, if that\'s the address. You land on the Workspaces page, which leads with "You\'ve been invited" and an accept banner. Accept there and the workspace opens.\nIf that invite is your only workspace, the page also offers Create my own site instead — accepting isn\'t your only option. If you already belong to other workspaces, the invite banner appears above your usual workspace picker.\nAn invitation never changes who owns the workspace\nAccepting an invite normally sets your role to whatever the invite offered. The one role it cannot touch is the owner\'s. If an invitation is sent to the address that owns the workspace, accepting it is refused rather than applied — otherwise the owner would be quietly stepped down to a viewer or an admin, and only the owner can transfer ownership back, so nobody left in the workspace could undo it.\nOwnership moves one way only: Settings → Transfer ownership, by the current owner, to somebody already on the team. The previous owner becomes an admin. Nothing else in the product creates or moves an owner — an invitation cannot grant the role either.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'How team members act', anchor: '#how-team-members-act', text: 'Team members act in the owner\'s organization, not their own — so their changes apply to your site, and permissions are enforced across the console\'s APIs and surfaces. Seat limits are enforced per tier; if you\'re at your limit, add a seat add-on before inviting more.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'You are a site collaborator\'s support channel', anchor: '#you-are-a-site-collaborators-support-channel', text: 'Someone you invite to a single site gets a console scoped to that site, which leaves out the organization pages — including Support. That is deliberate: a support ticket is a conversation between the whole organization and Aglyn, readable by your team, not a per-site channel.\nThe practical consequence is that a site collaborator who hits a problem comes to you. Open a ticket on their behalf if it needs Aglyn — include the site and the exact error, as Support & community describes, since you will be relaying rather than reproducing. Someone invited to the whole organization keeps Support unchanged.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Help a teammate who is locked out', anchor: '#help-a-teammate-who-is-locked-out', text: 'Open the member from the Team page and use the Password card. It has two options, and the first is almost always the right one.\nSend password reset email emails the member a link to choose their own password. Their current password keeps working until they use the link, and nobody else ever sees the new one. This works for every member. A few sends per hour to the same person is the cap — it\'s their inbox, and a reset link is good for an hour anyway.\nSet a password directly replaces the member\'s password with one you choose. Use it only when the member cannot receive email at all — you then have to pass the new password to them over a channel you trust. When you do:\n- they are signed out on every device, and\n- they are emailed to say an administrator changed their password.\nWhy you can\'t always set a password\nAn Aglyn login is personal, not per-organization. One person has one account no matter how many organizations they work with, so setting someone\'s password can hand you the keys to workspaces that have nothing to do with yours.\nThe Set a password directly option is therefore unavailable — with the reason shown in its place — when the member:\n- also belongs to another organization,\n- is the organization owner (use Settings → Transfer ownership instead),\n- is an Aglyn staff account, or\n- is you (change your own password in your account settings).\nIn every one of those cases, Send password reset email still works. The link goes to the member\'s own inbox, so it is safe regardless of what else their account can reach.\nBoth actions are recorded in the organization\'s activity log, along with who performed them. The password itself is never written to the log.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Activity log', anchor: '#activity-log', text: 'The organization\'s Team page shows a Recent Activity feed — renames, workspace URL changes, ownership transfers, members added/removed or re-roled, and invites sent, revoked, or accepted — each with who did it and when.\nVisible to members whose role carries the Activity & audit log permission. Owners and admins have it by default; viewers do not, and neither does a custom role until you grant it. Revoking it does not merely hide the card — the feed is served by an API that checks the permission, so a member without it cannot read the log by any route.\nEntries name the thing that changed and link straight to it, so "Saved the screen — Home" takes you to that screen. Entries recorded before this shipped show a plain description instead of a link.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Tips', anchor: '#tips', text: '- Start people on a least-privilege role and widen it with per-member overrides only where needed.\n- Removing a member frees their seat.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Related', anchor: '#related', text: '- Custom roles\n- Members-only areas\n- Billing & plans' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: '', anchor: '', text: 'Members-only areas\nBeyond your team, your site visitors can become members — and you can restrict certain screens to signed-in members only.\nPlan availability Business and above. Members-only screens, gated video, and the content paywall need the content-gating feature; on lower plans (or if a subscription lapses) gated content is not served.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Let visitors sign up', anchor: '#let-visitors-sign-up', text: 'Enable site membership so visitors can sign in / sign up to your site. New members flow into your Contacts CRM automatically.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Sign-in, sign-up, and recovery pages', anchor: '#sign-in-sign-up-and-recovery-pages', text: 'Every site serves three membership routes out of the box:\n- /signin — email + password sign-in\n- /signup — create an account\n- /recover — forgotten-password recovery\nBy default these render simple built-in forms styled with your site theme. To make them fully yours, design them in the besigner like any other screen:\n1. Create a screen and drop in the matching block from the Members group of the element picker — Member sign-in, Member sign-up, or Password recovery. Add anything else you like around it: your logo, imagery, copy.\n2. Open Admin → Plugins → User Accounts and assign the screen to its route on the Sign-in & sign-up pages card.\nAssigned screens render through the normal pipeline — your theme, shared layout, and all — and are kept out of search results. Clearing a slot falls back to the built-in form.\nSend members back where they came from The sign-in and sign-up blocks honor a continue query parameter (e.g. /signin?continue=/members/welcome), so links from gated pages can return the visitor to the page they wanted. Only same-site paths are followed.\nForgotten passwords\nMembers who forget their password can request a reset from the Forgot password? link on the sign-in form (or by visiting /recover directly):\n1. The member enters their account email. The response is always the same, so the form can\'t be used to check whether an address has an account.\n2. If the address belongs to a member, they receive an email with a reset link to your site. The link works once and expires after one hour — and completing a reset invalidates any other outstanding links.\n3. The member sets a new password and signs in with it. Suspended members don\'t receive reset emails.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Gate a screen', anchor: '#gate-a-screen', text: '1. Open the screen you want to protect.\n2. Mark it members-only.\n3. Publish. Only signed-in members can now view it; everyone else is prompted to sign in.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Manage your members', anchor: '#manage-your-members', text: 'The site\'s Users page lists everyone who signed up on your published site — searchable and paged, newest first. Click a member to open their detail drawer:\n- Profile — email, display name, join date, and saved addresses.\n- Order history — the member\'s payment records, newest first: order number, status, total, and date, plus the Stripe payment reference and any refunded amount. Order history is visible to site admins and editors.\n- Subscriptions — active and past storefront subscriptions with their renewal date.\n- Lifetime purchases — everything the member actually paid: charged order totals minus refunds (pending and canceled orders don\'t count).\nSuspend or reactivate a member\nFrom the drawer you can suspend a member (with a confirmation). A suspended member:\n- can no longer sign in on your published site — they see a clear "account suspended" message;\n- is signed out the next time their account page loads;\n- keeps all orders, subscriptions, and history — nothing is deleted.\nReactivate restores access with the member\'s existing password. The member list shows each account\'s Active/Suspended status at a glance.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Tips', anchor: '#tips', text: '- Combine members-only screens with email campaigns to nurture your member base.\n- For one-off protection without accounts, use a per-screen password instead.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Related', anchor: '#related', text: '- Invite teammates\n- Contacts CRM\n- Site protection & error pages' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: '', anchor: '', text: 'Teams, Roles & Membership\nAglyn has two kinds of people: your team (who build and manage the site) and site members (visitors who sign up to your site). Both are permission-aware.\nPlan availability Paid. Seats are metered per tier; see Billing & plans.' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Team roles', anchor: '#team-roles', text: '- Invite teammates to a site and assign roles.\n- Create custom roles with unique permission sets.\n- Apply per-member overrides on top of a role.\n- Permissions are enforced across the console\'s APIs and surfaces, and team members act in the owner\'s organization, not their own.' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Organizations', anchor: '#organizations', text: 'Aglyn is built around organization workspaces: an organization subscribes once, owns multiple websites, and shares media, plugins, dynamic data and billing across them. You can belong to several organizations with a different role in each (owner, admin, editor, viewer), and editors/viewers can be limited to specific sites. Each organization gets a Slack-style workspace address (your-org.aglyn.com).\nEvery account operates inside an organization — solo accounts simply get a personal workspace automatically. The team features above keep working unchanged.\nThree kinds of user\nThe Team table labels every row with its type, because the type — not the role — decides which seat it uses. The same editor role is one or the other depending on whether their reach is the whole organization or a list of sites:\n| Type | Reach | Seat |\n| Team manager | The whole organization | One of your team seats (managersPerOrg) |\n| Site collaborator | Only the site(s) they\'re granted | A collaborator seat on each site they can reach — never a team seat |\n| Site member | A published site, as a visitor with an account | None. Free and unlimited on every plan |\nPending invites carry the same label, so you can tell a pending manager from a pending collaborator before it\'s accepted.\nSite roles\nEvery person with access to a site holds one of four site roles. Managers get admin on every site in the organization; collaborators are given a role per site.\n| Site role | Can edit content | Can publish | Notes |\n| Viewer | No | No | Read-only |\n| Author | Yes | No | Drafts and edits everything; nothing they do goes live |\n| Editor | Yes | Yes | The usual working role |\n| Admin | Yes | Yes | Also manages the site\'s people, domain and plugins |\nAuthor is the role to give a client who should work on their own con' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Site membership', anchor: '#site-membership', text: '- Visitors can sign in / sign up to your site.\n- Member accounts are unlimited on every plan — including Free. Signups are never metered, capped, or charged per account.\n- Gate screens as members-only so only signed-in members can view them.\n- New members flow into your contacts CRM.\nThe platform safety limit {#visitor-record-ceiling}\nThere is one ceiling behind all of that, and it is an abuse control rather than a plan dimension — the same number on every plan, free through enterprise, with nothing to buy:\n| Records on one site | Ceiling |\n| Member accounts | 50,000 |\n| Leads | 200,000 |\nPast the ceiling, new sign-ups (or lead captures) are refused. The visitor sees a plain "not accepting new accounts right now" message that does not name a limit, and your console shows a New member sign-ups are paused notice with the count of refusals this month.\nIt does not clear on its own. Unlike the form and bandwidth ceilings, this one counts records you currently hold rather than a month\'s activity, so nothing lifts it at the month boundary — the notice deliberately never names a date. Deleting records below the limit starts acceptance again immediately, and if the traffic is real, support will raise it.' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Seats', anchor: '#seats', text: 'Seats cover your team only: organization seats (workspace-wide) and per-site collaborator seats (teammates limited to one site). Both are metered and enforced; buy seat add-ons to grow. Site member accounts — visitors who sign up to your published site — are not seats and are never capped. See Billing & plans.\nHow-tos\n- Invite teammates\n- Custom roles & permissions\n- Members-only areas' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Related', anchor: '#related', text: '- Billing & plans\n- Staff console (Aglyn staff only)' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: '', anchor: '', text: 'White-label\nWhite-labeling replaces the Aglyn brand everywhere your organization and its sites are shown: the console your team signs in to, the sites you publish, and the transactional email your members and customers receive.\nIt is one setting card, and the fields are short. The part worth reading closely is what each field actually replaces — a few of them change a surface you never look at yourself.\nPlan availability White-labeling is the whiteLabel entitlement. Exactly two plans carry it by default: Agency and Enterprise. No lower tier does, and no add-on buys it.\nEntitlements can also be granted per organization on top of a plan\'s defaults, which is how an Enterprise agreement enables it for one organization — the card\'s own upgrade notice says so.\nAn organization that white-labels and then downgrades reverts cleanly: the stored brand is ignored, not deleted, and the Aglyn brand comes back everywhere at once. Upgrade again and the same values return.' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: 'Where the settings are', anchor: '#where', text: '1. Open your organization\'s Settings page — the heading reads Organization Settings.\n2. Choose the Branding tab.\n3. The card is White-label brand.\nYou need the admin role. The Branding tab is not shown at all to members below it, so a teammate who cannot find it is looking at a shorter tab strip than you are, not at a hidden card.\nWhile your plan is still being read the card says "Checking your plan…". On a plan without the entitlement it shows an information notice instead of the editor: "White-labeling the platform is included on the Agency plan — see Billing to upgrade. Enterprise plans can enable it per organization."' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: 'The fields', anchor: '#fields', text: 'Every field is optional. Leave one blank and it keeps the Aglyn default for that field — the greyed-out placeholder text in each box is that default, so a blank box is showing you exactly what will be used.\nTwo fields are the exception, and both fall back to nothing rather than to an Aglyn value: Support URL and Email logo URL. Their placeholders say so. Leaving Support URL blank means no support link is shown anywhere — your customers are never sent to Aglyn\'s support desk, which could not help them and would name us to someone who was never told we exist.\n| Field | Helper text under it | What it replaces |\n| Product name | Shown in the console chrome, site badge, and emails. | The word "Aglyn" wherever the product names itself |\n| Email from-name | Display name on transactional email (the verified sending address is unchanged). | The display name in the recipient\'s inbox |\n| Support URL | Linked from branded surfaces and email footers. Leave it blank and no support link appears at all — your customers are never sent to Aglyn. | Where a "need help?" link points, or nothing |\n| Primary color | CSS hex color used for the console primary and site badge. | The console\'s primary color, live |\n| Logo URL | Console chrome + site badge. Browse the org media library or paste an https URL. | The Aglyn wordmark in the console header |\n| Favicon URL | Browser tab icon for branded console surfaces. | The browser-tab icon |\n| Email logo URL | Logo shown in transactional email headers (a hosted PNG works best). | Nothing — it adds a header to your email. See below |\n| Custom console domain | Saved now; domain routing to it ships in a later phase. | Nothing yet. See below |\nLogo URL, Favicon URL and Email logo URL each carry a Browse button that opens your organization\'s media library' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: 'Where you will see the change', anchor: '#where-you-see-it', text: '- Console header. Your Logo URL replaces the Aglyn wordmark. Set a Product name but no logo and the name is rendered as text in the same place instead.\n- Console theme and tab. Primary color and Favicon URL are applied to the page you are already on, so the change is visible without a reload.\n- Published sites. The site badge and the site favicon follow the same brand.\n- Site fingerprint. The tag and the x-powered-by header that otherwise credit Aglyn are suppressed on a white-label organization\'s published sites. This one is worth knowing about because it is invisible in a browser and is the part a technically curious visitor would otherwise read.\n- Transactional email. Covered in its own section next.\nOne counter-intuitive rule governs all of it: the branded chrome activates only once you have actually set a product name or a logo, not the moment your plan grants the entitlement. An Agency organization that has never opened this card keeps the plain Aglyn wordmark — there is no half-branded state and no flash of one brand turning into the other.' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: 'The email half', anchor: '#email', text: 'Email is where white-labeling used to leak, and it is the part that changed most recently.\nMerge tokens {#merge-tokens}\nEvery system email resolves three brand tokens, for every organization:\n| Token | Resolves to |\n| {{brand.productName}} | Your Product name, or Aglyn |\n| {{brand.fromName}} | Your Email from-name, or Aglyn |\n| {{brand.supportUrl}} | Your Support URL, or empty |\nThey resolve on Aglyn\'s own organizations too, which is what lets one email template be correct for both populations instead of hard-coding the majority case. If your organization is not white-labeled, the tokens render the Aglyn values.\n{{brand.supportUrl}} is the one that can render as nothing, and only for a white-labeled organization that left the field blank. Aglyn\'s own support page is never substituted — the email your customer receives reads as you throughout, and a link to our desk in it would be the one thing on the page that is not. Aglyn\'s built-in emails drop the whole "Need help?" line rather than leave a dangling phrase; a template you design places the token yourself, so put it somewhere a blank reads cleanly.\nThe email logo {#email-logo}\nEmail logo URL renders as a centered header row at the top of the email body, above whatever the template itself lays out, inside the same 600-pixel column — so on a phone it scales with the message rather than floating against the viewport. Its height is capped rather than fixed, so a wide wordmark and a square mark both land at a sensible size without you supplying dimensions.\nTwo details are deliberate and quiet:\n- A blank Email logo URL emits nothing at all — not an empty row, not a spacer. (Support URL behaves the same way, for the same reason.) An email with a gap where a logo should be reads as broken; an email with no logo reads as plain' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: 'Known limitation: the custom console domain', anchor: '#custom-console-domain', text: 'Custom console domain is saved but does nothing yet, and the field says so in its own helper text: "Saved now; domain routing to it ships in a later phase." Your team still signs in at the standard console address.\nSaving it is not entirely inert. The name is reserved for your organization when you save it, so nobody else can claim it in the meantime, and the reservation is released if you clear the field or change it to a different name. What has not shipped is the routing and certificate half — until that lands, a reservation is all the field buys, and pointing DNS at it achieves nothing.' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: 'Not the same as renaming a self-hosted platform', anchor: '#platform-brand', text: 'These two get confused constantly, and they are unrelated mechanisms:\n| | White-label brand | Platform brand |\n| Who sets it | An organization admin, in the console | Whoever runs the deployment, in its environment |\n| Scope | That one organization | The entire installation, every organization on it |\n| How | The card on this page | NEXTPUBLICPLATFORMBRANDNAME and friends |\n| Gated on | The whiteLabel entitlement | Nothing — it is deployment configuration |\n| Takes effect | On save | On the next image build, not a restart |\nIf you are running Aglyn yourself and want the product to stop calling itself Aglyn for everybody, that is the platform brand, not this card — see Self-hosting. The two compose: on a self-hosted installation, an organization without the whiteLabel entitlement falls back to the operator\'s platform brand rather than to Aglyn\'s.' },
  { path: '/workspace-and-billing/white-label', title: 'White-label', heading: 'Related', anchor: '#related', text: '- Billing & plans\n- Teams, roles & membership\n- Self-hosting' },
]
